INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(281829, 'چ', '<span class=\"hlight\">چ .</span> (حرف ) نشانه ٔ حرف هفتم از حروف تهجی است و آن را جیم فارسی یا جیم معقودة نیز گویند و در حساب جُمَّل نماینده ٔ عددی نیست مگر مانند جیم عدد سه بشمار آید، و در حساب ترتیبی نشانه ٔ عدد هفت است .<br />ابدالها:<br /> <font color=\"Red\">حرف چ در فارسی :</font><br />>گاه بدل به «ت » شود. مؤلف آنندراج آرد: «و صاحب برهان لوت به لام به معنی عریان و برهنه و پوک به بای فارسی و واو مصروف و کاف تازی به معنی بی مغز و میانه تهی آورده و این اگر به اثبات رسد مبدل لوچ و پوچ تواند شد» - انتهی .<br />> گاه به «ج » بدل شود:<br />چوزه = جوجه . رجوع به «ج » شود.<br />و گاه با «ج » هم قافیه شود <span class=\"hlight\">:</span> <br />یکی دختر مهتر چاچ بود<br />به بالای سرو و به رخ عاج بود.<br /> <font color=\"Red\">فردوسی </font><br />دلش گرچه در حال از او رنجه شد<br />دوا کرد و خوشبوی چون غنچه شد.<br /> <font color=\"Red\">سعدی .</font><br />رجوع به «ج » شود.<br />> گاه به «د» بدل شود:<br />کوچک = کودک .<br />ماچه = ماده . (ماچه خر = ماده خر).<br />> گاه به «ز» بدل شود:<br />نایچه = نایزه .<br />ایچه = ایزه .<br />بچشک = پزشک .<br />مشکیچه = مشکیزه .<br />> گاه به «ژ» بدل شود:<br />کاچ = کاژ.<br />دانچه = دانژه .<br />> گاه به «س » بدل شود:<br />چریش = سریش .<br />> گاه به «ش » بدل شود:<br />لخچه = لخشه <span class=\"hlight\">:</span> <br />آتش عشق را ز بس سورت <br />آه شعله ست و غم بود لخشه .<br /> <font color=\"Red\">بدر چاچی .</font><br />پخج = پخش .<br />چاچ = شاش .<br />کریچ = کریش <br />کریچه = کریشک .<br />لوچ = لوش <br />لوچه = لوشه .<br />سپچ = سپش (شپش ).<br />چلتوک = شلتوک <br />چوپان = شبان <br />هیچ = هیش <span class=\"hlight\">:</span> <br />احمد جامی ترا پندی دهد<br />آخرت را باش دنیا هیش نیست .<br /> <font color=\"Red\">احمد شیخ ژنده پیل .</font><br />بهرام چوبین = بهرام شوبین .<br />پاچیدن = پاشیدن .<br />چنبر = شنبر.<br />پوچال = پوشال .<br />پرخچ = پَرَخش . (آنندراج ) <span class=\"hlight\">:</span> <br />دیوسیرت سروش نصرت بخش <br />ببرسینه پلنک رخش پرخش .<br /> <font color=\"Red\">مختاری .</font><br />فرخچ = فرخش .<br />> گاه به «ک » بدل شود:<br />پوچ = پوک .<br />چلپاسه = کربسه . کلباسو<br />چمچه = کمچه .<br />کرچ = کرک (مرغ ...).<br />انچوچک = انچوکک .<br />> گاه به «گ » بدل شود:<br />چِل = گِل .<br />> گاه به «ی » بدل شود:<br />ماچه = مایه .<br />پاچه = پایه .<br />مورچانه = موریانه <span class=\"hlight\">:</span> <br />آهنی را که مورچانه بخورد<br />نتوان برد از او به صیقل زنگ .<br /> <font color=\"Red\">سعدی (از آنندراج ).</font><br />> گاه زایده باشد:<br />کفچل = کفل .<br />کچل = کل .<br />کفچ = کف .<br />لفچ = لف <span class=\"hlight\">:</span> <br />فروهشته لفچ و برآورده کفچ <br />همه لفچ کفچ و همه کفچ لفچ .<br /> <font color=\"Red\">؟ (از آنندراج ).</font><br />نایچ =نای <span class=\"hlight\">:</span> <br />هزار ناله زدم بی گل رخت در باغ <br />به درد دل که شنیدم فغانی از نایچ .<br /> <font color=\"Red\">؟ (از آنندراج ).</font><br />نمچ = نم <span class=\"hlight\">:</span> <br />سنگ بی نمچ و آب بی زایش <br />بهتر از جاهلی به آرایش . <br /> <font color=\"Red\">عنصری (از آنندراج ).</font><br /> <font color=\"Red\">این حرف در عربی نیست و در تعریب :</font><br />> به «ج » بدل شود:<br />چلغوز = جلغوز.<br />> گاه به «س » بدل گردد:<br />چراغ = سراج .<br />> گاه به «ش » بدل شود:<br />چوبک = شوبق .<br />چالوس = شالوس .<br />چموش = شموس .<br />چهارسو = شهارسو.<br />چادر = شوذر.<br />چنبر = شنبر. (خیار...).<br />چاچ = شاش .<br />چاه بهار = شاه بهار.<br />چغانیان = شغانیان .<br />چین = شین .<br />ابن البیطار وقتی می خواهد بگوید ایرانیان مملکت مشهور چین (صین ) را چه می نامندمیگوید: «انّهم یسمون الصین، شین ». (ابن البیطار درشرح کلمه ٔ راوند).<br />چنگ = شنگ (شنج ) (معجم الادباء چ مارگلیوث ج <span class=\"hlight\" dir=\"rtl\">٥</span> ص <span class=\"hlight\" dir=\"rtl\">٢٠٥</span> سطر <span class=\"hlight\" dir=\"rtl\">٦</span>).<br />> گاه به «ص » بدل گردد:<br />چنگ = صنگ . (صنج ).<br />چلیپا = صلیب .<br />چنار = صنار.<br />چرم = صرم .<br />بلوچ = بلوص .<br />چهاربخت = صهاربخت .<br />چارو = صاروج .<br />گچ = جص .<br />دارچین = دارصین .<br />چغانیان = صغانیان .<br />چول = صول .<br />چندن = صندل .<br />چیدنی = صیدنه .<br />چین = صین .<br />رچاچ = رصاص .<br />چک = صک .<br />چغانه = صغانه .<br />چا = صا.<br />رسم الخط. در رسم الخط قدیم «چه » موصوله را در بعضی موارد بدون «ها» می نوشته اند <span class=\"hlight\">:</span> تا از همه جوانب آنچ رفتی و تازه گشتی معلوم او میگردانیدندی . (فارسنامه ص <span class=\"hlight\" dir=\"rtl\">٩٣</span>). از آنچ تا هزار ناداشت باشد یک توانگر تواند بود. (فارسنامه ص <span class=\"hlight\" dir=\"rtl\">٨٧</span>). و در مواردی با «ها مختفی » نوشته میشده <span class=\"hlight\">:</span> و هرچه شاهنشاه فرماید آن کنیم . (فارسنامه ص <span class=\"hlight\" dir=\"rtl\">٦٧</span>). و بر خصوص حاجب درگاه و منشی تنوق هر چه تمامتر کرد. (فارسنامه ص <span class=\"hlight\" dir=\"rtl\">٩٢</span>). هرچه از وی بپرسیدندی به زجر بگفتی . (فارسنامه ص <span class=\"hlight\" dir=\"rtl\">٩٧</span>).<br />و گاه «چه » استفهامی در مواردی، از قبیل : «چه گونه » و «چه تواند بود» و امثال آن با حذف «ها» به کلمه ٔ بعد وصل میشده است <span class=\"hlight\">:</span> روز اول مرا چگونه بشناختی ؟. (فارسنامه ص <span class=\"hlight\" dir=\"rtl\">٨٧</span>). کسری او را بخواند و این احوال با او بگفت و پرسید کی چتواند بودن ؟ (فارسنامه ص <span class=\"hlight\" dir=\"rtl\">٩٧</span>). و گاه در رسم الخط قدیم بجای «چه » «چی » می نوشته اند <span class=\"hlight\">:</span> به لغت دری آورد چی دانست که فایده ٔ آن عامتر باشد. (المعجم ص <span class=\"hlight\" dir=\"rtl\">١٨</span> چ مدرس رضوی ). و اگر غلط به نساخ حوالت کنیم هم نیک نیست چی آب را به التهاب صفت نکنند. (المعجم ص <span class=\"hlight\" dir=\"rtl\">٢٣٦</span> چ مدرس رضوی ). چی هر کرا به تنصیص این تخصیص داده اند کی، الرجال قوامون علی النساء. (قرآن <span class=\"hlight\" dir=\"rtl\">٣٤/٤</span>) (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">١١٢</span>). چی هر ضیافتی کی اطعمه ٔ او کوتاه مزه بود آن ضیافت سراسر وبال و بزه بود. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">١٦٨</span>). چی یافتن منال بی وسیلت مال دشخوار و ناممکن بود. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٢٩٣</span>).<BR><font color=\"Blue\">◄</font> حرف «چ » مانند «چه » گاهی موصول است و معنی «چیز» را رساند و در این مورد غالباً «چ » را بعد از «هر» یا «آن » آورند <span class=\"hlight\">:</span> <br />و آنچ از پس اوست از این پنج روز همه جشن هاست . (التفهیم لاوایل صناعة التنجیم از سبک شناسی ج دوم ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>). من خواستم کی کتابی بنا کنم و هرچ شایسته اندر او یاد کنم . (الابنیه عن حقایق الادویه از سبک شناسی ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٢٤</span>). تا از همه جوانب آنچ رفتی و تازه گشتی معلوم او میگردانیدندی . (فارسنامه ص <span class=\"hlight\" dir=\"rtl\">٩٣</span>).<br />زبانم خود چنین پر زخم از آن است <br />که هرچ او میدهد زخم زبان است .<br /><font color=\"Red\">نظامی (خسرو و شیرین ص <span class=\"hlight\" dir=\"rtl\">٢٠٣</span>).</font><br /></font></div>'),
(281830, 'چا', '<span class=\"hlight\">چا.</span> (چینی، اِ) معروف و مشهور است به «چای » معرب آن «صای » و «شای » و آن برگی است که از چین و ختا آورند و در آب جوشانیده مانند قهوه خورند. در برهان آمده که چون مردم تبت شراب بسیار میخورند و چای دافع مضرت شراب است آن را به قیمت مشک میخرند و بس عزیز میدارند. بلی اکنون در ایران نیز متداول شده . صاحب مخزن گفت مصلح چای بادیان ختائی است که در وقت پختن در آن اندازند. در خوارزم و بخارا چای تلخ خورند و در آن قند و شکر نکنند و دیده شده که نمک در آن ریزند و خورند و معرب آن «صا» باشد. (آنندراج ) (انجمن آرا ص <span class=\"hlight\" dir=\"rtl\">٢٢٩</span>). رجوع به چای و چائی شود.<br /></font></div>'),
(281831, 'چابار', '<span class=\"hlight\">چابار.</span> (اِخ ) دهی جزء دهستان بزجلو بخش وفس شهرستان اراک در <span class=\"hlight\" dir=\"rtl\">١٧</span> هزارگزی جنوب خاوری کمیجان و <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی راه مالرو عمومی .کوهستانی و سردسیر است با <span class=\"hlight\" dir=\"rtl\">٢٠٢</span> تن سکنه، آب آن از قنات، محصول عمده ٔ آنجا غلات، انگور و لبنیات است . شغل مردان زراعت و گله داری، صنایع دستی زنان قالی بافی و راه آنجا مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(281832, 'چابق', '<span class=\"hlight\">چابق .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِ) سر تازیانه . در فرهنگ رشیدی ذیل کلمه ٔ «چابک » چنین آمده : «چابک به معنی تازیانه در غیر شعر خسرو دیده نشد و ظاهراً هندی است :<br />خشم ستیزنده را چابک تأدیب زن .<br />اما در صراح در لغت عذب گفته که عذبةالسوط؛ چابق . پس ظاهر شد که لفظ چابق است بقاف و به معنی سرتازیانه و ظاهراً زبان مغولی است نه فارسی »؟ ارباذ؛ تازیانه ٔ چابق دار ساختن . (منتهی الارب ). رَبَذَة؛ چابق تازیانه . عَذَبَة؛ چابق تازیانه . (منتهی الارب ). صیله ؛ گره چابق تازیانه . (صراح ). و رجوع به چابک در این معنی شود.<br /></font></div>'),
(281833, 'چابلوس', '<span class=\"hlight\">چابلوس .</span> (ص )چرب زبان . متملق . مردم فریب . و رجوع به چاپلوس شود.<br /></font></div>'),
(281834, 'چابلوسی', '<span class=\"hlight\">چابلوسی .</span> (حامص ) تملق گویی . چرب زبانی . و رجوع به چاپلوسی شود.<br /></font></div>'),
(281835, 'چابوک', '<span class=\"hlight\">چابوک .</span> (ص ) چابک . چست . چالاک . جلد. و رجوع به چابک و چابوک دست شود.<br /></font></div>'),
(281836, 'چابوک دست', '<span class=\"hlight\">چابوک دست .</span><font color=\"DarkGreen\"><b>[ دَ ]</font></b> (ص مرکب ) چابکدست . ماهر. تردست <span class=\"hlight\">:</span> <br />چه چابوک دستی است بازی سگال <br />که در پرده داند نمودن خیال .<br /><font color=\"Red\">اسدی (گرشاسبنامه ).</font><br /></font></div>'),
(281837, 'چابک', '<span class=\"hlight\">چابک .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِ) چابق . تازیانه . (برهان ) (غیاث از بهار عجم و سراج و سروری ) <span class=\"hlight\">:</span> <br />اسپی است مرا ز سایه ٔ خود به گریز<br />دشت از عرق سستی او طوفان خیز<br />یک گام به گام بسپرد گر به مثل <br />شمشیر بود چابک و خنجر مهمیز.<br /><font color=\"Red\">سنجرکاشی (از آنندراج ).</font><br /></font></div>'),
(281838, 'چابک', '<span class=\"hlight\">چابک .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (ص ) چست و چالاک . فرز. تند. سبک . زرنگ . زبر و زرنگ . ظریف . رعنا. قبراق . زود. قچاق . چابوک . چاپوک . چپوک (دهات تربت حیدریه ): جلیت ؛ مرد چابک و چست . جلد؛ چابک از هر چیزی . جلدة؛ چابک و چالاک گردیدن .جلید؛ چابک از هر چیزی . جمل خذانیة؛ یعنی سطبر و چابک . خنوت ؛ مرد چابک شتابزده که بر نهالی نخسبد. دلهمس ؟ مرد چابک سطبر. ذفر؛ جوان چابک درازبالا تمام بدن .صعتری ؛ مرد چابک و شوخ و دلاور. نیرب ؛ مرد چابک و چست . هذف ؛ مرد شتابرو چابک . (منتهی الارب ) <span class=\"hlight\">:</span> <br />چو آن مرد چابک به اندک سپاه <br />ز جایی بیاید بدرگاه شاه .<br />مر این ترک را ناگهان بشکند<br />همه لشکرش را بهم برزند.<br /> <font color=\"Red\">فردوسی .</font><br />همواره این سرای چو باغ بهشت باد<br />از رومیان چابک و ترکان نازنین .<br /> <font color=\"Red\">فرخی .</font><br />نزد او آن جوان چابک رفت <br />از غم ره گران و گوش سبک .<br /> <font color=\"Red\">منطقی .</font><br />چرخ را انجم بسان دستهای چابکند<br />کز لطافت خاک بی جان را همی باجان کنند.<br /> <font color=\"Red\">ناصرخسرو.</font><br />مشو درخط ز خط کانهم ز حسن است <br />دغا چون چابک آید هم ز نرد است .<br /> <font color=\"Red\">عمادی شهریاری .</font><br />چابک استاده ام به زیر فلک <br />مگر از چنبرش برون گذرم .<br /> <font color=\"Red\">خاقانی .</font><br />استادان حاذق و عمله ٔ چابک ترتیب دادند. (ترجمه ٔ تاریخ یمینی ).<br />شگرفی چابکی چستی دلیری <br />به مهر آهو به کینه تندشیری .<br /> <font color=\"Red\">نظامی .</font><br />خر خود را چنان چابک نبینم <br />که با تازی سواری برنشینم .<br /> <font color=\"Red\">نظامی .</font><br />بازی کن و چابک و طرب ساز<br />مالیده سرین و گردن افراز.<br /> <font color=\"Red\">نظامی .</font><br />هر نفس این پرده ٔ چابک رقیب <br />بازیی از پرده برآرد غریب .<br /> <font color=\"Red\">نظامی .</font><br />قلم زن چابکی صورتگری چست <br />که بی کلک از خیالش نقش میرست .<br /> <font color=\"Red\">نظامی .</font><br />همیشه بر قد دولت قبای حکم تو چابک <br />همیشه بر سر دشمن قضای تیغ تو مبرم .<br /> <font color=\"Red\">امامی هروی .</font><br />چو از چابکان در دویدن گرو<br />نبردی، هم افتان و خیزان برو.<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />باچابکان دلبر و شوخان دلفریب <br />بسیار در فتاده و اندک رمیده اند.<br /> <font color=\"Red\">سعدی .</font><br />به چابکتر از خود مینداز تیر<br />چو افتاددامن بدندان بگیر.<br /> <font color=\"Red\">سعدی .</font><br />اگر بنده چابک نیاید بکار<br />عزیزش ندارد خداوندگار.<br /> <font color=\"Red\">سعدی .</font><br />قبا بست و چابک نوردید دست <br />قبایش دریدند و دستش شکست .<br /> <font color=\"Red\">سعدی .</font><br />غلامان و کنیزان دلاویز دارد و شاگردان چابک (گلستان ). رجوع به چست، تند، زود، فرز شود.<br /></font></div>'),
(281839, 'چابک ادا', '<span class=\"hlight\">چابک ادا.</span> <font color=\"DarkGreen\"><b>[ ب ُ اَ ]</font></b> (ص مرکب ) حاضرسخن . <BR><font color=\"Blue\">◄</font> سازنده و نوازنده (ناظم الاطباء) <span class=\"hlight\">:</span> <br />اگر لفظ و معنی نظیر هم اند<br />به چابک ادائی اسیر هم اند.<br /><font color=\"Red\">ظهوری (از آنندراج ).</font><br /></font></div>'),
(281840, 'چابک اندیش', '<span class=\"hlight\">چابک اندیش .</span> <font color=\"DarkGreen\"><b>[ ب ُ اَ ]</font></b> (ص مرکب ) زیرک . هوشیار. تیزفهم . سریعالانتقال <span class=\"hlight\">:</span> <br />مرا این زن پیر چون مادر است <br />یکی چابک اندیش کندآور است .<br /> <font color=\"Red\">فردوسی .</font><br />و آن نمودن که بنگرم پیشی <br />کارها را به چابک اندیشی .<br /> <font color=\"Red\">نظامی (هفت پیکر).</font><br />که شنیدم به خردی از خویشان <br />خرده کاران و چابک اندیشان .<br /><font color=\"Red\">نظامی (هفت پیکر).</font><br /></font></div>'),
(281841, 'چابک اندیشه', '<span class=\"hlight\">چابک اندیشه .</span> <font color=\"DarkGreen\"><b>[ ب ُ اَ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (ص مرکب ) زیرک . تیزفهم <span class=\"hlight\">:</span> <br />که آنگه شاعری پیشه نبوده ست <br />حکیمی چابک اندیشه نبوده ست .<br /> <font color=\"Red\">فخرالدین اسعد(ویس و رامین ).</font><br />تو همشهری او را و هم پیشه ای <br />هم اندر سخن چابک اندیشه ای .<br /> <font color=\"Red\">اسدی (گرشاسبنامه ص <span class=\"hlight\" dir=\"rtl\">١٤</span>).</font><br />چابک اندیشه ای رسیده نخست <br />همه را نظم داده بود درست .<br /> <font color=\"Red\">نظامی (هفت پیکر).</font><br />در همه کاری آن هنرپیشه <br />چاره گر بود و چابک اندیشه .<br /> <font color=\"Red\">نظامی (هفت پیکر).</font><br />رجوع به چابک اندیش شود.<br /></font></div>'),
(281842, 'چابک بازی', '<span class=\"hlight\">چابک بازی .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (حامص مرکب ) تازیانه زنی . (ناظم الاطباء).<br /></font></div>'),
(281843, 'چابک خرام', '<span class=\"hlight\">چابک خرام .</span> <font color=\"DarkGreen\"><b>[ ب ُ خ ِ <span class=\"hlight\" dir=\"rtl\">/</span> خ َ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ ]</font></b> (ص مرکب ) تیزگام .<br /></font></div>'),
(281844, 'چابک خیزی', '<span class=\"hlight\">چابک خیزی .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (حامص مرکب ) تندی . تیزی . عمل اشخاصی که سبک خیزند <span class=\"hlight\">:</span> <br />دست حفظت بهر چابک خیزی و بربستگی <br />بر میان شعله بربندد نطاق از برگ کاه .<br /><font color=\"Red\">عرفی (از بهار عجم ).</font><br /></font></div>'),
(281845, 'چابک دستی', '<span class=\"hlight\">چابک دستی .</span> <font color=\"DarkGreen\"><b>[ ب ُ دَ ]</font></b> (حامص مرکب ) استادی . مهارت . چالاکی <span class=\"hlight\">:</span> <br />به چابکدستی و استادکاری <br />کنی در کار این قصر استواری .<br /> <font color=\"Red\">نظامی (خسرو و شیرین ).</font><br />از حکم تقدیر مقدران آسمانی و چابکدستی مهندسان لامکانی . (ترجمه ٔ محاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">٥٧</span>). حقایق خرده کاری و چابکدستی بتقدیم رسانیده . (ترجمه ٔ محاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">٦٣</span>).<br /></font></div>'),
(281846, 'چابک ربا', '<span class=\"hlight\">چابک ربا.</span> <font color=\"DarkGreen\"><b>[ ب ُ رُ ]</font></b> (نف مرکب ) زودربا. رباینده ٔ چالاک و چابک <span class=\"hlight\">:</span> <br />ستاننده چابک ربائی است زود <br />که نتوان ستدباز هرچ آن ربود.<br /><font color=\"Red\">اسدی .</font><br /></font></div>'),
(281847, 'چابک رقیب', '<span class=\"hlight\">چابک رقیب .</span> <font color=\"DarkGreen\"><b>[ ب ُ رَ ]</font></b> (ص مرکب ) حریف ماهر. رقیب چالاک <span class=\"hlight\">:</span> <br />هر نفس این پرده ٔ چابک رقیب <br />بازییی از پرده برآرد غریب .<br /><font color=\"Red\">نظامی (مخزن الاسرار).</font><br /></font></div>'),
(281848, 'چابک روی', '<span class=\"hlight\">چابک روی .</span> <font color=\"DarkGreen\"><b>[ ب ُ رَ ]</font></b> (حامص مرکب )چابک رفتاری . تندروی . چالاکی در راه رفتن <span class=\"hlight\">:</span> <br />به چابک روی پیکرش دیوزاد<br />به گردندگی کنیتش دیو باد.<br /> <font color=\"Red\">نظامی (شرفنامه ).</font><br />که چون خسرو از تخت کیخسروی <br />سوی لشکر آمد به چابک روی .<br /><font color=\"Red\">نظامی (شرفنامه ).</font><br /></font></div>'),
(281849, 'چابک رکاب', '<span class=\"hlight\">چابک رکاب .</span> <font color=\"DarkGreen\"><b>[ ب ُ رِ ]</font></b> (ص مرکب ) سوار نیک و فارس <span class=\"hlight\">:</span> <br />ز جنگی سواران چابک رکاب <br />به نهصد هزار آمد اندر حساب .<br /> <font color=\"Red\">نظامی (شرفنامه ).</font><br />سوار هنرمند چابک رکاب <br />که بر آتش انگشت زد بی حساب .<br /><font color=\"Red\">نظامی (از شرفنامه ).</font><br /></font></div>'),
(281850, 'چابک رکیب', '<span class=\"hlight\">چابک رکیب .</span> <font color=\"DarkGreen\"><b>[ ب ُ رَ ]</font></b> (ص مرکب ) سوار نیک و فارس . (ناظم الاطباء). و رجوع به چابک رکاب شود.<br /></font></div>'),
(281851, 'چابک سخن', '<span class=\"hlight\">چابک سخن .</span> <font color=\"DarkGreen\"><b>[ ب ُ س ُ خ َ ]</font></b> (ص مرکب ) سخنور. ناطق .کسی که در سخن مضامین نیکو تواند آورد <span class=\"hlight\">:</span> <br />به آن چابک سخن دشت بیاض شعر ارزانی <br />که صد مضمون بهم از یک خدنگ خامه میدوزد.<br /><font color=\"Red\">؟ (از آنندراج ).</font><br /></font></div>'),
(281852, 'چابک سر', '<span class=\"hlight\">چابک سر.</span> <font color=\"DarkGreen\"><b>[ ب ُ س َ ]</font></b> (اِخ ) دهی جزء دهستان اوشیان بخش رودسر شهرستان لاهیجان، در سی ودو هزارگزی جنوب خاوری رودسر، سر راه شوسه ٔ رودسر به شهسوار کنار دریا جلگه، معتدل، مرطوب . آب آن از نهر مایده، محصول آنجا برنج و مرکبات و چای، شغل اهالی زراعت، راه آن شوسه است و <span class=\"hlight\" dir=\"rtl\">٢٥</span> باب دکان و ماشین برنج کوبی و مالش چای دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>). و رجوع به فهرست سفرنامه ٔ مازندران رابینو شود.<br /></font></div>'),
(281853, 'چابک سرای', '<span class=\"hlight\">چابک سرای .</span> <font color=\"DarkGreen\"><b>[ ب ُ س َ ]</font></b> (نف مرکب ) شاعر خوش سخن . <BR><font color=\"Blue\">◄</font> ماهر در سخنوری . <BR><font color=\"Blue\">◄</font> خوش آواز <span class=\"hlight\">:</span> <br />بیار ای سخنگوی چابک سرای <br />بساط سخن را یکایک بجای .<br /><font color=\"Red\">نظامی (شرفنامه ).</font><br /></font></div>'),
(281854, 'چابک سوار', '<span class=\"hlight\">چابک سوار.</span> <font color=\"DarkGreen\"><b>[ ب ُ س َ ]</font></b> (ص مرکب ) سوارکار. ماهر و چالاک در سواری . رایض و سوقان دهنده ٔ اسب <span class=\"hlight\">:</span> <br />به میدان دین اندر، اسب سخن را<br />اگر خوب چابکسواری بگردان .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ازینست جانت ز دانش پیاده <br />از این تو به تن جلد و چابکسواری .<br /> <font color=\"Red\">ناصرخسرو.</font><br />وولید سخت عظیم چابک سوار بود و مردانه . (مجمل التواریخ و القصص ).<br />برون از کنیزان چابک سوار<br />غلامان شمشیرزن سی هزار.<br /> <font color=\"Red\">نظامی (شرفنامه ).</font><br />از آن تیغزن مرد چابک سوار<br />سخن راند با انجمن شهریار.<br /> <font color=\"Red\">نظامی (شرفنامه ).</font><br />بر این ابلق کسی چابک سوار است <br />که در میدان عشق آشفته کار است .<br /> <font color=\"Red\">نظامی (خسرو و شیرین ).</font><br />دلا طپیدن میلی نشانه است از آن <br />که نیم کشته ٔ چابک سوار من شده است .<br /> <font color=\"Red\">محمد قلی میلی (از آنندراج ).</font><br />و بر پشت هر یک چابک سواری چون ماه با قبا و کلاه نشسته . (ترجمه ٔ محاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">٥٢</span>). چابک سوار نیزه گذار. (سمط العلی ص <span class=\"hlight\" dir=\"rtl\">٦٨</span>). <BR><font color=\"Blue\">◄</font> سوداگراسب . <BR><font color=\"Blue\">◄</font> تازیانه زن . (ناظم الاطباء).<br /></font></div>'),
(281855, 'چابک سواری', '<span class=\"hlight\">چابک سواری .</span> <font color=\"DarkGreen\"><b>[ ب ُ س َ <span class=\"hlight\" dir=\"rtl\">/</span> س ُ ]</font></b> (حامص مرکب ) جلدی و چالاکی .مهارت در سواری و تربیت اسب . سوارکاری <span class=\"hlight\">:</span> <br />گران جوشن و خود گردی گزین <br />بچابک سواری ربودی ز زین .<br /> <font color=\"Red\">اسدی (گرشاسبنامه ص <span class=\"hlight\" dir=\"rtl\">٤٥</span>).</font><br />بدان نازک تنی و آبداری <br />چو مرغی بود در چابک سواری .<br /> <font color=\"Red\">نظامی (خسرو و شیرین ).</font><br />ملک زآن ماده شیران شکاری <br />شگفتی مانده در چابک سواری .<br /> <font color=\"Red\">نظامی (خسرو و شیرین ).</font><br />و چابک سواری و موی شکافی در تیراندازی و قوت و شجاعت و حسن تدبیر. (ترجمه ٔ محاسن اصفهان ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>).<br /></font></div>'),
(281856, 'چابک سیر', '<span class=\"hlight\">چابک سیر.</span> <font color=\"DarkGreen\"><b>[ ب ُ س ِی ْ ]</font></b> (ص مرکب ) تندرو. زودگذر. شتابناک <span class=\"hlight\">:</span> <br />آن نگر کآسمان چابک سیر<br />نام من شر نهاد و نام تو خیر.<br /><font color=\"Red\">نظامی (هفت پیکر).</font><br /></font></div>'),
(281857, 'چابک عنان', '<span class=\"hlight\">چابک عنان .</span> <font color=\"DarkGreen\"><b>[ ب ُ ع ِ ]</font></b> (ص مرکب ) سوارکار. تندرو. کنایه از مرد جنگی و دلیر. رجوع به چابک سوار شود <span class=\"hlight\">:</span> <br />همایون سواری چو غرنده شیر<br />توانا و چابک عنان و دلیر.<br /> <font color=\"Red\">نظامی (شرفنامه ).</font><br />یکی حمله ٔ نیک را ساز داد<br />عنان را به چابک عنان بازداد.<br /> <font color=\"Red\">نظامی (شرفنامه ).</font><br />قویدست و چابک عنان دیدمت .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> مرکب تندرو و تیزگام <span class=\"hlight\">:</span> <br />گذشته است مکرر ز ماه گردون سیر<br />براق همت چابک عنان درویشی .<br /><font color=\"Red\">صاحب (از آنندراج ).</font><br /></font></div>'),
(281858, 'چابک قدم', '<span class=\"hlight\">چابک قدم .</span> <font color=\"DarkGreen\"><b>[ ب ُق َ دَ ]</font></b> (ص مرکب ) تندرو. تیزگام . چالاک <span class=\"hlight\">:</span> <br />چابک قدم بسیط افلاک <br />والاگهر محیط لولاک .<br /><font color=\"Red\">فیض فیاض (از آنندراج ).</font><br /></font></div>'),
(281859, 'چابک نشین', '<span class=\"hlight\">چابک نشین .</span> <font color=\"DarkGreen\"><b>[ ب ُ ن ِ ]</font></b> (نف مرکب ) چالاک . کسی که چابک و سبک نشیند و خیزد. خوش ادا <span class=\"hlight\">:</span> <br />چنان چابک نشین بود آن دلارام <br />که برجستی برین مقدار ده گام .<br /><font color=\"Red\">نظامی (خسرو و شیرین ).</font><br /></font></div>'),
(281860, 'چابک نفس', '<span class=\"hlight\">چابک نفس .</span> <font color=\"DarkGreen\"><b>[ ب ُ ن َ ف َ ]</font></b> (ص مرکب ) تندرو. سریع. حاضرسخن .<br /></font></div>'),
(281861, 'چابک نفسی', '<span class=\"hlight\">چابک نفسی .</span> <font color=\"DarkGreen\"><b>[ ب ُ ن َ ف َ ]</font></b> (حامص مرکب ) شتاب . سرعت . تندروی . چابک سخنی <span class=\"hlight\">:</span> <br />ذوق چابک نفسی ناله ربایان دارند<br />هر کجا درد بدر تاخت عنان گیر شدیم .<br /><font color=\"Red\">ظهوری (از آنندراج ).</font><br /></font></div>'),
(281862, 'چابک پای', '<span class=\"hlight\">چابک پای .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (ص مرکب ) تیزپا و تندرو. <BR><font color=\"Blue\">◄</font> چالاک و ماهر در رقص <span class=\"hlight\">:</span> <br />با همه نیکویی سرود سرای <br />رودسازی به رقص چابک پای .<br /><font color=\"Red\">نظامی (هفت پیکر).</font><br /></font></div>'),
(281863, 'چابکدست', '<span class=\"hlight\">چابکدست .</span> <font color=\"DarkGreen\"><b>[ ب ُ دَ ]</font></b> (ص مرکب ) تیزدست . ماهر. جلدکار. باوقوف . شتابکار: رجل دمشق الیدین ؛ مرد شتابکار چابکدست . مدره ؛ چرب زبان و چابک دست وقت خصومت و کارزار. (منتهی الارب ) <span class=\"hlight\">:</span> <br />از روی تو نسختی به چین بردستند<br />آنجا که دو صد بتگر چابکدستند<br />در پیش مثال روی تو بنشستند<br />انگشت گزیدند و قلم بشکستند.<br /> <font color=\"Red\">؟ (از تفسیر ابوالفتوح سوره ٔ آل عمران ).</font><br />نقاش چابکدست از قلم صورتها انگیزد. (کلیله و دمنه ). اگر کسی خواهد که مثل آن آینه انشا کند و صد هزار بار هزار دینار بر آن خرج شود در مدت دویست سال بر دست استادان چابکدست به اتمام نرسد. (ترجمه ٔ تاریخ یمینی ).<br />گر چه کاتب نبوده چابکدست <br />پندگوینده را عیاری هست .<br /> <font color=\"Red\">نظامی (هفت پیکر).</font><br /><BR><font color=\"Blue\">◄</font> ظریف . (ناظم الاطباء). رجوع به چربدست شود.<br /></font></div>'),
(281864, 'چابکی', '<span class=\"hlight\">چابکی .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (حامص ) چالاکی . تندی . جلدی . سبکی . چستی . سرعت . شتاب . چربدستی . و رجوع به چستی شود: جَلدَة؛ چابکی مردم و غیر وی . تَجَلّدَ؛ به تکلف چابکی کرد. تَصَرّم ؛ چابکی کردن . (منتهی الارب ) <span class=\"hlight\">:</span> <br />بچابکی برباید کجا نیازارد<br />ز روی مرد مبارز بنوک پیکان خال .<br /> <font color=\"Red\">منجیک .</font><br />بهرام چابکی کرد و بر پشت آن شیر نشست و بهر دو پهلوهاش بفشرد. (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">٧٧</span>).<br />میدان فضل و مرکب اقبال در جهان <br />همتای تو سوار نبیند به چابکی .<br /> <font color=\"Red\">سوزنی .</font><br />خواست پریدن چمن از چابکی <br />خواست چکیدن سمن از نازکی .<br /> <font color=\"Red\">نظامی .</font><br />در آن خدمت بغایت چابکی داشت <br />که کار نازنینان نازکی داشت .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> اسب راهواری را نیز گویند که اگر تازیانه برو زنند راه غلط نکند. (برهان ) <span class=\"hlight\">:</span> <br />نه چابک شد این چابکی تاختن <br />کمندی بکوهی در انداختن .<br /> <font color=\"Red\">نظامی .</font><br />داد به احسان رهی پرورم <br />چابکی خاصه دو بدره زرم .<br /><font color=\"Red\">امیرخسرو (از جهانگیری ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٨</span>).</font><br /></font></div>'),
(281865, 'چات', '<span class=\"hlight\">چات .</span> (اِخ ) محلی در مرز ایران و روسیه به گرگان و رود اترک ازاین جا تا خلیج حسینقلی سرحد ایران محسوب می شود و سپس خط مرزی بطرف شمال منحرف میگردد. دهی است در مرز ایران و روسیه واقع بین مقر طایقه ٔ یاموت و کوکلان .<br /></font></div>'),
(281866, 'چات قیه', '<span class=\"hlight\">چات قیه .</span> <font color=\"DarkGreen\"><b>[ ق َ ]</font></b> (اِخ ) دهی از بخش نمین شهرستان اردبیل واقع در <span class=\"hlight\" dir=\"rtl\">١٦</span> هزارگزی شمال اردبیل و <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی راه ارابه رو گرمی اردبیل .کوهستانی، معتدل با <span class=\"hlight\" dir=\"rtl\">١٧١</span> تن سکنه، آب آن از چشمه، محصول آنجا غلات و حبوبات . شغل اهالی زراعت و گله داری، راه آن مالرو. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٣</span>).<br /></font></div>'),
(281867, 'چاتالجه', '<span class=\"hlight\">چاتالجه .</span> <font color=\"DarkGreen\"><b>[ ج َ ]</font></b> (اِخ ) رجوع به چاتلجه شود.<br /></font></div>'),
(281868, 'چاتام', '<span class=\"hlight\">چاتام .</span> (اِخ )(لرد...) یکی از وزرای انگلستان رجوع به پیت شود.<br /></font></div>'),
(281869, 'چاتام', '<span class=\"hlight\">چاتام .</span>(اِخ ) نام گنگباری نزدیک زلاند جدید در اقیانوسیه .<br /></font></div>'),
(281870, 'چاتام', '<span class=\"hlight\">چاتام .</span> (اِخ ) بندری نظامی درکشور انگلستان واقع در ایالت کنت در ساحل دریای مانش دارای <span class=\"hlight\" dir=\"rtl\">٤٣٠٠٠</span> تن سکنه .<br /></font></div>'),
(281871, 'چاتانوغه', '<span class=\"hlight\">چاتانوغه .</span> <font color=\"DarkGreen\"><b>[ غ َ ]</font></b> (اِخ ) شهری به آمریکای شمالی در ایالت تنسی دارای <span class=\"hlight\" dir=\"rtl\">٦٠٠٠٠</span> تن سکنه .<br /></font></div>'),
(281872, 'چاتخ', '<span class=\"hlight\">چاتخ .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) محلی در شمال قارص .<br /></font></div>'),
(281873, 'چاترتون', '<span class=\"hlight\">چاترتون .</span> <font color=\"DarkGreen\"><b>[ ت ِ ت ُ ]</font></b> (اخ ) نمایشنامه ای تألیف الفرد دو وینی شاعر فرانسوی . موضوع آن مرگ چاترتون شاعر است .<br /></font></div>'),
(281874, 'چاترتون', '<span class=\"hlight\">چاترتون .</span> <font color=\"DarkGreen\"><b>[ ت ِ ت ُ ]</font></b> (اِخ ) توماس شاعر انگلیسی . مولد بریستول متولد سال <span class=\"hlight\" dir=\"rtl\">١٧٥٢</span> م . و در سال <span class=\"hlight\" dir=\"rtl\">١٧٧٠</span> م . بر اثر بدبختی بوسیله ٔ سم ّ خودکشی کرد.<br /></font></div>'),
(281875, 'چاتلانقوش', '<span class=\"hlight\">چاتلانقوش .</span> (ترکی، اِ) حبةالخضراء. بَن . بَنسه . چتلانقوش . و رجوع به بَن و بَنسه شود.<br /></font></div>'),
(281876, 'چاتلجه', '<span class=\"hlight\">چاتلجه .</span> <font color=\"DarkGreen\"><b>[ ت َ ج َ ]</font></b> (اِخ ) نام شهری در ترکیه واقعدر <span class=\"hlight\" dir=\"rtl\">٤٣</span> هزارگزی مغرب استانبول دارای <span class=\"hlight\" dir=\"rtl\">٣١٤٠</span> تن سکنه .<br /></font></div>'),
(281877, 'چاتلمه', '<span class=\"hlight\">چاتلمه .</span> <font color=\"DarkGreen\"><b>[ ل َ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ) نوعی گلوله . گلوله ٔ دُم دُم .<br /></font></div>'),
(281878, 'چاتلی', '<span class=\"hlight\">چاتلی .</span> (اِخ ) نام یکی از مواضع سکنای طایفه ٔ یموت در گرگان واقع در پنجاه هزارگزی چکشلر و پنجاه هزارگزی شمال غربی گنبد قابوس .<br /></font></div>'),
(281879, 'چاتلیق', '<span class=\"hlight\">چاتلیق .</span> (ص، اِ) رجوع به جاثلیق شود.<br /></font></div>'),
(281880, 'چاتمه', '<span class=\"hlight\">چاتمه .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (ترکی، اِ) چند تفنگ را صلیبی بهم پیوسته در زمین نصب کردن . <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاتمه قراول </span> ؛ قراول مواظب چاتمه .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاتمه گذاشتن </span> ؛ انجام دادن عمل چاتمه .<br /></font></div>'),
(281881, 'چاتمه ای', '<span class=\"hlight\">چاتمه ای .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (ص نسبی ) چاتمه وار. وضعی از اوضاع که سر دو چیز را به یک دیگر تکیه دهند که هر یک پایه و قیم دیگری شود و هر دو بر پا توانند ماند.<br /></font></div>'),
(281882, 'چاتمه زدن', '<span class=\"hlight\">چاتمه زدن .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ زَ دَ ]</font></b> (مص مرکب ) چند تفنگ را به شکل چاتمه در محلی گذاشتن . از چند تفنگ تشکیل چاتمه دادن . چند قراول یا نگهبان در حال مراقبت از کسی یا جایی تفنگ های خود را بوضع چاتمه قرار دادن . <BR><font color=\"Blue\">◄</font> در خانه ٔ کسی ماندن و مزاحم شدن . <BR><font color=\"Blue\">◄</font> برای مطالبه ٔ چیزی یاانجام تقاضایی منتظر کسی ماندن و مزاحم آنکس شدن .<br /></font></div>'),
(281883, 'چاتو', '<span class=\"hlight\">چاتو.</span> (اِ) ریسمانی باشد که بدان دزدان را از حلق آویزند. (برهان ).<br /></font></div>'),
(281884, 'چاتیل', '<span class=\"hlight\">چاتیل .</span> (اِخ ) موضعی است در شمال اقلمیش از نواحی شرقی قره بغاز.<br /></font></div>'),
(281885, 'چاج', '<span class=\"hlight\">چاج .</span> (اِخ ) دهی از دهستان نهارجانات بخش حومه ٔ شهرستان بیرجند <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی جنوب خاوری بیرجند. دامنه معتدل با <span class=\"hlight\" dir=\"rtl\">٥٢١</span> تن سکنه، آب آن از قنات، محصول آنجا غلات و پنبه وزعفران و ابریشم، شغل اهالی زراعت و قالی بافی، راه آن مالرو است کلاته های نو، زنج، ابوطالب حسن یزدی، تاج کوه جزء این ده است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(281886, 'چاخار', '<span class=\"hlight\">چاخار.</span> (اِخ ) نام ایالتی در چین بمساحت <span class=\"hlight\" dir=\"rtl\">٢٧٩</span> هزار کیلومتر مربع دارای دو میلیون و چهل هزار نفوس . و کرسی آن (ون چوان ) است .<br /></font></div>'),
(281887, 'چاخان', '<span class=\"hlight\">چاخان .</span> (ترکی، ص ) متملق . چاپلوس . با زرنگی و زیرکی . حقه باز. لافی . لاف زن . شارلاتانی در گفتار.زبان بازی . آنکه به تندی و چابکی گوید در فریفتن تو آنچه در دل ندارد. خوش محاوره . زبان آور. خوش آمدگو.<br /></font></div>'),
(281888, 'چاخان بازی', '<span class=\"hlight\">چاخان بازی .</span> (حامص مرکب ) تملق گویی . حقه بازی . شارلاتانی . چرب زبانی و خوش آمدگویی . عمل اشخاص چاخان .<br /></font></div>'),
(281889, 'چاخان پاخان', '<span class=\"hlight\">چاخان پاخان .</span> (اِ مرکب، از اتباع ). سخنان دروغین و بیهوده .<br /></font></div>'),
(281890, 'چاخان کردن', '<span class=\"hlight\">چاخان کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) گول زدن . فریفتن . چاپلوسی کردن . بدروغ و ریا سخنی گفتن یا کسی را ستودن .<br /></font></div>'),
(281891, 'چاخانسر', '<span class=\"hlight\">چاخانسر.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) دهی جزء دهستان سیاهکلرود بخش رودسر شهرستان لاهیجان <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزارگزی جنوب خاوری رودسر و یک هزارگزی راه شوسه ٔ رودسر بشهسوار. جلگه، معتدل، مرطوب با <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن سکنه آب آن از نهر سیاهکلرود.محصول آنجا برنج و مرکبات، شغل اهالی زراعت است و راه شوسه فرعی و قهوه خانه ٔ سر راه شوسه و شش باب دکان در داخل آبادی دارد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(281892, 'چاخانچی', '<span class=\"hlight\">چاخانچی .</span> (ترکی، ص مرکب ) با دیگری چاخان کننده . کسی که عادت به چاخان کردن و خوش آمد گفتن دارد.<br /></font></div>'),
(281893, 'چاخانی', '<span class=\"hlight\">چاخانی .</span> (اِخ ) نام کوهی در اشکور واقع در ناحیه ٔ تنکابن به مازندران .<br /></font></div>'),
(281894, 'چاخرق', '<span class=\"hlight\">چاخرق .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِ) چاخروق . قسمی از پرندگان .<br /></font></div>'),
(281895, 'چاخروق', '<span class=\"hlight\">چاخروق .</span> (اِ) چاخرق . قسمی پرنده .<br /></font></div>'),
(281896, 'چاخرچمنی', '<span class=\"hlight\">چاخرچمنی .</span> <font color=\"DarkGreen\"><b>[ خ ِ چ َ م َ ]</font></b> (اِخ )دهی از دهستان ارشق بخش مرکزی شهرستان مشکین شهر <span class=\"hlight\" dir=\"rtl\">٤٢٠٠٠</span> گزی شمال مشکین شهر و <span class=\"hlight\" dir=\"rtl\">٨٠٠٠</span> گزی شوسه ٔ گرمی اردبیل . کوهستانی، معتدل . با <span class=\"hlight\" dir=\"rtl\">١٥٩</span> تن سکنه . آب آن از چشمه، محصول آن : غلات و حبوبات، شغل اهالی زراعت و گله داری و راه آن مالرو است . (فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(281897, 'چاخسوک', '<span class=\"hlight\">چاخسوک .</span> (اِ) رجوع به چاخشوک شود.<br /></font></div>'),
(281898, 'چاخشوک', '<span class=\"hlight\">چاخشوک .</span> (اِ) داس . (فرهنگ بیانکی ) . اوبهی این لغت را دامن معنی کرده ولی ظاهراً اشتباه است و معنی صحیح کلمه همان داس است که بغلط دامن خوانده و نوشته اند.<br /></font></div>'),
(281899, 'چاخلاماز', '<span class=\"hlight\">چاخلاماز.</span> (اِخ ) دهی از دهستان کاودول بخش مرکزی شهرستان مراغه واقع در <span class=\"hlight\" dir=\"rtl\">٥٨٠٠٠</span> گزی جنوب خاوری مراغه درمسیر ارابه رو میاندواب به شاهین دژ. جلگه، معتدل، مالاریائی با <span class=\"hlight\" dir=\"rtl\">٣٦٣</span> تن سکنه . آب آن از قوریچای و زرینه رود، محصول آنجا غلات و کشمش و بادام و چغندر و حبوبات، شغل اهالی زراعت، صنایع دستی پارچه و جاجیم بافی، راه آن مالرو است . (فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٥٣</span>).<br /></font></div>'),
(281900, 'چاخو', '<span class=\"hlight\">چاخو.</span> (اِخ ) قریه ای نزدیک بیجار گروس . (ناظم الاطباء).<br /></font></div>'),
(281901, 'چاخو', '<span class=\"hlight\">چاخو.</span> (نف مرکب ) چاه خو. چاه کن . مقنی .<br /></font></div>'),
(281902, 'چاخوره', '<span class=\"hlight\">چاخوره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (نف مرکب ) نقّاب، حفّار. ج، چاخورگان . رجوع به چاخو و چاخوئی شود.<br /></font></div>'),
(281903, 'چاخورگان', '<span class=\"hlight\">چاخورگان .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ) ج ِ چاخوره . رجوع به چاخوره شود <span class=\"hlight\">:</span> و چاخورگان را فرمان شد تا بیک شب حوالی خندق را چون غربال سوراخ کردند و از آب گذشتند بر روی آن خاک ریز... پنج نفر مرد مردانه مسلح بیرون آمده بر چاخورگان تاختند چاخورگان چون واقف شدند از میانه ٔ نقب بیرون آمده از زیر روی به بالا کردند (ظفرنامه ٔ شامی ).<br /></font></div>'),
(281904, 'چاخچور', '<span class=\"hlight\">چاخچور.</span> (اِ) چاقچور. نوعی جامه ٔ زنانه مخصوص پوشانیدن ساق پا که زنان هنگام بیرون رفتن از خانه می پوشیده اند. رجوع به چادر چاخچور شود.<br /></font></div>'),
(281905, 'چاد', '<span class=\"hlight\">چاد.</span> (اِخ ) دریاچه ٔ بزرگی است در افریقای مرکزی در سودان به وسعت <span class=\"hlight\" dir=\"rtl\">٢٧</span> هزار کیلومتر مربعکه حوضه ٔ آن یکی از مراکز عمده ٔ گله داری مرکز افریقاست . <BR><font color=\"Blue\">◄</font> بخش شمال افریقای شرقی فرانسه، دارای <span class=\"hlight\" dir=\"rtl\">١٢٤٨٠٠٠</span> کیلومتر مربع مساحت و <span class=\"hlight\" dir=\"rtl\">٩٧٣٠٠٠</span> تن سکنه . شهر عمده ٔ آن فرلامی است .<br /></font></div>'),
(281906, 'چادان', '<span class=\"hlight\">چادان .</span> (اِ مرکب ) چای دان . (ناظم الاطباء).<br /></font></div>'),
(281907, 'چادر', '<span class=\"hlight\">چادر.</span><font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ]</font></b> (اِ) خیمه . سایبان . بالاپوش زنان . ردا. (حاشیه ٔ برهان قاطع چ معین ). پارچه ای که زنان برای پوشانیدن چهره و دستها و سایر اعضا و البسه بر روی همه ٔ لباسها پوشند. جامه ٔ رویین زنان . جامه ٔ بی آستین زبرین زنان که تمام سر و تن و پای و دست را از نظرها مستور دارد. پارچه ای است عریض و طویل که زنهاسر میکنند. (فرهنگ نظام ). ردای زنان . بالاپوش . پرده . حجاب . و رجوع به حجاب شود <span class=\"hlight\">:</span> زن از چادر غافل ماند، گوشه ٔ چادر بگشاد... پاره ای خاک در چادر بست . (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٧٠</span>). در مثل میگویند: «حمام نرفتن بی بی از بی چادری است » یا «خانه نشستن بی بی از بی چادری است ». <BR><font color=\"Blue\">◄</font> روپوش . روبنده . حجاب . رجوع به حجاب شود. ترجمه ٔ وطاء و بدین معنی با لفظ در سرکشیدن و به چهره کشیدن و پوشیدن وبر کتف برافکندن و از پشت برکشیدن . (آنندراج ). <BR><font color=\"Blue\">◄</font> مطلق سرپوش . پوشش . مطلق پوشش . هر چیزی از پارچه و جز آن که جایی یا کسی یا چیزی را بپوشاند. <BR><font color=\"Blue\">◄</font> پارچه ٔ عریض و طویل که رختخواب در آن می بندند. (فرهنک نظام ). چادر شب . <BR><font color=\"Blue\">◄</font> لحاف . روپوش که هنگام خواب بر روی خود اندازند. لحاف ... هر جامه ای که بالای جامه ها باشد همچو چادر و مانند آن . (منتهی الارب ). ملحفة. چادر (منتهی الارب ) <span class=\"hlight\">:</span> <br />بخسبند و یک گوش بستر کنند<br />دگر بر تن خویش چادر کنند.<br /> <font color=\"Red\">فردوسی .</font><br />بخفت اندران سایه بوزرجمهر<br />یکی چادر اندر کشیده به چهر.<br /> <font color=\"Red\">فردوسی .</font><br />بگفت این و چادر بسر برکشید<br />تن آسانی و خواب را برگزید.<br /> <font color=\"Red\">فردوسی .</font><br />از سنگ بسی ساخته ام بستر و بالین <br />وز ابر بسی ساخته ام خیمه و چادر.<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <BR><font color=\"Blue\">◄</font> خیمه . خرگاه . شادروان . سایبان . صاحب آنندراج نویسد: «در ترکی به معنی خیمه و با لفظ زدن مستعمل است ». <BR><font color=\"Blue\">◄</font> سفره و سماط. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> خرقه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آبشار. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بالن . <BR><font color=\"Blue\">◄</font> کفن <span class=\"hlight\">:</span> <br />سرانجام با خاک باشیم جفت <br />دو رخ را به چادر بباید نهفت .<br /> <font color=\"Red\">فردوسی .</font><br />همه دشت از ایشان تن بی سر است <br />زمین بستر و خاکشان چادر است .<br /> <font color=\"Red\">فردوسی .</font><br />بر چشمه تختی و مردی بر اوی <br />بمرده به چادر نهان کرده روی .<br /> <font color=\"Red\">اسدی .</font><br />اتحمی ؛ نوعی از چادرهای یمن . اتحمیه ؛ نوعی از چادرهای یمن . تحمه ؛ چادرهایی که بر آن خطوط زرد باشد. ازار؛چادر و شلوار. لفاع ؛ چادر یا گلیم یا گستردنی ... جرده ؛ چادر سوده و کهنه . جنینة؛ نوعی از چادر ابریشمی است . جلباب ؛ پیراهن و چادر زنان و معجر یا چادری که زنان لباس خود را بدان از بالا بپوشند. خملة؛ چادر جامه ٔ خواب دار و جامه ٔ مخمل مانند چادر و جز آن . خمیلة؛ چادر مخمل خواب دار. رداء؛ چادر. مرداة؛ چادر. ریطة؛ چادر یک لخت یا هر جامه ٔ نرم و تنک که زنان بر سر اندازند. رائطة؛ چادر یک لخت که زنان بر سر افکنند. سیح ؛ نوعی از چادر. سند؛ نوعی از چادرها. سمط؛ چادر بی آستر که بر دوش اندازند یا چادر از پنبه . شرعبی ؛ نوعی از چادرها. صیدن ؛ چادر درشت بافت . صتیة؛ چادر و جامه ای است یمنی . طیلس ؛ چادر. طیلسان ؛ چادر. طرحة؛ چادر. عصب ؛ نوعی از چادر. عطاف ؛ چادر. عاطف ؛ چادر. معطف ؛ چادر. عبعب ؛ چادر باریک و نازک از پشم شتر. غدفلة؛ چادر فراخ . فوطة؛ چادر نگارین یا چادر خط دار. قرطاس ؛ چادر مصری . تحول الکساء؛ چیزی در چادر نهاد و بر پشت برداشت آن را. کرُ؛ چادر. لوط؛ چادر. معقد؛ نوعی از چادر. ملف ؛ چادر. ملاءة؛ چادر یک لخت . ریطة؛ چادر یک لخت . مریش ؛ چادر منقش . مئزر؛ چادر. مهاصری ؛ چادری است یمنی . نصیف ؛ چادر دو رنگ . تجواز؛ نوعی از چادر منقش . التفاع ؛ چادر درخود پیچیدن . (منتهی الارب ) <span class=\"hlight\">:</span> <br />پوپک دیدم بحوالی سرخس <br />بانگک بربرده به ابر اندرا<br />چادرکی دیدم رنگین بر او<br />رنگ بسی گونه بر آن چادرا.<br /> <font color=\"Red\">رودکی .</font><br />یک سو کنمش چادر یک سو نهمش موزه <br />این مرده اگر خیزد ورنه من و چلغوزه .<br /> <font color=\"Red\">رودکی .</font><br />بگفت این و بگشاد چادر ز روی <br />همه روی ماه و همه مشک موی .<br /> <font color=\"Red\">فردوسی .</font><br />ز کافورزیر اندرش بستری <br />کشیده ز دیبا بر او چادری .<br /> <font color=\"Red\">فردوسی .</font><br />چو پنهان شد آن چادر آبنوس <br />بگوش آمد از دور بانگ خروس .<br /> <font color=\"Red\">فردوسی .</font><br />چو پیدا شد آن چادر زرد رنگ <br />از او گشت گیتی چو پشت پلنگ .<br /><font color=\"Red\">فردوسی .</font><br />چو شب چادر قیرگون کرد نو<br />ز شهر و ز بازار برخاست غو.<br /> <font color=\"Red\">فردوسی .</font><br />چو خور چادر زرد بر سر کشید<br />بشد باختر چون گل شنبلید.<br /> <font color=\"Red\">فردوسی .</font><br />چو خورشید از آن چادر لاجورد<br />برآمد بپوشید دیبای زرد.<br /> <font color=\"Red\">فردوسی .</font><br />تو گفتی که جامی ز یاقوت زرد<br />نهادند بر چادر لاجورد.<br /> <font color=\"Red\">فردوسی .</font><br />دویاره یکی طوق با افسری <br />ز دیبای چین بافته چادری .<br /> <font color=\"Red\">فردوسی .</font><br />ز دیبا کشیده برو چادری <br />ز هرگوهری بر سرش افسری .<br /> <font color=\"Red\">فردوسی .</font><br />هامون گردد چو چادروشی سبز<br />گردون گردد چو مطرف خز ادکن .<br /> <font color=\"Red\">فرخی (دیوان چ دبیرسیاقی ص <span class=\"hlight\" dir=\"rtl\">٢٧١</span>).</font><br />سلاح یلی بازکردی و بستی <br />بسام یل و زال زر، دوک و چادر.<br /> <font color=\"Red\">فرخی .</font><br />تو گویی بباغ اندرون روز برف <br />صف ناژوان و صف عرعران <br />بسی خواهرانند در راه رز<br />سیه موزگان و سمن چادران <br />بپوشیده در زیر چادر همه <br />ستبرق ز بالای سر تا به ران .<br /> <font color=\"Red\">منوچهری .</font><br />چهل جنگی همه گرد دلاور<br />کشیده چون زنان در روی چادر.<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ص <span class=\"hlight\" dir=\"rtl\">٤٩١</span>).</font><br />پس آنگه چون زنان پوشیده چادر<br />به پیش ویس بانو شد سراسر.<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br />مر او را گفت رامین ای برادر<br />بپوش این راز ما را زیر چادر.<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br />بیارم ویسه را با کیش و چادر<br />پیاده چون سگان در پیش لشکر.<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br />ز خون رخ به غنجار بند و دخور<br />ز گرد اندر آورد چادر بسر.<br /> <font color=\"Red\">اسدی .</font><br />چوشیر ژیان جست از افراز تخت <br />گرفتش گلوبند و بفشارد سخت <br />بدرید چادرش و بفکند پست <br />دهانش بیاکند و دستش ببست .<br /> <font color=\"Red\">اسدی .</font><br />نهالی به زیرش غلیژن بدی <br />ز بر چادرش آب روشن بدی .<br /> <font color=\"Red\">اسدی .</font><br />فکرت ما زیر این چادر بماند<br />راز یزدانی برون زین چادر است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />گل سرخ نوکفته بر بار گویی <br />برون کرده حوری سر از سبز چادر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />تسبیح میکنندش پیوسته <br />در زیر این کبود و تنک چادر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />هر کسی را زیر این چادر درون <br />خاطر جویا به راهی دیگر است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />زیر این چادر نگه کن کز نبات <br />لشکری بسیارخوار و بیمر است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />مسبب چون بود پس هر کسی را<br />که وهمش گرد او گردد چو چادر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />زیر سخن است عقل پنهان <br />عقل است عروس و قول چادر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />یکی چادری جوی پهن و دراز<br />بیاویز چادر ز بالای گاز.<br /> <font color=\"Red\">ازرقی .</font><br />بر چادر کوه گازرآسا<br />از داغ سیه نشان برافکند.<br /> <font color=\"Red\">خاقانی .</font><br />گفتم چادر ز روی بازنگیری ؟<br />بکر نیی، شرم داشتن چه مجال است ؟<br />چادر بر سر کشیدتا بن دامن <br />یعنی بکرم من این چه لاف محال است ؟<br />از پس بکران غیب چادر فکرت <br />بفکن خاقانیا که بر تو حلال است .<br /> <font color=\"Red\">خاقانی .</font><br />صبح را تقدیر او از شیر چادر میدهد<br />شام را تقدیر او از قیر معجر میکند<br /> <font color=\"Red\">شهاب زرگر (از لباب الالباب ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٤</span> و <span class=\"hlight\" dir=\"rtl\">٥</span>).</font><br />زیر چادر مرد رسوا و عیان <br />سخت پیدا چون شتر بر نردبان .<br /> <font color=\"Red\">مولوی .</font><br />رفت جوحی چادر و روبند ساخت <br />در میان آن زنان شد ناشناخت .<br /> <font color=\"Red\">مولوی .</font><br />این غول روی بسته ٔ کوته نظر فریب <br />دل میبرد بغالیه اندوده چادری .<br /> <font color=\"Red\">سعدی (کلیات چ مصفا ص <span class=\"hlight\" dir=\"rtl\">٧٤١</span>).</font><br />بس قامت خوش که زیر چادر باشد<br />چون باز کنی مادر مادر باشد.<br /><font color=\"Red\">سعدی (گلستان ).</font><br /></font></div>'),
(281908, 'چادر آب', '<span class=\"hlight\">چادر آب .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ ]</font></b> (ترکیب اضافی، اِ مرکب ) آبشار. (آنندراج ).<br /></font></div>'),
(281909, 'چادر اجساد', '<span class=\"hlight\">چادر اجساد.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ اَ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از عناصراربعه (آب و باد و خاک و آتش ) است . (ناظم الاطباء).<br /></font></div>'),
(281910, 'چادر احرام', '<span class=\"hlight\">چادر احرام .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ اِ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه است از برف . (آنندراج ) <span class=\"hlight\">:</span> <br />از پشت کوه چادر احرام برکشد<br />بر کتف ابر چادر ترسا بر افکند.<br /> <font color=\"Red\">خاقانی .</font><br />کعبه ز آتش ساز چون بر فرق کوه <br />چادر احرامیان پوشیده اند.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(281911, 'چادر افراختن', '<span class=\"hlight\">چادر افراختن .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ اَ ت َ ]</font></b> (مص مرکب ) چادر زدن . چادر افراشتن . خیمه زدن . خیمه بپا کردن و رجوع به خیمه افراختن شود.<br /></font></div>'),
(281912, 'چادر اژدها', '<span class=\"hlight\">چادر اژدها.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِاَ دَ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه است از عناصر اربعه . (ناظم الاطباء).<br /></font></div>'),
(281913, 'چادر بسر', '<span class=\"hlight\">چادر بسر.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ب ِ س َ ]</font></b> (اِ مرکب ) کنایه است از زن . لچک بسر.<br /></font></div>'),
(281914, 'چادر به یک شاخ افکندن', '<span class=\"hlight\">چادر به یک شاخ افکندن .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ب ِ ی ِ اَ ک َ دَ ]</font></b> (مص مرکب ) به یک سو زدن چادر رعنائی و خودنمائی را. دور کردن چادر. (آنندراج ). رجوع به یک شاخ شود <span class=\"hlight\">:</span> <br />کشیده برقع از رخساره گستاخ <br />فکنده چادر از شوخی به یک شاخ .<br /> <font color=\"Red\">اشرف (از آنندراج ).</font><br />بر نخل هر شکوفه در این باغ لیلی است <br />کز خیرگی فکنده بیک شاخ چادرش .<br /><font color=\"Red\">صائب (از آنندراج ).</font><br /></font></div>'),
(281915, 'چادر ترسا', '<span class=\"hlight\">چادر ترسا.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ ت َ ]</font></b> (ترکیب اضافی، اِ مرکب ) وطا و جامه ای باشد زرد و کبود و درهم بافته . (برهان ). صاحب آنندراج نویسد: «ملاسروری گوید چادر ترسا، وِطای زرد و کبود» <span class=\"hlight\">:</span> <br />از پشت کوه چادر احرام برکشد<br />بر کتف ابر چادر ترسا برافکند.<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> کنایه ازشفق و روشنایی آفتاب . (برهان ). کنایه از سپیدی صبح و شفق آفتاب . (آنندراج ) <span class=\"hlight\">:</span> <br />صبح که رهبان این کبود کلیسا<br />بر سر گیتی کشید چادر ترسا.<br /><font color=\"Red\">وصال (از آنندراج ).</font><br /></font></div>'),
(281916, 'چادر خانه', '<span class=\"hlight\">چادر خانه .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) چادری که زنان در خانه بر سر کنند.<br /></font></div>'),
(281917, 'چادر خطدار', '<span class=\"hlight\">چادر خطدار.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ خ َ ]</font></b> (ترکیب وصفی، اِ مرکب ) چادر شطرنجی . چادر چارخانه . چادر راه راه . چادر مخطط: قَوْصَف، چادر خطدار مربع. (منتهی الارب ).<br /></font></div>'),
(281918, 'چادر خواب', '<span class=\"hlight\">چادر خواب .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ خوا <span class=\"hlight\" dir=\"rtl\">/</span>خا ]</font></b> (اِ مرکب ) پرده و حجاب خواب . (ناظم الاطباء).<br /></font></div>'),
(281919, 'چادر رختخواب', '<span class=\"hlight\">چادر رختخواب .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ رَ ت ِ خوا <span class=\"hlight\" dir=\"rtl\">/</span>خا ]</font></b> (ترکیب اضافی، اِ مرکب ) کرباسی که رختخواب در آن پیچند. (آنندراج ). چادرشب . رجوع به چادرشب شود.<br /></font></div>'),
(281920, 'چادر زدن', '<span class=\"hlight\">چادر زدن .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ زَ دَ ]</font></b> (مص مرکب ) خیمه زدن . چادر برپا کردن . خیمه افراشتن .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(281921, 'چادر سبز', '<span class=\"hlight\">چادر سبز.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ س َ ]</font></b> (ترکیب وصفی، اِ مرکب ) نوعی چادر. چادری برنگ سبز: طاق، ... چادر سبز. (منتهی الارب ). <BR><font color=\"Blue\">◄</font> کنایه است از حجاب شب <span class=\"hlight\">:</span> <br />صبح صادق پس کاذب چه کند بر تن دهر<br />چادر سبز درد تا زن رسوا بینند.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(281922, 'چادر سر', '<span class=\"hlight\">چادر سر.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ س َ ]</font></b> (ترکیب اضافی، اِ مرکب ) چادری که زنان بر سر افکنند.<br /></font></div>'),
(281923, 'چادر سرکردن', '<span class=\"hlight\">چادر سرکردن .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ س َ ک دَ ]</font></b> (مص مرکب ) چادر برسر افکندن . چادر برسر کردن . چادرپوشیدن .<br /></font></div>'),
(281924, 'چادر عبایی', '<span class=\"hlight\">چادر عبایی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ ع َ ]</font></b> (ترکیب وصفی، اِ مرکب ) در تربت حیدری، چادِر عَبائی .چادری که از پارچه ٔ ابریشمی سیاه رنگ بر سر کنند.<br /></font></div>'),
(281925, 'چادر لاجورد', '<span class=\"hlight\">چادر لاجورد.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ وَ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از آسمان است . (برهان ) <span class=\"hlight\">:</span> <br />چو روشن شد آن چادر لاجورد<br />جهان شد بکردار یاقوت زرد.<br /> <font color=\"Red\">فردوسی .</font><br />چو پنهان شدی چادر لاجورد<br />شدی کوه مانند یاقوت زرد.<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> سبزه زار ومرغزار را نیز گویند. (برهان ). رجوع به «چادر لاجوردی » شود.<br /></font></div>'),
(281926, 'چادر لاجوردی', '<span class=\"hlight\">چادر لاجوردی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ وَ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از آسمان . (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه ازشب . (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از سبزه زار. (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از چار عناصر. (انجمن آرا). <BR><font color=\"Blue\">◄</font> کنایه از چار ستاره ٔ نعشی که گرد قطب باشند. (انجمن آرا). رجوع به «چادر لاجورد» شود.<br /></font></div>'),
(281927, 'چادر نیلی', '<span class=\"hlight\">چادر نیلی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ ]</font></b> (ترکیب وصفی، اِ مرکب ) چادر نیلگون . چادر کحلی . <BR><font color=\"Blue\">◄</font> کنایه است از آسمان .<br /></font></div>'),
(281928, 'چادر پوشیدن', '<span class=\"hlight\">چادر پوشیدن .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ دَ ]</font></b> (مص مرکب ) چادر بسر افکندن . چادر بسر کردن . پوشیدن زن صورت و اندام خود رادر زیر چادر: اعتطاب ؛ چادر پوشیدن . (منتهی الارب ).<br /></font></div>'),
(281929, 'چادر پیه', '<span class=\"hlight\">چادر پیه .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ]</font></b> (اِ مرکب ) پیه رقیقی است چون پرده ای که شکمبه و امعاء دقیق یا معده و امعاء را پوشیده است و آن از فم معده آغاز کند و به معاء قولون منتهی گردد و آن چون آستر صفاق و ابره ٔ معده است . (بحر الجواهر). ثرب ؛ پیه تنک بالای شکنبه و روده . (منتهی الارب ). خلم ؛ پیه روده های گوسپند. (منتهی الارب ). عثل ؛ چادر پیه بالای روده و شکنبه ٔ گوسپند. (منتهی الارب ). هورب ؛ پیه تنک بالای شکنبه وروده . (منتهی الارب ).<br /></font></div>'),
(281930, 'چادر پیچه', '<span class=\"hlight\">چادر پیچه .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ مرکب ) چادر، حجاب زنان و پیچه، نقاب آنان . پیچه . رجوع به پیچه شود.<br /></font></div>'),
(281931, 'چادر چاخچور', '<span class=\"hlight\">چادر چاخچور.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ]</font></b> (اِ مرکب ) رجوع به چادر چاقچور شود.<br /></font></div>'),
(281932, 'چادر چاقچور', '<span class=\"hlight\">چادر چاقچور.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ]</font></b>(اِ مرکب ) جامه ٔ زنان آنگاه که از خانه بیرون میرفتند مرکب از شلواری فراخ و دوپاچه بهم پیوسته که از کمر تا نوک انگشتان پای را می پوشید (چاقچور) و چادری چون عبایی فراخ که از فرق سر تا پای ایشان میرسید.<br /></font></div>'),
(281933, 'چادر چاقچور کردن', '<span class=\"hlight\">چادر چاقچور کردن .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ک َ دَ ]</font></b> (مص مرکب ) ملبس به چادر و چاقچور شدن . چادر و چاقچور پوشیدن . <BR><font color=\"Blue\">◄</font> کنایه از آماده شدن زن برای خارج شدن از خانه .<br /></font></div>'),
(281934, 'چادر چاقچوری', '<span class=\"hlight\">چادر چاقچوری .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ]</font></b> (ص نسبی ) زنی که چادر و چاقچور پوشیده است . <BR><font color=\"Blue\">◄</font> کنایه است از جنس زن .<br /></font></div>'),
(281935, 'چادر چرخی', '<span class=\"hlight\">چادر چرخی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ چ َ ]</font></b> (اِ مرکب ) چادرنماز. نوعی چادر مخصوص که زنان در خانه بر سر کنند. رجوع به چادرنماز شود.<br /></font></div>'),
(281936, 'چادر کافوری', '<span class=\"hlight\">چادر کافوری .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از سفیدی صبح صادق باشد. (برهان ). کنایه از سپیدی صبح و روشنایی آفتاب . (آنندراج ).<br /></font></div>'),
(281937, 'چادر کبود', '<span class=\"hlight\">چادر کبود.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِک َ ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از آسمان . (آنندراج ). چادر نیلگون .<br /></font></div>'),
(281938, 'چادر کحلی', '<span class=\"hlight\">چادر کحلی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ ک ]</font></b> (ترکیب وصفی، اِ مرکب ) کنایه از آسمان . (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از شب . (برهان ) (آنندراج ).<br /></font></div>'),
(281939, 'چادر گلریز', '<span class=\"hlight\">چادر گلریز.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ گ ُ ]</font></b> (ترکیب وصفی، اِ مرکب ) آسمان با ستارگان . (آنندراج ).<br /></font></div>'),
(281940, 'چادر یزدی', '<span class=\"hlight\">چادر یزدی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ ی َ ]</font></b> (ترکیب وصفی، اِ مرکب ) نوعی از چادر سپید مخصوص زنان یزد که در وقت بیرون آمدن از خانه بسر کشند. (آنندراج ). حجاب سفیدی مخصوص زنان یزد و کرمان که در وقت بیرون شدن از خانه بسر کشند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نوعی از قماش خوب و لطیف که در یزد بافند. (آنندراج ) <span class=\"hlight\">:</span> <br />همقد شجرش بنخل کوفه <br />در چادر یزدی از شکوفه .<br /><font color=\"Red\">تأثیر (از آنندراج ).</font><br /></font></div>'),
(281941, 'چادر یک لخت', '<span class=\"hlight\">چادر یک لخت .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِی ِ ل َ ]</font></b> (ترکیب وصفی، اِ مرکب ) چادر یک شقه، چادر یک تخته . ملاَءة. (منتهی الارب ). ریطة. (منتهی الارب ).<br /></font></div>'),
(281942, 'چادرتکانیدن', '<span class=\"hlight\">چادرتکانیدن .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ت َ دَ ]</font></b> (مص مرکب ) خیمه برپا کردن . از اهل زبان بتحقیق پیوسته . (آنندراج ). رجوع به چادر تکیدن شود.<br /></font></div>'),
(281943, 'چادرتکیدن', '<span class=\"hlight\">چادرتکیدن .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ت َ دَ ]</font></b> (مص مرکب ) خیمه برپا کردن . از اهل زبان بتحقیق پیوسته . (آنندراج ). چادر تکانیدن .<br /></font></div>'),
(281944, 'چادردران کردن', '<span class=\"hlight\">چادردران کردن .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ دِ ک َ دَ ]</font></b> (مص مرکب ) زنی بانوی مهمان را از مراجعت به خانه ٔ خود سخت مانع شدن از راه دوستی و مهر و محبت .<br /></font></div>'),
(281945, 'چادردرانی', '<span class=\"hlight\">چادردرانی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ دِ ]</font></b> (حامص مرکب ) ممانعت لجوجانه ٔ زن بانوی مهمان را از بازگشت بخانه ٔ خود.<br /></font></div>'),
(281946, 'چادردوز', '<span class=\"hlight\">چادردوز.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ]</font></b> (نف مرکب ) خیمه دوز. کسی که شغل وی دوختن انواع چادر و خیمه باشد. خیام .<br /></font></div>'),
(281947, 'چادردوزی', '<span class=\"hlight\">چادردوزی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ]</font></b> (حامص مرکب ) خیمه دوزی . دوختن انواع خیمه و چادر. خیام .<br /></font></div>'),
(281948, 'چادرسوز', '<span class=\"hlight\">چادرسوز.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ]</font></b> (نف مرکب ) پرده سوز. آنکه پرده ٔ نقاشی را بسوزد <span class=\"hlight\">:</span> <br />چو نقش حیله بر چادر نشانی <br />بدان نقاش چادرسوز مانی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(281949, 'چادرسیاه', '<span class=\"hlight\">چادرسیاه .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ]</font></b> (اِ مرکب ) روپوش سیاه . حجاب سیاه : طَلْس ؛ چادر سیاه . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> خیمه ٔ سیاه رنگ . سیاه چادر. چادر بلوچی . (تربت حیدری خراسان ). خانه ٔ سیاه . (تربت حیدری ).<br /></font></div>'),
(281950, 'چادرشب', '<span class=\"hlight\">چادرشب .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ش َ ]</font></b> (اِ مرکب ) جامه ای که در آن رختخواب و بستر پیچند. (ناظم الاطباء). چادر رختخواب ؛ چارشب . چارچب <span class=\"hlight\">:</span> <br />راحت میخوارگان از پرتو ماهست و بس <br />بسته در چادرشب مهتاب رختخواب را.<br /><font color=\"Red\">تأثیر (از آنندراج ).</font><br /></font></div>'),
(281951, 'چادرفگندی', '<span class=\"hlight\">چادرفگندی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ف ِ گ َ ]</font></b> (اِ مرکب ) قسمی از خیمه . (ناظم الاطباء).<br /></font></div>'),
(281952, 'چادرقلندری', '<span class=\"hlight\">چادرقلندری .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ رِ ق َ ل َ دَ ]</font></b> (ترکیب وصفی، اِ مرکب ) نوعی از خیمه . (آنندراج ). نوعی از خیمه ٔ یک دیرکی شبیه به کلاه قلندران . (ناظم الاطباء).<br /></font></div>'),
(281953, 'چادرنشین', '<span class=\"hlight\">چادرنشین .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ن ِ ]</font></b> (نف مرکب ) صحرانشین . بادیه نشین . اهل وَبرَ. و بری . بَدَوی . مقابل شهرنشین و دِه نشین .مقابل تخته قاپو. <BR><font color=\"Blue\">◄</font> کنایه از طوایف و قبایلی که زندگی ایلی دارند و همه ٔ فصول سال را در بیابان و زیر چادر بسر میبرند و غالباً بکار گله داری و گوسفندچرانی مشغولند و در طلب آبشخور اغنام و احشام خود از نقطه ای بنقطه ای میروند و ییلاق قشلاق میکنند.<br /></font></div>'),
(281954, 'چادرنشینی', '<span class=\"hlight\">چادرنشینی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ن ِ ]</font></b> (حامص مرکب ) صحرانشینی . بادیه نشینی . بداوت . زندگی ایلیاتی .<br /></font></div>'),
(281955, 'چادرنماز', '<span class=\"hlight\">چادرنماز.</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ن َ ]</font></b> (اِ مرکب ) پوشش ِ عبا مانند بدون آستین که سیاه رنگ نباشد و زنان بر سر افکنند به هنگام نماز خواندن و جز آن . جامه ای که از سر تا پا همه ٔ بدن را فراگیرد و زنان در خانه در وقت نماز آن را به سر کشند. (ناظم الاطباء).<br /></font></div>'),
(281956, 'چادرنمازی', '<span class=\"hlight\">چادرنمازی .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ ن َ ]</font></b> (ص نسبی ) منسوب به چادر نماز. زنی که چادرنماز بسر گذارد. زن که چادرنماز حجاب اوست . پارچه ٔ چادرنمازی . پارچه ای مناسب برای چادرنماز.<br /></font></div>'),
(281957, 'چادروا', '<span class=\"hlight\">چادروا.</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِ) به لغت مردم اصفهان : صبر زرد. (ناظم الاطباء).<br /></font></div>'),
(281958, 'چادرچب', '<span class=\"hlight\">چادرچب .</span> <font color=\"DarkGreen\"><b>[ دَ<span class=\"hlight\" dir=\"rtl\">/</span> دُ چ َ ]</font></b> (اِ مرکب ) چادرشب . رجوع به چادرشب شود.<br /></font></div>'),
(281959, 'چادرچه', '<span class=\"hlight\">چادرچه .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ مرکب ) در گناباد خراسان، چادرنماز. روسری .<br /></font></div>'),
(281960, 'چادرگرفته', '<span class=\"hlight\">چادرگرفته .</span> <font color=\"DarkGreen\"><b>[ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دُگ ِ رِ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (ن مف مرکب ) آنکه چادر پوشیده باشد. (آنندراج ) <span class=\"hlight\">:</span> <br />باغ از شکوفه لیلی چادرگرفته ای است <br />از لاله کوه عاشق ِ در خون طپیده ای است .<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> پرده دار و نهفته . (ناظم الاطباء).<br /></font></div>'),
(281961, 'چاده', '<span class=\"hlight\">چاده .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b>(اِخ ) دهی از دهستان پسکوه بخش قاین شهرستان بیرجند. واقع در <span class=\"hlight\" dir=\"rtl\">٣٣</span>هزارگزی جنوب باختری قاین . دامنه، معتدل، <span class=\"hlight\" dir=\"rtl\">٥٧</span> تن سکنه . شیعه، فارسی . آب آن از قنات . محصول آنجا غلات، زعفران، تریاک . شغل اهالی زراعت و مالداری راه آن مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(281962, 'چار', '<span class=\"hlight\">چار.</span> (اِ)(اِخ ) تزار. تیسار. تزار : چار روسیه (پادشاه روس ).<br /></font></div>'),
(281963, 'چار', '<span class=\"hlight\">چار.</span> (اِ)(ص ) سزاوار و لایق . (ناظم الاطباء).<br /></font></div>'),
(281964, 'چار', '<span class=\"hlight\">چار.</span> (اِ) به زبان علمی اهل هند به معنی جاسوس باشد. (برهان ). مأخوذ از سانسکریت «چاره » .<br /></font></div>'),
(281965, 'چار', '<span class=\"hlight\">چار.</span> (اِ) چاره . گزیر. علاج . بُد.... مخفف چاره . (برهان ). رجوع به «چاره » شود <span class=\"hlight\">:</span> <br />ز دشمن به دینار و یا زینهار<br />برستن توان و آز را نیست چار.<br /> <font color=\"Red\">ابوشکور بلخی .</font><br />چه چار است واین کار را راه چیست ؟<br />که برکرد و ناکرد باید گریست .<br /> <font color=\"Red\">فردوسی .</font><br />خردمند از خرد جوید همه چار<br />بدست چاره بگذارد همه کار.<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br />دوان آید ز هامون سوی دیوار<br />به آوردنش آنگاهی کنم چار.<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br />بلبل دستان سرا چاره همی جوید ز من <br />چاره زآن جوید که او را جست باید نیز چار.<br /> <font color=\"Red\">؟ (از لغت فرس اسدی ).</font><br />همی ندانم چاره ٔ فراق وین نه عجب <br />که هیچ عاقل، خودکرده را نداند چار.<br /> <font color=\"Red\">قطران .</font><br />چو من از پس دین دویدم بباید<br />دویدن پس من به ناچار و چارش .<br /> <font color=\"Red\">ناصرخسرو.</font><br />از این بند و زندان بناچار و چار<br />همان کش درآورد بیرون برد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />اگر بازگردی ز راه ستور<br />شود بید تو عود ناچار و چار.<br /> <font color=\"Red\">ناصرخسرو.</font><br />تیزخشمی زودخشنودی قناعت پیشه ای <br />داروی هر دردمندی چار هر بیچاره ای .<br /> <font color=\"Red\">سوزنی .</font><br />دست برآور ز میان چارجوی <br />وین غم دل را دل غمخوار جوی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(281966, 'چار', '<span class=\"hlight\">چار.</span> (عدد، ص، اِ) مخفف «چهار» که به عربی «اربعة» گویند. (برهان ). رجوع به «چهار» شود <span class=\"hlight\">:</span> <br />دقیقی چار خصلت برگزیده ست <br />به گیتی در ز خوبی ها و زشتی .<br /> <font color=\"Red\">دقیقی .</font><br />جهان را ببخشید بر چار بهر<br />یکایک همه نامزد کرد شهر.<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت روشندل پارسی <br />که بگذشت سال از برش چارسی .<br /> <font color=\"Red\">فردوسی .</font><br />خدنگی گزین کرد پیکان چو آب <br />نهاده بر او چار پر عقاب .<br /> <font color=\"Red\">فردوسی .</font><br />همان باژ کشور که بد چاربار<br />ز دینار رومی هزاران هزار.<br /> <font color=\"Red\">فردوسی .</font><br />همی داشت خود در دل این شهریار<br />چنین تا برآمد بر این روز چار.<br /> <font color=\"Red\">فردوسی .</font><br />به گرد جهان چار سالار من <br />که هستند بر جان نگهدار من .<br /> <font color=\"Red\">فردوسی .</font><br />همیشه به پیش سپهدار پیل <br />طلایه پراکنده بر چار میل .<br /> <font color=\"Red\">فردوسی .</font><br />بفرمودتا خانگی مرغ چار<br />پرستنده آرد بر شهریار.<br /> <font color=\"Red\">فردوسی .</font><br />ببرید هر چارانگشت خویش <br />بریده همی داشت در مشت خویش .<br /> <font color=\"Red\">فردوسی .</font><br />کمان را بمالید جنگی به چنگ <br />بزد بر کمر چار تیر خدنگ .<br /> <font color=\"Red\">فردوسی .</font><br />کنیزک بدش چار چون آفتاب <br />کسی روی ایشان ندیده بخواب .<br /> <font color=\"Red\">فردوسی .</font><br />از آن آهن لعلگون تیغ چار<br />هم از روهنی و بلا لک هزار.<br /><font color=\"Red\">اسدی (گرشاسبنامه ص <span class=\"hlight\" dir=\"rtl\">٢٠٠</span>).</font><br />هر چار چار حد بنای پیمبری <br />هر چار چار عنصر ارواح اولیا.<br /> <font color=\"Red\">خاقانی .</font><br />اگر شد چار مولای عزیزت <br />بشارت میدهم بر چار چیزت .<br /> <font color=\"Red\">نظامی .</font><br />چار کس را داد مردی یک درم <br />هر یکی افتاده از شهری بهم .<br /> <font color=\"Red\">مولوی .</font><br />گویند چاره اش به زر و سیم و صبر کن <br />بیچاره را نمی دهد این هر سه چار دست .<br /><font color=\"Red\">سلمان .</font><br /></font></div>'),
(281967, 'چار', '<span class=\"hlight\">چار.</span> (اِ) کوره ای که در آن آجر پزند. (از مهذب الاسماء). داشی را گویند که در آن خشت و آهک و کاسه و کوزه و امثال آن پزند. (برهان ).<br /></font></div>'),
(281968, 'چار باغ امین آباد علیا', '<span class=\"hlight\">چار باغ امین آباد علیا.</span> <font color=\"DarkGreen\"><b>[ غ ِ اَ دِ ع ُ ]</font></b> (اِخ ) از بناهای عبداﷲخان امین الدوله پسر مرحوم حاجی محمد حسینخان صدر اصفهانی است در اصفهان . ابتداء میشود از پل خواجو و منتهی میشود به دروازه ٔ تخت فولاد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣١</span>).<br /></font></div>'),
(281969, 'چار تکبیر زدن', '<span class=\"hlight\">چار تکبیر زدن .</span> <font color=\"DarkGreen\"><b>[ ت َ زَ دَ ]</font></b> (مص مرکب ) کنایه از نماز جنازه هم هست که بعد از آن میت را وداع کنند. (برهان ). نماز جنازه کردن زیرا که در نمازجنازه چهار تکبیر مقرر است . (آنندراج ) <span class=\"hlight\">:</span> <br />هر دم از ماتم برگی نتوان آه کشید<br />چار تکبیر بر این نخل خزان دیده زدیم .<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> کنایه از ترک محلی کردن و تبرای مطلق از ماسوی نمودن باشد. (برهان ). کنایه از ترک نمودن همه چیز را.(آنندراج ). یکباره ترک چیزی یا ترک کسی گفتن <span class=\"hlight\">:</span> <br />سه شراب حقیقتی بخوریم <br />چارتکبیر بر مجاز زنیم .<br /> <font color=\"Red\">سنایی .</font><br />اتابک ایلد گزشاه جهانگیر<br />که زد بر هفت کشور چار تکبیر.<br /> <font color=\"Red\">نظامی .</font><br />من همان دم که وضو ساختم از چشمه ٔ عشق <br />چار تکبیر زدم یکسره بر هرچه که هست .<br /> <font color=\"Red\">حافظ.</font><br />کبریای حرم حسن تو چون روی نمود<br />چار تکبیر زدیم از همه بیزار شدیم .<br /><font color=\"Red\">(از قرة العیون ملا محسن فیض ).</font><br /></font></div>'),
(281970, 'چار تکبیر کردن', '<span class=\"hlight\">چار تکبیر کردن .</span> <font color=\"DarkGreen\"><b>[ ت َ ک َ دَ ]</font></b>(مص مرکب ) نماز جنازه کردن . (آنندراج ) <span class=\"hlight\">:</span> <br />هر که در میدان عشق نیکوان گامی نهاد<br />چارتکبیری کند بر ذات او لیل و نهار.<br /> <font color=\"Red\">سنائی .</font><br />قبله ٔ روی ترا هر که شبی برد نماز<br />چار تکبیر، دگر روز برین پنج کند.<br /> <font color=\"Red\">انوری .</font><br />چار تکبیر بر آن حضرت کرد و عنان عزیمت بر صوب غور و غزنین گردانید. (بدایع الازمان ص <span class=\"hlight\" dir=\"rtl\">١٠٩</span>). و رجوع به چارتکبیر زدن شود. <BR><font color=\"Blue\">◄</font> کنایه از ترک همه چیز یا همه کس گفتن . از همه کس یا از همه چیز گذشتن . پشت پا به دنیا و ما فیها زدن . کنایه از ترک کردن همه چیز را. (آنندراج ) <span class=\"hlight\">:</span> <br />رغبتش رغم کان و دریا را<br />چار تکبیر کرده و سه طلاق .<br /><font color=\"Red\">انوری (از آنندراج ).</font><br /></font></div>'),
(281971, 'چار تکبیر گفتن', '<span class=\"hlight\">چار تکبیر گفتن .</span> <font color=\"DarkGreen\"><b>[ ت َ گ ُ ت َ ]</font></b> (مص مرکب ) نماز جنازه کردن . (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از ترک کردن همه چیز را. (آنندراج ). و رجوع به چار تکبیر زدن و چار تکبیر کردن شود.<br /></font></div>'),
(281972, 'چار روسا', '<span class=\"hlight\">چار روسا.</span> (اِخ ) پنج فرسخ میانه ٔ شمال و مشرق لنده است . (فارسنامه ٔ ناصری ).<br /></font></div>'),
(281973, 'چار رگ', '<span class=\"hlight\">چاررگ .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ مرکب ) رجوع به چهار رگ شود.<br /></font></div>'),
(281974, 'چار زبر', '<span class=\"hlight\">چار زبر.</span> <font color=\"DarkGreen\"><b>[ زَ ب َ ]</font></b> (اِخ ) رجوع به چهار زبر شود.<br /></font></div>'),
(281975, 'چار زیر', '<span class=\"hlight\">چار زیر.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام محلی کنار راه کرمانشاه و قصر شیرین میان شاه پسند و حسن آباد.<br /></font></div>'),
(281976, 'چار سالگی', '<span class=\"hlight\">چار سالگی .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (حامص مرکب ) حالت و چگونگی چار ساله . در فاصله ٔ چهار سال . (ناظم الاطباء).<br /></font></div>'),
(281977, 'چار ستون بدن', '<span class=\"hlight\">چار ستون بدن .</span> <font color=\"DarkGreen\"><b>[ س ُ ن ِ ب َ دَ ]</font></b> (اِ مرکب ) دو دست و دو پای . چار دست و پای .<br /></font></div>'),
(281978, 'چار سر', '<span class=\"hlight\">چار سر.</span><font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ مرکب ) (اصطلاح قمار) اصطلاحی در بازی آس . اصطلاح بازی ورق . چارصورت از قبیل چار شاه و چار بی بی و چار سرباز و چار آس، چار ورق ده خال . چار لکات .<br /></font></div>'),
(281979, 'چار سرآوردن', '<span class=\"hlight\">چار سرآوردن .</span> <font color=\"DarkGreen\"><b>[س َ وَ دَ ]</font></b> (مص مرکب ) (اصطلاح قمار) در اصطلاح بازی ورق چار صورت آوردن . چار شاه یا چار بی بی یا چار سرباز آوردن . چار آس آوردن . چار ورق از یک صورت آوردن .<br /></font></div>'),
(281980, 'چار سرشت', '<span class=\"hlight\">چار سرشت .</span> <font color=\"DarkGreen\"><b>[ س ِ رِ ]</font></b> (اِ مرکب ) چارطبع. طبایع اربعه . امزجه ٔاربعه . حرارت و برودت و رطوبت و یبوست <span class=\"hlight\">:</span> <br />نقش این هفت لوح چار سرشت <br />ز ابتدا جز یکی قلم ننبشت .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(281981, 'چار سلطان', '<span class=\"hlight\">چار سلطان .</span> <font color=\"DarkGreen\"><b>[ س ُ ]</font></b> (اِ مرکب )ظاهراً در این شعر منظور چاردرویش است <span class=\"hlight\">:</span> <br />بدان چار سلطان درویش نام <br />شده چارتکبیر دولت تمام .<br /> <font color=\"Red\">نظامی .</font><br />و رجوع به چار درویش شود.<br /></font></div>'),
(281982, 'چار و ناچار', '<span class=\"hlight\">چار و ناچار.</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (ق مرکب، اتباع ) خواه و ناخواه . طوعاً ام کرهاً <span class=\"hlight\">:</span> <br />چاره آن شد که چاروناچارش <br />مهربانی بود سزاوارش .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(281983, 'چار و هفت', '<span class=\"hlight\">چار و هفت .</span> <font color=\"DarkGreen\"><b>[ رُ هََ ]</font></b> (ترکیب عطفی، اِ مرکب ) عناصر اربعه و سیارات سبعه . (آنندراج ).<br /></font></div>'),
(281984, 'چار و چدر', '<span class=\"hlight\">چار و چدر.</span> <font color=\"DarkGreen\"><b>[ رُ چ َ دَ ]</font></b> (اِ مرکب، اتباع ) تدبیر. (برهان ) (آنندراج ). چاره . (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br />او چار به کارمن چو درکرد<br />چاروچدر از کسی نخواهم .<br /> <font color=\"Red\">قریعالدهر (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> علاج . (برهان ) (آنندراج ).<br /></font></div>'),
(281985, 'چار و چنگول', '<span class=\"hlight\">چار و چنگول .</span> <font color=\"DarkGreen\"><b>[ رُ چ َ ]</font></b> (اِ مرکب، اتباع ) دست ها و پاها خشک شده در حالی که جمع و خم شده باشد. با دستها و پاهای بسوی تنه گرد آمده چون مبتلا بفالجی یا از سرمازدگی مرده ای و غیره . و رجوع به چارچنگولی شود.<br /></font></div>'),
(281986, 'چارآخر', '<span class=\"hlight\">چارآخر.</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (اِ مرکب ) کنایه از چهار عنصر است که خاک و باد و آب و آتش باشد. (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِخ ) چهار ستاره از بنات النعش باشد که آنها را نعش خوانند. (برهان ) (آنندراج ). چهارستاره ٔ دب اکبر. (ناظم الاطباء).<br /></font></div>'),
(281987, 'چارآخشیج', '<span class=\"hlight\">چارآخشیج .</span> (اِ مرکب ) چارعنصر (آب و باد و خاک و آتش ). اربع عناصر است و آخشیج بمعنی یک عنصر آید. (آنندراج ). عناصر اربعه . (ناظم الاطباء).<br /></font></div>'),
(281988, 'چارآس', '<span class=\"hlight\">چارآس .</span> (اِ مرکب ) چهار تک خال . چهار ورق قمار در بازی «آس » که بر هر یک شکل خال نقش شده باشد. چهار ورق برنده در بازی «آس » که بر چهار شاه و چهار بی بی و چهار سرباز و چهار لکات مقدم است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چار شاهش به چار آس خوردن </span> ؛ بقویتر از خودی مصادف شدن . بحیله و چاره ای رساتر از چاره ٔ خود دچار گشتن . رجوع به آس شود.<br /></font></div>'),
(281989, 'چارآسیاب', '<span class=\"hlight\">چارآسیاب .</span> (اِخ ) از توابع کوهکیلویه است این بلوک طولش از لیراوی الی رودخانه ٔ خرسان تخمیناً چهل فرسخ واز باشت تا جایزان بیست و شش فرسنگ میباشد. دو رودخانه ٔ عظیم از کوه کوهکیلویه از طرف مغرب کردستان و از جانب مشرق خیرآباد و دو رودخانه ٔ کوچک یکی از ممسنی و دیگری از ماهورات که اهالی آنجا آن را کمبل مینامند ملحق به این رودخانه میشود در این بلوک یازده حمام و پانزده مسجد میباشد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span>ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>).<br /></font></div>'),
(281990, 'چارآینه', '<span class=\"hlight\">چارآینه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) یکی از پوشش های جنگجویان قدیم . نوعی از اسلحه و این عبارت از چهار پاره آهن پهن باشد که در زره بر سینه پیوند کنند. (آنندراج ). نوعی از لباس جنگ که چهار تخت از آهن ساخته و در مخمل گرفته گرد پشت و سینه کشند. (ناظم الاطباء) <span class=\"hlight\">:</span> <br />ز بس میدان کین از حمله ات شد تنگ بر اعدا<br />نگنجد عکس در آئینه چارآئینه داران را.<br /> <font color=\"Red\">واله هروی (از آنندراج ).</font><br />آماده ٔ جنگ است شب و روز بعاشق <br />چارآینه آئینه ٔ آن ترک جفاجوست .<br /><font color=\"Red\">رایج (از آنندراج ).</font><br /></font></div>'),
(281991, 'چارابرو', '<span class=\"hlight\">چارابرو.</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (ص مرکب ) نوخط که پشت لب او بحد موی ابرو برآمده است . آنکه خط پشت لب او دمیده است . شاهدی که خط بر پشت لب دارد. کنایه از معشوق نوخط. (آنندراج ). امردی که تازه بروت وی سبز شده باشد. (ناظم الاطباء) <span class=\"hlight\">:</span> <br />عشق افزون می شود چون حسن میگردد زیاد<br />تا تو چارابرو شدی چشمم ز شوقت گشت چار.<br /> <font color=\"Red\">غنی (از آنندراج ).</font><br />بلاست عاشقی نوخطان چارابرو<br />ز چارموجه ٔ دریا نجات ممکن نیست .<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br />رجوع به چارابرو شدن شود. <BR><font color=\"Blue\">◄</font> یک قسم از قلندران که موهای ریش و بروت و ابرو را می تراشند. (ناظم الاطباء).<br /></font></div>'),
(281992, 'چارابرو شدن', '<span class=\"hlight\">چارابرو شدن .</span> <font color=\"DarkGreen\"><b>[ اَ ش ُ دَ ]</font></b> (مص مرکب ) دمیدن موی بر پشت لب . رجوع به چار ابرو شود.<br /></font></div>'),
(281993, 'چارات', '<span class=\"hlight\">چارات .</span> (اِخ ) ده کوچکی است از دهستان جراحی بخش شادگان شهرستان خرمشهر <span class=\"hlight\" dir=\"rtl\">٨١</span> هزارگزی شمال خاوری شادگان و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی باختر راه اتومبیل رو اهواز به خلف آباد با <span class=\"hlight\" dir=\"rtl\">١٠</span> تن سکنه . ساکنین از طایقه ٔ بنی خالد می باشند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(281994, 'چاراجساد', '<span class=\"hlight\">چاراجساد.</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (اِ مرکب ) چارعنصر. عناصر اربعه (آب و خاک و باد و آتش ).<br /></font></div>'),
(281995, 'چارادویه', '<span class=\"hlight\">چارادویه .</span> <font color=\"DarkGreen\"><b>[ اَدْ ی َ ]</font></b> (اِ مرکب ) چاردارو، مخلوطی از چند داروی مختلف (چهار یا بیشتر) که دراغذیه بکار میبرند. در تداول عوام به مخلوطی از میخک، جوز بویا، فلفل و دارچین یا زنجبیل اطلاق میشود.<br /></font></div>'),
(281996, 'چارارکان', '<span class=\"hlight\">چارارکان .</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (اِ مرکب ) چهارعنصر. چارآخشیج . ارکان اربعه یعنی آب و خاک و باد و آتش . رجوع به چهار ارکان شود <span class=\"hlight\">:</span> <br />از این چارارکان که داری بنام <br />ببین کاین هنرها جز او را کدام .<br /> <font color=\"Red\">اسدی .</font><br />گرد چارارکان او بین هفت طوق و شش جهت <br />چارارکانش ز یاران چار اقران آمده .<br /> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">٣٧٢</span>).</font><br />ز چارارکان برگرد و پنج ارکان جوی <br />که هست قائد این پنج پنج نوبت لا.<br /> <font color=\"Red\">خاقانی .</font><br />و هم این رکن چون مقوم روح <br />چار ارکان جسم را معیار.<br /> <font color=\"Red\">خاقانی .</font><br />از آن منسوج کاورا دور داده ست <br />به چارارکان کمربندی فتاده ست .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(281997, 'چاراسب', '<span class=\"hlight\">چاراسب .</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (اِ مرکب ) دسته ٔ چهاراسبی . (ناظم الاطباء). چاراسبه .<br /></font></div>'),
(281998, 'چاراسباب', '<span class=\"hlight\">چاراسباب .</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (اِ مرکب ) علل اربعه یعنی علت مادی و علت فاعلی و علت صوری و علت غائی . (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> چهارقوه یعنی قوه ٔ جاذبه و ماسکه و هاضمه و دافعه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> چهارعنصر. (ناظم الاطباء).<br /></font></div>'),
(281999, 'چاراسبه', '<span class=\"hlight\">چاراسبه .</span> <font color=\"DarkGreen\"><b>[ اَ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (ص مرکب ) با چهار اسب :کالسکه ٔ چاراسبه . کالسکه ای که چهار اسب آن را میکشند. <BR><font color=\"Blue\">◄</font> کنایه است از بسرعت . بشتابی تمام .<br /></font></div>'),
(282000, 'چاراستار', '<span class=\"hlight\">چاراستار.</span> <font color=\"DarkGreen\"><b>[ اُ ]</font></b> (اِ مرکب ) کنایه از چارعنصر است . (برهان ) (آنندراج ).<br /></font></div>'),
(282001, 'چاراصل', '<span class=\"hlight\">چاراصل .</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (اِ مرکب ) عناصر اربعه (آب و خاک و باد و آتش ) <span class=\"hlight\">:</span> <br />یک دو شد از سه حرفش چاراصل و پنج شعبه <br />شش روز و هفت اختر نه قصر و هشت منظر.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(282002, 'چارامین', '<span class=\"hlight\">چارامین .</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (اِخ ) خلفای اربعه . خلفای راشدین . رجوع بفرهنگ ضیاء شود.<br /></font></div>'),
(282003, 'چاران', '<span class=\"hlight\">چاران .</span> (اِخ ) دهی جزء دهستان ارنگه بخش کرج شهرستان تهران <span class=\"hlight\" dir=\"rtl\">٢٧</span> هزارگزی شمال خاور کرج و <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی خاوری راه شوسه ٔ کرج بچالوس، کوهستانی و سردسیر با <span class=\"hlight\" dir=\"rtl\">٦٩٨</span> تن سکنه . آب آن از چشمه سار، محصول آنجا غلات، باغات میوه، لبنیات، شغل اهالی زراعت و گاوداری و کرباس بافی، راه آن ماشین رو است . مزرعه ٔ چمن زار و مرتع پنج سار جزء این ده است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282004, 'چاراویماق', '<span class=\"hlight\">چاراویماق .</span> <font color=\"DarkGreen\"><b>[ اُ ]</font></b> (اِخ ) از بلوکات ولایت هشترود دارای <span class=\"hlight\" dir=\"rtl\">٢٠٦</span> قریه و <span class=\"hlight\" dir=\"rtl\">٤٠</span> فرسخ مساحت آن است . مرکز آن سریک حد شمالی بلوک هشترود شرقی محال اوچ تپه جنوبی ولایت افشار و غربی گرمرود میباشد. (جغرافیای سیاسی کیهان ).<br /></font></div>'),
(282005, 'چاراژدها', '<span class=\"hlight\">چاراژدها.</span> <font color=\"DarkGreen\"><b>[ اَ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِ مرکب ) چارعنصر. چارارکان . چارآخشیج . عناصر اربعه باشد. (برهان ). کنایه از عناصر اربعه باشد و آن را چاراستاد و چارآخر نیز گویند. (آنندراج ) <span class=\"hlight\">:</span> <br />آن آدمی که زبده ٔارکانش می نهند<br />پیوسته در کشاکش این چار اژدهاست .<br /><font color=\"Red\">ظهیر فاریابی (از آنندراج ).</font><br /></font></div>'),
(282006, 'چارایستی', '<span class=\"hlight\">چارایستی .</span> (ص مرکب ) مؤلف آنندراج در شرح این ترکیب گوید: «چارصدی . طغرا در مشابهات گوید: فقره و بهادران یاسمین با قصباتیان سه برگه بچارایستی شگفتگی رسیدند. از غوامض سخن » و چارصدی و چهارصدی را نیز شرح نکرده است، و در مأخذ دیگر یافته نشد.<br /></font></div>'),
(282007, 'چاربازار', '<span class=\"hlight\">چاربازار.</span> (اِ مرکب ) بازارهای چهارگانه ٔ متقاطع.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاربازار تهران </span> ؛ عبارت است از چهار بازار که یکی لبافی است و دیگری کرجی دوزی و سومی سراجی و چهارمی نعلچیگری و چاربازار مسطور منتهی میشود بچارسویی که فاصله ٔ آن تا چهارسو بزرگ معروف طهران زیاده از صد قدم نیست . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاربازار قیصریه ٔ اصفهان </span> ؛ از اسواق معتبره ٔ این شهر و از بناهای شاه عباس اول و نادر بازاری است که به این استحکام و خوبی و وسعت و ارتفاع ساخته شده باشد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>).<br /></font></div>'),
(282008, 'چارباغ', '<span class=\"hlight\">چارباغ .</span> (اِخ ) دهکده ای است در سر ولایت نیشابور. آب آن از چشمه و قنات، هوایش گرم سکنه ٔ آن بیست و دو خانوار است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤١</span>).<br /></font></div>'),
(282009, 'چارباغ', '<span class=\"hlight\">چارباغ .</span> (اِخ ) از مزارع درب جوقای کاشان است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>).<br /></font></div>'),
(282010, 'چارباغ', '<span class=\"hlight\">چارباغ .</span> (اِخ ) قریه ای است از قرای هرات در هشت فرسخی این شهر واقع و مابین شمال و مشرق هرات میباشد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢</span>).<br /></font></div>'),
(282011, 'چارباغ', '<span class=\"hlight\">چارباغ .</span> (اِخ ) قریه ای است از قرای لواسان . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٢</span>).<br /></font></div>'),
(282012, 'چارباغ', '<span class=\"hlight\">چارباغ .</span> (اِخ ) قریه ای است از توابع بلوک درب قاضی شهر نیشابور در پنج فرسخی بلده در میان دره واقع، زراعت آن از آب رودخانه خوسفرود مشروب میشود. هوای این قریه در زمستان و تابستان معتدل سکنه ٔ آن از متفرقه و بومی چهار خانوار. (مرآت البلدان <span class=\"hlight\" dir=\"rtl\">٤</span>ص <span class=\"hlight\" dir=\"rtl\">٤٢</span>).<br /></font></div>'),
(282013, 'چارباغ', '<span class=\"hlight\">چارباغ .</span> (اِخ ) و در حضرت دهلی نام باغی بنا کرده ٔ نواب جملة الملک اعتمادالدوله بهادر دستور الاعظم هندوستان . (آنندراج ). نام باغی در حوالی دهلی . (ناظم الاطباء) <span class=\"hlight\">:</span> <br />نسیم آسا به گرد سر بگردم چارباغش را<br />بهر باغی که بنشیند دل من آشیان سازم .<br /><font color=\"Red\">صائب (از آنندراج ).</font><br /></font></div>'),
(282014, 'چارباغ', '<span class=\"hlight\">چارباغ .</span> (اِخ ) قریه ای است از قرای اردستان و مسافت و فاصله ٔ آن تا قصبه ٔ اردستان چهار فرسخ است . حاصل این قریه جو و گندم و روناس میباشد. زراعت آن از آب قنات مشروب میشود و تقریباًبیست خانوار سکنه دارد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤١</span>).<br /></font></div>'),
(282015, 'چارباغ', '<span class=\"hlight\">چارباغ .</span> (اِخ ) اسم مزرعه ای است در دروازه دولت کاشان حوالی خیابان واز آب شاه مشروب میشود. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>).<br /></font></div>'),
(282016, 'چارباغ', '<span class=\"hlight\">چارباغ .</span> (اِ مرکب ) باغهای چهارگانه در کنار هم که با خیابانها از هم جدا شوند یا در پیرامون عمارتی باشند. <BR><font color=\"Blue\">◄</font> دو رشته خیابان موازی یکدیگر که در دو طرف دارای درختکاری بوده و در وسط بوسیله ٔ یک رشته پیاده رو یا گردشگاه از هم جدا باشند. <BR><font color=\"Blue\">◄</font> کوشک و قصر. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> از الحان موسیقی . آهنگ مخصوصی در یکی از دستگاههای موسیقی قدیم ایران . و رجوع به «آهنگ » در همین لغت نامه شود.<br /></font></div>'),
(282017, 'چارباغ ابراهیم سلطان', '<span class=\"hlight\">چارباغ ابراهیم سلطان .</span> <font color=\"DarkGreen\"><b>[ غ ِ اِ س ُ ]</font></b> (اِخ ) از بناهای ابراهیم سلطان گورکانی است در حوالی بلخ در بیرون شهر. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤</span>).<br /></font></div>'),
(282018, 'چارباغ اصفهان', '<span class=\"hlight\">چارباغ اصفهان .</span> <font color=\"DarkGreen\"><b>[ غ ِاِ ف َ ]</font></b> (اِخ ) در سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٠٠٦</span> هَ . ق . که شاه عباس اول قصد کرد پایتخت را از قزوین به اصفهان قرار دهد از دروازه ٔ باغ نقش جهان که موسوم به درب دولت کرده بودتا کنار زاینده رود خیابانی احداث نمود و چارباغی درهر دو طرف خیابان طرح شد و قطعه ای در تاریخ بنای چارباغ بنظم درآورده اند که صورت آن از قرار ذیل است :<br />عجب چارباغی است عشرت فزا<br />گرش ثانی خلد گویند شاید.<br />چو تاریخ آن دل طلب کرد گفتم <br />نهالش بکام دل شه برآید.<br />مؤلف گوید اهل اصفهان الاَّن که چارباغ گویند مقصودشان همان خیابان است نه باغات حوالی و وضع خیابان چنان است که از اول الی آخر چهار ردیف چنارغرس شده و در این زمان آن چنارها به درجه ای عظمت بهم رسانیده که مطرح انظار و معروف امصار است . در وسط آب نما و در طرفین سردرهای متعدد است متوازی که هر یک سر در باغی است و فیمابین هر دو سر در حوضی و بعضی باغها هنوز مشجر و برخی بی درخت یا کم درخت است و الان بجای اشجار زراعت میکنند در خیابان درختهای گل سرخ و غیره بسیار غرس کرده بودند که در این عصر معدودی از این درخت ها دیده میشود وسط این چارباغ سر در مدرسه ٔ چارباغ است از بناهای سلاطین صفویه که از ابنیه ٔ بزرگ بسیار مستحکم و با صفای ایران بلکه عالم محسوب میشود نهر آبی به عظمت رودخانه از وسط مدرسه میگذرد نزهت این چارباغ خاصه در فصل بهار بواسطه ٔ کثرت گل و ازهار و نغمات طیور و لطافت هوا و حسن موقع به درجه ای است که از حیز وصف بیرون است و یکی از شعرای اصفهان راست <span class=\"hlight\">:</span> <br />شنیده ای که ارم روضه ای است بس خرم <br />به چارباغ صفاهان شباهتی دارد.<br />در فصل گردش و تفرج اغلب از روزها اهل اصفهان فوج فوج در این خیابان و مدرسه ٔمزبوره به تفرج میگذرانند. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>). نام باغی در صفاهان . (آنندراج ). باغ سلطنتی معروفی دراصفهان از بناهای شاه عباس اول . (ناظم الاطباء).<br /></font></div>'),
(282019, 'چارباغ امیر مزید ارغون', '<span class=\"hlight\">چارباغ امیر مزید ارغون .</span> <font color=\"DarkGreen\"><b>[ غ ِ اَ م َ اَ ]</font></b>(اِخ ) در ظاهر بلخ است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>).<br /></font></div>'),
(282020, 'چارباغ طهران', '<span class=\"hlight\">چارباغ طهران .</span> <font color=\"DarkGreen\"><b>[ غ ِ طِ ]</font></b> (اِخ ) این چهار باغ در محلی بوده که حالا ارگ سلطنتی و عمارات دیوانی است و بعضی درختهای چنار کهن که الاَّن در عمارات مبارکات است دلیل است که سابقاً اینجا باغ و آبادی بوده و بنای چارباغ مسطور را شاه عباس ماضی نموده و چنارهای کهن که حالا به چنار عباسی معروف است یحتمل به حکم شاه عباس غرس شده باشد والا مورخین دانند که عباس بن علی بن ابیطالب علیه السلام به ایران نیامده یعنی از کربلا به این طرف توجه نفرموده است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٥١٩</span>).<br /></font></div>'),
(282021, 'چارباغ طوقچی', '<span class=\"hlight\">چارباغ طوقچی .</span> <font color=\"DarkGreen\"><b>[ غ ِ طُ ]</font></b> (اِخ ) در بیرون دروازه ٔ طوقچی اصفهان خیابانی است معروف به چارباغ که نادراً درخت در این خیابان دیده میشود در وسط خیابان حوضی است و در یکطرف خیابان محاذی این حوض سر در باغ معروف بباغ قوشخانه است که از چند گاه قبل الی الاَّن حکام دارالسطنه ٔ اصفهان هر وقت از جانب سنی الجوانب اقدس همایون شاهنشاهی بخلعتی نایل و سرافراز میشوند آن خلعت را با تشریفات معموله در باغ قوشخانه زیب پیکراعتبار خود میسازند در وسط باغ قوشخانه عمارتی عالی ساخته شده است . چارباغ طوقچی و باغ قوشخانه از بناهای شاه عباس ثانی است ... (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣١</span>).<br /></font></div>'),
(282022, 'چارباغ مشهد', '<span class=\"hlight\">چارباغ مشهد.</span> <font color=\"DarkGreen\"><b>[ غ ِ م َ هََ ]</font></b> (اِخ ) در شهر مشهد مقدس است از بناهای اولاد امیرتیمور گورکان و همیشه مسکن سلاطین و حکام و امرای بزرگ بوده در سنه ٔ <span class=\"hlight\" dir=\"rtl\">٨٦١</span> هَ . ق . صبح روز سه شنبه بیست وپنجم ربیع الثانی میرزا ابوالقاسم بابر گورکانی بن بایسنقربن میرزا شاهرخ در چارباغ مشهد وفات نمود... در سنه ٔ نهصد و چهل محمد حسین میرزا پسر سلطان حسین میرزای بایقرای گورکان الشهیر بخاقان که بر پدر یاغی شده بود و فراراً بعراق و آذربایجان رفته بود جمعی ازمتجنده را با خود همراه ساخته بحسب ظاهر بقصد دیدن پدر و استعفا از جرایم گذشته و در باطن بخیال تصرف مملکت و دفع پدر به مشهد مقدس رسید از طرف سلطان حسین میرزای بایقرا امیرمبارزالدین محمد ولی بیک و امیر باباعلی با دو هزار سوار از هرات رسیده در چارباغ مشهد جنگ سختی در داده محمد حسین میرزا را فراراً و مقهوراً بسمت جرجان دوانیدند. در سال <span class=\"hlight\" dir=\"rtl\">١٠٠٩</span> هَ . ق . که بمقتضای نذر شرعی، شاه عباس اول پیاده از اصفهان به مشهد مقدس رفت در چارباغ مشهد منزل نمود به این معنی که بعد از زیارت مرقد مطهر و چند شب و روز اعتکاف در زیر آن قبه ٔ گردون مطاف و تقدیم شرایط طاعت و عبادت به چارباغ مشهد که سرای شاهی بود منزل گزین شد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤</span>). و اکنون در مشهد از چهار باغ مذکور جز محله ای بدین نام آثاری باقی نمانده است .<br /></font></div>'),
(282023, 'چارباغ میرزا شاهرخ', '<span class=\"hlight\">چارباغ میرزا شاهرخ .</span> <font color=\"DarkGreen\"><b>[ غ ِ رُ ]</font></b>(اِخ ) این چارباغ در بیرون شهر سمرقند است بعد از فوت امیر تیمور گورکانی در اُترار در شب چهارشنبه ٔ هفدهم شعبان سنه ٔ هشتصد و هفت که اختلاف کلی فیمابین اولاد امیرتیمور پیدا شد عیال امیرتیمور سرای ملک خانم و تومان آغا با سایر خواتین و شاه زادگان صغار برای تعزیه و فاتحه ٔ مضجع امیر تیمور به سمرقند آمدند ارغون شاه و خواجه یوسف آنها را بسمرقند راه نداده چندی در بیرون شهر در چارباغ میرزا شاهرخ ساکن و متوقف بودند و تا ورود امیرزاده خلیل سلطان که شانزدهم ماه رمضان همانسال باشد ایشان همانطور در بیرون شهر در چارباغ مزبور بسر میبردند. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٤</span>).<br /></font></div>'),
(282024, 'چارباغ هرات', '<span class=\"hlight\">چارباغ هرات .</span> <font color=\"DarkGreen\"><b>[ غ ِ هََ ]</font></b> (اِخ ) این چارباغ غالباً منزلگاه سلاطین بوده . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٥</span>).<br /></font></div>'),
(282025, 'چارباغ گروس', '<span class=\"hlight\">چارباغ گروس .</span> <font color=\"DarkGreen\"><b>[ غ ِ گ َ ]</font></b> (اِخ ) باغی است در سمت جنوب قصبه ٔ بیجار واقع و بواسطه ٔ خیابان های طویل عریض منقسم به چهار قسمت شده و بهمین جهت موسوم به این اسم شده ... در وسط باغ عمارتی عالی بنا کرده اند... این عمارت و باغ را مرحوم لطفعلی خان حاکم گروس جد ششمی جناب حسنعلی خان وزیر فواید که در اواخر سلطنت شاه سلیمان و در تمام مدت پادشاهی شاه سلطان حسین صفوی حکومت گروس را داشته در سنه ٔ هزار و صد و چهار هجری بنا کرده است و چون در امتداد زمان و انقلابات رو بخرابی نهاده بود مرحوم جنت جایگاه نایب السطنه عباس میرزا طاب اﷲ ثراه هنگام عبوراز گروس و اقامت دو روزه در بیجار و حوالی آن به محمد صادق خان مرحوم والد جناب حسنعلی خان که آن زمان حاکم آنجا بوده امر به تعمیر آن فرمودند و مبلغی هم ازبرای مصارف و مخارج تعمیر آن به محمد صادق خان دادندو مرحوم مشارالیه با کمال سلیقه در مرمت و توسعه ٔ عمارت و باغ مزبور کوشیده ازاره های تالارها را مرمر کرده و استاد محمد رضای حجار مشهور اصفهانی آنها را حجاری و منبت نموده و کتیبه ای هم که اشعار بسیار خوب دارد بخط میرزارضای خوشنویس معروف در مرمرهای ازاره ترقیم یافته که شعر آخری آن که ماده ٔ تاریخ تعمیر آنجاست و مطابق با سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٢٤٤</span> هَ . ق . میباشد این است :<br />کلک هجران بهر تاریخش بزد جامی و گفت <br />دایماً شاداب باد از مقدمت این لاله زار.<br />و ایهامی در این شعر است و آن در لفظ«بزد جامی » است یعنی معادل عدد جامی را منها کنند باقی ماده ٔ تاریخ است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٣٣</span>).<br /></font></div>'),
(282026, 'چاربالش', '<span class=\"hlight\">چاربالش .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِ مرکب ) مسند و وساده ای که پادشاهان و صدور و اکابر بر آن نشینند و بر آن تکیه کنند. (ناظم الاطباء). مسندی را گویند که پادشاهان و صدور و اکابر برآن نشینند. (برهان ). مسند ملوک و اکابر از این جهت که ظاهراً سابق تکیه ٔ کلانی که حالا بر پشت میدارند مرسوم نبود بلکه رسم آن بود که دو تکیه بر یمین و یسار. میگذاشتند یا آنکه یکی بر پشت و یکی پیش سینه و دو بر یمین و یسار. پس حقیقت چاربالش همان چارتکیه باشد که به مجاز معنی مسند مذکور شهرت گرفته . (آنندراج ) <span class=\"hlight\">:</span> <br />از گوشه ٔ چاربالش تو<br />اقبال بسالیان نجنبد.<br /> <font color=\"Red\">خاقانی .</font><br />به تیر ناوکی از شست آه یاوگیان <br />که چاربالش سلطان درد بیک پرتاب .<br /> <font color=\"Red\">خاقانی .</font><br />چار دیوار عزلتی که تراست <br />بهتر از چاربالش جم دان .<br /> <font color=\"Red\">خاقانی .</font><br />نهم چاربالش در ایوان عزلت <br />زنم چند نوبت چو میر مطاعی .<br /> <font color=\"Red\">خاقانی .</font><br />بهر آگین چاربالش اوست <br />هر پری کاین کبوتر افشانده ست .<br /> <font color=\"Red\">خاقانی .</font><br />چاربالش نهاده چون جمشید<br />پنج نوبت رسانده بر خورشید.<br /> <font color=\"Red\">نظامی (هفت پیکر).</font><br />گفت از اول که پنج نوبت شاه <br />باد بالای چاربالش ماه .<br /> <font color=\"Red\">نظامی (هفت پیکر).</font><br />سر آنگاه بر چاربالش نهیم <br />کزین گنبد چاربالش رهیم .<br /><font color=\"Red\">نظامی (شرفنامه ).</font><br />گر نیازت را پذیرد شمس تبریزی به لطف <br />بعد از این بر عرش نه تو چاربالش بر نیاز.<br /> <font color=\"Red\">مولوی .</font><br />چشم و چراغ جمع رسل هادی سبل <br />سلطان چاربالش ایوان اصفیا.<br /> <font color=\"Red\">(منسوب به حافظ).</font><br />عصمت به چاربالش غفلت چه خفته ای <br />آهنگ راه کن که رفیقان روان شدند.<br /> <font color=\"Red\">عصمت بخاری .</font><br /> <BR><font color=\"Blue\">◄</font> کنایه از دنیا باشد. (برهان ). کنایه از دنیاست به اعتبار چهار گنبد. (آنندراج ) <span class=\"hlight\">:</span> <br />چو در چاربالش ندیدم درنگ <br />نشستم در این چاردیوار تنگ .<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> کنایه از عناصر اربعه . (برهان ). و رجوع به چاربالشت و چهاربالش شود.<br /></font></div>'),
(282027, 'چاربالش ارکان', '<span class=\"hlight\">چاربالش ارکان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ش ِ اَ ]</font></b> (ترکیب اضافی، اِ مرکب ) طبایع اربعه . (آنندراج ):<br />واثق مشو بعمر که درخواب غفلت است <br />آن کس که چاربالش ارکانش متکاست .<br /> <font color=\"Red\">ظهیر فاریابی (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> حرارت و برودت و رطوبت و یبوست . (ناظم الاطباء).<br /></font></div>'),
(282028, 'چاربالش نشین', '<span class=\"hlight\">چاربالش نشین .</span> <font color=\"DarkGreen\"><b>[ ل ِ ن ِ ]</font></b> (نف مرکب ) مسندنشین . تخت نشین . کسی که بر مسند یا تخت نشیند یا تکیه زند <span class=\"hlight\">:</span> <br />چاربالش نشین عزلت را<br />پنج نوبت زن دو عالم دان .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(282029, 'چاربالش نه', '<span class=\"hlight\">چاربالش نه .</span> <font color=\"DarkGreen\"><b>[ ل ِ ن ِه ْ ]</font></b> (نف مرکب ) آن که چاربالش نهد <span class=\"hlight\">:</span> <br />پنج نوبت زن شریعت پاک <br />چاربالش نه ولایت خاک .<br /> <font color=\"Red\">نظامی (هفت پیکر).</font><br />رجوع به چاربالش شود<br /></font></div>'),
(282030, 'چاربالشت', '<span class=\"hlight\">چاربالشت .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِ مرکب ) مسند سلاطین . (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> دنیا. (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> عناصر اربعه . (برهان ). و رجوع به چاربالش و چهاربالش و چهار بالشت شود.<br /></font></div>'),
(282031, 'چاربامک', '<span class=\"hlight\">چاربامک .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِ مرکب ) رجوع به چهار بامک شود.<br /></font></div>'),
(282032, 'چاربانگ', '<span class=\"hlight\">چاربانگ .</span> (ص مرکب ) زود. چالاک . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> محسوس . (ناظم الاطباء).<br /></font></div>'),
(282033, 'چاربر', '<span class=\"hlight\">چاربر.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ص مرکب ) مربع. ذواربعة اضلاع . چارضلعی . (فرهنگستان ).<br /></font></div>'),
(282034, 'چاربرج', '<span class=\"hlight\">چاربرج .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) دو قلعه میباشد در بجنورد که از دو چشمه مشروب میگردد و زراعت این دو قلعه دیم و از حیثیت هوا ییلاق و سکنه ٔ آن پنجاه خانوار است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282035, 'چاربرج', '<span class=\"hlight\">چاربرج .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) قریه ای است در ناحیه ٔ حیاط داود و دشتستان دو فرسنگی بیشتر میانه ٔ شمال و شرق بندر ریگ است . (فارسنامه ).<br /></font></div>'),
(282036, 'چاربرج', '<span class=\"hlight\">چاربرج .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) قریه ای است در چهارفرسخی شهر مشهد مقدس از میان ولایت حول و حوش شهر.سکنه ٔ آن بیست وچهار خانوار و از ایل تیموری . مدار شرب زراعتش بر آب قنات میباشد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(282037, 'چاربرج', '<span class=\"hlight\">چاربرج .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) قریه ای است از شبانکاره ٔ دشتستان و کلیه ٔ بلوکی که این قریه جزء آن است گرمسیر و در مغرب شیراز بمسافت سی و هشت فرسخ واقع و حاصل این بلوک غله و خرما، شکار صحرایش آهو و قلیلی دراج، آبش از باران، آبادی دهکده هایش خیلی بتفاوت چنانکه دهکده دارد که دارای دویست خانوار است تا ده خانوار. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282038, 'چاربرج', '<span class=\"hlight\">چاربرج .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) از قرای حومه ٔ شهر مشهد مقدس و در سمت راست جاده ٔ چناران است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282039, 'چاربرج', '<span class=\"hlight\">چاربرج .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) اسم قریه ای است واقع در بلوک خشت و کمارج و این بلوک در مغرب شیراز بمسافت بیست و هفت فرسخ اهلش سلاح ورز، حاصلش غله و خرما و پنبه و تنباکو و مرکبات . شکار جلگه ٔ آن خوک و دراج آبش از چشمه و رودخانه . قریه ٔ خشت تقریباً هشتصد خانوار سکنه دارد و سایر قرای این بلوک را از بیست خانه الی دویست خانه است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282040, 'چاربرج', '<span class=\"hlight\">چاربرج .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) اسم قریه ای است از طبس که قدیم النسق و بلاسکنه میباشد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282041, 'چاربرج', '<span class=\"hlight\">چاربرج .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) در بلوک ساتلمش مراغه دو قریه میباشد که هر دو به چاربرج موسوم است این دو قریه وصل بیکدیگرند و اراضی آنها از آب جغتو مشروب میشود. هر قریه چهل پنجاه خانوار دارد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282042, 'چاربرج', '<span class=\"hlight\">چاربرج .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) قلعه ای است در دهنه ٔ کوه صغلوک، سکنه ٔ آن از ایل ویران لو و رعیت شادلو میباشند که در جمع بجنورد مالیات و خانواری خود را میدهند... این قلعه از قلاع قدیمه و سکنه ٔ آن از طائفه اکراد میباشد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282043, 'چاربرج', '<span class=\"hlight\">چاربرج .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) اسم عمارت حکومتی بندر بوشهر و آن عمارتی است که در چهار ضلع آن چهار برج ساخته و بهمین مناسبت به این اسم موسوم گردیده است . شیخ نصرخان از طایفه ٔ آل مذکور که سمت مصاهرت مرحوم حسنعلی میرزای فرمانفرما ولد خاقان خلدآشیان فتحعلی شاه طاب ثراه را داشته و هنوز از خانواده ٔ او در بندر بوشهر هستند این عمارت را در عهد خاقان مغفور مبرور بنا نموده است و بعد خرابی بهمرسانیده در عهد ناصرالدین شاه سنگ بستی در کنار مرداب که غاوی مینامندساخته شده و مخارج بسیاری کرده اند و دهنه ٔ چاربرج گردیده . در زمان حکومت مرحوم مؤیدالدوله طهماسب میرزا ولد مرحوم محمد علی میرزا بالاخانه ای رو به غاوی و دوبری شهر بنا نموده اند که در حقیقت یک ضلع یعنی یک برج از این چهار برج محسوب میشود و تقریباً منزل شخصی حاکم بندر بوشهر همان بالا خانه است : در تاریخ فارس تألیف میرزا جعفرخان خورموجی در ذکر بندر بوشهر مسطور است، «که در اواخر دولت نادری شیخ ناصرخان ابومهیری که از اعراب نجد و در جهازات نادرشاهی ناخدایی با اعتبار بود شهر را بانی و صاحب اختیار آمد چون سه سمت بحر و یک طرف متصل براست سمت خشکی را حصنی حصین و بروجی رصین برافراشت » ممکن است بنای چاربرج را نیزهمین شیخ ناصرخان کرده باشد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282044, 'چاربرج آباد', '<span class=\"hlight\">چاربرج آباد.</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) از قنوات قدیمه ٔ قم بوده و حالا خراب است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282045, 'چاربرد', '<span class=\"hlight\">چاربرد.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) نام شهری است که چاربردی شارح شافیه منسوب بدان است کذا سمع من الاوستاد العلامه شیخ محمد خضرشیرازی . (آنندراج ). جاربَرد. رجوع به جاربرد شود.<br /></font></div>'),
(282046, 'چاربردی', '<span class=\"hlight\">چاربردی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ص نسبی ) منسوب به چاربرد. رجوع به جاربردی شود. <BR><font color=\"Blue\">◄</font> (اِخ ) نام شارح کتاب شافیه در علم صرف . (ناظم الاطباء).<br /></font></div>'),
(282047, 'چاربرگ', '<span class=\"hlight\">چاربرگ .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِ مرکب ) چاربرگ مختلف در بازی آس . چهار ورق مختلف بازی، (تک خال و شاه و بی بی و سرباز).<br /></font></div>'),
(282048, 'چاربرگ', '<span class=\"hlight\">چاربرگ .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِ مرکب ) نام گلی است . (آنندراج ). <BR><font color=\"Blue\">◄</font> لاله ٔ کوهی . (آنندراج ).<br /></font></div>'),
(282049, 'چاربرگه', '<span class=\"hlight\">چاربرگه .</span> <font color=\"DarkGreen\"><b>[ ب َ گ َ <span class=\"hlight\" dir=\"rtl\">/</span> گ ِ ]</font></b> (اِ مرکب ) نام گیاهی است . (آنندراج ).<br /></font></div>'),
(282050, 'چاربرگی', '<span class=\"hlight\">چاربرگی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (ص نسبی مرکب ) اصطلاح قمار. آنکه در بازی آس چهار برگ مختلف در دست دارد.<br /></font></div>'),
(282051, 'چاربری', '<span class=\"hlight\">چاربری .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) شاخه ای از ایل بختیاری منسوب به طایفه ٔ «آسترکی » که شعبه ای از هفت لنگ بختیاری است . (جغرافی سیاسی کیهان ).<br /></font></div>'),
(282052, 'چاربسیط', '<span class=\"hlight\">چاربسیط.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِ مرکب ) ظاهراً بمعنی چارعنصر است . (آنندراج ).<br /></font></div>'),
(282053, 'چاربلاغ', '<span class=\"hlight\">چاربلاغ .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) صنیعالدوله آرد: قریه ای است از محال ایچرود زنجان ملکی جناب عمیدالملک هوایش ییلاق زراعت آن هم دیمی و هم آبی، یک رشته قنات دارد که خراب است و چهار چشمه که زراعت و صیفی این قریه را مشروب میسازد.سکنه ٔ آن پانزده خانوار است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282054, 'چاربند', '<span class=\"hlight\">چاربند.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِ مرکب ) کنایه از دنیا و عالم باشد. (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از عناصر اربعه میباشد. (آنندراج ) <span class=\"hlight\">:</span> <br />برون جست از این گنبد چاربند<br />فرس راند بر هفت چرخ بلند.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> چهار مفصل که دو دست و دو پای را به تن پیوندد. مفصل دو دست و دو پا که به تنه پیوندند. پیوند گاه چهارگانه ٔ تنه به دو دست و دو پا. مجموع مفاصل دو دست و دو پا که به تنه پیوندند. مفصل دو پای از طرف زیرین و مفصل دو دست هم از بالا. مجموع پیوندگاه دوپا و دو دست به تن . چارپیوند گاه دو دست و دو پا به تنه . <BR><font color=\"Blue\">◄</font> ریسمان یا طنابی که سوار کار را بر اسب بندند. چاربندی <span class=\"hlight\">:</span> <br />به جوی زر نیازمندی چند<br />هفت قفلی و چاربندی چند.<br /> <font color=\"Red\">نظامی (هفت پیکر).</font><br />بِه کزین رهزنان کناره کنی <br />بر خود این چاربند پاره کنی .<br /> <font color=\"Red\">نظامی (هفت پیکر).</font><br /> <BR><font color=\"Blue\">◄</font> میان کمر. (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاربند قایم، در ورزش </span> ؛فرمانی است که استاد ورزش به ورزش کنندگان دهد.<br /></font></div>'),
(282055, 'چاربندی', '<span class=\"hlight\">چاربندی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِ مرکب ) ریسمان یا طنابی که طفل نوآموز را که میخواهد سوار کاری بیاموزد بدان وسیله به اسب می بندند <span class=\"hlight\">:</span> <br />دو دری شدچو کوی طراران <br />چاربندی چو بند عیاران .<br /><font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> زنبیل و توشه دان . (ناظم الاطباء). چنته مانندی است که مسافر به پشت بسته دو بند از زیر بغل و دوبند از روی دو شانه میگذرانند. (گنجینه ٔ گنجوی ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>). <BR><font color=\"Blue\">◄</font> (ص نسبی ) منسوب به چاربند. رجوع به چاربند شود. کودک نوآموز یا هر سوارکاری که به وسیله ٔ طناب یا ریسمان به اسب بسته شده باشد <span class=\"hlight\">:</span> <br />چاربندی رسید پیکی چست <br />راه شش طاق هفت گنبد جست .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282056, 'چاربنیچه', '<span class=\"hlight\">چاربنیچه .</span> <font color=\"DarkGreen\"><b>[ ب ُ چ َ ]</font></b> (اِخ ) شعبه ای از طائفه ٔ ایل باصری که تیره ای از ایلات خمسه ٔ فارس بشمار میرود. (جغرافی سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٨٧</span>).<br /></font></div>'),
(282057, 'چاربی بی', '<span class=\"hlight\">چاربی بی .</span> (اِ مرکب ) اصطلاحی در بازی آس . چاربرگ بازی ورق یا آس که هر برگ آن نقش «بی بی » دارد و در بازی آس پس ازچارآس و چارشاه امتیازش از سایر برگها بیشتر است .<br /></font></div>'),
(282058, 'چاربیخ', '<span class=\"hlight\">چاربیخ .</span> (اِ مرکب ) اصول اربعه . چهار ریشه و آن ریشه ٔ خطمی و رازیانه و کرفس و کَبَر باشد. بیخ کاسنی و بیخ رازیانه و بیخ کبر و بیخ کرفس را گویند. (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> (ص مرکب ) دارای چهار ریشه . چارریشه . چاراصل <span class=\"hlight\">:</span> <br />درختی است شش پهلو و چاربیخ <br />تنی چند را بسته بر چارمیخ .<br /> <font color=\"Red\">نظامی (شرفنامه ص <span class=\"hlight\" dir=\"rtl\">٨٩</span>).</font><br /><BR><font color=\"Blue\">◄</font> کنایه است از چار عنصر. (برهان ).<br /></font></div>'),
(282059, 'چاربیخی', '<span class=\"hlight\">چاربیخی .</span> (ص نسبی ) چاراصلی . چارریشه ای . کنایه از ریشه ٔمحکم و استوار. <BR><font color=\"Blue\">◄</font> چارعنصری <span class=\"hlight\">:</span> <br />کاین هفت خدنگ چاربیخی <br />وین نه سپر هزارمیخی .<br /><font color=\"Red\">نظامی (لیلی و مجنون ).</font><br /></font></div>'),
(282060, 'چاربید', '<span class=\"hlight\">چاربید.</span> (اِخ ) قلعه ای است در بجنورد. از آب چشمه مشروب میشود، زراعتش آبی است . هوایش ییلاق . پانزده خانوار سکنه دارد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282061, 'چاربیستی', '<span class=\"hlight\">چاربیستی .</span> (اِ مرکب ) نام منصب که از طرف پادشاه باشد. (آنندراج ).<br /></font></div>'),
(282062, 'چارتا', '<span class=\"hlight\">چارتا.</span> (اِ مرکب ) طنبور و رباب چهار تار را گویند. (برهان ). <BR><font color=\"Blue\">◄</font> کنایه از چهار عنصر و عالم و دنیا هم هست به اعتبار چهار رکن . (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> چارگوهر. (آنندراج ). <BR><font color=\"Blue\">◄</font> چارلا و رجوع به چار تار و چار تاره شود.<br /></font></div>'),
(282063, 'چارتار', '<span class=\"hlight\">چارتار.</span> (اِ مرکب ) طنبور و رباب چهارتار را گویند. (برهان ) <span class=\"hlight\">:</span> <br />طبع گیتی راست شد درعهد تو زآنسان که باز<br />نشنود صوت مخالف هیچکس زین چارتار.<br /> <font color=\"Red\">سلمان ساوجی .</font><br /><BR><font color=\"Blue\">◄</font> کنایه از چهارعنصر و عالم و دنیا هم هست به اعتبار چهاررکن . (برهان ). رجوع به چارتا و چارتاره شود.<br /></font></div>'),
(282064, 'چارتاره', '<span class=\"hlight\">چارتاره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ مرکب ) به معنی چارتار است که طنبور و رباب و هر سازی که بر آن چهارتار بندند. (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از عناصر و دنیا هم هست . (برهان ). و رجوع به چارتا و چارتار شود.<br /></font></div>'),
(282065, 'چارتاق', '<span class=\"hlight\">چارتاق .</span> (ص مرکب ) چارطاق .بالتمام باز (در). رجوع به چارطاق و چهارطاق شود.<br /></font></div>'),
(282066, 'چارتان', '<span class=\"hlight\">چارتان .</span> (اِخ ) قریه ای است از قرای قراباغ واقع در کنار ارس نزدیک به پل خداآفرین و از پل تا چارتان دو فرسخ و نیم مسافت دارد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282067, 'چارتای', '<span class=\"hlight\">چارتای .</span> (اِ مرکب ) نوعی ساز. چارتار. رباب . تنبور <span class=\"hlight\">:</span> <br />به منعمان بهل آواز چنگ، رندان را<br />ترانه ٔ سبک از چار تای میکده بس .<br /><font color=\"Red\">اوحدی .</font><br /></font></div>'),
(282068, 'چارتخمه', '<span class=\"hlight\">چارتخمه .</span> <font color=\"DarkGreen\"><b>[ ت ُ <span class=\"hlight\" dir=\"rtl\">/</span> م َ<span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب ) چارتخم (قدومه و بارهنگ و بهدانه و سپستان ) جوشانده ٔ مخصوص از بارهنگ و سپستان و قدومه و بهدانه که در سرماخوردگی برای نرم کردن اخلاط سینه و رفع سینه درد میخورند. شربتی از جوشانده ٔ بهدانه و بارتنگ و قدامه و سپستان نرم کردن اخلاط سینه را.<br /></font></div>'),
(282069, 'چارترک', '<span class=\"hlight\">چارترک .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ مرکب ) قسمی از کلاه چهارگوشه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> در اصطلاح بنایی، نوعی سقف گنبدی شکل را گویند. (درفیض آباد محولات بخش تربت حیدریه اکنون مصطلح است ).<br /></font></div>'),
(282070, 'چارترکیب', '<span class=\"hlight\">چارترکیب .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ مرکب ) چهارگوهر. چهارعنصر <span class=\"hlight\">:</span> <br />از این چارترکیب آراسته <br />ز هر گوهری عاریت خواسته .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282071, 'چارتو', '<span class=\"hlight\">چارتو.</span> (اِ مرکب ) چارلا. چارتا.<br /></font></div>'),
(282072, 'چارتکبیر', '<span class=\"hlight\">چارتکبیر.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِ مرکب ) نماز میت درمذهب اهل سنت . نماز جنازه . نمازی در مذهب اهل سنت وجماعت . نمازی که بمذهب اهل سنت بر جسد میت گزارند. نماز مخصوص جنازه که فقط چهار تکبیر دارد. <BR><font color=\"Blue\">◄</font> کنایه از ترک چیزی است، چه این کنایه است به نماز جنازه چرا که در نماز جنازه فقط چهار تکبیر میباشد. (آنندراج ) <span class=\"hlight\">:</span> <br />بدان چارسلطان درویش نام <br />شده چارتکبیر دولت تمام .<br /> <font color=\"Red\">نظامی .</font><br />رجوع به ماده ٔ ذیل شود.<br /></font></div>'),
(282073, 'چارجامه', '<span class=\"hlight\">چارجامه .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (اِ مرکب ) پوششی از سقرلاط و مخمل و امثال آن ساخته، اسبان را بدان آرایش کنند در حالت پیری و اسبی را که آن را زین نبندند و لجام کرده غاشیه بر آن اندازند و سوار شوند. (آنندراج ) <span class=\"hlight\">:</span> <br />سواری کی توان بر اسب عمری <br />که باشد از عناصر چار جامه .<br /> <font color=\"Red\">اشرف (از آنندراج ).</font><br />جلی که بر پشت اسب بجای زین اندازند.<br />(ناظم الاطباء). <BR><font color=\"Blue\">◄</font> زین بدون قلتاغ . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> چار جامه کردن ستور. صاحب برهان در ذیل لغت (کفل ) نویسد: «وپلاس را نیز گویند که ستوران را بدان چار جامه کنند و سوار شوند».<br /></font></div>'),
(282074, 'چارجانب', '<span class=\"hlight\">چارجانب .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (اِ مرکب ) چارسمت . چارطرف . چارسو.<br /></font></div>'),
(282075, 'چارجل', '<span class=\"hlight\">چارجل .</span> <font color=\"DarkGreen\"><b>[ ج ُ ]</font></b> (اِ مرکب ) چارجامه . (آنندراج ).<br /></font></div>'),
(282076, 'چارجهت', '<span class=\"hlight\">چارجهت .</span> <font color=\"DarkGreen\"><b>[ ج َ هََ ]</font></b> (اِ مرکب ) چهارسوی و چهارطرف . (ناظم الاطباء). مشرق و مغرب و شمال و جنوب . چهارسمت . <BR><font color=\"Blue\">◄</font> عالم . (ناظم الاطباء).<br /></font></div>'),
(282077, 'چارجو', '<span class=\"hlight\">چارجو.</span> (اِخ ) نام یکی از معابر جیحون . به مناسبت شهری با همین نام بدانجا، چارجوی . صاحب مرآت البلدان آرد: در سنه ٔ نهصد و سی و در مرتبه ٔ دوم که عبیداﷲخان اوزبک از ماوراءالنهر بقصد تسخیر خراسان از معبر چارجوی جیحون عبور نموده بمرو آمد و ازمرو بجانب مشهد مقدس رانده این شهر را محاصره کرد وبحیطه ٔ تصرف درآورد و از آنجابه استراباد تاخت و بعد بطرف بلخ معاودت نمود. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(282078, 'چارجو', '<span class=\"hlight\">چارجو.</span>(اِ مرکب ) چارجوی . چاره جوی . رجوع به چاره جوی شود.<br /></font></div>'),
(282079, 'چارجوهر', '<span class=\"hlight\">چارجوهر.</span> <font color=\"DarkGreen\"><b>[ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> جُو هََ ]</font></b> (اِ مرکب ) کنایه از عناصر اربعه و چهار ستاره ٔ نعش است از بنات النعش . (آنندراج ).چهار عنصر و چهار ستاره ٔ دب اکبر. (ناظم الاطباء).<br /></font></div>'),
(282080, 'چارجوی', '<span class=\"hlight\">چارجوی .</span> (اِخ ) چارجو. شهرکی از اجزای بخارا است بر لب جیحون بخوارزم نزدیک . (آنندراج ).<br /></font></div>'),
(282081, 'چارجوی بهشتی', '<span class=\"hlight\">چارجوی بهشتی .</span> <font color=\"DarkGreen\"><b>[ ی ِ ب ِ هَِ ]</font></b> (اِ مرکب ) چهار نهر، یکی از آب دوم از شیر، سوم از خمر، چهارم از عسل . (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از سیحون و جیحون و نیل و فرات .(آنندراج ). <BR><font color=\"Blue\">◄</font> کوثر و سلسبیل و تسنیم و طهور در بهشت . (اقبالنامه چ وحید ص <span class=\"hlight\" dir=\"rtl\">٢٥٠</span>) <span class=\"hlight\">:</span> <br />ز دوزخ مشو تشنه را چاره جوی <br />سخن در بهشت است و آن چار جوی .<br /><font color=\"Red\">نظامی (اقبالنامه ).</font><br /></font></div>'),
(282082, 'چارجوی فطرت', '<span class=\"hlight\">چارجوی فطرت .</span> <font color=\"DarkGreen\"><b>[ ی ِ ف ِ رَ ]</font></b> (اِ مرکب ) عناصر اربعه . (آنندراج ). <BR><font color=\"Blue\">◄</font> چهار مزاج انسانی یعنی دموی و صفراوی و بلغمی و سودائی . (ناظم الاطباء).<br /></font></div>'),
(282083, 'چارحد', '<span class=\"hlight\">چارحد.</span> <font color=\"DarkGreen\"><b>[ ح َ ]</font></b> (اِ مرکب ) شرق و غرب و جنوب و شمال . (آنندراج ). مشرق و مغرب و شمال و جنوب . (ناظم الاطباء). چار جهت <span class=\"hlight\">:</span> <br />کردرها در حرم کاینات <br />هفت خط و چارحد و شش جهات .<br /> <font color=\"Red\">نظامی .</font><br />سرای شرع را چون چارحد بست <br />بنابر چاردیوار ابد بست .<br /> <font color=\"Red\">نظامی .</font><br />بر قرعه ٔ چارحد کویت <br />فالی زنم ازبرای رویت .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> توسعاً همه و تمامی جائی <span class=\"hlight\">:</span> <br />جهان را همه چارحد گشت و دید<br />که بی چارحد ملک نتوان خرید.<br /> <font color=\"Red\">نظامی .</font><br />که حکم تو بر چارحد جهان <br />رونده است بر آشکار و نهان .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282084, 'چارحد', '<span class=\"hlight\">چارحد.</span> <font color=\"DarkGreen\"><b>[ ح َ ]</font></b> (اِخ ) چهارحد، دهی جزء بخش خرقان شهرستان ساوه، <span class=\"hlight\" dir=\"rtl\">٤٢</span> هزارگزی باختر رازقان و <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی راه عمومی . کوهستانی و سردسیر با<span class=\"hlight\" dir=\"rtl\">٥٨٩</span> تن سکنه و آب آن از چشمه سار و رود محلی، محصول آنجا غلات و سیب و قلمستان و لبنیات و عسل، شغل اهالی آن زراعت و گله داری و قالیچه و جاجیم و گلیم بافی است، راه مالرو ایل شاهسون بغدادی در بهار به حدود این ده می آیند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282085, 'چارحرفی', '<span class=\"hlight\">چارحرفی .</span><font color=\"DarkGreen\"><b>[ ح َ ]</font></b> (ص نسبی ) کلمه ای که دارای چهار حرف باشد. هرکلمه ای که چارحرف از حروف الفباء در آن باشد. کلمه ٔچارحرفی از قبیل : مادر، بابا، جهان، زانو و غیره .<br /></font></div>'),
(282086, 'چارحصار', '<span class=\"hlight\">چارحصار.</span> <font color=\"DarkGreen\"><b>[ ح ِ ]</font></b> (اِ مرکب ) دعائی که بر پیراهن غازیان نوشتندی .<br /></font></div>'),
(282087, 'چارحمال', '<span class=\"hlight\">چارحمال .</span> <font color=\"DarkGreen\"><b>[ ح َم ْما ]</font></b> (اِ مرکب ) کنایه از چاردیوار خانه . کنایه از چار ستون خانه که سقف بر آنها قرار گیرد <span class=\"hlight\">:</span> <br />گر سه حمال کارگر داری <br />چار حمال خانه برداری .<br /><font color=\"Red\">نظامی (هفت پیکر).</font><br /></font></div>'),
(282088, 'چارحوض اصفهان', '<span class=\"hlight\">چارحوض اصفهان .</span> <font color=\"DarkGreen\"><b>[ ح َ <span class=\"hlight\" dir=\"rtl\">/</span> ح ُ ض ِ اِ ف َ ]</font></b> (اِخ ) میدانی است کوچکتر از میدان نقش جهان اصفهان و فیمابین این دو میدان، بازار مسگرهای اصفهان واقع و راه این میدان به آن میدان میباشد میدان چارحوض وصل به عمارات دیوانی است و عمارت مشهور به سردرچار حوض عبارت است از چند اطاق فوقانی و تحتانی . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(282089, 'چارخ', '<span class=\"hlight\">چارخ .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (ترکی، اِ) چارق . کفش درشت روستایی . نوعی پای افزار که دهقانان و روستائیان در پای کنند <span class=\"hlight\">:</span> <br />سواران ولی بر نمد زین چارخ <br />شجاعان ولیکن بفسق و بساغر.<br /> <font color=\"Red\">عمعق بخارایی .</font><br />و رجوع به چارق و چارغ شود.<br /></font></div>'),
(282090, 'چارخال', '<span class=\"hlight\">چارخال .</span> (اِ مرکب ) اصطلاحی در بازی ورق که بر یک برگ چار خال یا دو برگ دو خال یا بر دو برگ که یکی سه خال و دیگری تک خال است اطلاق شود. چارخال بازی نرد که چون کعبتین اندازندهر یک دو خال یا یکی سه خال و دیگری یک خال باشد.<br /></font></div>'),
(282091, 'چارخان', '<span class=\"hlight\">چارخان .</span> (اِ مرکب ) خانه ٔ چهارم نرد. اصطلاحی در بازی نرد. خانه ٔ چهارم از نرد در زیر خانه ٔ افشار.<br /></font></div>'),
(282092, 'چارخانه', '<span class=\"hlight\">چارخانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص مرکب، اِ مرکب ) یک نوع پارچه . پارچه ای که دارای خطوط صلیبی رنگارنگ باشد. (ناظم الاطباء). پارچه ای که دارای نقوش مربعی شکل باشد. پارچه ٔ شطرنجی . <BR><font color=\"Blue\">◄</font> هر کس که تجاوز از شأن وحد خود کند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> دیگ بزرگی که دارای چارخانه باشد. (ناظم الاطباء) <span class=\"hlight\">:</span> <br />نخواهد ماند آخر جاودانه <br />در این نه مطبخ این یک چارخانه .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282093, 'چارخایه', '<span class=\"hlight\">چارخایه .</span> <font color=\"DarkGreen\"><b>[ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (ص مرکب ) شجاع و جنگجوی . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کسی که مایل به زنان باشد. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کنایه از مفسد و محیل . (آنندراج ).<br /></font></div>'),
(282094, 'چارخایگی', '<span class=\"hlight\">چارخایگی .</span> <font color=\"DarkGreen\"><b>[ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (حامص مرکب ) شجاعت و جنگجویی . <BR><font color=\"Blue\">◄</font> میل وافر به زنان داشتن <span class=\"hlight\">:</span> <br />پیرانه سر که پشت امیدی دوتا شده <br />از چارخایگی دو سه جا کدخدا شده .<br /> <font color=\"Red\">امیدی (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> کنایه از مفسدی و حیله گری . <br /></font></div>'),
(282095, 'چارخصم', '<span class=\"hlight\">چارخصم .</span> <font color=\"DarkGreen\"><b>[ خ َ ]</font></b> (اِ مرکب ) چارعنصر. آب و باد و خاک و آتش <span class=\"hlight\">:</span> <br />و آن پادشاه ده سر و شش روی و هفت چشم <br />با چارخصمشان به یکی خانه اندرند.<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(282096, 'چارخلط', '<span class=\"hlight\">چارخلط.</span> <font color=\"DarkGreen\"><b>[ خ ِ]</font></b> (اِ مرکب ) خون و بلغم و صفرا و سودا. صفرا و سوداو بلغم و خون مطابق اصطلاح پزشکان قدیم <span class=\"hlight\">:</span> <br />از سر و پای تا بگردن و گوش <br />هست از این چارخلط عاریه پوش .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282097, 'چارخلیفه', '<span class=\"hlight\">چارخلیفه .</span> <font color=\"DarkGreen\"><b>[ خ َ ف َ <span class=\"hlight\" dir=\"rtl\">/</span> ف ِ ]</font></b> (اِ مرکب ) کنایه از چهار عنصر <span class=\"hlight\">:</span> <br />وین خانه ٔ هفت سقف کرده <br />بر چارخلیفه وقف کرده .<br /> <font color=\"Red\"> نظامی .</font><br />زین چارخلیفه ملک پیداست <br />خانه به چهار حد مهیاست .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282098, 'چارخم', '<span class=\"hlight\">چارخم .</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (اِ مرکب ) خمهای چهارگانه رنگرزی . چهارخم دکان رنگ رزی که رنگرز رنگهای مختلف را در آنها میریزد <span class=\"hlight\">:</span> <br />این سه گز خاک و پهنی تو گزی <br />چارخم در دکان رنگرزی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282099, 'چارخم', '<span class=\"hlight\">چارخم .</span> <font color=\"DarkGreen\"><b>[ خ َ ]</font></b> (اِ مرکب ) فنی است از کشتی . (آنندراج ). نام فنی در کشتی گیری . (ناظم الاطباء) <span class=\"hlight\">:</span> <br />نهد دست و پا چون به پشت و شکم <br />نهد نام این شیوه را چار خم .<br />اعجاز اصفهانی (درصفت کیسه مال حمام از آنندراج ).<br /> <BR><font color=\"Blue\">◄</font> کمان را چون گوش تا گوش کشند گویندچارخم شد. (آنندراج ) <span class=\"hlight\">:</span> <br />سرکش به یک دو ضرب نگیرد فروتنی <br />تا زور ما ندید کمان، چارخم نشد.<br /> <font color=\"Red\">ملاطغرا (از آنندراج ).</font><br />بیک خمی ز کمان دو ابروت مردم <br />کرشمه ات اگرش چارخم کند چه علاج .<br /> <font color=\"Red\">ملاطغرا (از آنندراج ).</font><br />بر سر زانوی قدرش کمان حلقه ٔ افلاک چارخم . (تاج المدایح از آنندراج ).<br /></font></div>'),
(282100, 'چارخمی', '<span class=\"hlight\">چارخمی .</span> <font color=\"DarkGreen\"><b>[ خ َ ]</font></b> (اِخ )مزرعه ای است از سیستان، قدیم النسق سکنه ٔ این مزرعه شصت و پنج نفر میباشند. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(282101, 'چارخوان', '<span class=\"hlight\">چارخوان .</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (اِ مرکب )چارجوی بهشت . (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه است ازنیل و فرات و دجله و جیحون . (آنندراج ) (مصطلحات ).<br /></font></div>'),
(282102, 'چارخیابان', '<span class=\"hlight\">چارخیابان .</span> (اِ مرکب ) میدانی که از شمال و جنوب و مشرق و مغرب آن خیابان ممتد باشد. میدانی که از چهار سمت بخیابان متصل است و از هر طرف آن خیابانی امتداد یافته است . <BR><font color=\"Blue\">◄</font> محل تقاطع چهار خیابان که بر یکدیگر عمود باشند. آنجا که دو خیابان تقاطع کنند.<br /></font></div>'),
(282103, 'چاردار ملک', '<span class=\"hlight\">چاردار ملک .</span> <font color=\"DarkGreen\"><b>[ رِ م ُ ]</font></b> (اِخ ) چهار شهر خراسان که مورد هجوم غزان قرارگرفت و ویران شد و عبارت بودند از مرو و بلخ و هرات و نیشابور.<br /></font></div>'),
(282104, 'چاردانگ', '<span class=\"hlight\">چاردانگ .</span> (اِ مرکب ) کنایه از چیزی که نسبت بامثال خود دو چندان باشد چه دینار شش دانگ میباشد دانگ ششم حصه دینار است پس چهاردانگ به نسبت دودانگ زائد میباشد و لفظ چهاردانگ که گاهی صفت هندوستان واقع میگردد بنابر آن است که چون عرض و طول هندوستان سوای روس از اکثر بلاد عالم بیشتر است یا آنکه آبادی و تحصیل از هندوستان به نسبت تحصیل دیگر بلاد عالم بیشتر است پس از این سبب تمام عالم را یک دینار فرض کردند و هندوستان را از آن بمنزله ٔ چهاردانگ شمردند، یا آنکه هندوستان در چهاراقلیم واقع است چنانکه در نقشه ٔ ربع مسکون ظاهر است در لفظ هفت اقلیم . (آنندراج ). چهار ربع کره . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> اصطلاح موسیقی . <BR><font color=\"Blue\">◄</font> اصطلاح بنایی . <BR><font color=\"Blue\">◄</font> اصطلاح در تراشیدن قلم . <BR><font color=\"Blue\">◄</font> هر چیز که نه کلان باشد و نه خرد. (ناظم الاطباء).<br /></font></div>'),
(282105, 'چاردانگه', '<span class=\"hlight\">چاردانگه .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِخ ) جزو دشتی است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> حاشیه ٔ ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(282106, 'چاردانگه', '<span class=\"hlight\">چاردانگه .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِخ ) قریه ای است از ورامین . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(282107, 'چاردانگه', '<span class=\"hlight\">چاردانگه .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِخ ) قریه ای است از قرای خراسان . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(282108, 'چاردانگه', '<span class=\"hlight\">چاردانگه .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِخ ) قریه ای است از قرای غار مِن اعمال طهران این قریه خالصه ٔ دیوان اعلی میباشد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(282109, 'چاردرد', '<span class=\"hlight\">چاردرد.</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ مرکب ) درد زاهو. درد وضع حمل زنان . درد شدید زن هنگام وضع حمل . آخرین و سخت ترین درد بچه زائیدن زنان . سخت ترین درد زه نزدیک به زادن . موقع سخت درد زه . درد شدید زایمان .<br /></font></div>'),
(282110, 'چاردرویش', '<span class=\"hlight\">چاردرویش .</span> <font color=\"DarkGreen\"><b>[ دَرْ ]</font></b> (اِخ ) نام افسانه ٔ ملی . نام یکی از افسانه های باستانی ایران . نام افسانه ای ملی و باستانی که به نثر فارسی نوشته شده و آن را بنظم هم در آورده اند. نام یکی از افسانه های کهن ایرانی به نثر و نظم .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">قصه ٔ چار درویش </span> ؛ کنایه از سخن دراز و ملال آور.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">قصه ٔ چار درویش گفتن </span> ؛ کنایه از چیزهای بی معنی و دراز گفتن است .<br /></font></div>'),
(282111, 'چاردری', '<span class=\"hlight\">چاردری .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ مرکب ) اطاقی که چار در داشته باشد. اطاقی دارای چهار در. خانه ٔ چاردری <span class=\"hlight\">:</span> <br />عیسی ز چاردری با جمله جمع رسل <br />پیش آمده بادب کرده سلام ادا.<br /> <font color=\"Red\">مجیر بیلقانی (در وصف معراج رسول ).</font><br /><BR><font color=\"Blue\">◄</font> کنایه است از عالم . (از ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کنایه است از عناصر اربعه . (از مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">٢٥١</span>).<br /></font></div>'),
(282112, 'چاردست', '<span class=\"hlight\">چاردست .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِمرکب ) کنایه است از چارعنصر. چارآخشیج <span class=\"hlight\">:</span> <br />این هفت قواره ٔ شش انگشت <br />یکدیده ٔ چاردست و نه پشت .<br /><font color=\"Red\">نظامی (لیلی و مجنون ).</font><br /></font></div>'),
(282113, 'چاردست وپا', '<span class=\"hlight\">چاردست وپا.</span> <font color=\"DarkGreen\"><b>[ دَ ت ُ ]</font></b> (ص مرکب ) روشی در راه رفتن چون روش سگ و گوسفند و اسب و جز آن . شیوه ٔ راه رفتنی چون راه رفتن حیوانات .<br /></font></div>'),
(282114, 'چاردست وپا رفتن', '<span class=\"hlight\">چاردست وپا رفتن .</span><font color=\"DarkGreen\"><b>[ دَ ت ُ رَ ت َ ]</font></b> (مص مرکب ) رفتن آدمی بر روی دو دست و دو پای چون ستور. کف هردو دست و هر دو پای را بر زمین نهاده رفتن . راه رفتن کودکانی که تازه به راه میافتند و راه رفتن آدمی بشیوه ٔ راه رفتن چارپایان .<br /></font></div>'),
(282115, 'چاردستور', '<span class=\"hlight\">چاردستور.</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) ظاهراً پیشوایان مذاهب اربعه (شافعی، حنفی، حنبلی، مالکی ) چارامام . چارخلیفه . چارتن پیشوایان مذاهب اهل سنت <span class=\"hlight\">:</span> <br />همه کاری از داوری دور کن <br />بدستوری چاردستور کن .<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> (اِ مرکب ) چارطبع.<br /></font></div>'),
(282116, 'چاردستی', '<span class=\"hlight\">چاردستی .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ مرکب ) اصطلاح قمار. اصطلاحی در بازی ورق .قمار چارنفری . شرکت چار نفر در قمار با ورق . همبازی شدن چار نفر در قماری که بیش از چار نفر هم میتوانند در آن بازی شرکت کنند. چهار حریف در بعضی قمارها. چارتایی . چار نفری . چارحریفی . چار نفری بازی کردن .<br /></font></div>'),
(282117, 'چاردندانه', '<span class=\"hlight\">چاردندانه .</span> <font color=\"DarkGreen\"><b>[ دَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص مرکب ) صفتی شتر را. اشتر چاردندانه . رباعی الابل .<br /></font></div>'),
(282118, 'چاردندانه شدن', '<span class=\"hlight\">چاردندانه شدن .</span> <font color=\"DarkGreen\"><b>[ دَ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ش ُ دَ ]</font></b> (مص مرکب ) چاردندانه شدن اشتر. بسن خاصی رسیدن شتر و آن سالی است که شتر دندان رباعیه را افکند، و آن سال هفتم از عمر شتر است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /><span class=\"hlight\">اشتر که چاردندانه شود از آوای درای نترسد</span> . (تذکرة الاولیای عطار). و این مثل ظاهراً ترجمه ٔ مثل عربی است که گوید: رباعی الابل لاترتاعه الجرس، و مراد آن است که مرد جهان دیده، و گرم و سرد چشیده و با حوادث و تصاریف زمان دچار شده، از پیش آمدهای صعب نهراسد.<br /></font></div>'),
(282119, 'چارده', '<span class=\"hlight\">چارده .</span> <font color=\"DarkGreen\"><b>[ دِه ْ ]</font></b> (اِخ ) در چند ولایت واقع است در ملک هزار جریب قریب بدامغان چون بر پشته ٔ کوه قلعه ای دارد و قلعه ٔ بالای کوه را کلات و کلاته گویند به چارده کلاته موسوم شده و اجدادمؤلف از آنجا برخاسته اند. دیگری در خراسان است و آن چارده سنخاس گویند و چهار قلعه ٔ بزرگ است که بفاصله ٔ اندک در فضای جلگه ٔ سنخاس واقع شده و از آنجا تا جاجرم هشت فرسنگ راه کویر بی آب است و مایل بسمت مغرب است و در بندها در این راه است که معبر تراکمه است به جاجرم و اسفراین و شاهرود و این چارده بر سمت جنوب بجنورد واقع شده و سنخاس و قلعه سپید و اندجان و جعفرآباد در این محل واقع است . (انجمن آرای ناصری ).<br /></font></div>'),
(282120, 'چارده', '<span class=\"hlight\">چارده .</span> <font color=\"DarkGreen\"><b>[ دِه ْ ]</font></b> (اِ مرکب ) نام چند ناحیه که در هر یک چهار ده و یا چهار قلعه واقع است . (ناظم الاطباء).<br /></font></div>'),
(282121, 'چارده', '<span class=\"hlight\">چارده .</span> <font color=\"DarkGreen\"><b>[ دَه ْ ]</font></b> (اِ مرکب ) چهارورق ده خال . اصطلاحی در بازی ورق . چارلکات در بازی آس .چاربرگ ورق بازی که بر روی هر یک ده خال نقش شده .<br /></font></div>'),
(282122, 'چارده', '<span class=\"hlight\">چارده .</span> <font color=\"DarkGreen\"><b>[ دَه ْ ]</font></b> (عدد مرکب، ص مرکب، اِ مرکب ) مخفف چهارده . تعیینی عددی که شامل میشود عدد ده بعلاوه ٔ چهار را. (ناظم الاطباء). عدد دورقمی مرکب از چهار و ده . عددی در مرتبه ٔ عشرات . اربعةعشر. دو برابر عدد هفت . عددی است میان سیزده و پانزده و صورت آن با ارقام هندی این است : (<span class=\"hlight\" dir=\"rtl\">١٤</span>) و (<span class=\"hlight\" dir=\"rtl\">١٤</span>) و با ارقام رومی (<span class=\"hlight\" dir=\"rtl\">XIV</span>) <span class=\"hlight\">:</span> <br />چو عمر آمد بحد چارده سال <br />برآمد مرغ دانش را پر وبال .<br /> <font color=\"Red\">نظامی .</font><br />گر شغل دگر حرام بودی <br />در چارده مه تمام بودی .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> بدر و ماه تمام . (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مثل ماه شب چارده </span> ؛ سخت زیباروی . و رجوع به بدر و ماه شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">مه چارده </span> ؛ ماه چارده .ماه شب چارده . پُرماه <span class=\"hlight\">:</span> <br />حور عین میگذرد در نظر سوختگان <br />یا مه چارده یا لعبت چین میگذرد.<br /> <font color=\"Red\">سعدی .</font><br />تو سرو دیده ای که کمر بست بر میان <br />یا ماه چارده که بسر برنهد کلاه .<br /> <font color=\"Red\">سعدی .</font><br />چارده ساله بتی چابک شیرین دارم <br />که به جان حلقه بگوش است مه چاردهش .<br /><font color=\"Red\">حافظ (دیوان چ قزوینی ص <span class=\"hlight\" dir=\"rtl\">١٩٦</span>).</font><br /></font></div>'),
(282123, 'چارده روایت', '<span class=\"hlight\">چارده روایت .</span> <font color=\"DarkGreen\"><b>[ دَه ْ رِ ی َ ]</font></b> (اِ مرکب ) مراد از چارده روایت شاگردان هفت امام قرائت است چراکه هر امام را دو شاگرداند. (آنندراج ) <span class=\"hlight\">:</span> <br />عشقت رسد به فریاد گر خود بسان حافظ<br />قرآن ز بر بخوانی در چارده روایت .<br /><font color=\"Red\">حافظ (از آنندراج ).</font><br /></font></div>'),
(282124, 'چارده ساله', '<span class=\"hlight\">چارده ساله .</span> <font color=\"DarkGreen\"><b>[ دَه ْ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (ص نسبی مرکب ) دختر و پسری که بسن چهارده سالگی رسیده باشند <span class=\"hlight\">:</span> <br />ای چارده ساله قرةالعین <br />بالغنظر علوم کونین .<br /> <font color=\"Red\">نظامی .</font><br />چارده ساله بتی چابک شیرین دارم <br />که بجان حلقه بگوش است مه چاردهش .<br /> <font color=\"Red\">حافظ (دیوان چ قزوینی ص <span class=\"hlight\" dir=\"rtl\">١٩٦</span>).</font><br />می دوساله و محبوب چارده ساله <br />همین بس است مرا صحبت صغیر و کبیر.<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(282125, 'چارده سنخاص', '<span class=\"hlight\">چارده سنخاص .</span> <font color=\"DarkGreen\"><b>[ دِ هَِ س ِ ]</font></b> (اِخ ) از راه بجنورد که بطرف عراق میایند بعد از دو سه منزل به چارده سنخاص سنخاص میرسند قبل از ورود بجلگه از قریه ٔ دربند که واقع در دربندی است که نیم فرسخ امتداد دارد و عرضاً تنگ میباشد عبور میشود. چارده سنخاص مابین اسفراین و بجنورد واقع و عبارت از چهار قلعه ٔ بزرگ است که به اندک فاصله با یکدیگر در جلگه ٔ سنخاص بناشده یکی از آن قلاع قریب الانهدام و سه قلعه ٔ دیگر آباد ودر هر قلعه پنجاه الی شصت خانوار رعیت هست اسم یکی از قلعه ها اندغان است از دهنه ٔ دربند که وارد جلگه ٔ سنخاص میشوند بفاصله ٔ نیم فرسنگ این قلعه واقع است وقدری پائین تر قلعه ٔ موسوم به خدا شاه و قریه ٔ سنخاص معتبر و با سکنه و باغات است این محل یکی از معابر تراکمه بوده که بسمت عباس آباد و بسطام بتاخت و تاز میآمده اند چارده سنخاص بادهای تند بد دارد و در اطراف آن جنگل اورس زیاد است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥</span>).<br /></font></div>'),
(282126, 'چارده طبس', '<span class=\"hlight\">چارده طبس .</span> <font color=\"DarkGreen\"><b>[ دِ هَِ طَ ب َ ]</font></b> (اِخ ) نام ناحیه ای در طبس خراسان . در سال هشتصد و نه هجری که میانه ٔ دو برادر یعنی میرزا پیر محمد و میرزا اسکندر گورکانی بهم خورده یگانگی به بیگانگی بدل شد میرزا پیر محمد میرزا اسکندر را گرفته بندی بر پایش نهاد و به صحابت بعضی از معتمدان بصوب خراسان فرستاداو در چارده طبس بند را شکسته و از چنگ محصلان خود را خلاص کرده باصفهان رفت . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥</span>).<br /></font></div>'),
(282127, 'چارده معصوم', '<span class=\"hlight\">چارده معصوم .</span> <font color=\"DarkGreen\"><b>[ دَه ْ <span class=\"hlight\" dir=\"rtl\">/</span> دَ م َ ]</font></b> (اِخ ) حضرت محمد (ص ) و دخترش فاطمه (ع ) و دوازده امام که از علی بن ابیطالب (ع )شروع و به امام دوازدهم حجةبن الحسن ختم میشود. حضرت محمد (ص ) و فاطمه (ع ) با دوازده امام . محمد (ص ) و علی (ع ) و فاطمه (ع ) و حسن و حسین با نه امام دیگر.<br /></font></div>'),
(282128, 'چارده چناران', '<span class=\"hlight\">چارده چناران .</span> <font color=\"DarkGreen\"><b>[ دِهَِ چ ِ ]</font></b> (اِخ ) بلوکی است از بلوکات بجنورد واقع در سمت مشرق این بلده و اسامی قرا و مزارع آن از این قرار است : چناران، نوده، اسفندان، ترفی، بیغو، کوک و کمر. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥</span>).<br /></font></div>'),
(282129, 'چارده کلاته', '<span class=\"hlight\">چارده کلاته .</span> <font color=\"DarkGreen\"><b>[دِ هَِ ک َ ت َ ]</font></b> (اِخ ) یکی از بلوکات هزارجریب است در جلگه واقع شده و رودخانه ای از مشرق بمغرب در آن جاری است . کوههای اطراف این جلگه از هر قبیل چرنده و طیور و وحوش دارد حتی حیوانات شکاری و سباع از قبیل پلنگ و گرگ و غیره در آنجا یافت میشود. چارده کلاته عبارت است از چار قریه که «ورزن » و «زردوان » و «قلعه » و «خرابه ده » باشد گندم آنجا معروف است و نان خاصه ٔ سفره ٔ سلاطین قاجار همیشه از گندم چارده کلاته بوده و هست کلیه ٔ این بلوک فیمابین چشمه علی دامغان و شاه کوه است یعنی از شاه کوه به چارده کلاته شش فرسخ و از چشمه علی سه فرسخ و چون بدریای خزر نزدیک است آنجا را مه میگیرد و سلاطین با فر و تمکین قاجار قبل از آنکه بر تمام ایران استیلا پیدا نمایند از صفحات مازندران به چارده کلاته ییلامیشی میکردند خاقان خلد آشیان فتحعلی شاه طاب اﷲ ثراه باغی در چارده کلاته طرح کرده اند که معروف بباغ شاه است زکیخان زند در زمان سرداری استرآباد و مازندران در سنه ٔ هزار و صد و هشتاد و هشت چارده کلاته را قتل نمود و چندین کله منار ساخت از معارف چارده کلاته رضا قلیخان امیرالشعراء متخلص به هدایت است که از امرای بزرگ این دولت ابد آیت و مصنفین معتبر و اساتید شعراء و بفنون فضایل و مکارم اخلاق معروف و موصوف بوده ... (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٥</span> و <span class=\"hlight\" dir=\"rtl\">٤٦</span>).<br /></font></div>'),
(282130, 'چاردهم', '<span class=\"hlight\">چاردهم .</span> <font color=\"DarkGreen\"><b>[ دَ هَُ ]</font></b> (عدد ترتیبی مرکب، ص نسبی ) مخفف چهاردهم . چیزی که در مرتبه ٔ چهارده واقع شود. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بدر و ماه تمام . (ناظم الاطباء).<br /></font></div>'),
(282131, 'چاردهمی', '<span class=\"hlight\">چاردهمی .</span> <font color=\"DarkGreen\"><b>[ دَ هَُ ]</font></b> (ص نسبی، اِ مرکب ) هر چیز که در مرتبه ٔ چاردهم واقع شود. مرتبه ای بین سیزدهم و پانزدهم .<br /></font></div>'),
(282132, 'چاردهمین', '<span class=\"hlight\">چاردهمین .</span> <font color=\"DarkGreen\"><b>[ دَ هَُ ]</font></b> (ص نسبی، اِ مرکب ) مخفف چهاردهمین . چاردهمی . چیزی در مرتبه ٔ چهاردهم .<br /></font></div>'),
(282133, 'چاردوال', '<span class=\"hlight\">چاردوال .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ مرکب ) زنجیر دسته دار که بدان خر رانند. <BR><font color=\"Blue\">◄</font> چوبی باشد بمقدار یک قبضه که چارواداران بر سر آن میخی کوچک بقدرمهمیزی نصب نمایند و زنجیری با چند حلقه و چهار تسمه بر آن تعبیه کنند و الاغ و چاروا را بدان برانند. (برهان قاطع). <BR><font color=\"Blue\">◄</font> در بیت زیر از رضی الدین نیشابوری ظاهراً چاردوال معنی دیگر دارد <span class=\"hlight\">:</span> <br />آن خداوند که همواره همایونش صیت <br />هفت اقلیم همی برّد بی چاردوال .<br /> <font color=\"Red\">رضی نیشابوری .</font><br />رجوع به سُک شود.<br /></font></div>'),
(282134, 'چاردوالی', '<span class=\"hlight\">چاردوالی .</span> <font color=\"DarkGreen\"><b>[دَ ]</font></b> (اِخ ) اسم طائفه ای . نام ایلی . ایل چاردوالی .<br /></font></div>'),
(282135, 'چاردولی', '<span class=\"hlight\">چاردولی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) اسم بلوک غربی از توابع صاین قلعه ٔ افشار. (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">١٧٥</span>).<br /></font></div>'),
(282136, 'چاردولی', '<span class=\"hlight\">چاردولی .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام بلوکی از یازده بلوک ناحیه ٔ کردستان سنه . (جغرافیای مفصل تاریخی غرب ایران نگارش بهمن کریمی ص <span class=\"hlight\" dir=\"rtl\">٧١</span>).<br /></font></div>'),
(282137, 'چاردیوار', '<span class=\"hlight\">چاردیوار.</span> <font color=\"DarkGreen\"><b>[ دی ]</font></b> (اِمرکب ) خانه ای که از هر چهار طرف دیوار داشته باشد. (آنندراج ). مخفف چهار دیوار. دیوارهای چهارگانه ٔ اطاق یا جایگاهی که سقف بر آنها نهاده شود <span class=\"hlight\">:</span> <br />بود چار دیوار آن خانه سست <br />که بنیادش اول نباشد درست .<br /> <font color=\"Red\">نظامی .</font><br />بگفت از پس چار دیوار خویش <br />همه عمر ننهاده ام پای پیش .<br /> <font color=\"Red\">نظامی .</font><br />شه آسایش و خواب را کار بست <br />دو لختی در چاردیوار بست .<br /> <font color=\"Red\">نظامی .</font><br />چو در چاربالش ندیدم درنگ <br />نشستم در این چار دیوار تنگ .<br /> <font color=\"Red\">نظامی .</font><br />پیش قدرش سپهر نه بالش <br />همچو ویرانه چاردیواریست .<br /> <font color=\"Red\">جوینی .</font><br />چاردیواری نمایان نیست غیر از چارموج <br />گشت سیلاب سرشکم در جهان نا آشکار.<br /> <font color=\"Red\">غنی (از آنندراج ).</font><br />هر زمینی و جایی که از همه طرف محدود به دیوار باشد. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کنایه از چار حد دنیا هم هست . (برهان ) (آنندراج ) (ناظم الاطباء) <span class=\"hlight\">:</span> <br />چه بازیچه کاین چرخ بازیچه رنگ <br />نبازد در این چاردیوار تنگ .<br /> <font color=\"Red\">نظامی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاردیوار خانه روزن شدن </span> ؛ کنایه از خراب شدن و فرو افتادن خانه . (آنندراج ) <span class=\"hlight\">:</span> <br />چاردیوار خانه روزن شد<br />بام بنشست و آستان برخاست .<br /> <font color=\"Red\">افضل الدین خاقانی (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاردیوار ظلمانی </span> ؛ دنیا و قالب انسانی . (آنندراج ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاردیوار نفس </span> . (ناظم الاطباء).<BR>۩ قالب و جسد آدمی . (ناظم الاطباء).<br /></font></div>'),
(282138, 'چاردیوار', '<span class=\"hlight\">چاردیوار.</span> <font color=\"DarkGreen\"><b>[ دی ]</font></b> (اِخ ) قریه ای است از قرای حوالی قندهار. پادشاه هندوستان جلال الدین اکبر دفعه ٔ ثانی بعد از سه سال و هشت ماه و بیست روز که از اول محاصره ٔ قندهار گذشته بود از جهان آباد پایتخت خود بقصد تصرف قندهار حرکت کرده در کابل اردو زد و اورنگ زیب پسر خود را با یکصد هزار سوار از یکسو و سعداﷲخان وزیر اعظم را با یک صد هزار دیگر و نه عراده توپ از جانب دیگر در اواخر ربیع الثانی هزار و شصت ودو بسمت قندهار حرکت داد، اردوی سعداﷲخان وزیر اعظم در چمن طلی خان سه فرسنگی شهر و اردوی اورنگ زیب بقریه ٔ چاردیوار نزول نمود. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٨</span>).<br /></font></div>'),
(282139, 'چاردیوار نفس', '<span class=\"hlight\">چاردیوار نفس .</span> <font color=\"DarkGreen\"><b>[ دی رِ ن َ ]</font></b> (اِ مرکب ) کنایه ازدنیا و قالب و جسد آدمی باشد. (برهان ) (آنندراج ).<br /></font></div>'),
(282140, 'چاردیواری', '<span class=\"hlight\">چاردیواری .</span> <font color=\"DarkGreen\"><b>[ دی ]</font></b> (اِ مرکب ) خانه . محوطه ای که فقط چهار دیوار دارد بی هیچ بنای دیگر. جدیر؛ چاردیواری . (منتهی الارب ). جدرالجدار؛ چاردیواری ساخت . (منتهی الارب ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">چاردیواری اختیاری </span> ؛ مثلی است که از آن آزادی مسکن و منزل اراده کنند یعنی هر خانه مصون از تعرض است .<br /><BR><font color=\"Blue\">◄</font> بودجه ٔ چاردیواری یعنی بودجه ٔ کامل و دربست . <BR><font color=\"Blue\">◄</font> میدان و آبشتگاه . (ناظم الاطباء).<br /></font></div>'),
(282141, 'چارراه', '<span class=\"hlight\">چارراه .</span> (اِ مرکب ) محل تقاطع دو راه . محلی که از چهار سمت آن راهی امتداد یافته است . محلی که دو راه یکدیگر را آنجا قطع کرده و هر یک بسمتی امتداد یافته است .<br /></font></div>'),
(282142, 'چارراه', '<span class=\"hlight\">چارراه .</span> (اِخ ) فرسخی بیشتر شمالی باشت است . (فارسنامه ٔ ناصری ص <span class=\"hlight\" dir=\"rtl\">٢٧١</span>).<br /></font></div>'),
(282143, 'چارراه', '<span class=\"hlight\">چارراه .</span> (اِخ ) سه فرسخ مشرقی قلعه گل است . (فارسنامه ٔ ناصری ص <span class=\"hlight\" dir=\"rtl\">٢٧٤</span>).<br /></font></div>'),
(282144, 'چارراهی', '<span class=\"hlight\">چارراهی .</span> (اِخ ) طائفه ای است اصل آنها از خلج بلوک قونقیری است همه چادرنشین ییلاق آنها در پاکت بلوک قونقیری و قشلاق آنها در جزیره ٔ علی یوسف از دریاچه ٔ بختکان معیشت آنها از گوسفند و بز است . (فارسنامه ٔ ناصری ص <span class=\"hlight\" dir=\"rtl\">٣٣١</span>).<br /></font></div>'),
(282145, 'چارروزه', '<span class=\"hlight\">چارروزه .</span> <font color=\"DarkGreen\"><b>[ زَ <span class=\"hlight\" dir=\"rtl\">/</span> زِ ]</font></b> (ص نسبی ) چهارروزه . مجازاً به معنی کوتاه . دنیای چهارروزه، کنایه از عمر کوتاه است .<br /></font></div>'),
(282146, 'چارروستا', '<span class=\"hlight\">چارروستا.</span> (اِخ ) قریه ای است واقع در سه فرسنگی میانه ٔ شمال و مشرق بندر ریگ . (فارسنامه ٔ ناصری ).<br /></font></div>'),
(282147, 'چاررکن', '<span class=\"hlight\">چاررکن .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِ مرکب ) چهار رکن . در مناسک حج عبارت است از مسح و طواف و سعی و حلق . <BR><font color=\"Blue\">◄</font> دو دست و دو پای . <br /></font></div>'),
(282148, 'چارزانو', '<span class=\"hlight\">چارزانو.</span> (اِ مرکب ) نوعی نشستن . مربع نشستن . چهار زانو نشستن . <BR><font color=\"Blue\">◄</font> وضع نشست خیاط. (نا ظم الاطباء).<br /></font></div>'),
(282149, 'چارزانو زدن', '<span class=\"hlight\">چارزانو زدن .</span> <font color=\"DarkGreen\"><b>[ زَ دَ ]</font></b> (مص مرکب ) کنایه از مربع نشستن . (آنندراج ) <span class=\"hlight\">:</span> <br />چار زانو چون توان در مجلس سلطان زدن <br />تا بخدمت چست باشی بر سر یکپا نشین .<br /><font color=\"Red\">باقر کاشی (از آنندراج ).</font><br /></font></div>'),
(282150, 'چارزانو نشستن', '<span class=\"hlight\">چارزانو نشستن .</span> <font color=\"DarkGreen\"><b>[ ن ِ ش َ ت َ ]</font></b> (مص مرکب ) مربع نشستن . چار زانو زدن . نشستن به طرز چار زانو.<br /></font></div>'),
(282151, 'چارزبان', '<span class=\"hlight\">چارزبان .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (ص مرکب ) کنایه است از پرگوی و کثیرالکلام . (آنندراج ).<br /></font></div>'),
(282152, 'چارزبانی', '<span class=\"hlight\">چارزبانی .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِ مرکب ) کنایه از چار عناصر است که به چار زبانیه ٔ دوزخ تشبیه شده است . (انجمن آرای ناصری ) <span class=\"hlight\">:</span> <br />اسیر طبعمخالف مدار جان و خرد<br />زبون چارزبانی مکن دو حور لقا.<br /><font color=\"Red\">خاقانی (از انجمن آرا).</font><br /></font></div>'),
(282153, 'چارسال', '<span class=\"hlight\">چارسال .</span> (اِ مرکب ) مدت چهار سال . (ناظم الاطباء). چهارساله .<br /></font></div>'),
(282154, 'چارساله', '<span class=\"hlight\">چارساله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (ص نسبی ) منسوب به چهار سال . (ناظم الاطباء).دارای چهارسال . (ناظم الاطباء).<br /></font></div>'),
(282155, 'چارسرباز', '<span class=\"hlight\">چارسرباز.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ مرکب ) اصطلاحی در بازی آس و اصطلاحی در بازی ورق . چار سرباز در قمار آس . چارصورت سرباز در ورق بازی . چار سرباز در بازی پاسور چار ورق که بر هر یک صورتی بنام سرباز نقش شده است .<br /></font></div>'),
(282156, 'چارسف', '<span class=\"hlight\">چارسف .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) نام کوهی است که شعبه ای از آب «چار سفرود» از آن برمیخیزد. (نزهة القلوب ص <span class=\"hlight\" dir=\"rtl\">٢٢٧</span>).<br /></font></div>'),
(282157, 'چارسفرود', '<span class=\"hlight\">چارسفرود.</span> <font color=\"DarkGreen\"><b>[ س َ]</font></b> (اِخ ) مجموع دو رشته آب است که یکی از جبال باردویه بر میخیزد و دیگری از جبال طغان و چارسف، و بیکدیگر پیوسته اراضی حدود مجاور را مشروب سازند طول این رودخانه پانزده فرسنگ است (از نزهة القلوب ص <span class=\"hlight\" dir=\"rtl\">٢٢٧</span>).<br /></font></div>'),
(282158, 'چارسمت', '<span class=\"hlight\">چارسمت .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ مرکب ) چارطرف . چارجانب . چارسو. مشرق و مغرب و شمال و جنوب .<br /></font></div>'),
(282159, 'چارسنجاق', '<span class=\"hlight\">چارسنجاق .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) قصبه ای از قصبات کشور ترکیه که در ولایت معمورة العزیز در <span class=\"hlight\" dir=\"rtl\">٤٠</span> هزارمتری شمال خرپوت واقع است . (قاموس الاعلام ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(282160, 'چارسو', '<span class=\"hlight\">چارسو.</span> (اِ مرکب ) جائی که چهار بازار در آنجا منشعب شوند. (برهان ). بازاری که هر چهار طرف راه داشته باشد. (آنندراج ). نام آن جای از بازار که به هر چهار طرف راسته و دکانها راه دارد. (ناظم الاطباء). چهارسوی . چهارسوق . بازاری که از چهار طرف بیرون شو دارد. جائی که چهار بازار از آنجا گذرد <span class=\"hlight\">:</span> <br />که دارد دکانی در این چارسو<br />که رخنه نیارد ز بسیار سو.<br /> <font color=\"Red\">نظامی .</font><br />در این چارسو چند سازیم جای <br />شکم چارسو کرده چون چارپای .<br /> <font color=\"Red\">نظامی .</font><br />در این چارسو هیچ هنگامه نیست <br />که کیسه بر مرد خودکامه نیست .<br /> <font color=\"Red\">نظامی .</font><br />بمعیار این چارسو رهروی <br />نسنجد دو جو تا ندزدد جوی .<br /> <font color=\"Red\">نظامی .</font><br />در این چارسوی هنرپروری <br />ز راه سخن میکنی زرگری .<br /> <font color=\"Red\">ملاطغرا (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> نیز بمعنی راه کلان که در آن چهارراه مجتمع شده باشد. (آنندراج ) (ناظم الاطباء). چار راه <span class=\"hlight\">:</span> <br />بدین چارسو چون نهم دستگاه <br />که ایمن نباشم ز دزدان راه .<br /> <font color=\"Red\">نظامی .</font><br />در چارسوی دنیا مضطر بمانده ام من <br />گر وارهانی از خوددانم که میتوانی .<br /> <font color=\"Red\">عطار.</font><br />بر منادی گاه کن این کار تو<br />بر سر راهی که باشد چارسو.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> چارسمت . چارطرف . چارجانب . شمال و جنوب وشرق و غرب . راست و چپ و پیش و پس <span class=\"hlight\">:</span> <br />نباشد سپاه تو هم پایدار<br />چو برخیزد از چارسو کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />نگه کرد گرد اندرون چارسو<br />سپه دید افکنده چین در برو.<br /> <font color=\"Red\">فردوسی .</font><br />بدان بام شد کش نبود آرزو<br />سپه دید گرد اندرش چارسو.<br /> <font color=\"Red\">فردوسی .</font><br />روی از این چارسوی غم برتاب <br />چند از این خاک و باد و آتش و آب .<br /> <font color=\"Red\">نظامی .</font><br />زلفت هزار دل به یکی تار موببست <br />راه هزارچاره گر از چارسو ببست .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> هر چیز راگویند که چهار پهلو داشته باشد. (برهان ) (ناظم الاطباء). چهار پهلو. <BR><font color=\"Blue\">◄</font> کنایه از شکم سیر و بسیار پر و مملو <span class=\"hlight\">:</span> <br />مکن در خورش خویشتن چارسو<br />چنان خور که نوزت بود آرزو.<br /> <font color=\"Red\">فردوسی .</font><br />شکم از خورد چارسو چه کنی <br />خویشرا بنده ٔ گلو چه کنی .<br /> <font color=\"Red\">سنایی .</font><br />در این چارسو چند سازیم جای <br />شکم چارسو کرده چون چارپای .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> کنایه از انتظار کشیدن . (برهان ). انتظار و نگرانی و چشمداشت . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نوعی آچار که دَم ِ آن چار پره دارد. <BR><font color=\"Blue\">◄</font> نوعی میخ پیچ که بر سر چهار فرورفتگی به شکل + دارد. پورداود استاد دانشگاه تهران در معنی لغت «چارسو» شرح جامع و محققانه ای در کتاب «هرمزدنامه » نگاشته اشتباهات بعضی فرهنگ نویسان را یادآور شده اند که در اینجا نوشته ٔ ایشان را عیناً از کتاب مزبورنقل میکنیم :<br />«در این گفتار از چارسو (= چهارسوی یا سون ) که در تازی جهات اربعه خوانند سخن میداریم . این چارسو را در پهلوی و فارسی، خراسان (= خوراسان ). و خُروران یا خُرابران (= خاور- خوروران ) و باختر (= اپاختر) و نیمروز (= نیمروچ ) خوانند و در تازی مشرق و مغرب و شمال و جنوب گویند. چون دیرگاهی است که این واژه ها در نوشته های فارسی بجای خود بکار نرفته، خاور بجای باختر و باختر بجای خاور آورده شده بجاست که از آنها سخن بداریم و ارزش آنها را بدرستی بشناسیم . در نوشته های پهلوی بجای جهت یا طرف و سو (= سون ) کست آورده شده و جهات اربعه را چهار کستیک خوانده اند. اما این واژه به این مفهوم در فارسی بجای نمانده بلکه به هیئت کشتی یا کستی (معرب کستیج ) در زبان ما بجای مانده و آن بندی است که زرتشتیان در سن بلوغ دینی بر میان بندند:<br />همه سوی شاه زمین آمدند<br />به بستند کستی بدین آمدند...<br /> <font color=\"Red\">دقیقی .</font><br />بسا هم کستی بمعنی زنار ترسایان بکار رفته :<br />کستی هرقل به تیغ هندی بگسل <br />بر سر قیصر صلیبها همه بشکن .<br /> <font color=\"Red\">فرخی .</font><br />کستی یا کشتی در فارسی رایج کنونی مصارعه ٔ دو تن است با همدیگر و گرفتن کمربند یکدیگررا از برای چیر شدن و بزانو درآوردن و بزمین افکندن :<br />ز کشتی گرفتن سخن بود دوش <br />نگیرم فریب تو زین در مکوش .<br /> <font color=\"Red\">فردوسی .</font><br />چون درگزارش (تفسیر) اوستای خود از سدره و کستی یاد کردیم در اینجا بیش از این بایسته نیست . چارسوی یکبار هم در شاهنامه در سخن از بازی شطرنج بمعنی چهار گوشه آمده . هم چنین ابوریحان بیرونی در کتاب التفهیم چهارسو را بمعنی چهارگوشه گرفته : «چهارسو چند گونه اند؟ نخستین مربع است که متساوی الاضلاع گویند و این آن است که هر چهار پهلوی او با یکدیگر راست و برابر باشد... و دیگر مستطیل که درازا دارد و این آن است که هر چهار زاویه ٔ او قائمه باشند...» . چهارسوی نیز بمعنی چهار راه است و بهمین معنی در فارسی کنونی رایج است : «بعد از دو روز آن جوان را بکاری بگرفتند که مستوجب دست بیرون کردن بود و بر سر چهارسوی بغداد دست بیرون کردند.» چارسو در اوستا مشرق یا خراسان از آنجائی که هور بدر آید یا خورشید سرزند در اوستا اوشستره آمده، از واژه ٔ اوشه (اوشنگه ) که بمعنی بامداد و سپیده دم است . جزء آخر کلمه که تره باشد، جزئی که در آخرکلمات دیگر «چارسو» نیز دیده میشود، همان است که درفارسی «تر» گوئیم و در ترکیب صفت تفضیلی بکار بریم . چون بهتر و بتر و مهمتر و جز اینها. مغرب یا خوروران (خوربران = خاور) بجائی که آفتاب فرو نشیند یا خورشید نهفته گردد، در اوستادئوشستره (= دئوشتره ) خوانده شده است . از همین واژه است دوش و دوشینه و دوشین و پرندوش و پرندوشین ؛ بمعنی دیشب و پریشب :<br />گویدت همی گرچه دراز است ترا عمر<br />بگذشته ثمر یکسره چون دوش و پرندوش .<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <br />شمال یا اپاختر (= باختر) در اوستا اپاختره (= اپاخذره ) آمده جزء اول آن از کلمه ٔ اپاک (= اپانک ) بمعنی پس و پشت سر است و در پهلوی اپاچ و فارسی باز بمعنی عقب و برگشت است از این که کلمه ٔ اپاختر با این لغت ترکیب یافته برای این است که پیروان مزدیسنا هماره روی بجنوب و پشت بشمال دارند. در هر جای از اوستا که از جنوب یاد شده، همان سوی و جهت بخشایش ایزدی است و شمال سوی گزند و آسیب است . در فرگرد هفتم و ندیداد پاره ٔ <span class=\"hlight\" dir=\"rtl\">٢</span> آمده : پس از مرگ دیو، لاشه و مردار بصورت مگس زشتی از سوی باختر پرواز گرفته به پیکر مرده روی آورد. در فرگرد نوزدهم و ندیداد پاره ٔ <span class=\"hlight\" dir=\"rtl\">١</span> آمده : از سوی باختر به اهریمن تباهکار دیو دروغ را از برای کشتن زرتشت پاک برانگیخت . در هادخت نسک فرگرد سوم پاره ٔ <span class=\"hlight\" dir=\"rtl\">٧</span> گوید: چون روان ناپاکدین پس از سپری شدن شب سوم، در سپیده دم بجهان دیگر گراید، باد از سوی باختر وزیدن گیرد و بوی گند بسیار ناخوش بدو رساند در نوشته های پهلوی کوه ارزور . در باختر در دوزخ است . جنوب یا نیمروز در اوستا رپیتوی تره خوانده شده و از رپیتوا که بمعنی نیمروز (= ظهر) است ترکیب یافته است رپیتوا خود جداگانه در اوستا بکار رفته است . نام جنوب در اوستا مانند نام آن در لاتین مریدیس در فرانسه میدی هم بمعنی نیمه ٔ روز است و هم سوی جنوب، چنانکه نیمروز در پهلوی و فارسی که یاد خواهیم کرد چنین است .<br />چارسو در نوشته های پهلوی :<br />بسا در نامه های پهلوی از چارسو یاد شده، از آنهاست بندهش که چهار کوستیک (= سو) را چنین خوانده : کوست خوراسان کوست خوروران - کوست نیمروچ - کوست اپاختر. در شهرستانهای ایران، نامه ای که در بنیاد شهرهای ایران بزبان پهلوی در زمان خلیفه ٔ عباسی المنصور (<span class=\"hlight\" dir=\"rtl\">١٣٦</span>-<span class=\"hlight\" dir=\"rtl\">١٥٨</span> هَ . ق .) نوشته شده چنین آمده : کوست خراسان - کوست خوربران - کوست نیمروچ - کوست آتورپاتکان . موسی خورنجی تاریخ نویس ارمنی که در پایان خلافت اموی یا در آغاز خلافت عباسی (از سال <span class=\"hlight\" dir=\"rtl\">١٣٢</span> هَ . ق .) نوشته و بخش جغرافیای وی ناگزیر از روی نوشته های پهلوی است، چارسو را چنین یاد کرده : کست خُربران - کست نیمروچ - کست خراسان - کست کاپ کوه . چنانکه دیده میشود لغتهائی که در پهلوی از برای چارسو بکار رفته (جز از اپاختر) غیر از لغتهای اوستائی است . خوراسان که در پهلوی بجای مشرق یا از آنجائی که خورشید بدر آید، گفته شده همان است که امروزه خراسان گوئیم و نام یکی از ایالتهای ایران است . در پارینه همین نام به همه ٔ زمینهای ایران مشرقی تابرود آمویه (= جیحون ) اطلاق میشده، ناگزیر به این مناسبت که این سرزمینها در همان جهت برآمدن خورشید واقع است و خود کلمه خورآسان (= خراسان ) لفظاً بهمین معنی است . فخرالدین اسعد استرآبادی، (گرگانی ) که در حدود <span class=\"hlight\" dir=\"rtl\">٤٤٦</span> هَ . ق . داستان ویس و رامین را از پهلوی بنظم فارسی درآورده معنی خراسان را درست یاد کرده :<br />زبان پهلوی هر کوشناسد<br />خراسان آن بود کزوی خورآسد<br />خورآسد پهلوی باشد خورآید<br />عراق و پارس راخور زو برآید<br />خوراسان را بود معنی خودآیان <br />کجا از وی خورآید سوی ایران .<br />فخر گرگانی در جای دیگر داستان ویس و رامین، خراسان را بمعنی خورآید = آسد به کاربرده :<br />دو خورشید از خراسان روی بنمود<br />که از گیتی دو گونه زنگ بزدود<br />یکی بزدود زنگ شب ز کیهان <br />یکی بربود زنگ غم ز جانان .<br />شبهه نیست که آسان در کلمه ٔ خراسان بمعنی برآینده و سر زننده است، از مصدر آسدن و از ریشه ٔ آس بمعنی بلند شدن و برخاستن . بهمین معنی است آسغ در لهجه ٔ بلوچی و آسین در لهجه ٔ استرآبادی (گرگانی ) که بمعنی آمدن است . درلهجه ٔ بلوچی نیز آسان با کلمه ٔ روش ترکیب یافته، روش آسان یعنی برآمدن آفتاب و برخاستن خورشید. در زبان ارمنی اسن که از زبان ایران بعاریت گرفته شده نیز موجود است . خوربران یا خوروران که در فارسی کنونی خاور گوئیم (خاوران سرزمینهای خاوری است ) نشستگاه خورشید است، یا آنسوی که هوربدانجا گراید و نهفته گردد. در نوشته های پهلوی در همه جا نیمروچ بمعنی جنوب است و از حیث مفهوم با کلمه ٔ اوستائی رپیتوا که یاد کردیم یکی است . نیمروز در فارسی که در لهجه ٔ کردی نیمه رو گویند بمعنی ظهر است :<br />ظالمی را خفته دیدم نیمروز<br />گفتم این فتنه است خوابش برده به .<br /> <font color=\"Red\">سعدی .</font><br />همچنین سرزمین سیستان نیمروز نامیده شده، گردیزی در زین الاخبار گوید: که به رأی العین خویش بدیدم که امیر محمود رحمةاﷲ اندر هندوستان چه کرده است و به نیمروز و بخراسان و بعراق چگونه قلعها گشاده است . «و اندر شوال سنه سبعة عشر و اربعمائة نامه ٔ القادرباﷲ آمد با عهد و لوای خراسان و هندوستان ونیمروز و خوارزم مر امیر محمود را»ء .<br />آن ملک نیمروز و خسرو پیروز<br />دولت او یوز و دشمن آهوی نالان .<br /> <font color=\"Red\">رودکی .</font><br />از اینکه سیستان را نیز نیمروز خوانده اند برای این است که این سرزمین در پائین جنوب خاک خراسان افتاده است . اما کوست آتورپاتکان و کوست کاپ کوه، گفتیم در شهرستانهای ایران و جغرافیای موسی خورنجی، بجای شمال آورده شده، یادآور خبری است که خسرو انوشیروان کشورهای ایران را چهار بخش کردو هر یک از آن بخشها را به فرمانگزاری یک پادوسپان سپرد. اتورپاتکان (آذربایجان ) و کاپ کوه (= کوه قاف، قفقاز قبق یاقبح ) یکی ازآن چارسو است، در شمال ایران . از این گذشته شمال درپهلوی اپاختر خوانده شده و در آثار پهلوی تورفان نیز چارسوی چنین نامیده گردیده : اواختر= شمال ؛ نیمروچ = جنوب ؛ خوراسان = مشرق ؛ خوروران = مغرب . لغتهای ثابت از برای تعیین نامهای چارسو در پهلوی همین است . دربرخی از نوشته های عربی و فارسی تا باندازه ای که نگارنده دیده این نامها درست یاد شده و در برخی دیگر لغت مغرب بجای لغت مشرق و لغت شمال بجای مغرب بکار رفته و این خود میرساند، این تخلیط که امروزه در لغتهای فارسی جهات اربعه، دچار آن هستیم، دیرگاهی است که روی داده است .<br />چارسو در نوشته های عربی و فارسی : ابن رسته (ابوعلی احمدبن عمر) که در سده ٔ سوم هجری میزیسته در کتاب اعلاق النفیسه در «صفة ایرانشهر والسواد» مینویسد: «قال و کانت ایرانشهر مقسومة باقسام قسمة منها ما بین مطلع اطول النهار الی مطلع اقصرالنهار وتسمی خراسان : وقسمة منها مابین مغیب اطول النهار الی مغیب اقصرالنهار وتسمی خربران تفسیره مغرب الشمس ؛ وقسمة منها مابین مطلعالنهار الاقصر الی مغیب النهار الاقصر وتسمی نیمروز و تفسیره الجنوب ؛ وقسمة منها مابین مطلعالنهار الاطول الی مغیب النهارالاطول و تسمی باختر و تفسیره الشمال .» الخوارزمی که گویا در سال <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> هَ . ق . درگذشت در مفاتیح العلوم گوید: «خراسان تفسیره المشرق و خُرباران هوالمغرب و نیمروز هو مهب الجنوب لان شمس تسامته نصف النهار و آذربادکان هو مهب الشمال و آذرمن شهور الشتاء و باد هو الریح و معناء مهب ریح الشتاء ثم عربت الکلمة فصیرت آذربیجان » مسعودی که در سال <span class=\"hlight\" dir=\"rtl\">٣٤٥</span> یا<span class=\"hlight\" dir=\"rtl\">٣٤٦</span> هَ . ق . درگذشته در کتاب التنبیه والاشراف گوید که بخش آبادان زمین را چنین نامند: «و تسمیتهم مشارق الارض و ما قارب ذالک من مملکتها خراسان و خرالشمس فاضافوا مواضع المطلع الیها والجهة و الثانیة و هی المغرب خُربران و هو مغیب الشمس و الجهة الثالثة و هی الشمال باختراً و الجهة الرابعه و هی الجنوب نیمروز.» ابن خرداذبه در المسالک و الممالک که درحدود <span class=\"hlight\" dir=\"rtl\">٢٣٢</span> هَ . ق . نوشته شده گوید: «و المغرب ربع المملکة و کان اصبهبد. یسمی علی عهدالفرس خُربران اصبهبد» در تاریخ سیستان که در حدود <span class=\"hlight\" dir=\"rtl\">٧٢٥</span> - <span class=\"hlight\" dir=\"rtl\">٤٤٥</span> نوشته شده آمده : «و این جمله را (جهان را) به چهار قسمت کرده اند: خراسان و ایران (خاوران ) و نیمروز و باختر: هر چه حد شمال است باختر گویند و هر چه حد جنوب است نیمروزگویند و میانه اندر بدو قسمت شود. هر چه حد شرق است خراسان گویند و هر چه مغرب است ایرانشهر.» چنانکه دیده میشود این نویسندگان نامهای فارسی چارسو را درست مانند نویسندگان پهلوی یادکرده اند و الخوارزمی گذشته از وجه اشتقاق نادرستی که به کلمه ٔ آذربادکان داده، طرف شمال را مانند نامه شهرستانهای ایران، آذربادکان نامیده است . برخلاف همه ٔ این اسناد، در مقدمه ٔ شاهنامه ٔ ابومنصوری که کهنترین نمونه ٔ نثر فارسی است و در آغاز سال <span class=\"hlight\" dir=\"rtl\">٣٤٦</span> هَ . ق . نوشته شده چنین آمده : «و آفتاب برآمدن را باختر خواندند و فروشدن را خاور خواندند.» نظر بوجه اشتقاقی که از برای کلمات خاور (= خوروران ) و باختر (= اپاختر یا اواختر) یاد کردیم، خاور باید مغرب باشد یا فروشدن آفتاب اما باختر که شمال است به خطا بمعنی برآمدن آفتاب (= خراسان ) یا مشرق دانسته شده است . همچنین نزد فردوسی سراینده ٔ شاهنامه کلمه ٔ باختر گاهی به خطا بمعنی مغرب گرفته شده و گاهی باز به خطا باختر بمعنی مشرق بکار رفته . همچنین خاور گاهی بخطا بمعنی مشرق گرفته شده و گاهی به صواب، خاور آن چنانکه باید مغرب است . فخر گرگانی در ویس و رامین که گفتیم خراسان را بمعنی مشرق یاد کرده، درجای دیگر منظومه اش دچار اشتباه گویندگان دیگر شده خاور را بمعنی مشرق و باختر را بمعنی مغرب گرفته . چنانکه دیده میشود سغد و خوارزم و چغان از سرزمینهای خاوری شام و مصر و قیروان از سرزمینهای باختری خوانده شده در جای دیگر باز بخطا باختر به معنی مغرب است :<br />بترسم کافتاب آسمانی <br />کنون در باختر گردد نهانی . <br />بسیاری از گویندگان باختر را مغرب و خاور را مشرق دانسته اند. آنچنانکه این دو لغت بهمین معانی نادرست مایه ٔ اشتباه فرهنگ نویسان ما گردیده، در فرهنگ جهانگیری یادشده : «خاور مشرق را گویند.» و بعضی از شعرا بمعنی مغرب نیز آورده اند در فرهنگ سروری آمده : «باختر مشرق بود.. لفظ باختر و خاور را متأخرین بر عکس تصور نموده اند. خاور رامشرق میدانند و باختر را مغرب و حال آنکه متقدمین باختر را مشرق و خاور را مغرب «کذا فی التحفه » ناگزیرهمین سهو گویندگان سبب شده که فرهنگ نویسان لغتهای اختر و باختر را بهم ریخته اند: در فرهنگ رشیدی آمده : «...و تحقیق آن است که باختر مخفف با اختر است و اختر ماه و آفتاب و هر دو را گویند پس از باختر مشرق و مغرب را توان گفت .» رضاقلی هدایت که غالباً اشتباه دیگران مورد پسند اوست، همین وجه اشتقاق بی بنیاد را در انجمن آرای خود تکرار کرده است اختر بمعنی ستاره هیچ پیوستگی با اپاختر(= اواختر= باختر) که معنی لفظی آن را یاد کردیم ندارد از آنچه گذشت پیداست که دیرگاهی است لغتهای چارسو، مفاهیم دیرین و ثابت خود را در فارسی از دست داده و همین تخلیط به لهجه های ایرانی هم رسیده در لهجه رایج زرتشتیان ایران خاور بمعنی مشرق و باختر بمعنی مغرب است . <br />امروز همان سهو پارینه در نوشته های فارسی رواج یافته، خاور بمعنی مشرق و باختر به معنی مغرب بکارمیرود و خود نگارنده نیز بناچار آن را پیروی کردم اما چنانکه دیدیم لغات درست جهات اربعه یا چهارسو، خراسان = مشرق، خاور= مغرب، باختر= شمال، نیمروز=جنوب است . چون امروزه خراسان نام سرزمینهای شرقی ایران است، شاید پذیرفتن آن بجای واژه مشرق ناروا بنماید اما چنانکه یاد کردیم خراسان به این معنی از لغات دیرین ایران است، ساختگی نیست .<br />از خراسان بردمد طاوس وش <br />سوی خاور می شتابد شاد و کش .<br /> <font color=\"Red\">رودکی .</font><br /> <br />(نقل از هرمزد نامه نگارش استاد پور داود ازص <span class=\"hlight\" dir=\"rtl\">٣٨٩</span> تا ص <span class=\"hlight\" dir=\"rtl\">٤٠٣</span>).<br /></font></div>'),
(282161, 'چارسو', '<span class=\"hlight\">چارسو.</span> (اِخ ) قریه ای است از قرای کجور و مقبره ٔ مصقلةبن هبیره ٔ شیبانی در آنجاست و مردم کیا- شغله مینامنداز قراری که در تاریخ ظهیرالدین مسطور است در زمان خلافت حضرت امیرالمؤمنین علی علیه السلام قومی در طبرستان موسوم به بنی ناجیه مرتد شده به نصرانیها پیوسته عیسوی شدند حضرت امیرالمؤمنین مصقلةبن هبیره ٔ شیبانی را بتدمیر ایشان فرستاده آنها را غارت و تاراج کردند و زن و فرزندان ایشان را دستگیر و اسیر نمودند اما مصقله اسرا را از لشکر بصد هزار درهم خریده آزاد ساخت و بعضی از قیمت آنها را ادا کرده و قدری را نداد و بگریخت امیرالمؤمنین علیه السلام بقیه ٔ وجه قیمت را از همشیره ٔ او بگرفتند و به لشکر قسمت کرده در حق او فرمود: «قبح اﷲ مصقلة لانه فعل الساده وفرَّ فرارالعبید» و این مصقلة در خلافت معاویه داوطلب شد که اگر چهار هزار مرد به او بدهند طبرستان را مسخر نماید، معاویه چهار هزار مرد به او داد چون بطبرستان رسیددو سال با فرّخان جنگید عاقبت در جنگ کشته شد و در چارسو مدفون گردید. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span> و <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br /></font></div>'),
(282162, 'چارسو بزرگ طهران', '<span class=\"hlight\">چارسو بزرگ طهران .</span> <font color=\"DarkGreen\"><b>[ ب ُ زُ گ ِ طِ ]</font></b> (اِخ ) در سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٢٢٢</span> هَ . ق . در عهد خاقان مغفور فتحعلی شاه طاب اﷲ ثراه ساخته شده است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(282163, 'چارسو شاه اصفهان', '<span class=\"hlight\">چارسو شاه اصفهان .</span> <font color=\"DarkGreen\"><b>[ ه ِ اِ ف َ ]</font></b> (اِخ ) در حوالی میدان نقش جهان است و مدرسه ٔ ملا عبداﷲ که از مدارس معتبره ٔ اصفهان است در این چارسو واقع است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(282164, 'چارسو شیرازیها', '<span class=\"hlight\">چارسو شیرازیها.</span> (اِخ ) اسم یکی از محلات معتبره ٔ اصفهان است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(282165, 'چارسو علیقلی آقا', '<span class=\"hlight\">چارسو علیقلی آقا.</span> <font color=\"DarkGreen\"><b>[ ع َ ق ُ ]</font></b> (اِخ ) یکی از چارسوهای اصفهان و در محله ای واقع آن محله را نیز بهمین اسم مینامند و با محله ٔ بیدآباد مجاورت دارد. مدرسه ای عالی و حمامی بسیار معتبر موسوم بمدرسه و حمام علیقلی آقا در نزدیکی چارسو است علیقلی آقا ظاهراً از امرای صفویه بوده و در بناهای مزبور منتهای سلیقه را به کار برده و در کمال استحکام و امیتاز ساخته است و سنگهای مرمر و غیره و کاشیهای قیمتی نفیس که در مسجدو حمام علیقلی بکار رفته محل توجه ابصار و انظار مسافرین و سیّاحان عالم است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(282166, 'چارسو مخلص اصفهان', '<span class=\"hlight\">چارسو مخلص اصفهان .</span> <font color=\"DarkGreen\"><b>[ وِ م ُ ل ِ ص ِ اِ ف َ ]</font></b> (اِخ ) محل مخصوصی است در بازار اصفهان قرب قیصریه و کاروانسرای مخلص که الان از کاروانسراهای معتبر اصفهان است در این محل واقع شده . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(282167, 'چارسو مقصود اصفهان', '<span class=\"hlight\">چارسو مقصود اصفهان .</span> <font color=\"DarkGreen\"><b>[ م َ دِ اِ ف َ ]</font></b> (اِخ ) بازاری است در حوالی مسجد شاه اصفهان . از میدان نقش جهان وارد این بازار میشوند. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(282168, 'چارسو نقاشی اصفهان', '<span class=\"hlight\">چارسو نقاشی اصفهان .</span> <font color=\"DarkGreen\"><b>[ ن َق ْ قا اِ ف َ ]</font></b> (اِخ ) واقع در نزدیکی دروازه ٔ حسن آباد است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(282169, 'چارسو نمکی', '<span class=\"hlight\">چارسو نمکی .</span> <font color=\"DarkGreen\"><b>[ ن َ م َ ]</font></b> (اِخ ) یکی از چارسوهای اصفهان که واقع در قسمت جنوبی شهر است و بعضی چارسوهای دیگر درشهر اصفهان هست که اگر چه بنای آنها نسبت به ابنیه ٔسایر بلاد معتبر است ولی نسبت بعمارات خود اصفهان چندان رفعت و عظمتی ندارد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(282170, 'چارسو کهنه', '<span class=\"hlight\">چارسو کهنه .</span> <font color=\"DarkGreen\"><b>[ ک ُ ن َ ]</font></b> (اِخ )یکی از محلات کرمان است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(282171, 'چارسو کوچک طهران', '<span class=\"hlight\">چارسو کوچک طهران .</span> <font color=\"DarkGreen\"><b>[ چ َ ک ِ طِ ]</font></b> (اِخ ) در سنه ٔ <span class=\"hlight\" dir=\"rtl\">١٢٤٣</span> هَ . ق . بنا شده است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٩</span>).<br /></font></div>'),
(282172, 'چارسوق', '<span class=\"hlight\">چارسوق .</span> (اِ مرکب ) چارسو. چاربازار. محلی در بازار که بچارسمت راه دارد و هر سمت دارای بازار و دکاکین است .<br /></font></div>'),
(282173, 'چارسوی', '<span class=\"hlight\">چارسوی .</span> (اِ مرکب ) چارسو. چاربازار. محلی که چارسمت آن بازار است <span class=\"hlight\">:</span> <br />در چارسوی فقر درآ تا ز راه ذوق <br />دل را ز پنج نوش سلامت کنی دوا.<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> چارراه <span class=\"hlight\">:</span> <br />در چارسوی کون و مکان وحشت است خیز<br />خلوتسرای انس جز از لامکان مخواه .<br /> <font color=\"Red\">خاقانی .</font><br />از شهر شما دواسبه راندیم <br />وز خون سر چارسوی شستیم .<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> چارسمت . چارطرف . چارجانب . شمال و جنوب و مشرق و مغرب <span class=\"hlight\">:</span> <br />یکی مرد پاکیزه ٔ نیکخوی <br />بدو دین یزدان شود چارسوی .<br /> <font color=\"Red\">فردوسی .</font><br />بدان بام شد کش نبود آرزوی <br />سپه دید گرد اندرش چارسوی .<br /> <font color=\"Red\">فردوسی .</font><br />گرت دیگر آید یکی آرزوی <br />که گرد اندرآید سپه چارسوی .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(282174, 'چارشاخ', '<span class=\"hlight\">چارشاخ .</span> (اِ مرکب ) نوعی از تعذیب . (آنندراج ) (لطائف اللغات ) (غیاث اللغات ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آلتی که بدان خرمن کوفته را باد دهند تا دانه از کاه جدا گردد. (ناظم الاطباء). در بیشتر شهرها و روستاهای خراسان اسم آلتی است که سر آن بشکل پنجه ٔ دست یا دارای چهار شاخ و بیشتر است که بوسیله ٔ آن خرمن کوفته ٔ جو یا گندم را باد دهند تا کاه از دانه جدا شود. مِنشار؛ چوب پنجه دار که بدان گندم و جز آن را بر باد دهند. (منتهی الارب ). سکو که بدان گندم و جز آن برباد دهند. (منتهی الارب ).<br /></font></div>'),
(282175, 'چارشاخ زدن', '<span class=\"hlight\">چارشاخ زدن .</span> <font color=\"DarkGreen\"><b>[زَ دَ ]</font></b> (مص مرکب ) در غالب شهرها و روستاهای خراسان اصطلاحی است برای باد دادن خرمن کوفته ٔ جو و گندمی که هنوز دانه از کاه جدا نشده . بکار بردن چارشاخ برای باد دادن خرمن جو و گندم و جدا کردن دانه از کاه .<br /></font></div>'),
(282176, 'چارشاخ ماندن', '<span class=\"hlight\">چارشاخ ماندن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص مرکب ) بعلت دردی در احشاء یا پشت یا کمر بی حرکت ماندن . بی حرکت ماندن یا عسیرالحرکة شدن بواسطه ٔ درد یا پرخوارگی . جنبش نتوانستن از شدت درد و المی که بیشتر در پشت و کمر عارض شود. بی حرکت ماندن از شدت درد کمر یا پشت .<br /></font></div>'),
(282177, 'چارشاخه', '<span class=\"hlight\">چارشاخه .</span> <font color=\"DarkGreen\"><b>[ خ َ <span class=\"hlight\" dir=\"rtl\">/</span> خ ِ ]</font></b> (اِ مرکب ) هر چیز که چهار شاخه داشته باشد. جار. لوستر. شمعدان چارشاخه ای که از سقف می آویزند یا بر روی جاچراغی میگذارند؛ چراغ چارشاخه ای .<br /></font></div>'),
(282178, 'چارشانه', '<span class=\"hlight\">چارشانه .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (ص مرکب ) کسی که قدش کوتاه و شانه هایش پهن و قوی باشد. (از آنندراج ) <span class=\"hlight\">:</span> <br />ز ضرب گرز کین از هر کرانه <br />شده بالا بلندان چارشانه .<br /> <font color=\"Red\">محمد قلی سلیم (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> قوی هیکل و تنومند. (آنندراج ). تنومند و قوی هیکل و فربه . (ناظم الاطباء). کسی که سینه و بر پهن و قوی و درشت دارد. قوی جثه . تناور و سطبر اندام <span class=\"hlight\">:</span> <br />کمان ابروش کوتاه خانه <br />قد شمشاد پیشش چارشانه .<br /> <font color=\"Red\">اشرف (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> ناموزون قد و بداندام . (ناظم الاطباء).<br /></font></div>'),
(282179, 'چارشاه', '<span class=\"hlight\">چارشاه .</span> (اِ مرکب ) (اصطلاحی در قمار) اصطلاحی در بازی آس و ورق . چهارورق از اوراق بازی که بر هر یک تصویر شاه نقش شده باشد. چار صورت شاه در بازی آس و دیگر بازیهای ورق .<br /></font></div>'),
(282180, 'چارشاهی', '<span class=\"hlight\">چارشاهی .</span> (اِ مرکب ) یک قسمت از بیست قسمت ریال (قران ). هشت پول سیاه . یک عباسی . دوتا صناری (صد دیناری ). <BR><font color=\"Blue\">◄</font> کنایه از پولی مختصر. مبلغی ناچیز.<br /></font></div>'),
(282181, 'چارشب', '<span class=\"hlight\">چارشب .</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِ مرکب ) مخفف چادرشب . پارچه ٔ بزرگ چهارگوشی که رخت خواب در آن بندند و زنان ده چون چادر بسرافکنند. چادر شب <span class=\"hlight\">:</span> <br />نازکت چارشب اولیست که بالا افکن <br />چون درشت است و قوی میرسدت ز آن آزار.<br /> <font color=\"Red\">نظام قاری .</font><br />گاه گردد سپیج سر در شب <br />و ربود چارشب مدانش عار.<br /> <font color=\"Red\">نظام قاری .</font><br />وجب وجب همه شب چارشب بپیمایم <br />چه صرفها که مرادر نهالی عزبیست .<br /><font color=\"Red\">نظام قاری .</font><br /></font></div>'),
(282182, 'چارشنبه', '<span class=\"hlight\">چارشنبه .</span> <font color=\"DarkGreen\"><b>[ شَم ْ ب َ ]</font></b> (اِخ ) نام شهری بر شمال آسیة الصغری بساحل دریای سیاه .<br /></font></div>'),
(282183, 'چارشنبه', '<span class=\"hlight\">چارشنبه .</span> <font color=\"DarkGreen\"><b>[ ش َ شَم ْ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ مرکب ) چهارشنبه . نام روز پنجم از هفته که بتازی اربعاء گویند. (ناظم الاطباء). نام روزی از روزهای هفته که بین سه شنبه و پنجشنبه است . اربعاء <span class=\"hlight\">:</span> <br />بشد چارشنبه هم از بامداد<br />بدین باغ کامروز باشیم شاد.<br /> <font color=\"Red\">فردوسی .</font><br />ستاره شمر گفت بهرام را<br />که در چارشنبه مزن گامرا.<br /> <font color=\"Red\">فردوسی .</font><br />چارشنبه که از شکوفه ٔ مهر<br />گشت پیروزه گون سواد سپهر.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282184, 'چارشنبه سوری', '<span class=\"hlight\">چارشنبه سوری .</span> <font color=\"DarkGreen\"><b>[ شَم ْ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ مرکب ) آخرین چهارشنبه ٔ اسفند ماه هر سال شمسی که ایرانیان در شب آن جشن چارشنبه سوری میگیرند و آداب و رسوم خاصی را در آن شب برگزار میکنند. جشن چارشنبه سوری که از جشن های ملی و باستانی ایرانیان است و هنوز در بسیاری از شهرهاو روستاهای ایران شب این روز را بطرزی خاص جشن میگیرند. سعید نفیسی استاد دانشگاه تهران در شماره ٔ <span class=\"hlight\" dir=\"rtl\">١١</span> سال اول و شماره ٔ <span class=\"hlight\" dir=\"rtl\">١</span> سال دوم مجله ٔ مهر درباره ٔ «چارشنبه سوری » مقاله ٔ مفصل و محققانه ای نوشته اند که قسمتهایی از آن را در اینجا نقل میکنیم : چهارشنبه سوری یعنی چهارشنبه ٔ عیش و عشرت و میرساند که این شب را برای جشن و سرور بنیاد گذاشته اند. این جشن ملی از قدیمترین زمانهای تاریخ در میان ایرانیان بوده است ... شب چهارشنبه سوری در ایران آئین خاص و تشریفات گوناگون دارد که هر یک از آنها را در ناحیه ٔ دیگر میتوان یافت . آئین چهارشنبه سوری یا شب چهارشنبه ٔ آخر سال بر دو قسم است یک قسمت از آن عمومی و مشترک میان تمام مردم ایران است که حتی بعضی از آنها را در ملل دیگر نژاد آریا میتوان یافت و قسمت دیگر آئین خصوصی است که مردم تهران بدعت گذاشته اند و از اینجا کم و بیش بشهرهای دیگر ایران رفته است . آن قسمت از آئین این شب که در تمام ایران معمول است از کرمان گرفته تا آذربایجان واز خراسان تا خوزستان و از گیلان تا فارس یعنی تمام این دشت وسیع که ایران امروز را فراهم ساخته است و زیباترین بقایای ایران باستانی است در هر شب چهارشنبه آخر سال با شور و دلبستگی خاصی آشکار میشود تمام مردم آذربایجان چه در شهر و چه در ده ها در آن شرکت دارند و حتی هنوز در میان مردم قفقاز معمول است . ایرانیانی که از دیار خود دور افتاده اند نیز آن را فراموش نمیکنند و ایرانیان مقیم ترکیه و مصر و هندوستان نیزدر جامعه ٔ خود این رسوم و آداب را معمول میدارند.<br />توپ مروارید: در میدان ارک طهران توپ کهن سالی بود که مدت صد سال بر فراز صفه ای جاگرفته بود و چون پیران زمین گیر از جای خود نمی جنبید - شبهای چهارشنبه سوری زنان و دخترانی که حاجتی داشتند مخصوصاً آن زنانی که در آرزوی شوی بودند ازآن توپ بالا میرفتند و بر فراز آن دمی می نشستند و اززیر آن میگذشتند و در برآورده شدن آرزوی خود شک نداشتند و بچه های شیرخوار را که به اصطلاح «نحسی » میکردند یا ریسه میرفتند از زیر توپ مروارید و سر در نقاره خانه میگذراندند. این توپ را توپ مروارید مینامیدندو افسانه های گوناگون در حق آن میگفتند.<br />آتش افروختن : زیباترین و شاید قدیمترین آداب چهارشنبه سوری آتش افروختن و جستن از آن و شادی کردن در کنارآتش است ....<br />اینک تقریباً در تمام ایران شب چهارشنبه سوری توده هایی از بوته ٔ خودروی بیابانی فراهم می آورند و نزدیک یکدیگر قرارمیدهند زن و مرد و پیر و جوان در صحن خانه یا در میدانهای عمومی و بر سر چهارسوها و چهارراههای شهر و ده از روی این اخگرهای افروخته یکی پس از دیگری جستن میکنند و در هر جستنی میگویند: «زردی من از تو سرخی تو از من » یعنی زردی بیماری و ناتوانی را از من بستان و سرخی و شادابی و تندرستی را که در خود داری بمن ببخش » پس از سوخته شدن خاکستری را که از آتش میماند باید در خاک اندازی جمع کنند و از خانه بیرون برند و در کنار دیوار بریزند و آنکس که بیرون ریخته است در بازگشت در میزند باید از درون خانه از او بپرسند: «کیست ؟» و او هم جواب دهد؛ «منم » گویند: «از کجاآمده ای ؟» جواب دهد که : «از عروسی » بپرسند: «چه آورده ای ؟» گوید: «تندرستی ».<br />کوزه شکستن : مردم طهران تا چند سال پیش که از سر در نقاره خانه بالا میرفتند کوزه ای آب ندیده با خود میبردند و از آنجا بزمین می افکندند و میشکستند و کسانی که بدانجا دسترس نداشتند از بام خویش کوزه را بزمین می افکندند اینکار در بسیاری از نقاط ایران معمول است و عقیده دارند که بلاها و قضاهای بد را در کوزه متراکم کرده اندو چون بشکنند آن قضا و آن بلا دفع شود...<br />آجیل : در شب چهارشنبه سوری آجیل خوردن از رسوم و آداب مخصوص است و مخصوصاً بایستی آجیل شور و شیرین باشد... در میان زنان ایران درشب چهارشنبه سوری و حتی مواقع دیگری که کسی را مشکلی در پیش باشد و استجابت مرادی را بخواهد آجیل مخصوصی با آداب و حضور قلب خاصی معمول است که نذر میکنند وداستان شیرینی برای ابتکار آن میگویند...<br />آجیل مشکل گشا از آداب خاص شب چهارشنبه سوری نیست ولی کسانی که بدان اعتقاد کامل دارند گذشته از آنکه شب جمعه ٔ آخر هر ماه بدان عمل میکنند شب چهارشنبه سوری نیز به آداب آن میپردازند.<br />فالگوش : کسانی که حاجتی دارند شب چهارشنبه سوری نیت میکنند و بر سر چهارراهی یا اگر چهارراه نبود بر سر رهگذری به فالگوش میایستند و نخستین عابری را که گذشت بسخن او توجه میکنند و هر چه از دهان او برون آمد در استجابت مقصود خود به فال نیک یا به فال بد میگیرند اگر آن نخستین سخن به اجابت آرزوی صاحب حاجت مطابق باشد آن آرزوی برآورده است و گرنه برآورده نیست . همین فال را ممکن است بر پشت در خانه ای یا در اطاقی گرفت و باید آهسته بپشت درآمد و بی آنکه کسانی که اندرون خانه یا اطاقند بدانند که کسی بر در ایستاده است گوش فراداد و اولین سخنی را که گفته میشود در اجابت مقصود خود یا ناروا ماندن آن فال گرفت .<br />گره گشایی : کسانی که بخت ایشان گره خورده و عقده ای در کارشان روی داده است چاره ای جز آن ندارند که شب چهارشنبه سوری گوشه ٔ دستمالی یا چارقدی یا گوشه ٔ دیگر از جامه ٔ خود و یا پارچه ای را گره زنند و بر سر راهی بایستند و از اولین کسی که بر ایشان گذشت خواستار شوند که آن گره را بدست خود بگشاید ممکن است قفلی را بر پارچه یا دستمال و یا گوشه ای از جامه بست و بر سر راه ایستاد و کلید آن را به نخستین کسی که از راه میگذرد داد که با آن کلید قفل را بگشاید و عقده از کار فروبسته ٔ آن درمانده باز کند.<br />دفع چشم زخم و بخت گشایی : برای بخت گشایی در شب چهارشنبه سوری تدابیری معمول است و از همه شگفت تر آن است که به دبّاغ خانه میروند و از آب دباغ خانه اندکی برمیدارند و با خود بخانه می آورند و برای گشوده شدن بخت بر سر میریزند.<br />کندر و خوشبو: یکی از آداب چهارشنبه سوری آن است که زنان بر در دکان عطاری میروند و از او «کندر وشا برای کارگشا» میخواهند و تا عطار برود بیاورد فرار میکنند این دکان باید رو بقبله باشد سپس بدکان دیگری که رو بقبله باشد میروند و «خوشبو» میخواهند که مراداسفند است و چون عطار پی آن برود باز میگریزند و سپس بدکان سومی که رو بقبله باشد میروند و مقداری کندرو اسفند میخرند و در خانه برای دفع چشم زخم و حل مشکل خود دود میکنند.<br />قلیا سودن : یکی از وسایل دفع جادو در شب چهارشنبه سوری قلیا سودن است اندکی قلیای خشک در هاون برنجین کوچکی میریزند و هفت دختر نابالغ دسته میزنند و با آب میسایند و بر آن بول میکنند و آن آب را در چهارگوشه ٔ صحن خانه ای که آن را جادو کرده اند میریزند و یقین دارند که بهمین تدبیر جادو باطل میشود.<br />آش بیمار: در خانه ای که بیماری باشد شب چهارشنبه سوری باید در شفای او کوشید که بیماری او بسال دیگر نرسد برای این کار آشی میپزند که در میان زنان به اسم «آش بیمار» یا «آش امام زین العابدین بیمار» معروف است باید بادیه ٔ مسین بدست گرفت و با قاشق بدرخانه ای یا به در اطاق همسایه رفت و چنانکه او نداند که این خواهش از جانب کیست با آن قاشق بر آن ظرف مسین کوبید و صاحب خانه یا اطاق وجداناً مکلف است که چیزی که بتوان در آش ریخت مانند آرد یا برنج یا غلات و بنشن و پیاز و هر چه از این قبیل در خانه موجود باشد و اگر نیست چند شاهی پول در آن ظرف بریزد. هر چه در ظرف ریخته میشود باید در ترکیب آش داخل شود و اگرپول در آن ظرف دریوزه گری ریختند با آن پول باید لوازم آش را تدارک دیده و از آن آش بیمار را داد و بازمانده ٔ آن رابه تهی دستان رهگذر داد و همین آش هر دردی را شفا می بخشد.<br />فال گرفتن با بولونی : یکی از شیرین ترین آداب چهارشنبه سوری که بیشتر جنبه ٔ بازی و تفریح گوارایی دارد فال گرفتن با بولونی است . بولونی کوزه ٔ دهان گشاد کوچکی است که در خانه های ما فراوان است و در آن ادویه ٔ خشک یا ترشی ومربا و غیره میریزند زنان و دختران جوان گرد یکدیگرجمع میشوند و کوزه ای را می آورند هر کس هر چه همراه خود دارد و نشانه ای از او بشمار میرود در آن بولونی می اندازد و اشعار مختلف در وصف الحال که بتوان بدان تفأل کرد بر قطعه های کاغذ مینویسند و تا کرده در بولونی میاندازند سپس دختر نابالغی را میخوانند و او دست در بولونی میکند و پاره ای کاغذ را بیرون می آورد و یکی از حاضران شعری را که بر آن نوشته است میخواندسپس همان دختر یکی از آن اشیاء را بیرون می آورد و ارائه میدهد و آن شعر که خوانده شده است فالی است که در حق صاحب آن نشانی زده اند در اصفهان یک سرمه دان و یک آئینه ٔ کوچک نیز علاوه بر آن اشیاء در بولونی میاندازند و با دیوان حافظ تفأل میکنند یعنی هر چیزی که از بولونی بیرون آمد برای صاحب آن فالی از دیوان حافظ میزنند.<br />آداب چارشنبه سوری در شهرهای دیگر ایران : شهر تهران بهترین مجموعه ٔ آداب ملی ایران است ... و در آداب چهارشنبه سوری نیز مردم تهران تمام رسوم متداول را حفظ کرده اند...<br />در شیراز: آتش افروختن در معابر و خانه ها، فالگوش، اسپند سوختن، نمک گرد سر گرداندن ! در موقع اسفند دود کردن و نمک گردانیدن اوراد مخصوصی است که زنان میخوانند، قلمرو چهارشنبه سوری در شیراز صحن بقعه ٔ شاه چراغ است و در آنجا نیز توپ کهنه ای است که مانند توپ مروارید تهران زنان از آن حاجت میخواهند.<br />در کرمانشاه : مراسم چهارشنبه سوری چندان جالب دقت نیست و تنها چیزی که مرسوم است همان پریدن از روی آتش است .<br />در اصفهان : آتش افروختن در معابر؛ کوزه شکستن، فالگوش ؛ گره گشایی و غیره کاملاً متداول است و تمام آن آدابی که در طهران معمول است در اصفهان نیز رواج دارد و شکوه شب چهارشنبه سوری در اصفهان از تمام شهرهای ایران بیشتر است .<br />در مشهد: گره گشایی ؛ آتش افروختن ؛ کوزه شکستن و آتش بازی متداول است و علاوه بر آن تفنگ خالی کردن نیز معمول است و در هر خانه ای یکی دو تیر تفنگ میاندازند. در سایر شهرهای خراسان نیز چنین است .<br />در زنجان : آتش افروختن، فالگوش و کوزه شکستن معمول است و در کوزه شکستن اختصاصی که مردم زنجان دارند این است که پولی با آب در کوزه میاندازند و از بام زیر میافکنند. دیگر از خصوصیات مردم زنجان این است که دخترانی را که میخواهند زودتر شوهر بدهند به آب انبار میبرند و هفت گره بر جامه ٔ ایشان میزنند و پسران نابالغ باید آن هفت گره را بگشایند. یکی از آداب دیگر مردم زنجان این است که از روزنه ٔ بخاریها یا اجاقهای خانه طنابی داخل اطاق میکنند و بوسیله ٔ آن طناب چیزی طلب میکنند صاحب اطاق مکلف است اولین چیزی که در دسترس او بود بر طناب ببندد و چون طناب را بالاکشیدند بوسیله ٔ آن چیزی که بر طناب بسته اند فال میگیرند مثلاً اگر جاروبی بر طناب بسته باشند از آن فال بد میگیرند که خانه خراب خواهد شد و خانه ٔ ایشان را جاروب خواهند کرد و اگر پاره نانی ببندند فالی نیک میگیرند که وفور نعمت خواهد بود و اگر شیرینی به طناب ببندند نشانه ٔ شیرین کامی است .<br />در تبریز: آتش بازی و گره گشایی از قدیم معمول بوده است آتش افروختن در این اواخر متداول شده است . آجیل و میوه ٔخشک خوردن از ضروریات است و ترک نمیشود اگر دوست یامهمان و تازه واردی داشته باشند باید حتماً شب چهارشنبه سوری خوانچه ای از آجیل و میوه ٔ خشک برای او بفرستند دیگر از خصوصیات مردم تبریز آن است که از بام خانه ها بر سر عابرین آب میپاشند این عادت از آداب بسیارقدیم نژاد ایرانی است و در زمان ساسانیان معمول بوده است که در جشن نوروز مردم بر یکدیگر آب میپاشیده اند. و هنوز در میان ارمنیان و زردشتیان ایران هم معمول است که در یکی از جشنهای خود بر یکدیگر آب میریزند. در تبریز هم در میدان ارک توپی است مانند توپ مروارید طهران که زنان به آن متوسل میشوند. در آذربایجان مخصوصاً در شهر تبریز تیر انداختن در شب و چهارشنبه سوری بسیار متداول است و حتی بدرجه ای در این باب مبالغه می کردند که سابقاً در هر کجا فوج سربازی بود می بایست در آن شب صف بکشند و دسته جمع تیر بیندازند و صاحبمنصبان نمیتوانستند افواج خود را از این کار مانع گردند.<br />در ارومیه . شب چهارشنبه سوری بر بام خانه ها میروند و کجاوه ای را که زینت کرده و آرایش داده و بر آن طاقه شال کشمیری کشیده و آئینه بسته اند با طنابی از بام بسطح خانه فرود می آورند و میگویند: «بکش که حق مرادت رابدهد» کسی که در خانه است مکلف است که در آن کجاوه شیرینی و آجیل شور و شیرین و میوه ٔ خشک بریزد و پس از آنکه چیزی در آن ریختند با طناب آن را بالا میکشند و بخانه ٔ دیگر میبرند مخصوصاً دامادی که تازه زن گرفته و هنوز عروسی نکرده است موظف است که چنین کجاوه ای ببام خانه ٔ عروس ببرد و اگر نتوانند از بام بالا روند باید به پشت در روند و در پشت در پنهان شوند که کسی نبیند و آن کجاوه را در اطاق بیندازند و بهمین نهج چیزی طلب کنند. (نقل از مقاله ای تحت عنوان «چهارشنبه سوری » بقلم سعید نفیسی مندرج در شماره ٔ یازدهم سال اول و شماره ٔ اول سال دوم مجله ٔ مهر). دکتر محمد مقدم استاد زبان شناسی دانشکده ٔ ادبیات در جشن چهارشنبه سوری (اسفند <span class=\"hlight\" dir=\"rtl\">١٣٣٦</span> هَ . ش .) که در آن دانشکده برگزار شده سخنرانی کرده اند و مجله ٔ دانشکده ٔ ادبیات در شماره ٔ سوم سال پنجم خلاصه ٔ سخنرانی ایشان را چاپ کرده است که قسمتی از آن سخنرانی را در اینجا نقل میکنیم : خاستگاه چهارشنبه سوری مانندبسیاری دیگر از مشکلات تاریخی ایران باستان پوشیده بود تا «ذ.بهروز» در بررسیهای خود آن را روشن کرد (نگاه کنید به ذ.بهروز تقویم و تاریخ در ایران از رصد زردشت تا رصد خیام، زمان مهر و مانی، تهران <span class=\"hlight\" dir=\"rtl\">١٣٣١</span> شماره ٔ <span class=\"hlight\" dir=\"rtl\">١٥</span> ایران کوده ) اکنون میدانیم که شب چهارشنبه سوری جشنی است که مانند بیشتر جشنهای ایرانی که با ستاره شناسی بستگی دارند مبداء همه ٔ حسابهای علمی تقویمی است . در آن روز در سال <span class=\"hlight\" dir=\"rtl\">١٧٢٥</span> ق .م . زردشت بزرگترین حساب گاه شماری جهان را نموده کبیسه پدید آورده و تاریخهای کهن را درست و منظم کرده است . امسال که جشن چهارشنبه سوری میگیریم سه هزار و ششصد و هشتاد و سومین باری است که این جشن در ایران گرفته میشود. (مجله ٔ دانشکده ادبیات شماره ٔ <span class=\"hlight\" dir=\"rtl\">٣</span> سال پنجم ). رجوع شود بشماره ٔ <span class=\"hlight\" dir=\"rtl\">١١</span> سال اول و شماره ٔ <span class=\"hlight\" dir=\"rtl\">١</span> سال دوم مجله ٔ مهر و نشریه ٔ شماره ٔ <span class=\"hlight\" dir=\"rtl\">٢</span> انجمن ایرانشناس و شماره ٔ <span class=\"hlight\" dir=\"rtl\">١٥</span> ایران کوده . <BR><font color=\"Blue\">◄</font> چارشنبه ٔ آخرین ِ ماه صفر. (آنندراج ).<br /></font></div>'),
(282185, 'چارشنبهی', '<span class=\"hlight\">چارشنبهی .</span> <font color=\"DarkGreen\"><b>[ شَم ْ ب ِ ]</font></b> (ص نسبی ) منسوب به چارشنبه <span class=\"hlight\">:</span> <br />در منکر صنعتم بهی نیست <br />کالاّ شب چارشنبهی نیست .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282186, 'چارشوب', '<span class=\"hlight\">چارشوب .</span> (اِ مرکب ) چارسو. (ناظم الاطباء). بمعنی چارسو است و بترکی چارشو هم میگویند. (شعوری ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٣٢٩</span>) <span class=\"hlight\">:</span> <br />گر شودت مقتضی رفتن بازارها<br />ورنه مرو بهر هیچ جانب هر چارشوب .<br /><font color=\"Red\">(از شعوری ).</font><br /></font></div>'),
(282187, 'چارشکل', '<span class=\"hlight\">چارشکل .</span> <font color=\"DarkGreen\"><b>[ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (اِ مرکب ) اشکال اربعه ٔ منطق .<br /></font></div>'),
(282188, 'چارشیرینی', '<span class=\"hlight\">چارشیرینی .</span> (اِ مرکب ) چهارنوع شیرینی . مخلوطی از چار قسم شیرینی : گزانگبین، شکرسرخ، قند و نبات . رجوع به چهارشیرینی شود.<br /></font></div>'),
(282189, 'چارصباح', '<span class=\"hlight\">چارصباح .</span> <font color=\"DarkGreen\"><b>[ ص َ ]</font></b> (اِ مرکب ) چارروز.چارروزه ٔ عمر. چندروزه ٔ عمر؛ چارصباحی زنده بودن .<br /></font></div>'),
(282190, 'چارصد', '<span class=\"hlight\">چارصد.</span> <font color=\"DarkGreen\"><b>[ ص َ ]</font></b> (عدد مرکب، ص مرکب، اِ مرکب ) مخفف چهارصد. رجوع به چهارصد شود.<br /></font></div>'),
(282191, 'چارصنف حیوان', '<span class=\"hlight\">چارصنف حیوان .</span> <font color=\"DarkGreen\"><b>[ص ِ ف ِ ح َ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ح َ ی ْ ]</font></b> (اِ مرکب ) اصناف اربعه ٔ حیوان (انسان، پرندگان، خزندگان و چرندگان ) <span class=\"hlight\">:</span> <br />باد بر هفت فلک پایه ٔ تختش چندانک <br />چارصنف حیوان خواب و خور آمیخته اند.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(282192, 'چارصورت', '<span class=\"hlight\">چارصورت .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ مرکب ) (اصطلاح قمار) اصطلاحی در بازی آس و آن چهاربرگ در بازی آس است که دو برگ آن تصویر شاه و دو برگ تصویر بی بی باشد. دو شاه و دو بی بی . شاه جور بی بی .<br /></font></div>'),
(282193, 'چارضد', '<span class=\"hlight\">چارضد.</span> <font color=\"DarkGreen\"><b>[ ض ِ ]</font></b> (اِ مرکب ) چهارضد. چهارطبع. حرارت و برودت و رطوبت و یبوست . گرمی و سردی و تری و خشکی <span class=\"hlight\">:</span> <br />گفتم مزاج هست ستمگار و چارضد<br />گفتا که اعتدال سیم را بود ضرور.<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(282194, 'چارضرب', '<span class=\"hlight\">چارضرب .</span> <font color=\"DarkGreen\"><b>[ ض َ ]</font></b> (اِ مرکب ) نوعی از نوازش ساز که بهندی چوتالا گویند. (آنندراج ). نوعی از نواختن ساز. (ناظم الاطباء). قسمی نواختن ضرب است . <BR><font color=\"Blue\">◄</font> نوعی از نواختن ضرب که در زورخانه معمول است . <BR><font color=\"Blue\">◄</font> نوعی از اشغال صوفیان .(آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از تراشیدن موی ریش و بروت و ابرو که بعضی قلندران کنند. (آنندراج ). و چهار ضرب ابدال نیز همین است . (آنندراج ) <span class=\"hlight\">:</span> <br />در چارضرب، ابدال، ابرو تراشد از رو<br />تا هیچکس نگوید بالای چشمت ابرو.<br /> <font color=\"Red\">ابراهیم ادهم (از آنندراج ).</font><br />مه تازه گدای شرق و غرب است <br />در زیر تراش چارضرب است .<br /> <font color=\"Red\">زلالی (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">لعن چارضرب </span> ؛ نوعی لعن که شیعیان متعصب کنند.<br /><BR><font color=\"Blue\">◄</font> حساس هوشیار مانند برده . (ناظم الاطباء).<br /></font></div>'),
(282195, 'چارضرب زدن', '<span class=\"hlight\">چارضرب زدن .</span> <font color=\"DarkGreen\"><b>[ ض َ زَ دَ ]</font></b> (مص مرکب ) کنایه از ریش وبروت و دو ابرو تراشیدن . (آنندراج ). <BR><font color=\"Blue\">◄</font> آئین قلندران نامقید است، گویند فلانی چارضرب زده است . (آنندراج ). و رجوع به چهارضرب زدن شود.<br /></font></div>'),
(282196, 'چارضرب زده', '<span class=\"hlight\">چارضرب زده .</span> <font color=\"DarkGreen\"><b>[ ض َ زَ دَ<span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (ن مف مرکب ) موی ریش و بروت و ابرو و مژگان تراشیده که معمول بعضی قلندران است . (ناظم الاطباء).<br /></font></div>'),
(282197, 'چارضربه زدن', '<span class=\"hlight\">چارضربه زدن .</span> <font color=\"DarkGreen\"><b>[ ض َ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ زَ دَ]</font></b> (مص مرکب ) از جهات مختلف بهره بردن . از چند محل کسب درآمد کردن . از چند کس یا چند جا بهره مند شدن .<br /></font></div>'),
(282198, 'چارطاق', '<span class=\"hlight\">چارطاق .</span> (اِخ ) اسم مزرعه ای است از بلوک اقطاع کرمان . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br /></font></div>'),
(282199, 'چارطاق', '<span class=\"hlight\">چارطاق .</span> (اِخ ) چهارفرسخ و نیم میانه ٔ شمال و مغرب بیرم است . (فارسنامه ٔ ناصری ص <span class=\"hlight\" dir=\"rtl\">٢٨٨</span>).<br /></font></div>'),
(282200, 'چارطاق', '<span class=\"hlight\">چارطاق .</span> (اِخ ) ده از دهستان سراجو بخش مرکزی شهرستان مراغه <span class=\"hlight\" dir=\"rtl\">١٧</span> هزارگزی شمال باختری مراغه <span class=\"hlight\" dir=\"rtl\">١٨/٥</span> هزارگزی شمال خاوری شوسه ٔ مراغه دهخوارقان . دره دارای <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه . آب آن از رودخانه ٔ چارطاق و محصول آنجا غلات ونخود. شغل اهالی زراعت و صنایع دستی، گلیم بافی و راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(282201, 'چارطاق', '<span class=\"hlight\">چارطاق .</span> (اِخ ) اسم مزرعه ای است از مزارع بلوک سیرجان کرمان که رعایای نصرت آباد در آن زراعت میکنند. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br /></font></div>'),
(282202, 'چارطاق', '<span class=\"hlight\">چارطاق .</span> (اِخ ) یکی از دهات متعلقه ببلوک جهرم فارس است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>). پنج فرسخ میانه ٔ شمال و مشرق جهرم است . (فارسنامه ٔ ناصری ص <span class=\"hlight\" dir=\"rtl\">١٩٠</span>).<br /></font></div>'),
(282203, 'چارطاق', '<span class=\"hlight\">چارطاق .</span> (اِ مرکب ) اطاقی که در بالای سرایها بر چهار ستون بنا کنند. (حاشیه ٔ برهان چ معین ). طاقی که بر چهارپایه استوار باشد بی دیوار <span class=\"hlight\">:</span> «... و چارطاقها بساختند از چوب سخت بلند و آن را به گز بیاکندند...». (تاریخ بیهقی چ ادیب ص <span class=\"hlight\" dir=\"rtl\">٤٥٠</span>). <BR><font color=\"Blue\">◄</font> نوعی از خیمه ٔ چهارگوشه هم هست که آن را در عراق شروانی ودر هند راوئی گویند (برهان ). نوعی از خیمه که از چهارقطعه مرکب سازند. (آنندراج ). نوعی از خیمه ٔ چهارگوشه که شروانی نیز گویند. (ناظم الاطباء) <span class=\"hlight\">:</span> <br />نخواهم چارطاق خیمه ٔ دهر<br />وگر سازد طنابم طوق گردن .<br /> <font color=\"Red\">خاقانی .</font><br />فلک برزمین چارطاق افکنش <br />زمین بر فلک چارنوبت زنش .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> خیمه ٔ مطبخ را نیز گفته اند. (برهان ). قسمی خیمه که برای آشپزخانه میزنند. <BR><font color=\"Blue\">◄</font> و کنایه از عناصر اربعه باشد. (برهان ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آسمان . (ناظم الاطباء). افلاک . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کنایه است از دنیا <span class=\"hlight\">:</span> <br />مزن پنج نوبت در این چارطاق <br />که بی ششدره نیست این نه رواق .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> ظاهراً قسمی جامه بوده است <span class=\"hlight\">:</span> <br />تخت پوش سبز بر صحن چمن گسترده اند<br />چارطاق لاله بر مینای اخضر بسته اند.<br /> <font color=\"Red\">(از ترجمه ٔ محاسن اصفهان ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چارطاق کردن ِ در</span> ؛ هر دو مصراع آن را بالتمام گشادن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چارطاق گذاشتن در</span> ؛ هر دو مصراع را بالتمام باز گذاشتن . و رجوع به چهارطاق شود.<br /></font></div>'),
(282204, 'چارطاق ارکانی', '<span class=\"hlight\">چارطاق ارکانی .</span> <font color=\"DarkGreen\"><b>[ ق ِ اَ ]</font></b> (اِ مرکب ) دنیا. (آنندراج ) (مجموعه ٔ مترادفات ) <span class=\"hlight\">:</span> <br />بشمع روشن خورشید میزند پنجه <br />چراغ بخت تو در چارطاق ارکانی .<br /><font color=\"Red\">ملا منیر (از آنندراج ).</font><br /></font></div>'),
(282205, 'چارطاق افکن', '<span class=\"hlight\">چارطاق افکن .</span> <font color=\"DarkGreen\"><b>[ اَ ک َ ]</font></b> (نف مرکب ) کنایه از فراش باشد. (آنندراج ) <span class=\"hlight\">:</span> <br />فلک بر زمین چارطاق افکنش <br />زمین بر فلک چارنوبت زنش .<br /> <font color=\"Red\">نظامی (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> فراش و بستر . (ناظم الاطباء).<br /></font></div>'),
(282206, 'چارطاق خوابیدن', '<span class=\"hlight\">چارطاق خوابیدن .</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا دَ ]</font></b> (مص مرکب ) بر پشت خوابیدن . نوعی و شکلی از خفتن و دراز کشیدن که شخص به پشت خوابیده دو دست و دو پای را باز و دراز افکند.<br /></font></div>'),
(282207, 'چارطاقی', '<span class=\"hlight\">چارطاقی .</span> (اِخ ) قریه ای است از قرای غار. از اعمال طهران . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br /></font></div>'),
(282208, 'چارطاقی', '<span class=\"hlight\">چارطاقی .</span> (اِ مرکب ) بنایی که برسر قبر کنند بی دیوار یعنی چند ستون که بر آن سقفی است . طاقی بر چهار ستون نهاده بی دیواری و غالباً آن را بر سر گورها سازند. بنای بی دیواری که چهار ستون و یک سقف دارد و بیشتر بر سر قبرها سازند <span class=\"hlight\">:</span> <br />بیرون رود ز زیر فلک مشت خاک ما<br />گو چارطاقیی بسر خاک ما مپوش . <br /> <font color=\"Red\">قاسم مشهدی (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> نوعی از کلاه که چهار ترک دارد. (آنندراج ).<br /></font></div>'),
(282209, 'چارطبع', '<span class=\"hlight\">چارطبع.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِ مرکب ) طبایع اربعه . امزجه ٔ اربعه . حرارت و برودت و رطوبت و یبوست . گرمی و سردی و خشکی و تری <span class=\"hlight\">:</span> <br />گفتم که مرمرا گهر جسم باز گوی <br />گفتا که چارطبع بود جسم را گهر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />رنگ از دو سیه سفید بزدای <br />هندوی زچارطبع بگشای .<br /> <font color=\"Red\">نظامی .</font><br />مزاجت تر و خشک و گرم است و سرد<br />مرکب از این چارطبع است مرد.<br /> <font color=\"Red\">سعدی .</font><br />چارطبع مخالف سرکش <br />چند روزی بوند با هم خوش <br />گر یکی زین چهار شد غالب <br />جان شیرین برآید از قالب .<br /> <font color=\"Red\">سعدی .</font><br /> <BR><font color=\"Blue\">◄</font> آب و آتش و خاک و باد <span class=\"hlight\">:</span> <br />در این چارطبع مخالف نهاد<br />که آب آمد و آتش وخاک و باد.<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> بلغم و صفراو سودا و خون .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(282210, 'چارطرف', '<span class=\"hlight\">چارطرف .</span> <font color=\"DarkGreen\"><b>[ طَ رَ ]</font></b> (اِ مرکب ) چهارطرف . چارسمت . چارجانب . مشرق و مغرب و شمال و جنوب . <BR><font color=\"Blue\">◄</font> فوق و تحت و یمین و یسار.<br /></font></div>'),
(282211, 'چارطوفان', '<span class=\"hlight\">چارطوفان .</span> (اِمرکب ) چهارطوفان . چارنوع طوفان . طوفان آب و طوفان خاک و طوفان باد و طوفان آتش . عبارت از طوفان آب که بر قوم نوح علیه السلام رسیده و طوفان باد بر قوم هود علیه السلام و طوفان آتش بر قوم لوط علیه السلام و طوفان خاک بر قوم صالح علیه السلام . (آنندراج ) <span class=\"hlight\">:</span> <br />نه مرد این دبستان است هر دم جنبشی در وی <br />به هر دم چارطوفان نیست در بنیاد ارکانش .<br /> <font color=\"Red\">خاقانی .</font><br />عدلش ار بند طبایع نامدی <br />چارطوفان هر زمان برخاستی .<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> و بعضی نوشته اند که چارطوفان کنایه از جهل که ضد حکمت است دوم جبن که ضد شجاعت است سوم حرص که ضد عفت است چهارم جود که ضد عدالت است . (آنندراج ).<br /></font></div>'),
(282212, 'چارعلم', '<span class=\"hlight\">چارعلم .</span> <font color=\"DarkGreen\"><b>[ ع َ ل َ ]</font></b> (اِخ ) ظاهراً پیشوایان مذاهب اربعه (شافعی، حنفی، حنبلی، مالکی ). چارامام . چارخلیفه . چارتن پیشوایان مذاهب اهل سنت <span class=\"hlight\">:</span> <br />چارعلم رکن مسلمانی است <br />پنج دعا نوبت سلطانی است .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282213, 'چارعلیا', '<span class=\"hlight\">چارعلیا.</span> <font color=\"DarkGreen\"><b>[ ع ُل ْ ]</font></b> (اِخ ) قریه ای است از قرای قاینات قدیم النسق که از آب قناب مشروب میشود و معدودی سکنه دارد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br /></font></div>'),
(282214, 'چارعمل', '<span class=\"hlight\">چارعمل .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ]</font></b> (اِ مرکب ) چهارعمل حساب، جمع وتفریق و ضرب و تقسیم . و رجوع به چارعمل اصلی شود.<br /></font></div>'),
(282215, 'چارعمل اصلی', '<span class=\"hlight\">چارعمل اصلی .</span> <font color=\"DarkGreen\"><b>[ ع َ م َ ل ِ اَ ]</font></b> (ترکیب وصفی، اِ مرکب ) چهار عمل اصلی حساب . چهارعمل حساب . عمل جمع و عمل تفریق و عمل ضرب و عمل تقسیم . جمع و تفریق وضرب و تقسیم . افزایش (جمع) کاهش (تفریق ) زدن (ضرب ) بخش کردن (تقسیم کردن ) <font color=\"DarkGreen\"><b>[ واژه های نو فرهنگستان ]</font></b> .<br /></font></div>'),
(282216, 'چارعنصر', '<span class=\"hlight\">چارعنصر.</span> <font color=\"DarkGreen\"><b>[ ع ُ ص ُ ]</font></b> (اِ مرکب ) چهارعنصر. عناصر اربعه . چارآخشیج . آب و خاک و باد و آتش باشد <span class=\"hlight\">:</span> <br />از ایشان گشت پیدا چارعنصر<br />ز من بشنو تو این معنی ّ چون دُر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />باد امرت در زمین چون چارعنصر پیشرو<br />باد نامت درزمان چون هفت سیاره سمر.<br /> <font color=\"Red\">سنایی .</font><br />چارعنصر چاراستون قویست <br />که بر ایشان سقف دنیا مستویست <br />هر ستونی اشکننده ٔ آندگر<br />استن آب اشکننده ٔ هرشرر.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(282217, 'چارعیال', '<span class=\"hlight\">چارعیال .</span> <font color=\"DarkGreen\"><b>[ ع ِ ]</font></b> (اِ مرکب ) چهارعیال . عناصر اربعه . (مجموعه ٔ مترادفات ).<br /></font></div>'),
(282218, 'چارغ', '<span class=\"hlight\">چارغ .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (ترکی، اِ) نوعی از پای افزار است که بیشتر دهقانان بپای خودبندند. (برهان ). قسمی از پای افزار روستائیان . (ناظم الاطباء). پوزار. پای افزار دهقانان . نوعی کفش مخصوص که دهقانان و روستائیان پوشند. <BR><font color=\"Blue\">◄</font> نوعی کفش کردی است . (گناباد خراسان ). و رجوع به چارق شود.<br /></font></div>'),
(282219, 'چارفاریاب', '<span class=\"hlight\">چارفاریاب .</span> <font color=\"DarkGreen\"><b>[ فارْ ]</font></b>(اِخ ) یکی از قرای متعلقه به بلوک کوهمره ٔ شیراز است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br /></font></div>'),
(282220, 'چارفرس', '<span class=\"hlight\">چارفرس .</span> <font color=\"DarkGreen\"><b>[ ف َ رَ ]</font></b> (اِ مرکب ) چارعنصر. (حاشیه ٔ لیلی و مجنون چ وحید) <span class=\"hlight\">:</span> <br />آنگه شود این گره گشاده <br />کز چارفرس شوی پیاده .<br /><font color=\"Red\">نظامی (لیلی و مجنون ).</font><br /></font></div>'),
(282221, 'چارفرسخی', '<span class=\"hlight\">چارفرسخی .</span> <font color=\"DarkGreen\"><b>[ ف َ س َ ]</font></b> (اِخ )از قرای خبیص کرمان است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br /></font></div>'),
(282222, 'چارفرسنگ', '<span class=\"hlight\">چارفرسنگ .</span> <font color=\"DarkGreen\"><b>[ ف َ س َ ]</font></b> (اِخ ) مزرعه ای است از مزارع طبس، این مزرعه از آب قنات مشروب میشود. هوایش گرم است . دویست نفر سکنه دارد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br /></font></div>'),
(282223, 'چارفصل', '<span class=\"hlight\">چارفصل .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (اِ مرکب ) چهارفصل . چارموسم . چارهنگام . چارفصل سال . بهار و تابستان و پائیز و زمستان . ربیع و صیف و خریف و شتاء <span class=\"hlight\">:</span> <br />در چنین فصل تا بخانه ٔ شاه <br />داشته طبع چارفصل نگاه .<br /> <font color=\"Red\">نظامی .</font><br />آنچه مقصود شد در این پیکار<br />چارفصل است به ز فصل بهار.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282224, 'چارق', '<span class=\"hlight\">چارق .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِخ ) دهی از دهستان چهاردولی اسدآباد شهرستان همدان واقع در <span class=\"hlight\" dir=\"rtl\">١٠</span> هزارگزی شمال باختری قصبه ٔ اسدآباد و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی جنوب چنار. کوهستانی سردسیر با <span class=\"hlight\" dir=\"rtl\">٢٤١</span> نفر سکنه . آب آن از چشمه و محصول آن غلات و شغل اهالی زراعت و گله داری و صنایع دستی زنان قالی بافی و راه آن مالرو است . (فرهنگ جغرافیایی ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282225, 'چارق', '<span class=\"hlight\">چارق .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (اِخ ) از قرای خدابنده لوی خمسه و جدیدالنسق . ملکی نواب والا رکن الدوله محمدتقی میرزا است . هوایش ییلاق و زراعت آنجا دیمی و آبی است . یکرشته قنات دارد که محصول و صیفی آن را مشروب میسازد. سکنه ٔ اینقریه پانزده خانوار است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br /></font></div>'),
(282226, 'چارق', '<span class=\"hlight\">چارق .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (ترکی، اِ) چارغ .نوعی از پاافزار. (آنندراج ). نوعی از کفش صحرائیان .(غیاث ). چاروق . پوزار. پای افزار. پاپوش . چاموش . شم .پالیک . قسمی کفش . نوعی پاپوش . کفش درشت روستائیان . کفش های روستائیان از انبان کرده . نوعی کفش که از انبان کنند. پای افزار از پوست انبان که آن را با ریسمانهای کلفت به پای بندند و فقرای روستا و ساربانان پوشند. کفش ترکان و آن پوست ناپیراسته باشد که با قاتمه (طناب باریک پشمین ) به پای بندند. پاپوش که زیر آن پوست و روی آن ریسمان است . پاپوش دهاتی <span class=\"hlight\">:</span> <br />ای ایاز آن مهرها بر چارقی <br />چیست آخر همچو بربت عاشقی .<br /> <font color=\"Red\">مولوی .</font><br />همچو مجنون بر رخ لیلی خویش <br />کرده ای تو چارقی را دین و کیش .<br /> <font color=\"Red\">مولوی .</font><br />بنگریدند از یسار و از یمین <br />چارقی بدریده بود و پوستین .<br /> <font color=\"Red\">مولوی .</font><br />باز گفتند این مکان بی نوش نیست <br />چارق اینجا جزپی روپوش نیست .<br /> <font color=\"Red\">مولوی .</font><br />پوستین و چارق آمد از نیاز<br />در طریق عشق محراب ایاز.<br /> <font color=\"Red\">مولوی .</font><br />میرود هر روز در حجره ٔ برین <br />تا ببیندچارقی با پوستین .<br /> <font color=\"Red\">مولوی .</font><br />تو کجایی تا شوم من چاکرت <br />چارقت دوزم زنم شانه سرت .<br /> <font color=\"Red\">مولوی .</font><br />چارقت دوزم شپشهایت کشم <br />شیر پیشت آورم ای محتشم .<br /> <font color=\"Red\">مولوی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">یک پا گیوه یک پا چارق </span> ؛ کنایه است از فقری تمام .<br /><span class=\"hlight\">کرد را به مسجد راه دهند با چارقش آید</span> ؛ کنایه است از جهل و آداب ندانی .<br /></font></div>'),
(282227, 'چارقاپ', '<span class=\"hlight\">چارقاپ .</span> (اِ مرکب ) چهارقاپ . (اصطلاح قمار). بازی که با چهار پژول (بُجُل ) یا کعب (قاپ ) بازند. همچنانکه سه قاپ که با سه کعب بازی کنند. نوعی قمار که عوام الناس بازی کنند. نوع مخصوصی از قمار که بازی آن بجوانان روستائی یا شهرنشینان عامی و بی سواد اختصاص دارد. و رجوع به قاپ شود.<br /></font></div>'),
(282228, 'چارقب', '<span class=\"hlight\">چارقب .</span> <font color=\"DarkGreen\"><b>[ ق َ ]</font></b> (اِ مرکب ) پوشش مخصوص سلاطین توران . (آنندراج ). نوعی از لباس امراء. (غیاث ) <span class=\"hlight\">:</span> <br />هر شاه بیت من که در این طرز گفته ام <br />شاهان به گرد چارقب زر نوشته اند.<br /> <font color=\"Red\">نظام قاری .</font><br />چارقب را بپادشاهی رخت <br />کوس اقلیم پنجگانه زدند.<br /> <font color=\"Red\">نظام قاری .</font><br />دامن آلوده مکن چارقب هستی را<br />جامه ٔ عاریه را پاک نگه باید داشت .<br /><font color=\"Red\">شفیع اثر (از آنندراج ).</font><br /></font></div>'),
(282229, 'چارقد', '<span class=\"hlight\">چارقد.</span> <font color=\"DarkGreen\"><b>[ ق َ ]</font></b> (اِ مرکب ) جامه ای که زنان زیر چادر بر سر افکنند. پارچه ای سه گوشه یا چهارگوشه که زنان بر سر بندند. روسری . روپاک . معجر. مقنعه . خمار. نصیف . شالی که آن را دور سر پیچند و سر و گردن را بدان پوشند و ظاهراً مخفف «چادرقد» باشد. و رجوع بچادر شود.<br /></font></div>'),
(282230, 'چارقل', '<span class=\"hlight\">چارقل .</span> <font color=\"DarkGreen\"><b>[ ق ُ ]</font></b> (اِ مرکب ) چهارقل . چهارسوره ٔ قرآن کریم که هر یک از آن چهار با کلمه ٔ «قل » آغاز میشود و عبارتند از: قل هواﷲ احد، قل اعوذ برب الفلق، قل اعوذ برب الناس، قل یا ایها الکافرون . مجموع چهار سوره ٔ قل یا ایها الکافرون، قل هواﷲ احد، قل اعوذ برب الناس و قل اعوذ برب الفلق . چهار سوره از سوره های قرآن کریم بنام : سوره ٔ کافرون (قل یا ایها الکافرون )، سوره ٔ اخلاص (قل هواﷲ احد)، سوره ٔ ناس (قل اعوذ برب الناس )، سوره ٔ فلق (قل اعوذ برب الفلق ) <span class=\"hlight\">:</span> <br />هر زمان پیش شاه داد و ستم <br />چارقل بر چهارطبع بدم .<br /> <font color=\"Red\">سنایی .</font><br />پس در این راه با سلاسل و غل <br />چارقل حِرز تو ز دیومه کل (؟!).<br /><font color=\"Red\">سنایی .</font><br /></font></div>'),
(282231, 'چارقلم', '<span class=\"hlight\">چارقلم .</span> <font color=\"DarkGreen\"><b>[ ق َ ل َ ]</font></b> (اِ مرکب ) چهارقلم . چهاراستخوان . چهارقلم دست و پای . چهارساق (دو ساق دست ودو ساق پای ). چهار قلم استخوانی ساقهای دست و پا.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چارقلم سفید (اسبی که چهارساق سفید دارد)</span> .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چارقلم سیاه (اسبی که چهارساق سیاه دارد)</span> .<br /></font></div>'),
(282232, 'چارقون', '<span class=\"hlight\">چارقون .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) دهی از دهستان قره قریون بخش حومه ٔ شهرستان ماکو در <span class=\"hlight\" dir=\"rtl\">٣٢</span> هزارگزی جنوب خاوری ماکو و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی باختر صوفی بشوت . دره کوهستانی، معتدل، مالاریایی با<span class=\"hlight\" dir=\"rtl\">٢١٠</span> تن سکنه . آب آن از چشمه . محصول آنجا غلات و توتون و حبوبات . شغل اهالی زراعت و گله داری . صنایع دستی آن گلیم بافی و راه آن مالرو است . (فرهنگ جغرافیائی ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(282233, 'چارقویه', '<span class=\"hlight\">چارقویه .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) از مزارع هشون بلوک اقطاع کرمان است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br /></font></div>'),
(282234, 'چارلا', '<span class=\"hlight\">چارلا.</span> (اِ مرکب ) چارتا. چارتو. و رجوع به چارتا و چارتو شود.<br /></font></div>'),
(282235, 'چارلا کردن', '<span class=\"hlight\">چارلا کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) چارتا کردن . چارتو کردن .<br /></font></div>'),
(282236, 'چارلاشه', '<span class=\"hlight\">چارلاشه .</span> <font color=\"DarkGreen\"><b>[ ش َ <span class=\"hlight\" dir=\"rtl\">/</span>ش ِ ]</font></b> (اِ مرکب ) عناصر اربعه . چارآخشیج <span class=\"hlight\">:</span> <br />از پشت چارلاشه فرودآمده چو عقل <br />بر هفت مرکبات فلک ره بریده ایم .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(282237, 'چارلنگ', '<span class=\"hlight\">چارلنگ .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) از مزارع اقطان بلوک کرمان است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥١</span>).<br /></font></div>'),
(282238, 'چارلنگ', '<span class=\"hlight\">چارلنگ .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) چهارلنگ . نام قبیله ای از ایل بختیاری . طائفه ای از ایل بختیاری مشتمل بر پنج طائفه بزرگ . و رجوع به چهارلنگ شود.<br /></font></div>'),
(282239, 'چارلنگر', '<span class=\"hlight\">چارلنگر.</span> <font color=\"DarkGreen\"><b>[ ل َ گ َ ]</font></b> (اِ مرکب ) کشتی بزرگ که چهارلنگر داشته باشد. (آنندراج ) <span class=\"hlight\">:</span> <br />لنگر شکوه باد کند دفع، پس چرا<br />در چارلنگر است روان باد صرصرش .<br /> <font color=\"Red\">خاقانی .</font><br />چو طوفانی دیده ٔ تر شدم <br />ز مژگان خود چارلنگر شدم .<br /> <font color=\"Red\">ملاطغرا (از آنندراج ).</font><br />نگه تا شنا کرد در بحر دید<br />چنین کشتی چارلنگر ندید.<br /><font color=\"Red\">ظهوری (از آنندراج ).</font><br /></font></div>'),
(282240, 'چارلو', '<span class=\"hlight\">چارلو.</span> (اِ مرکب ) چهارلو. اصطلاحی در بازی ورق . نام یکی ازورق های بازی . ورق بازی که چهار خال دارد. نام ورقی از اوراق بازی که چهار خال بر آن نقش شده . نام هر ورقی از ورقهای بازی که چهار خال از یکی از خالهای مختلف بر روی آن نقش شده باشد. و رجوع به چهارلو شود.<br /></font></div>'),
(282241, 'چارلکات', '<span class=\"hlight\">چارلکات .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِ مرکب ) اصطلاحی در بازی قمار آس . چهار ورق ده خال، چهار ورق از چهارخال مختلف که بر روی هر یک ده خال نقش شده . ورق ده خال خاج (گشنیز) و ده خال خشت و ده خال پیک (گلابی سیاه ) و ده خال دل (گلابی قرمز) که در بازی آس چارلکات نام دارند.<br /></font></div>'),
(282242, 'چارم', '<span class=\"hlight\">چارم .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (عددترتیبی، ص نسبی ) چهارم . رابع. رابعة. و رجوع به چهارم شود.<br /></font></div>'),
(282243, 'چارم اسطرلاب', '<span class=\"hlight\">چارم اسطرلاب .</span> <font color=\"DarkGreen\"><b>[ رُ اُ طُ ]</font></b> (اِخ ) کنایه از قرآن مجید زیرا که کتاب چهارم است بعد از توراة و انجیل و زبور. (آنندراج ).<br /></font></div>'),
(282244, 'چارم عرض', '<span class=\"hlight\">چارم عرض .</span> <font color=\"DarkGreen\"><b>[ رُ ع َ رَ ]</font></b> (اِ مرکب ) چهارم عرض . بعضی نوشته اند که مجازاً بمعنی انسانی است چه انسان مرتبه ٔ چهارم است از جسم مطلق و جسم نامی و حیوان . (آنندراج ) (غیاث ).<br /></font></div>'),
(282245, 'چارم کتاب', '<span class=\"hlight\">چارم کتاب .</span> <font color=\"DarkGreen\"><b>[ رُ ک ِ ]</font></b> (اِخ ) چهارم کتاب . قرآن مجید را گویند. یعنی قرآن عظیم . (آنندراج )(شرفنامه ٔ منیری ). کتاب چهارم آسمانی پس از توراة وانجیل و زبور. قرآن کریم که پس از زبور داود و توراة موسی و انجیل عیسی کتاب چهارم آسمانی بشمار آید.<br /></font></div>'),
(282246, 'چارمادر', '<span class=\"hlight\">چارمادر.</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِ مرکب ) کنایه از چارعنصر. (برهان ) (آنندراج ). چهارعنصر. عناصر اربعه . چارآخشیج . امهات اربعه . آب و خاک و باد و آتش . چارآخشیجان <span class=\"hlight\">:</span> <br />گل آبستن از باد مانند مریم <br />هزاران پسرزاده از چارمادر.<br /> <font color=\"Red\">ناصرخسرو.</font><br />تا تربیت کنند سه فرزند کون را<br />ترکیب چارمادر و تأثیر نه پدر.<br /> <font color=\"Red\">انوری (دیوان چ نفیسی ص <span class=\"hlight\" dir=\"rtl\">١٢٠</span>).</font><br />بودند تانبود وجودش در این سرا<br />این چارمادر و سه موالید بی نوا.<br /> <font color=\"Red\">خاقانی .</font><br />کشت و زاد از پی بیشی غلامانش کنند<br />چارمادر که در این نه پدر آمیخته اند.<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> (اِخ ) چهارستاره ٔ نعش باشد از بنات النعش . (برهان ) (آنندراج ).<br /></font></div>'),
(282247, 'چارمان', '<span class=\"hlight\">چارمان .</span> (اِخ ) نام موضعی . مؤلف مرآت البلدان نویسد: در استیلای عرب بر عجم و فرار یزدجردبن شهریار به ری «باو» نامی از اهل طبرستان از اولاد ملوک عجم که ملتزم رکاب یزدجرد بود مرخصی حاصل نموده که به طبرستان رفته آتشکده ٔ آنجا را زیارت نماید و بعد ازورود قشون عرب به مملکت ری و انقلاباتی که در ایران اتفاق افتاد اهالی طبرستان «باو» را پادشاه خود نمودند و او «چارمان » را که معرب «بشارمان » میشود پایتخت خود قرارداد. بعد از پانزده سال سلطنت «ولاش » نام، او را بضرب خشتی که بشانه ٔ او فروکوفت بکشت و خود سلطنت طبرستان را تصاحب کرد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥١</span>).<br /></font></div>'),
(282248, 'چارمان', '<span class=\"hlight\">چارمان .</span> (اِخ ) مؤلف مرآب البلدان نویسد: و نیزچارمان اسم یکی از دهات طبرستان بوده چنانکه در تاریخ ظهیرالدین مسطور است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥١</span>).<br /></font></div>'),
(282249, 'چارماه', '<span class=\"hlight\">چارماه .</span> (اِ مرکب ) چهارماه . <BR><font color=\"Blue\">◄</font> کنایه از چهارنعل دست و پای اسب . (آنندراج ) <span class=\"hlight\">:</span> <br />پرماه و پرستاره شود هر زمان زمین <br />زآن چار شش ستاره که در چارماه اوست .<br /> <font color=\"Red\">(از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چارماه و چار شش ستاره </span> ؛ کنایه از چهار نعل دست و پای اسب که هر نعلی شش میخ دارد. (آنندراج ).<br /></font></div>'),
(282250, 'چارماهه', '<span class=\"hlight\">چارماهه .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (ص نسبی ) چهارماهه . منسوب به چارماه . کسی یا چیزی که چهار ماه بر او گذشته باشد.<br /></font></div>'),
(282251, 'چارمثقالی', '<span class=\"hlight\">چارمثقالی .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (ص نسبی ) چهارمثقالی . منسوب به چهارمثقال . <BR><font color=\"Blue\">◄</font> کلمه ای که در مورد تحقیر و توهین کسی بر زبان می آورند. نوعی دشنام . فحش و ناسزا.<br /></font></div>'),
(282252, 'چارمحال', '<span class=\"hlight\">چارمحال .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: از مضافات اصفهان و چهار ناحیه است معروف به محال اربعه و شرح هر ناحیه از قرار ذیل است :<br /><span class=\"hlight\" dir=\"rtl\">١</span> - ناحیه ٔ رار: حدود این ناحیه جنوبی به شیراز، شمالی به فریدن، شرقی به اصفهان، غربی به میزدج .<br /><span class=\"hlight\" dir=\"rtl\">٢</span> - ناحیه ٔ کیار: حدود آن شمالی به میزدج، جنوبی به کندمان، مغربی پشتکوه بختیاری، شرقی به لنجان .<br /><span class=\"hlight\" dir=\"rtl\">٣</span> - ناحیه ٔ میزدج : درجرگه واقع است اطرافش از هر سمت کوه است چمنی وسط این دشت هست مسمی به چمن «کران » تخمیناًیک فرسخ زمین چمن است . حدود ناحیه ٔ میزدج از اینقرار است : جنوبی به بلوک کیار، شرقی برار، غربی به بختیاری، شمالی به فریدن . تمام این بلوک مخروبه بوده است حاجی محمد رضاخان آباد کرده همه جا حمام و مسجد و قلعه و آسیا ساخته و از اطراف رعیت جمع کرده آورد به میزدج سکنی داد. دویست نفر نوکر سواره مخصوصاً مواجب میداد که این بلوک را محافظت و محارست نمایند بعد از حاجی محمد رضاخان، خانباباخان هم همین حالت را داشت این اوقات در حکومت آنها نیست . گویند خیلی خرابی بهمرسانیده است .<br /><span class=\"hlight\" dir=\"rtl\">٤</span> - ناحیه ٔ کندمان :حدود آن شمالی به میزدج، جنوبی به خاک شیراز، شرقی به سمیرم، غربی به بختیاری و پشتکوه . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> صص <span class=\"hlight\" dir=\"rtl\">٥١</span> - <span class=\"hlight\" dir=\"rtl\">٦٣</span>). و برای کسب اطلاع از اسامی قراء و مزارع و آبادیهای چارمحال و خصوصیات هر یک از آنها و وضع طبیعی و اقتصادی این ناحیه به کتاب «مرآت البلدان » ج <span class=\"hlight\" dir=\"rtl\">٤</span> صص <span class=\"hlight\" dir=\"rtl\">٥١</span>-<span class=\"hlight\" dir=\"rtl\">٥٤</span> رجوع شود.<br /></font></div>'),
(282253, 'چارمخالف', '<span class=\"hlight\">چارمخالف .</span> <font color=\"DarkGreen\"><b>[ م ُ ل ِ ]</font></b> (اِ مرکب ) چهارمخالف . چهارطبع. چارطبع. حرارت و برودت و رطوبت و یبوست . گرمی و سردی و خشکی و تری <span class=\"hlight\">:</span> <br />ز دور هفت رونده طمع مدارثبات <br />میان چارمخالف مجوی عیش لذیذ.<br /> <font color=\"Red\">سنایی .</font><br />ز سیر هفت مشعبد اسیر ششدره ام <br />ز دست چارمخالف بنای هشت درم .<br /> <font color=\"Red\">سنایی .</font><br /><BR><font color=\"Blue\">◄</font> صفرا و بلغم و سودا و خون .<br /></font></div>'),
(282254, 'چارمذهب', '<span class=\"hlight\">چارمذهب .</span> <font color=\"DarkGreen\"><b>[ م َ هََ ]</font></b> (اِخ ) کنایه از حنفی ̍، شافعی، مالکی و حنبلی . (آنندراج ) (غیاث ). چهارمذهب . چارمذهب اهل تسنن، مذهب حنفی، مذهب شافعی، مذهب حنبلی و مذهب مالکی .<br /></font></div>'),
(282255, 'چارمردان', '<span class=\"hlight\">چارمردان .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) اسم یکی ازمحلات دارالایمان قم است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>).<br /></font></div>'),
(282256, 'چارمرغ خلیل', '<span class=\"hlight\">چارمرغ خلیل .</span> <font color=\"DarkGreen\"><b>[ م ُ غ ِ خ َ]</font></b> (اِ مرکب ) کبوتر و زاغ و خروس و طاوس که حضرت خلیل (ع ) بموجب امر حق تعالی گوشت هر یک از آن چهاربر سرکوهی نهاد و باز بسوی خود طلب فرمود آنها زنده شده حاضر آمدند. (آنندراج ) (غیاث ). <BR><font color=\"Blue\">◄</font> در ذبح طیور مذکور اشارت است بدان که کبوتر کنایه از الفت خلق و از خروس شهوت و از زاغ حرص مال و از طاوس زیب و آرایش ظاهری یعنی هر چهار صفات، ترک کن . (آنندراج ).<br /></font></div>'),
(282257, 'چارمسمار', '<span class=\"hlight\">چارمسمار.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِ مرکب ) در این شعر ظاهراً کنایه از چارطبع است <span class=\"hlight\">:</span> <br />جان کندن تن به چارمسمار<br />بر رقص رحیل هست دشوار.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282258, 'چارمضراب', '<span class=\"hlight\">چارمضراب .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِ مرکب ) اصطلاحی در موسیقی، اصطلاحی در نواختن آهنگ موسیقی . نوعی از آهنگ موسیقی که نوازنده ٔ سازدر دستگاههای مختلف آواز مینوازد تا آوازخوان برای خواندن مهیا شود. گونه ای از زدن که زننده خواننده رابرای خواندن مهیا سازد. و رجوع به چهارمضراب شود.<br /></font></div>'),
(282259, 'چارمغز', '<span class=\"hlight\">چارمغز.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِ مرکب ) چهارمغز. جوز را گویند که گردکان است . (برهان ). تخم درختی است از قسم میوه به فارسی گردکان و به هندی اکهروت گویند. (آنندراج ). جوز مغز فارسی که بهندش اکهروت نامند. (شرفنامه ٔ منیری ). گردکان که چهارمغز دارد.جوز. گردو. گوز. خسف . جوز چارمغز. ضَبْر و ضَبِر؛ درخت چارمغز. لُب ّ، چارمغز گردکان است . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> مغز تخمه ٔ کدو و خربزه و هندوانه و خیار. <BR><font color=\"Blue\">◄</font> مغز پسته و فندق و بادام و گردو.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دهن الجوز</span> ؛ روغن چارمغز.<br />و رجوع به گردکان شود.<br /></font></div>'),
(282260, 'چارملک', '<span class=\"hlight\">چارملک .</span> <font color=\"DarkGreen\"><b>[ م َ ل َ ]</font></b> (اِخ ) چهارملک . چهار فرشته ٔ مقرب خدا.جبرئیل و میکائیل و اسرافیل و عزرائیل <span class=\"hlight\">:</span> <br />گاهی براق چارملک را لگام گیر<br />گاهی به دیو هفت سری بر کند لگام .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(282261, 'چارمنزل', '<span class=\"hlight\">چارمنزل .</span> <font color=\"DarkGreen\"><b>[ م َ زِ ]</font></b> (اِ مرکب ) چهارمنزل . شریعت، طریقت، معرفت، حقیقت . (آنندراج ) (غیاث ). منزل شریعت، منزل طریقت، منزل معرفت، منزل حقیقت، شریعت و طریقت و معرفت و حقیقت .<br /></font></div>'),
(282262, 'چارمنگل', '<span class=\"hlight\">چارمنگل .</span> <font color=\"DarkGreen\"><b>[ م َ گ َ ]</font></b> (اِ مرکب ) کسی که قولنج کند و از حرکت بیفتد، گویند چارمنگل مانده است یعنی یارای حرکت بهیچ سوی ندارد. (لهجه ٔ قزوین ).<br /></font></div>'),
(282263, 'چارموج', '<span class=\"hlight\">چارموج .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> مُو ]</font></b> (اِ مرکب ) چهارموج . چارموجه . طوفان . گرداب که بهندی «بهنور» گویند. (آنندراج ) <span class=\"hlight\">:</span> <br />کسی کزشش جهت کرده کناره <br />فتد در چارموج از حسن پنجاب .<br /> <font color=\"Red\">آرزو (از آنندراج ).</font><br />و رجوع به چارموجه شود.<br /></font></div>'),
(282264, 'چارموجه', '<span class=\"hlight\">چارموجه .</span> <font color=\"DarkGreen\"><b>[ م َ ج َ <span class=\"hlight\" dir=\"rtl\">/</span> ج ِ]</font></b> (اِ مرکب ) چهارموجه . چهارموج . چارموج . غرقاب . طوفان . بمعنی گرداب . (غیاث ). طوفان دریایی <span class=\"hlight\">:</span> <br />آید به چارموجه ٔ دریای حسن تو<br />لرزد به خود چو کشتی بی لنگر آینه .<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br />و رجوع به چارموج شود.<br /></font></div>'),
(282265, 'چارموران', '<span class=\"hlight\">چارموران .</span> (اِخ ) جزء کهکیلویه است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>).<br /></font></div>'),
(282266, 'چارمکان', '<span class=\"hlight\">چارمکان .</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) از دهات متعلقه به کوهمره ٔ شیراز است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span>ص <span class=\"hlight\" dir=\"rtl\">٦٥</span>).<br /></font></div>'),
(282267, 'چارمی', '<span class=\"hlight\">چارمی .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (عدد ترتیبی، ص نسبی ) چهارمی . چهارمین . چیزی در مرتبه ٔ چهارم . و رجوع به چارمین شود.<br /></font></div>'),
(282268, 'چارمیخ', '<span class=\"hlight\">چارمیخ .</span> (اِ مرکب ) چهارمیخ . نوعی شکنجه . معروف است و آن چنان باشد که شخصی را خواهند شکنجه کنند بر پشت یا به روی خوابانند و چهار دست و پای او را به میخ بندند. (برهان ). نوعی از سیاست مقرری و آن چنان باشد که شخصی را که خواهند شکنجه کنند بر پشت یا به رو بخوابانند و هر چهار دست و پای او را محکم بر میخ بربندند. (آنندراج ). نوعی از تعذیب که مجرم را به چهارمیخ دست و پا بندند. (غیاث ) <span class=\"hlight\">:</span> <br />عدل تو ظلم و فتنه را نعل گرفت لاجرم <br />هر دو چو نعل مانده اند ازتو به چارمیخ در.<br /> <font color=\"Red\">مجیر بیلقانی .</font><br />جان یوسف زاد را کآزاد کرده ٔ همت است <br />وا رهان زین چارمیخ هفت زندان وا رهان .<br /> <font color=\"Red\">خاقانی .</font><br />درختی است شش پهلو وچاربیخ <br />تنی چند را بسته بر چارمیخ .<br /> <font color=\"Red\">نظامی .</font><br />یا برین تخت شمع من مفروز<br />یا چو تختم به چارمیخ بدوز.<br /> <font color=\"Red\">نظامی .</font><br />دشمنش چون درخت بیخ زده <br />بر در او به چارمیخ زده .<br /><font color=\"Red\">نظامی .</font><br />دچار چارمیخ و شکنجه و عذاب و قطع دستها میشود. (بهاءالدین ولد).<br />خون خوری در چارمیخ تنگنا<br />در میان حبس و انجاس و عنا.<br /> <font color=\"Red\">مولوی .</font><br />چارمیخ شه ز رحمت دور نی <br />چارمیخ حاسدی مغفور نی .<br /> <font color=\"Red\">مولوی .</font><br />دعوی خود را چو کاذب یافت پیش خلق تو<br />خویش را بر چارمیخ خار زدناچار گل .<br /> <font color=\"Red\">اشرف (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> کنایه از عناصر اربعه هم هست . (برهان ) <span class=\"hlight\">:</span> <br />شش جهت را ز هفت بیخ برآر<br />نه فلک را به چارمیخ برآر.<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> عمل لواطه را نیزگویند. (برهان ).<br /></font></div>'),
(282269, 'چارمیخ شدن', '<span class=\"hlight\">چارمیخ شدن .</span> <font color=\"DarkGreen\"><b>[ ش ُ دَ ]</font></b> (مص مرکب ) چهارمیخ شدن . تعذیب و شکنجه شدن . نوعی از تعذیب مجرمان که دراز بر زمین انداخته به چهارمیخ دست و پا بندند. (آنندراج ) (غیاث ) <span class=\"hlight\">:</span> <br />درسم رخشت که زمین راست بیخ <br />خصم توچون نعل شده چارمیخ .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> کمال محکم شدن . (آنندراج ) (غیاث ). و با لفظ شدن کنایه از نهایت قیام و استواری . (آنندراج در معنی چارمیخ ) <span class=\"hlight\">:</span> <br />جناح از هوا در زمین برد بیخ <br />پساهنگ شد در زمین چارمیخ .<br /><font color=\"Red\">نظامی (از آنندراج ).</font><br /></font></div>'),
(282270, 'چارمیخ کردن', '<span class=\"hlight\">چارمیخ کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) استوار کردن با چهارمیخ . کسی یا چیزی را به وسیله ٔ چهارمیخ به جایی بستن و استوار نمودن <span class=\"hlight\">:</span> <br />درختی راکه بینی تازه بیخش <br />کند روزی ز خشکی چارمیخش .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> نوعی از سیاست که گناهکار را با دوختن هریک از چهار کف دستها و پایها به جایی استوارکردندی <span class=\"hlight\">:</span> <br />در هفت دوزخ از چه کنی چارمیخشان <br />ویل ٌ لهم عقیله ٔ من بس عقابشان .<br /> <font color=\"Red\">خاقانی .</font><br />چارمیخت کرده ام من، راست گو<br />راست پیش آور دروغی را مجو.<br /> <font color=\"Red\">مولوی .</font><br /><BR><font color=\"Blue\">◄</font> ثابت و مقرر کردن دعوی با ادله واسناد و اقرارها. <BR><font color=\"Blue\">◄</font> و با لفظ کردن، کنایه از عمل لواطه کردن . (آنندراج درمعنی چارمیخ ).<br /></font></div>'),
(282271, 'چارمیخ کشیدن', '<span class=\"hlight\">چارمیخ کشیدن .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ دَ ]</font></b> (مص مرکب ) چهارمیخ کشیدن . شکنجه کردن . گناهکار را به چارمیخ بستن . نوعی تعذیب . قسمی کیفر دادن مجرم و بزه کار <span class=\"hlight\">:</span> <br />گر جز بتو محکم است بیخم <br />برکش چوصلیب چارمیخم .<br /> <font color=\"Red\">نظامی .</font><br />اصل قانون شریعت کاحتساب شرع او<br />میکشد آهنگ را بر چارمیخ چارتار.<br /><font color=\"Red\">اشرف (از آنندراج ).</font><br /></font></div>'),
(282272, 'چارمیخه', '<span class=\"hlight\">چارمیخه .</span> <font color=\"DarkGreen\"><b>[ خ َ <span class=\"hlight\" dir=\"rtl\">/</span> خ ِ ]</font></b> (ص مرکب ) چهارمیخه . استوار. محکم . پابرجا. تزلزل ناپذیر.<br /></font></div>'),
(282273, 'چارمیخه کردن', '<span class=\"hlight\">چارمیخه کردن .</span> <font color=\"DarkGreen\"><b>[ خ َ <span class=\"hlight\" dir=\"rtl\">/</span> خ ِ ک دَ ]</font></b> (مص مرکب ) چهارمیخه کردن . سخت محکم و استوارکردن . استوار ساختن کاری یا امری . پابرجا نمودن .<br /></font></div>'),
(282274, 'چارمیخی', '<span class=\"hlight\">چارمیخی .</span> (ص نسبی ) چهارمیخی . استوار. محکم <span class=\"hlight\">:</span> <br />زین پوده درخت چاربیخی <br />می بُرّم عرق چارمیخی .<br /><font color=\"Red\">نظامی (لیلی و مجنون ص <span class=\"hlight\" dir=\"rtl\">٢٣٠</span>).</font><br /></font></div>'),
(282275, 'چارمین', '<span class=\"hlight\">چارمین .</span> <font color=\"DarkGreen\"><b>[ رُ ]</font></b> (ص نسبی ) چهارمین . منسوب به عدد چهار. چیزی در مرتبه ٔ چهارم <span class=\"hlight\">:</span> <br />پهلوی عیسی نشینم بعد از این <br />بر فراز آسمان چارمین .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(282276, 'چارناچار', '<span class=\"hlight\">چارناچار.</span> (ق مرکب ) چار و ناچار. ناگزیر. (آنندراج ). بالضروره . (آنندراج ). لاعلاج . اجباراً.<br /></font></div>'),
(282277, 'چارنعل', '<span class=\"hlight\">چارنعل .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b>(اِ مرکب ) چهارنعل . نوعی از راه رفتن اسب . نوعی از دویدن اسب . راندن اسب بشتاب . قسمی از دوانیدن اسب .<br /></font></div>'),
(282278, 'چارنعل رفتن', '<span class=\"hlight\">چارنعل رفتن .</span> <font color=\"DarkGreen\"><b>[ ن َ رَ ت َ ]</font></b> (مص مرکب ) چهارنعل رفتن . تند رفتن اسب . دویدن اسب .<br /></font></div>'),
(282279, 'چارنفس', '<span class=\"hlight\">چارنفس .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِ مرکب ) چهارنفس . نفس اماره، نفس لوامه، نفس ملهمه، نفس مطمئنه . (آنندراج ). چارنفس اماره و لوامه و ملهمه و مطمئنه <span class=\"hlight\">:</span> <br />به چارنفس و سه روح و دو صحن و یک فطرت <br />به یک رقیب و دو فرع و سه نوع وچار اسباب .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(282280, 'چارنه', '<span class=\"hlight\">چارنه .</span> <font color=\"DarkGreen\"><b>[ ن ُه ْ ]</font></b> (اِ مرکب ) چهارنه . چهار ورق از اوراق بازی که بر روی هر یک نه خال نقش شده . نه خال گشنیز (خاج ) و نه خال پیک (گلابی سیاه ) و نه خال دل (گلابی قرمز). و نه خال خشت .<br /></font></div>'),
(282281, 'چاره', '<span class=\"hlight\">چاره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (اِ) علاج . (برهان ) (آنندراج ) (غیاث ) (انجمن آرا). معالجه . مداوا. درمان . دارو. دفع. رفع. عَندَد. وعی . (منتهی الارب ) <span class=\"hlight\">:</span> <br />بیلفغده باید کنون چاره نیست <br />بیلفنجم و چاره ٔ من یکی است .<br /> <font color=\"Red\">ابوشکور.</font><br />گفتا مرا چه چاره که آرام هیچ نیست <br />گفتم که زود خیز و همی گرد چام چام .<br /> <font color=\"Red\">منجیک (از لغت فرس اسدی ص <span class=\"hlight\" dir=\"rtl\">٣٤٦</span>).</font><br />او سنگدل و من بمانده نالان <br />چرویده و رفته ز دست چاره .<br /> <font color=\"Red\">منجیک .</font><br />چون نمک خود تبه شود چه علاج <br />چاره چه غرقه را ز رود برک .<br /> <font color=\"Red\">خسروی .</font><br />پرستنده برخاست از پیش اوی <br />سوی چاره بیچاره بنهاد روی .<br /> <font color=\"Red\">فردوسی .</font><br />به دل گفت خود کرده راچاره نیست <br />به کس بر اینکار بیغاره نیست .<br /> <font color=\"Red\">فردوسی .</font><br />مرآن درد را راه و چاره ندید<br />بسی باد سرد از جگر برکشید.<br /> <font color=\"Red\">فردوسی .</font><br />فراوان بگفتند و انداختند<br />مر آن کار را چاره نشناختند.<br /> <font color=\"Red\">فردوسی .</font><br />ورا برگزیدند ایرانیان <br />که آن چاره را تنگ بندد میان .<br /> <font color=\"Red\">فردوسی .</font><br />ز هر گونه نیرنگها ساختند<br />مرآن درد را چاره نشناختند.<br /> <font color=\"Red\">فردوسی .</font><br />چوایرانیان آگهی یافتند<br />یکایک سوی چاره بشتافتند.<br /> <font color=\"Red\">فردوسی .</font><br />به نزدیک گرسیوز آمد نوند<br />که بر چاره ٔ جان میان را ببند.<br /> <font color=\"Red\">فردوسی .</font><br />سپه را که چون او نگهبان بود<br />همه چاره ٔ جنگ آسان بود.<br /> <font color=\"Red\">فردوسی .</font><br />پر از درد گشتم سوی چاره باز<br />بدان تا نماند تن اندر گداز.<br /> <font color=\"Red\">فردوسی .</font><br />از آن درد «گردوی » غمخواره گشت <br />وز اندیشه ٔ دل سوی چاره گشت .<br /> <font color=\"Red\">فردوسی .</font><br />می زدگانیم ما در دل ما غم بود<br />چاره ٔ ما بامداد رطل دمادم بود.<br /> <font color=\"Red\">منوچهری .</font><br />ای ملک زداینده ٔ هر ملک زدایان <br />ای چاره ٔ بیچاره وای مفزع زوار.<br /> <font color=\"Red\">منوچهری .</font><br />باده فراز آورید چاره ٔ بیچارگان <br />قوموا شرب الصبوح یا ایهاالنائمین .<br /> <font color=\"Red\">منوچهری .</font><br />چو چاره نبد جنگی و لشکری <br />گرفتند زنهار و خواهشگری .<br /> <font color=\"Red\">اسدی .</font><br />به هر کار بر نیک و بد چاره هست <br />جز از مرگ کش چاره ناید بدست .<br /> <font color=\"Red\">اسدی .</font><br />همی ندانم چاره ٔ فراق وین نه عجب <br />که هیچ عاقل خود کرده را نداند چار.<br /> <font color=\"Red\">قطران .</font><br />داود گفت یا جبرئیل چاره ٔ این چیست و چه کنم ؟. (قصص الانبیاء ص <span class=\"hlight\" dir=\"rtl\">١٥٤</span>). چاره نمی شناسم از اعلام آنچه حادث شود. (کلیله و دمنه ).<br />همی خوانند و میرانند ما را<br />نیابد کس همی زین کار چاره .<br /> <font color=\"Red\">ناصرخسرو.</font><br />دل بیمار را دوا بتوان <br />حمق را هیچگونه چاره مدان .<br /> <font color=\"Red\">سنایی .</font><br />با این غم و درد بی کناره <br />داروی فرامشی است چاره .<br /> <font color=\"Red\">نظامی .</font><br />دانک هر رنجی ز مردن پاره ای است <br />جُزوِ مرگ از خود بران گر چاره ای است .<br /> <font color=\"Red\">مولوی (مثنوی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٤٢</span>).</font><br />بنال سعدی اگر چاره ٔ وصالت نیست <br />که نیست چاره ٔ بیچارگان بجز زاری .<br /> <font color=\"Red\">سعدی .</font><br />با جور و جفای تو نسازم چه بسازم ؟<br />چون زهره و یارانبود چاره مداراست .<br /> <font color=\"Red\">سعدی .</font><br />دست با سرو روان چون نرود در گردن <br />چاره ای نیست بجز دیدن و حسرت خوردن .<br /> <font color=\"Red\">سعدی .</font><br />یارش از کشتی بدر آمد که پشتی کند همچنین درشتی دید و پشت بداد چاره جز آن ندانستند که با اوبمصالحت گرایند. (گلستان سعدی ).<br />گفتم تو گربه ای نه شتر گفت چاره چیست <br />در حیز زمانه شتر گربه ها بسی است .<br /> <font color=\"Red\">سلمان ساوجی .</font><br /> <BR><font color=\"Blue\">◄</font> تدبیر کردن باشد و حیلت در کار. (صحاح الفرس ). تدبیر بود. (فرهنگ خطی ). و تدبیر باشد. (برهان ). تدبیر و اصلاح فساد امری . (آنندراج ). تدبیر. (غیاث ). حیلت . وسیله . تفکر و تأمل در انجام امور. راه اندیشی . وسیلت جویی . فن . اندیشه <span class=\"hlight\">:</span> <br />ای بر تو رسیده بهر تنگ چاره ای <br />از حال من ضعیف براندیش چاره ای .<br /> <font color=\"Red\">رودکی (از صحاح الفرس ).</font><br />بر این چاره اکنون که جنبد ز جای ؟<br />که خیزد میان بسته این را بپای ؟<br /> <font color=\"Red\">فردوسی .</font><br />به تنگی یک اندر دگر بافته <br />بچاره سر شوشه بر تافته .<br /> <font color=\"Red\">فردوسی (شاهنامه <span class=\"hlight\" dir=\"rtl\">١٠٦٢/٢٠</span>).</font><br />به «خراد برزین » چنین گفت شاه <br />که بگزین بر این کار بر چاره راه .<br /> <font color=\"Red\">فردوسی .</font><br />چو در طاس لغزنده افتاد مور<br />رهاننده را چاره باید نه زور.<br /> <font color=\"Red\">فردوسی .</font><br />کنون چاره ای هست نزدیک من <br />مگوی این سخن بر سر انجمن .<br /> <font color=\"Red\">فردوسی .</font><br />به زندان تنگ اندر آمد تخار<br />بدان چاره با جامه ٔ کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />بچاره سر چاه راه کرده کور<br />که مردم ندیدی نه چشم ستور.<br /> <font color=\"Red\">فردوسی .</font><br />بیامد بدرگاه فرخ پدر<br />دلی پر ز چاره پر از کینه سر.<br /> <font color=\"Red\">فردوسی .</font><br />پر از چاره و مهر و نیرنگ و رنگ <br />همه ازدر مرد فرهنگ و سنگ .<br /> <font color=\"Red\">فردوسی .</font><br />بسنده نباشی تو بالشکرش <br />نه با چاره و گنج و با کشورش .<br /> <font color=\"Red\">فردوسی .</font><br />ز کنده بصد چاره اندر گذشت <br />عنان را گران کرد بر سوی دشت .<br /> <font color=\"Red\">فردوسی .</font><br />یکی سخت پیمان ستدزو نخست <br />بچاره دلش را ز کینه بشست .<br /> <font color=\"Red\">فردوسی .</font><br />کرا گفت آتش زبانش نسوخت <br />بچاره بد از تن بباید سپوخت .<br /> <font color=\"Red\">فردوسی .</font><br />بپرسید ازو «کید»و غمخواره گشت <br />ز پرسش سوی دانش و چاره گشت .<br /> <font color=\"Red\">فردوسی .</font><br />بخندید و با او چنین گفت شاه <br />که چاره به از جنگ ای نیکخواه .<br /> <font color=\"Red\">فردوسی .</font><br />دبیر نویسنده را پیش خواند<br />وز آن چاره و جنگ لختی براند.<br /> <font color=\"Red\">فردوسی .</font><br />چنین تا بنزدیک کوه سپند<br />لب از چاره ٔ خویش در خندخند.<br /> <font color=\"Red\">فردوسی .</font><br />چو از چاره دلهابپرداختند<br />فرستاده را پیش بنشاختند.<br /> <font color=\"Red\">فردوسی .</font><br />شما چاره ها هر چه دانید زود<br />ز نیک و ز بد بازرانید زود.<br /> <font color=\"Red\">فردوسی .</font><br />بچاره بنزدیک مردم کشید<br />نهفته همه سودمندی گزید.<br /><font color=\"Red\">فردوسی .</font><br />بدان چاره تا مرد بیکار خون <br />نریزد نباشد ببد رهنمون .<br /> <font color=\"Red\">فردوسی .</font><br />چو بشنید افراسیاب این سخن <br />غمی گشت و پس چاره افکند بن .<br /> <font color=\"Red\">فردوسی .</font><br />مر او را بچاره ز روی زمین <br />نگونش برافکند بر پشت زین .<br /> <font color=\"Red\">فردوسی .</font><br />بچاره به رویین دژ اندرشدم <br />جهانی برآنگونه برهم زدم .<br /> <font color=\"Red\">فردوسی .</font><br />وزآن چاره هایی که میساختم <br />که تا دل ز کینه بپرداختم .<br /> <font color=\"Red\">فردوسی .</font><br />که من خود از او سخت آزرده ام .<br />بدل چاره ٔ کشتنش کرده ام .<br /> <font color=\"Red\">فردوسی .</font><br />که کین پدربازجست از نیا.<br />بشمشیر وبر چاره و کیمیا.<br /> <font color=\"Red\">فردوسی .</font><br />بدین چاره، گر زو نیابم رها<br />شوم بی گمان در دم اژدها.<br /> <font color=\"Red\">فردوسی .</font><br />به چاره بودی اگر بودی اندر او نخجیر<br />به بیم رفتی اگر رفتی اندر او شیطان .<br /> <font color=\"Red\">عنصری (در صفت بیابان صعب ).</font><br />بچاره آسیا سازند بر باد<br />برآرند از میان رود بنیاد.<br /> <font color=\"Red\">فخرالدین گرگانی .</font><br />سپه را چنین پنج ره برگماشت <br />بصد چاره برجایگهشان بداشت .<br /> <font color=\"Red\">اسدی .</font><br />بهر کار در زورکردن مشور<br />که چاره بسی جای بهتر ز زور.<br /> <font color=\"Red\">اسدی .</font><br />یکی چاره هزمان نماید همی <br />بدان چاره جانمان رباید همی .<br /> <font color=\"Red\">اسدی .</font><br />یلان را به پیکار وکین برگماشت <br />بصد چاره آن رزم تا شب بداشت .<br /> <font color=\"Red\">اسدی .</font><br />راست نگردد دروغ و مکر بچاره <br />معصیتت را بدین دروغ میاچار.<br /> <font color=\"Red\">ناصرخسرو (دیوان چ تقوی ص <span class=\"hlight\" dir=\"rtl\">١٦٦</span>).</font><br />و آن همه به مردی و چاره دفع کرد تا به شهرستان زرین رسید. (مجمل التواریخ ) گوید <font color=\"DarkGreen\"><b>[ نافع ]</font></b> برفتیم نزدیک کوه <font color=\"DarkGreen\"><b>[ دماوند ]</font></b> بدیهی باستادیم وچاره ٔ برشدن همی طلبیدیم . (مجمل التواریخ ). دشمن چو از همه چاره ای فروماند سلسله ٔ دوستی جنباند. (گلستان چ یوسفی ص <span class=\"hlight\" dir=\"rtl\">١٧٤</span>). <BR><font color=\"Blue\">◄</font> حیله نیز بود. (فرهنگ اسدی ). مکر و حیله را هم گفته اند. (برهان ). مکر و فریب . (غیاث ). کید. مکر. حیله . (زمخشری ). نیرنگ .دستان . افسون . وسوسه . تزویر. گول <span class=\"hlight\">:</span> <br />دگر آنکه بدگوهر افراسیاب <br />ز توران بدان چاره بگذاشت آب .<br /> <font color=\"Red\">فردوسی .</font><br />بدانست رستم که این نیست گور<br />ابا او کنون چاره باید نه زور.<br /> <font color=\"Red\">فردوسی .</font><br />بچاره بیاوردش از دشت و کوه <br />به بند آمدند آنکه بد زآن گروه .<br /> <font color=\"Red\">فردوسی .</font><br />جهاندیده پر دانش افراسیاب <br />جز از چاره چیزی نبیند به خواب .<br /> <font color=\"Red\">فردوسی .</font><br />ورا نیز«بندوی » بفریفتی <br />به بند اندر ازچاره نشکیفتی .<br /> <font color=\"Red\">فردوسی .</font><br />فرومایه ضحاک بیداد گر<br />بدین چاره بگرفت گاه پدر.<br /> <font color=\"Red\">فردوسی .</font><br />بگردان ز جانم بد روزگار<br />همان چاره ٔ دیو آموزگار.<br /> <font color=\"Red\">فردوسی .</font><br />شنیدم همه خام گفتار تو<br />نبینم جز ازچاره بازار تو.<br /> <font color=\"Red\">فردوسی .</font><br />از آن چاره آگه نبد هیچکس <br />که او داشت آن راز پنهان و بس .<br /> <font color=\"Red\">فردوسی .</font><br />زنی بود با او بپرده درون <br />پراز چاره و بند و رنگ و فسون .<br /> <font color=\"Red\">فردوسی .</font><br />بدین چاره ده کار بد را فروغ <br />که داند که این راست است ار دروغ .<br /> <font color=\"Red\">فردوسی .</font><br />از آن آگهی شد دلش پرنهیب <br />سوی چاره برگشت وبند وفریب .<br /> <font color=\"Red\">فردوسی .</font><br />بدانست کان کار «بندوی » بود<br />که بهرام شد کشته زآن چاره زود.<br /> <font color=\"Red\">فردوسی .</font><br />نه جشن و نه رامش نه کوشش نه کام <br />همه چاره و تنبل و سازدام .<br /> <font color=\"Red\">فردوسی .</font><br />زدشمنان زبردست خیره خانه ٔ خویش <br />نگاهداشت نداند بچاره و نیرنگ .<br /> <font color=\"Red\">فرخی .</font><br />نگهدار این دو جادو را در آن دز<br />ز رنگ و چاره ٔ رامین گربز.<br /> <font color=\"Red\">فخرالدین گرگانی .</font><br />توچاره دانی ونیرنگ بازی <br />در این تیمارمان چاره چه سازی .<br /> <font color=\"Red\">فخرالدین گرگانی .</font><br />مرا این چاه بدبختی توکندی <br />بصد چاره مرا در وی فکندی .<br /> <font color=\"Red\">فخرالدین گرگانی .</font><br />چو گفتند او بشهر اندر شد اکنون <br />بدانست او که آن چاره ست و افسون .<br /> <font color=\"Red\">فخرالدین گرگانی .</font><br />از مرگ کس نجست بچاره، مگوی <br />بیهوده ای که آن نبرد ره به ده .<br /> <font color=\"Red\">ناصرخسرو(دیوان چ تقوی ص <span class=\"hlight\" dir=\"rtl\">٣٩٥</span>).</font><br />کان چاره چو سنبیدن کوه است بسوزن <br />و آن حیله چو پیمودن آب است بغربال .<br /> <font color=\"Red\">معزی .</font><br /> <BR><font color=\"Blue\">◄</font> گزیر. بُدّ. مقابل ناگزیر. مقابل لابد. گزیر. غُنَیة؛ چاره . بُدّ. غُنیان ؛ بُدّ. چاره . غنی <font color=\"DarkGreen\"><b>[ بالفتح والقصر ]</font></b>؛ چاره . بد. مُحتَد؛ مُحَد، مُعلَندَد؛ چاره و گزیر و بُدّ. مُلتَد؛ چاره و گریز. وَغْل ٌ؛ بد. (منتهی الارب ) <span class=\"hlight\">:</span><br />بیلفغده باید کنون «چاره » نیست <br />بیلفنجم وچاره ٔ من یکی است .<br /> <font color=\"Red\">بوشکور.</font><br />مردمان مکه را از طایف چاره نیست زیرا که در مکه نه زرع است ونه درختهای میوه . (ترجمه ٔ طبری ).<br />ولیکن کنون زین سخن چاره نیست <br />وگر زو بتر نیز پتیاره نیست .<br /> <font color=\"Red\">فردوسی .</font><br />چودانی که از مرگ خود چاره نیست <br />چه از پیش باشد چه پستر یکی است .<br /> <font color=\"Red\">فردوسی .</font><br />نیابد کسی چاره از چنگ مرگ <br />چو باد خزان است و ما همچو برگ .<br /> <font color=\"Red\">فردوسی .</font><br />سه چیزت بباید کزو چاره نیست <br />وز آن نیز بر سرت بیغاره نیست .<br /> <font color=\"Red\">فردوسی .</font><br />اگر ترسی وگرنترسی یکی است <br />بباید شدنمان کزین چاره نیست .<br /> <font color=\"Red\">فردسی .</font><br />چنین گفت کز مرگ خودچاره نیست <br />مرا بر دل اندیشه زین باره نیست .<br /> <font color=\"Red\">فردوسی .</font><br />سرانجام مرگ است وز آن چاره نیست <br />بما بر بدین جای بیغاره نیست .<br /> <font color=\"Red\">فردوسی .</font><br />نبود چاره حسودان دغا را ز حسد<br />حسد آن است که هرگز نپذیرد درمان .<br /> <font color=\"Red\">فرخی .</font><br />گیتی چو یکی کالبد است او چو روان است <br />چاره نبود کالبدی را ز روانی .<br /> <font color=\"Red\">فرخی .</font><br />جهان را خدمتش آب زلال است <br />که را چاره بود ز آب زلالا؟<br /> <font color=\"Red\">عنصری .</font><br />بندگان را از فرمانبرداری چاره نیست . (تاریخ بیهقی ). خواجه ... گفت اگر چاره نیست از پذیرفتن این شغل اگر رای عالی بیند تا بنده بطارم نشیند. (تاریخ بیهقی ). گفتم اگر چاره نیست از زدن، خلوتی باید تا نیکو دو فصل سخن گویم . (تاریخ بیهقی ). مرا چاره نباشد از نگاهداشت مصالح . ملک . (تاریخ بیهقی ).<br />چو دانش نداری بکاری درون <br />نباشد ترا چاره از رهنمون .<br /> <font color=\"Red\">اسدی .</font><br />ز فرمان شه ننگ وبیغاره نیست <br />بهر روی که را زمه چاره نیست .<br /> <font color=\"Red\">اسدی .</font><br />چو چاره نیستش از صحبت جهان جهان <br />اگر جفاش نماید جفاش بردارد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />علم او تعالی از پیش رفته بود که باشندگان زمین را از آب چاره نباشد. (ذخیره ٔ خوارزمشاهی ).<br />آنکه زو چاره نیست یارش دان <br />و آن که نه یارتست بارش دان .<br /> <font color=\"Red\">سنایی .</font><br />و زنده را از دانش و کردار نیک چاره نیست . (کلیله و دمنه ). خردمند... را چاره نیست از گذارد حق . (کلیله و دمنه ). چون نزدیک شیر رسید ازخدمت و تواضع چاره ندید. (کلیله و دمنه ).<br />معادی مبادت وگر چاره نبود<br />مبادی تو هرگز بکام معادی .<br /> <font color=\"Red\">انوری .</font><br />زندگی از وصل اوست و ز غم او چاره نیست <br />گربکشد گو بکش پیش اجل کس نمرد.<br /> <font color=\"Red\">عمادی شهریاری .</font><br />بخت تو شد عاشق جمال تو آری <br />چاره نباشد ز عشق، خاصه جوان را.<br /> <font color=\"Red\">ظهیرفاریابی .</font><br />هر که جنایت و دزدی پیشه سازد او را از چوب جلاد چاره نبود. (سندبادنامه ص <span class=\"hlight\" dir=\"rtl\">٣٢٦</span>).<br />چو شه دید کان گفت بیغاره نیست <br />ز فرمانبری بنده را چاره نیست .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> جدایی و مفارقت را نیز گویند. (برهان ). بمعنی جدایی آمده . (جهانگیری ). جدایی از چیزی . (شرفنامه ٔ منیری ). <BR><font color=\"Blue\">◄</font> یکبار بود. (صحاح الفرس ). بمعنی یکبار هم آمده است و به این معنی بسیار غریب است . (برهان ) <span class=\"hlight\">:</span> <br />ای برّ تو رسیده بهر یک چاره <br />از حال من ضعیف جویی چاره .<br /></font></div>'),
(282282, 'چاره آراستن', '<span class=\"hlight\">چاره آراستن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ت َ ]</font></b> (مص مرکب ) تدبیر کردن . موجبات انجام کاری را فراهم نمودن <span class=\"hlight\">:</span> <br />به گنج و درم چاره آراستم <br />کنون آن چنان شد که من خواستم .<br /> <font color=\"Red\">فردوسی .</font><br />بر این گونه از جای برخاستند<br />همه شب همی چاره آراستند.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(282283, 'چاره اندیش', '<span class=\"hlight\">چاره اندیش .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ اَ ]</font></b> (نف مرکب ) محیل . مکار. حیله گر. فسونگر.<br /></font></div>'),
(282284, 'چاره اندیشی', '<span class=\"hlight\">چاره اندیشی .</span> <font color=\"DarkGreen\"><b>[ رَ<span class=\"hlight\" dir=\"rtl\">/</span> رِ اَ ]</font></b> (حامص مرکب ) احتیال . حیله گری . فسونگری .<br /></font></div>'),
(282285, 'چاره برانداختن', '<span class=\"hlight\">چاره برانداختن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ب َ اَ ت َ ]</font></b> (مص مرکب ) چاره پیداکردن . (آنندراج ). چاره جستن <span class=\"hlight\">:</span> <br />یکی چاره باید برانداختن <br />به تزویر مردم خوری ساختن .<br /> <font color=\"Red\">نظامی (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> تدبیر نمودن . (آنندراج ).<br /></font></div>'),
(282286, 'چاره بردار', '<span class=\"hlight\">چاره بردار.</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ب َ ]</font></b> (نف مرکب ) چاره پذیر. علاج پذیر. قابل علاج . و رجوع به چاره پذیر شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(282287, 'چاره جستن', '<span class=\"hlight\">چاره جستن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ج ُ ت َ ]</font></b> (مص مرکب ) تدبیر کردن . تفکر و تأمل در انجام کاری یا اصلاح امری نمودن <span class=\"hlight\">:</span> <br />نشستند دانش پژوهان بهم <br />یکی چاره جستند بر بیش و کم .<br /> <font color=\"Red\">فردوسی .</font><br />به اندیشه ٔ پاک دل را بشست <br />فراوان ز هر گونه ای چاره جست .<br /> <font color=\"Red\">فردوسی .</font><br />یکی چاره ٔ راه دیدار جوی <br />چه باشی تو بر باره ومن به کوی .<br /> <font color=\"Red\">فردوسی .</font><br />او... خلاص خود را چاره میجست . (کلیله و دمنه ). <BR><font color=\"Blue\">◄</font> علاج کردن .درصدد علاج برآمدن . درمان کردن . علاج و درمان خواستن <span class=\"hlight\">:</span> <br />بدین چاره جستن ترا خواستم <br />چو دیر آمدی تندی آراستم .<br /> <font color=\"Red\">فردوسی </font><br />همی چاره جستند از آن اژدها<br />که تا چین بیابد ز سختی رها.<br /> <font color=\"Red\">فردوسی .</font><br />بسی چاره جست و ندید اندر آن <br />همی بود پیچان و لرزان برآن .<br /> <font color=\"Red\">فردوسی .</font><br />دو مار سیاه از دوکتفش برست <br />غمی گشت و از هر سویی چاره جست .<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> حیله کردن . فسون کردن . بفریب و نیرنگ توسل جستن . خدعه نمودن <span class=\"hlight\">:</span> <br />یکی چاره جست اندر آن کار زشت <br />ز کینه بنوی درختی بکشت .<br /> <font color=\"Red\">فردوسی .</font><br />برآنگونه با او همی چاره جست <br />نهانیش بد بود و رایش درست .<br /> <font color=\"Red\">فردوسی .</font><br />تو بودی بر این پادشاهی فروغ <br />همی چاره جستی و گفتی دروغ .<br /> <font color=\"Red\">فردوسی .</font><br />نه مردی بود چاره جستن بجنگ <br />نرفتی بسان دلاور نهنگ .<br /> <font color=\"Red\">فردوسی .</font><br />بسی خیمها کرده بود او درست <br />مر این خیمهای مرا چاره جست . <br /> <font color=\"Red\">عنصری .</font><br />زن مهربان چاره ای جست زود<br />که از چاره جستنش چاره نبود.<br /> <font color=\"Red\">شمسی (یوسف و زلیخا).</font><br /> <BR><font color=\"Blue\">◄</font> دوری گزیدن . جدایی خواستن <span class=\"hlight\">:</span> <br />همی خواندش شاه و او چاره جست <br />همی داشت آن نامه ٔ شاه سست .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(282288, 'چاره جو', '<span class=\"hlight\">چاره جو.</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (نف مرکب ) چاره جوی . تدبیرکننده . مدبر. جویای اصلاح امور. آنکه تدبیر و حیله کند. مصلحت اندیش <span class=\"hlight\">:</span> <br />بفرمود تا پیش او آمدند<br />بدان آرزو چاره جو آمدند.<br /> <font color=\"Red\">فردوسی .</font><br />به فرمان همه پیش او آمدند<br />به جان هر کسی چاره جو آمدند.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(282289, 'چاره جوی', '<span class=\"hlight\">چاره جوی .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b>(نف مرکب ) چاره جو. رجوع به چاره جو شود <span class=\"hlight\">:</span> <br />چنین داد پاسخ که «گو» را بگوی <br />که هرگز نباشی بجز چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />چو سیندخت بشنید پیشش نشست <br />دل چاره جوی اندر اندیشه بست .<br /> <font color=\"Red\">فردوسی .</font><br />کنون مرد بازاری و چاره جوی <br />ز کلبه سوی خانه دارند روی .<br /> <font color=\"Red\">فردوسی .</font><br />چو او کینه ور گشت و من چاره جوی .<br />سپه را دو روی اندر آمد بروی .<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود تا رخش را پیش اوی <br />ببردند هرکس که بد چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />نهادند بر نامها مهر اوی <br />بیامدفرستاده ای چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />بر رستم آمد یکی چاره جوی <br />که امروز از این کار شد رنگ و بوی .<br /> <font color=\"Red\">فردوسی .</font><br />بدان تند بالا نهادند روی <br />چنان چون بود مردم چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت گشتاسب کای راستگوی <br />که هم راستگویی و هم چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />بپرسد ترا از کجایی بگوی <br />بگویش که من مهتری چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />سخن های این بنده ٔ چاره جوی <br />چو رفتی یکایک بقیصر بگوی .<br /> <font color=\"Red\">فردوسی .</font><br />چو روی اندر آرند هردو بروی <br />تهمتن بود بی گمان چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />کنیزک سوی چاره بنهاد روی <br />چنان چون بود مردم چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />که آن کتابت را دست چاره جویی از من کشف نتواند کرد. (قابوسنامه ).<br />چون شد آن چاره جوی چاره شناس <br />باز پس گشت با هزار سپاس .<br /> <font color=\"Red\">نظامی .</font><br />چو شیرین دید کایشان راستگویند<br />بچاره راست کردن چاره جویند.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> جوینده ٔ علاج . درمان جوی . آنکه علاج و درمان طلبد <span class=\"hlight\">:</span> <br />تو هرچ اندرین کار دانی بگوی <br />که تو چاره دانی و من چاره جوی .<br /> <font color=\"Red\">دقیقی .</font><br />بپرسید ماهوی زین چاره جوی <br />که برسم کرا خواستی راست گوی .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت هستم یکی چاره جوی <br />همی نان فراز آرم از چند روی .<br /> <font color=\"Red\">فردوسی .</font><br />نباید که چون من بوم چاره جوی <br />تو «سودابه » را سختی آری به روی .<br /> <font color=\"Red\">فردوسی .</font><br />ز بیدانشی آنچه آمد بروی <br />تو دانی که شاهی و ما چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />از ایران چرا بازگشتی بگوی <br />مرا کردی اندر جهان چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />یکی مرد بسته بد از شهر اوی <br />بزندان شاه اندرون چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />همه راز این کار با من بگوی <br />که من باشمت زین غمان چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />همان خواهران را و پیوند اوی <br />که بودند هر یک ازو چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />بیامد بنزدیک من چاره جوی <br />گشاده شد آن رازها پیش اوی .<br /> <font color=\"Red\">فردوسی .</font><br />یکی مرد ایرانیم چاره جوی <br />گریزان نهاده برین مرزروی .<br /> <font color=\"Red\">فردوسی .</font><br />کمند اندر افکند و برگاشت روی <br />ز کرده پشیمان و دل چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />ساقی می مشکبوی بردار<br />بند از من چاره جوی بردار.<br /> <font color=\"Red\">نظامی .</font><br />چاره جویان را نمیدادیم صائب دردسر<br />دردهای کهنه ٔ هم را دوا بودیم ما.<br /> <font color=\"Red\">صائب .</font><br /> <BR><font color=\"Blue\">◄</font> حیله گر. مکار. فریبنده . جویای نیرنگ و فریب <span class=\"hlight\">:</span> <br />بدل مهربان و بتن چاره جوی <br />اگر تو خداوند رخشی، بگوی .<br /> <font color=\"Red\">فردوسی .</font><br />به «بندوی » گفت ای بد چاره جوی <br />تو این داوریها به بهرام گوی .<br /> <font color=\"Red\">فردوسی .</font><br />چو تنهابدیدش زن چاره جوی <br />از آن مغفر تیره بگشاد روی .<br /> <font color=\"Red\">فردوسی .</font><br />تهمتن چنین داد پاسخ بدوی <br />که ای مرد بد گوهر چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />چوروشن شود، دشمن چاره جوی <br />نهد بیگمان سوی این کاخ روی .<br /> <font color=\"Red\">فردوسی .</font><br />فرستاده ای خواستی راستگوی <br />که رفتی بر دشمن چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاره جویی شدن، چاره جو شدن </span> ؛ در صدد یافتن راه حل برآمدن <span class=\"hlight\">:</span> <br />برانید فرمان یزدان بر اوی <br />بدان تا شود هر کسی چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />پس از رشک ضحاک شد چاره جوی <br />ز لشکر سوی کاخ بنهاد روی .<br /> <font color=\"Red\">فردوسی .</font><br />سواران ببخشید تا بر سه روی <br />شوند اندرین رزمگه چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />چنین اسب و زرین ستانم بکوی <br />بدزدد کسی من شوم چاره جوی .<br /> <font color=\"Red\">فردوسی .</font><br />برآشفت سهراب و شدچون پلنگ <br />چو بدخواه او چاره جو شد بجنگ .<br /> <font color=\"Red\">فردوسی .</font><br />ز دوزخ مشو تشنه را چاره جوی <br />سخن در بهشت است و آن چاره جوی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282290, 'چاره جویی', '<span class=\"hlight\">چاره جویی .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (حامص مرکب ) تدبیر. صلاح اندیشی <span class=\"hlight\">:</span> <br />سکندر جهاندیدگان را بخواند<br />در این چاره جویی بسی قصه راند.<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> حیله گری . فسونگری . فریبکاری <span class=\"hlight\">:</span><br />فسونگر در حدیث چاره جویی <br />فسونی به ندید از راستگویی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282291, 'چاره داشتن', '<span class=\"hlight\">چاره داشتن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ت َ ]</font></b> (مص مرکب ) علاج داشتن . درمان داشتن <span class=\"hlight\">:</span> <br />صبا گر چاره داری وقت وقت است <br />که درد اشتیاقم قصد جان کرد.<br /><font color=\"Red\">حافظ (از آنندراج ).</font><br /></font></div>'),
(282292, 'چاره دان', '<span class=\"hlight\">چاره دان .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ]</font></b> (نف مرکب ) داننده ٔ چاره . چاره ساز. صاحب تدبیر. و رجوع به چاره ساز شود. <BR><font color=\"Blue\">◄</font> داننده ٔ علاج دردها. معالج . آنکه علاج و درمان دردها داند <span class=\"hlight\">:</span> <br />تو هرچ اندرین کار دانی بگوی <br />که تو چاره دانی و من چاره جوی .<br /> <font color=\"Red\">دقیقی .</font><br />بسا چاره دان کاو بسختی بمرد<br />که بیچاره گوی سلامت ببرد.<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />و رجوع به چاره ساز و چاره گر شود.<br /></font></div>'),
(282293, 'چاره راست کردن', '<span class=\"hlight\">چاره راست کردن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ک َ دَ ]</font></b> (مص مرکب ) تدبیر کردن . در صدد اصلاح کاری برآمدن <span class=\"hlight\">:</span> <br />چو شیرین دید کایشان راستگویند<br />به چاره راست کردن چاره جویند.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282294, 'چاره ساختن', '<span class=\"hlight\">چاره ساختن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ت َ]</font></b> (مص مرکب ) تدبیر نمودن . در اصلاح کار یا امری حیلت اندیشیدن . کاری را از روی عقل و تدبیر به انجام رسانیدن . تامل و تفکر در اجرای امری نمودن <span class=\"hlight\">:</span> <br />بدانش کنون چاره ٔ خویش ساز<br />مبادا که آید بدشمن نیاز.<br /> <font color=\"Red\">فردوسی .</font><br />که تا از گریزش چه گوید پدر<br />مگر چاره ٔ نو بسازد دگر.<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت کاین چاره اندر جهان <br />بسازید و دارید اندر نهان .<br /> <font color=\"Red\">فردوسی .</font><br />چنین بد مکن تو بگفت گراز<br />همان چاره ٔ کار نیکو بساز.<br /> <font color=\"Red\">فردوسی .</font><br />وز آن پس یکی چاره ای ساختن <br />ز هر گونه اندیشه انداختن .<br /> <font color=\"Red\">فردوسی .</font><br />تو مرد دبیری یکی چاره ساز<br />و زین کار بر باد مگشای راز.<br /> <font color=\"Red\">فردوسی .</font><br />یکی چاره ساز ای خردمند پیر<br />نباید چنین ماند بر خیر خیر.<br /> <font color=\"Red\">فردوسی .</font><br />من اکنون بهوش دل و پاک مغز<br />یکی چاره سازم بدینکار نغز.<br /> <font color=\"Red\">فردوسی .</font><br />یکی چاره باید کنون ساختن <br />که رایش به آب آید انداختن .<br /> <font color=\"Red\">فردوسی .</font><br />مگر تا یکی چاره سازد نهان <br />که پردخته ماند ز مردم جهان .<br /> <font color=\"Red\">فردوسی .</font><br />سخنها که پرسیدی از ما درست <br />بگوئیم تا چاره سازی نخست .<br /> <font color=\"Red\">فردوسی .</font><br />چو این کرده شدچاره ٔ آب ساخت <br />ز دریا برآورد و هامون نواخت .<br /> <font color=\"Red\">فردوسی .</font><br />وگر ایدون به بن انجامدمان نقل و نبید <br />چاره ٔ هر دو بسازیم که ما چاره گریم .<br /> <font color=\"Red\">منوچهری .</font><br />بسی چاره ها سازی و داوری <br />بری رنج تا گنج گرد آوری .<br /> <font color=\"Red\">گرشاسبنامه (اسدی ).</font><br />عشق ببانگ بلند گفت که خاقانیا<br />کار نه خرد است خیز چاره بساز آن او.<br /> <font color=\"Red\">خاقانی (دیوان چ عبدالرسولی ص <span class=\"hlight\" dir=\"rtl\">٣٧٢</span>).</font><br />چاره ٔ دین ساز که دنیات هست <br />تا مگر آن نیز بیاری بدست .<br /> <font color=\"Red\">نظامی .</font><br />چاره ٔ ما ساز که بی داوریم <br />گر تو برانی به که رو آوریم .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> علاج کردن . درمان ساختن . مداوا نمودن <span class=\"hlight\">:</span> <br />من او را یکی چاره سازم که شاه <br />پسندد از این بنده ٔ نیکخواه .<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت من چاره سازم ترا<br />بخورشیدسربر فرازم ترا.<br /> <font color=\"Red\">فردوسی .</font><br />توچاره دانی و نیرنگ بازی <br />در این تیمارمان چاره چه سازی .<br /> <font color=\"Red\">(ویس و رامین ).</font><br />صبر ار نکنم چه چاره سازم <br />کآرام دل از یکی فزون نیست .<br /> <font color=\"Red\">سعدی (ترجیعات ).</font><br /> <BR><font color=\"Blue\">◄</font> احتیال . حیله کردن . فریب دادن . به خدعه و نیزنگ توسل جستن <span class=\"hlight\">:</span> <br />همین کودک از پشت آن بد هنر<br />همی چاره و حیله سازد دگر.<br /> <font color=\"Red\">فردوسی .</font><br />ز ما ایمنی خواه و چاره مساز<br />که بر چاره گر کار گردد دراز.<br /> <font color=\"Red\">فردوسی .</font><br />ترا ای پسر گاه آمد کنون <br />که سازی یکی چاره ٔ پرفسون .<br /> <font color=\"Red\">فردوسی .</font><br />بفرمود کز پیش بیرون برند<br />بسی چاره سازند و افسون برند.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(282295, 'چاره ساز', '<span class=\"hlight\">چاره ساز.</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (نف مرکب )چاره سازنده . چاره دان . چاره گر. مدبر. تدبیرکننده . اهل تدبیر. آنکه تدبیر کارها کند و داند. چاره کننده .<br />دلم در بازگشتن چاره ساز است <br />سخن کوتاه شد منزل دراز است .<br /> <font color=\"Red\">نظامی .</font><br />ز هر دانشی چاره ای جست باز<br />که فرخ بود مردم چاره ساز.<br /> <font color=\"Red\">نظامی .</font><br />فرستاده راچون بود چاره ساز<br />به اندرز کردن نباشد نیاز.<br /> <font color=\"Red\">نظامی .</font><br />چو دیدند شاهی چنان چاره ساز<br />به چاره گری در گشادند باز.<br /> <font color=\"Red\">نظامی .</font><br />چودانست فرمانده چاره ساز<br />که تعلیم دیو است از آنگونه راز.<br /> <font color=\"Red\">نظامی .</font><br />که اهل خرد را منم چاره ساز<br />ز علم دگر بخردان بی نیاز.<br /> <font color=\"Red\">نظامی .</font><br />بفرزانه آن قصه را گفت باز<br />وز او چاره ای خواست آن چاره ساز.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> معالج . علاج کننده . شفابخش . آنکه علاج بیماریی یا درمان دردی کند. آنچه موجب علاج و درمان شود <span class=\"hlight\">:</span> <br />گو مرا ز انتظار پشت شکست <br />مومیایی چاره ساز فرست .<br /> <font color=\"Red\">خاقانی .</font><br />ارسطو جهاندیده ٔ چاره ساز<br />به بیچارگی ماند از آن چاره باز.<br /> <font color=\"Red\">نظامی .</font><br />نشاید شدن مرگ را چاره ساز<br />در چاره بر کس نکردند باز.<br /> <font color=\"Red\">نظامی .</font><br />چاره سازان به چاره های خودش <br />دور کردند از خیال بدش .<br /> <font color=\"Red\">نظامی .</font><br />هم از راه سخن شد چاره سازش <br />بدان دانه بدام آورد بازش .<br /> <font color=\"Red\">نظامی .</font><br />خویشان که رقیب راز بودند<br />او را همه چاره ساز بودند.<br /> <font color=\"Red\">نظامی .</font><br />چاره سازی ز هر طرف میجست <br />که از او بند سخت گردد سست .<br /><font color=\"Red\">نظامی .</font><br />خویشان همه در نیاز با او<br />هر یک شده چاره ساز با او.<br /> <font color=\"Red\">نظامی .</font><br />گفتند به لطف چاره سازش <br />بردند بسوی خانه بازش .<br /> <font color=\"Red\">نظامی .</font><br />خدای خردبخش بخردنواز<br />همان ناخردمند را چاره ساز.<br /> <font color=\"Red\">نظامی .</font><br />صائب ز بس که درد مرا در میان گرفت <br />بیچاره شد ز چاره ٔ من چاره ساز من .<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> محتال . محیل . حیله گر. نیرنگ باز. مکار <span class=\"hlight\">:</span><br />جهان چاره سازی است بی ترس و باک <br />بجان بردن ماست بی خوف پاک .<br /> <font color=\"Red\">اسدی .</font><br />یکی بانگ زد روبه چاره ساز<br />که بند از دهان سگان کرد باز.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> نام خدای تعالی . نامی از نامهای باریتعالی . صفتی از اوصاف ایزد متعال <span class=\"hlight\">:</span> <br />نالید در آن که چاره ساز است <br />از جمله وجود بی نیاز است .<br /> <font color=\"Red\">نظامی .</font><br />و رجوع به چاره دان و چاره گر و چاره کن شود.<br /></font></div>'),
(282296, 'چاره سازی', '<span class=\"hlight\">چاره سازی .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (حامص مرکب ) چاره گری . چاره اندیشی . مصلحت اندیشی . تدبیر. تأمل و تفکر <span class=\"hlight\">:</span> <br />اگر دشمنی ترکتازی کند<br />رقیب حرم چاره سازی کند.<br /> <font color=\"Red\">نظامی .</font><br />به افکندنش چاره سازی کنند<br />و ز او دعوی بی نیازی کنند.<br /> <font color=\"Red\">نظامی .</font><br />شب و روز بی چاره سازی نیم <br />در این پرده با خود ببازی نیم .<br /> <font color=\"Red\">نظامی .</font><br />بسی کردند مردان چاره سازی <br />ندیدند از یکی زن راستبازی .<br /> <font color=\"Red\">نظامی .</font><br />حدیث بنده را در چاره سازی <br />بساطی هست با لختی درازی .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> علاج خواهی .درمان پذیری . شفاطلبی . سلامت خواهی <span class=\"hlight\">:</span> <br />دل دوش هزار چاره سازی میکرد<br />با وعده ٔ دوست عشق بازی میکرد.<br /> <font color=\"Red\">عسجدی .</font><br />دانست کز آن خیالبازی <br />کارش نرسد بچاره سازی .<br /> <font color=\"Red\">نظامی .</font><br />آن سوخته را به دلنوازی <br />آرندز راه چاره سازی .<br /> <font color=\"Red\">نظامی .</font><br />گفت ای پسر این چه جای بازی است <br />بشتاب که جای چاره سازی است .<br /> <font color=\"Red\">نظامی .</font><br />در پرده ٔ آن خیالبازی <br />بیچاره شدم ز چاره سازی .<br /> <font color=\"Red\">نظامی .</font><br />زید از غم آن بت طرازی <br />مشغول شده به چاره سازی .<br /> <font color=\"Red\">نظامی .</font><br />در چاره سازی بخود درمبند<br />که بسیار تلخی بود سودمند.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> حیله گری . نیرنگ بازی . دغل کاری <span class=\"hlight\">:</span> <br />جهاندیده پر دانش افراسیاب <br />جز از چاره سازی نبیند بخواب .<br /> <font color=\"Red\">فردوسی .</font><br />به چاره سازی با خصم تو همی کوشم <br />که «مروزی » را کاراوفتاده با «رازی ».<br /> <font color=\"Red\">سوزنی .</font><br />نیم من مرد ناز او که با این چاره سازیها<br />دلم چون خر بگل درماند از آن ناز بخروارش .<br /> <font color=\"Red\">مجیر بیلقانی .</font><br />چو مجنون سر مکش درعشقبازی <br />چو لیلی پاک شو در چاره سازی .<br /> <font color=\"Red\">نظامی .</font><br />چو گرگ افزون بود در چاره سازی <br />شبان را کرد باید خرقه بازی .<br /> <font color=\"Red\">نظامی .</font><br />گهی جستن بغمزه چاره سازی <br />گهی کردن ببوسه نردبازی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282297, 'چاره سنج', '<span class=\"hlight\">چاره سنج .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ س َ ]</font></b> (نف مرکب ) مدبر. با تدبیر. آنکه در کارها تأمل و تدبیر کند <span class=\"hlight\">:</span> <br />ز شادی بفرزانه ٔ چاره سنج <br />بسی تحفه ها داد از مال و گنج .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282298, 'چاره سگال', '<span class=\"hlight\">چاره سگال .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ س ِ ]</font></b> (نف مرکب ) چاره سگالنده . تدبیراندیش . مصلحت اندیش . آنکه اندیشه و تدبیر اصلاح امور کند <span class=\"hlight\">:</span> <br />شاه نامش خجسته دید بفال <br />گفت کای خیرمند چاره سگال .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> چاره اندیش . علاج اندیش . آنکه در اندیشه ٔ علاج و درمان دردی یا مرضی باشد <span class=\"hlight\">:</span> <br />چو عاجز شود مرد چاره سگال <br />ز بیچارگی درگریزد بفال .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> حیلت اندیش . آنکه در اندیشه ٔ مکر و فریب باشد <span class=\"hlight\">:</span> <br />بر دویدند هر دو چاره سگال <br />روبهان پیش و گرگ در دنبال .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282299, 'چاره سگالیدن', '<span class=\"hlight\">چاره سگالیدن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ س ِ دَ ]</font></b> (مص مرکب ) حیلت اندیشیدن . چاره اندیشیدن . خدعه کردن . فریب دادن . حقه زدن <span class=\"hlight\">:</span> <br />کدام چاره سگالم که با تو درگیرد<br />کجا روم که دل من دل از تو برگیرد.<br /><font color=\"Red\">سعدی (بدایع)</font><br /></font></div>'),
(282300, 'چاره شدن', '<span class=\"hlight\">چاره شدن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ش ُ دَ ]</font></b> (مص مرکب ) علاج شدن . درمان پذیرفتن . بهبود یافتن . <BR><font color=\"Blue\">◄</font> چاره شدن زخم و درد. کنایه از به شدن زخم و درد (آنندراج ) <span class=\"hlight\">:</span> <br />زخم دل چاره شد از نکهت آن عقده ٔ زلف <br />زهر این مار کم از مهره ٔ این مار نبود.<br /> <font color=\"Red\">تأثیر (از آنندراج ).</font><br />درد دلم چاره شد ز غنچه نهانی <br />کز نی شکر کشیده اند گلابش .<br /><font color=\"Red\">تأثیر (از آنندراج ).</font><br /></font></div>'),
(282301, 'چاره شناختن', '<span class=\"hlight\">چاره شناختن .</span> <font color=\"DarkGreen\"><b>[ رَ ش ِ ت َ]</font></b> (مص مرکب ) علاج شناختن . درمان دانستن <span class=\"hlight\">:</span> <br />میشد آن کس که چو او چاره ٔ کارم نشناخت <br />من همی دیدم و از کالبدم جان میرفت .<br /><font color=\"Red\">؟ (از آنندراج ).</font><br /></font></div>'),
(282302, 'چاره شناس', '<span class=\"hlight\">چاره شناس .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ش ِ ]</font></b> (نف مرکب ) شناسنده ٔ چاره . علاج شناس . معالج . آنکه درمان و علاج دردی یا مرضی داند و شناسد <span class=\"hlight\">:</span> <br />چون شد آن چاره جوی چاره شناس <br />باز پس گشت با هزار سپاس .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282303, 'چاره ناپذیر', '<span class=\"hlight\">چاره ناپذیر.</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ پ َ ]</font></b> (نف مرکب ) علاج ناپذیر. غیرقابل علاج . چاره ناپذیرنده .<br /></font></div>'),
(282304, 'چاره ور', '<span class=\"hlight\">چاره ور.</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ وَ ]</font></b> (ص مرکب )صاحب تدبیر. مدبر. <BR><font color=\"Blue\">◄</font> معالج . علاج کننده .<br /></font></div>'),
(282305, 'چاره پذیر', '<span class=\"hlight\">چاره پذیر.</span> <font color=\"DarkGreen\"><b>[ رَ<span class=\"hlight\" dir=\"rtl\">/</span> رِ پ َ ]</font></b> (نف مرکب ) چاره بردار. علاج پذیر. خوب شدنی .قابل علاج . چاره پذیرنده . و رجوع به چاره بردار شود.<br /></font></div>'),
(282306, 'چاره پرداز', '<span class=\"hlight\">چاره پرداز.</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ پ َ ]</font></b> (نف مرکب ) چاره گر. علاج گر. کسی که علاج دردی یا اصلاح امری کند <span class=\"hlight\">:</span> <br />جهان را در این آمدن راز بود<br />که شاه جهان چاره پرداز بود.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282307, 'چاره پژوه', '<span class=\"hlight\">چاره پژوه .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ پ َ ]</font></b> (نف مرکب ) چاره پژوهنده . چاره جو. وسیله جو. جویای تدبیر <span class=\"hlight\">:</span> <br />سکندر بیامد دلی همچو کوه <br />ز کرده پشیمان و چاره پژوه .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(282308, 'چاره کردن', '<span class=\"hlight\">چاره کردن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ک َ دَ ]</font></b> (مص مرکب ) تدبیر کردن .در اصلاح امری یا انجام کاری تأمل و تفکر نمودن . درصدد رهایی کسی یا رهانیدن چیزی برآمدن <span class=\"hlight\">:</span> <br />کنون یک بیک چاره ٔ جان کنید<br />همه با من امروزپیمان کنید.<br /> <font color=\"Red\">فردوسی .</font><br />بدو گفت بهرام پس چاره کن <br />وزین راز مگشای بر کس سخن .<br /> <font color=\"Red\">فردوسی .</font><br />کنون چاره ای کن که تا آن سپاه <br />ز بلخ آوری سوی این بارگاه .<br /> <font color=\"Red\">فردوسی .</font><br />چو فردا بیاید بدشت نبرد<br />به کشتن همی بایدم چاره کرد.<br /> <font color=\"Red\">فردوسی .</font><br />بسی چاره کرد اندر آن خوشنواز<br />که پیروز راسرنیاید به کاز.<br /> <font color=\"Red\">فردوسی .</font><br />به ارجاسپ از چاره کرد آنچه کرد<br />از آن لشکر دژ برآورد گرد.<br /> <font color=\"Red\">فردوسی .</font><br />جهاندار گفت اینت پتیاره ای <br />برو گر توانی بکن چاره ای .<br /> <font color=\"Red\">نظامی .</font><br />چو مه را دل به رفتن تیز کردم <br />پس آنگه چاره ٔ شبدیز کردم .<br /><font color=\"Red\">نظامی .</font><br />گر تو ز من فارغی من ز تو فارغ نیم <br />چاره ٔ کارم بکن کز تو مرا چاره نیست .<br /> <font color=\"Red\">عطار.</font><br />بعزم توبه سحر گفتم استخاره کنم <br />بهار توبه شکن میرسد چه چاره کنم .<br /> <font color=\"Red\">حافظ.</font><br />چاره ٔ دل عقل پرتدبیر نتوانست کرد<br />خضر این ویرانه را تعمیر نتوانست کرد.<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> علاج کردن . دفع کردن . رفع کردن . مداواکردن . درمان کردن <span class=\"hlight\">:</span> <br />چه سازیم و این را چه درمان کنیم <br />بدانش مگر چاره ٔ جان کنیم .<br /> <font color=\"Red\">فردوسی .</font><br />شماهر کسی چاره ٔ جان کنید<br />بدین خستگی تا چه درمان کنید.<br /> <font color=\"Red\">فردوسی .</font><br />فروریخت از دیدگان آب زرد<br />به آب دو دیده همی چاره کرد.<br /> <font color=\"Red\">فردوسی .</font><br />توانیم کردن مگر چاره ای <br />که بی چاره ای نیست پتیاره ای .<br /> <font color=\"Red\">فردوسی .</font><br />کنون چاره این دام را چون کنم <br />که آسان سر از بند بیرون کنم .<br /> <font color=\"Red\">فردوسی .</font><br />یار شو ای مونس غمخوارگان <br />چاره کن ای چاره ٔ بیچارگان .<br /> <font color=\"Red\">نظامی .</font><br />حدیث سعدی اگر نشنوی چه چاره کند<br />بدشمنان نتوان گفت ماجرا ای دوست .<br /> <font color=\"Red\">سعدی .</font><br />ای که گویی دیده از دیدار مهرویان بدوز<br />هر چه گویی چاره دانم کرد جز تقدیر را.<br /> <font color=\"Red\">سعدی .</font><br />دوش گفتم بکند لعل لبش چاره ٔ من <br />هاتف غیب ندا داد که آری بکند.<br /><font color=\"Red\">حافظ.</font><br />صد شیشه چاره ٔ دل تنگم نمیکند<br />میخانه ای عمارت رنگم نمیکند.<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> حیله کردن . خدعه کردن . فسون کردن <span class=\"hlight\">:</span> <br />بدو گفت کسری سخن راست گوی <br />مکن چاره و هیچ کژی مجوی .<br /> <font color=\"Red\">فردوسی .</font><br />چو بشنید این سخن دایه از آن ماه <br />گرفت از چاره کردن طبع روباه .<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br />هزار چاره بکردم که همعنان تو گردم <br />تو پهلوان تر از آنی که در کمند من افتی .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(282309, 'چاره کوش', '<span class=\"hlight\">چاره کوش .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (نف مرکب ) حیله گر. حیلت کوش . آنکه در مکر و حیله کوشد <span class=\"hlight\">:</span> <br />خود را بجهد حیله گر و چاره کوش کرد.<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(282310, 'چاره گر', '<span class=\"hlight\">چاره گر.</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ گ َ ]</font></b> (ص مرکب ) صاحب تدبیر. مدبر. آنکه در کارها تدبیر و تأمل کند. کسی که بحیلت و تدبیر و تفکر کارها را بسامان رساند: صیرفی ؛ مرد محتال و چاره گر و تصرف کننده در کارها. (منتهی الارب ) <span class=\"hlight\">:</span> <br />که دانست کاین چاره گر مرد سند<br />سپاه آرد از چین و سقلاب و هند.<br /> <font color=\"Red\">فردوسی .</font><br />شوم زو بپرسم بگوید مگر<br />ز چاره چه کرده ست آن چاره گر.<br /> <font color=\"Red\">فردوسی .</font><br />سر ماهرا کار شد ساخته <br />وز آن چاره گر گشت پرداخته .<br /> <font color=\"Red\">فردوسی .</font><br />زن چاره گر زود بردش نماز<br />چنین گفت کای شاه گردنفراز.<br /> <font color=\"Red\">فردوسی .</font><br />چنین گفت با چاره گر کدخدای <br />کزو آرزوها نیاید بجای .<br /> <font color=\"Red\">فردوسی .</font><br />بدادش بدان دایه ٔ چاره گر<br />یکی دست جامه بدان مژده بر.<br /> <font color=\"Red\">فردوسی .</font><br />که او پیل جنگی و چاره گر است <br />فراوان بگرد اندرش لشکر است .<br /> <font color=\"Red\">فردوسی .</font><br />از ایران بیامد یکی چاره گر<br />بفرمان دادار بسته کمر.<br /> <font color=\"Red\">فردوسی .</font><br />ز درگه یکی چاره گر برگزید<br />سخنگوی و دانا چنان چون سزید.<br /> <font color=\"Red\">فردوسی .</font><br />کردار بود چاره گر کار بزرگان <br />کردار چنین باشد و او عاشق کردار.<br /> <font color=\"Red\">فرخی .</font><br />وگر ایدون به بن انجامدمان نقل و نبید<br />چاره ٔ هر دو بسازیم که ما چاره گریم .<br /> <font color=\"Red\">منوچهری .</font><br />که داند گفت چون بد شادی ویس <br />زمرد چاره گر آزادی ویس .<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین )</font><br />در همه کاری آن هنرپیشه <br />چاره گر بود و چابک اندیشه .<br /> <font color=\"Red\">نظامی .</font><br />نجات آخرت را چاره گر باش <br />در این منزل ز رفتن باخبر باش .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> معالج . علاج کننده . آنکه علاج بیماری ودرمان درد کند. کسی که ناتوانان و دردمندان را علاج کند و بفریاد رسد <span class=\"hlight\">:</span> <br />سپهبد سوی آسمان کرد سر<br />که ای دادگر داور چاره گر.<br /> <font color=\"Red\">فردوسی .</font><br />ترا دیدم اندر جهان چاره گر<br />تو بندی بفریاد هر کس کمر.<br /> <font color=\"Red\">فردوسی .</font><br />بدین کار اگر تو نبندی کمر<br />نبینم به گیتی دگر چاره گر.<br /> <font color=\"Red\">فردوسی .</font><br />نیامد ز بیژن به ایران خبر<br />نیایش نخواهدبدن چاره گر.<br /> <font color=\"Red\">فردوسی .</font><br />بنزدیک خاتون شد آن چاره گر<br />تبه دید بیمار او را جگر.<br /> <font color=\"Red\">فردوسی .</font><br />ره آموز و روزی ده و چاره گر<br />بوداین شه بی پدر را پدر.<br /> <font color=\"Red\">اسدی .</font><br />چنین گفت چون مدت آمد بسر<br />نشاید شدن مرگ را چاره گر.<br /> <font color=\"Red\">نظامی .</font><br />مونس غمخواره غم دی بود<br />چاره گر می زده هم می بود.<br /> <font color=\"Red\">نظامی .</font><br />یار اگر چاره گر عاشق بیچاره شود<br />کی از این غم سر خود گیردو آواره شود<br /> <font color=\"Red\">کمال خجندی (از آنندراج ).</font><br />بیمار بی طبیب چو چشم توام ؛ که نیست <br />آن قوتم که منت هر چاره گر کشم .<br /> <font color=\"Red\">ابوطالب کلیم (از آنندراج ).</font><br />بکار خویش طبیب ار نبی است حیران است <br />مسیح چاره گر درد حمل مریم نیست .<br /> <font color=\"Red\">محسن تأثیر (ازآنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> محیل . حیله گر. مکار. فسونگر. نیرنگ باز. فریبکار <span class=\"hlight\">:</span> <br />نهانی ز سودابه ٔ چاره گر<br />همی بود پیچان و خسته جگر.<br /> <font color=\"Red\">فردوسی .</font><br />سخن چین و بیدانش و چاره گر<br />نباید که یابند پیشت گذر.<br /> <font color=\"Red\">فردوسی .</font><br />ز ما ایمنی خواه و چاره مساز<br />که بر چاره گر کار گردد دراز.<br /> <font color=\"Red\">فردوسی .</font><br />همیزد بر او تیغ تا پاره گشت <br />چنان چاره گرمرغ بیچاره گشت .<br /> <font color=\"Red\">فردوسی .</font><br />بداندیش گردد پدر بر پسر<br />پسر همچنین بر پدر چاره گر.<br /> <font color=\"Red\">فردوسی .</font><br />زن چاره گر بستد آن نامه را<br />شنیدآن سخنهای خودکامه را.<br /> <font color=\"Red\">فردوسی .</font><br />به گه معرکه ار شیر بود دشمن تو<br />همچو روباه شود چاره گر و حیلت کوش .<br /> <font color=\"Red\">سوزنی .</font><br />اگر شوی به دها حیله ور تر از دراج <br />و گر شوی به ذکا چاره گرتر از روباه .<br /> <font color=\"Red\">عبدالواسع جبلی .</font><br />شاه چون دید پیچ پیچی او<br />چاره گر شد ز بد بسیچی او.<br /> <font color=\"Red\">نظامی .</font><br />زین چاره گران بادپیمای <br />در کار فلک کرا رسدپای .<br /> <font color=\"Red\">نظامی .</font><br />دورنگی در اندیشه تاب آورد<br />سر چاره گر زیر خواب آورد.<br /> <font color=\"Red\">نظامی .</font><br />من بیچاره می نیارم گفت <br />آنچه زین چرخ چاره گر دارم .<br /> <font color=\"Red\">اسماعیل باخرزی .</font><br />زلفت هزار دل بیکی تار مو ببست <br />راه هزار چاره گر از چار سو ببست .<br /><font color=\"Red\">حافظ.</font><br /></font></div>'),
(282311, 'چاره گرفتن', '<span class=\"hlight\">چاره گرفتن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ گ ِ رِ ت َ ]</font></b>(مص مرکب ) مصمم شدن . اتخاذ تصمیم کردن <span class=\"hlight\">:</span> <br />مرا چاره ٔ خویش باید گرفت <br />ره خشک را پیش باید گرفت .<br /><font color=\"Red\">فردوسی (از آنندراج ).</font><br /></font></div>'),
(282312, 'چاره گری', '<span class=\"hlight\">چاره گری .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ گ َ ]</font></b> (حامص مرکب ) تدبیر. تأمل و تفکر. مصلحت اندیشی <span class=\"hlight\">:</span> <br />چو دیدند شاهی چنان چاره ساز<br />بچاره گری در گشادند باز.<br /> <font color=\"Red\">نظامی .</font><br />بگو هرچه داری که فرمان کنم <br />بچاره گری با توپیمان کنم .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> معالجة. مداوا. درمان و علاج خواهی . درمان طلبی <span class=\"hlight\">:</span> <br />بجز مرگ هر مشکلی را که هست <br />بچاره گری چاره آمد بدست .<br /> <font color=\"Red\">نظامی .</font><br />تا مادر مشفقش نوازد<br />در چاره گریش چاره سازد.<br /> <font color=\"Red\">نظامی .</font><br />بچاره گری چون ندارم توان <br />کنم نوحه برزاد سرو جوان .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> حیله گری . نیرنگ بازی . فسونگری . جادوگری . تردستی . احتیال <span class=\"hlight\">:</span> <br />ای بزفتی علم بگرد جهان <br />برنگردم ز تو مگر بمری <br />گرچه سختی چو نخکله مغزت <br />جمله بیرون کنم به چاره گری .<br /> <font color=\"Red\">لبیبی .</font><br />در نام سلیم عامری بود<br />در چاره گری چو سامری بود.<br /> <font color=\"Red\">نظامی .</font><br />و آنهمه دعویت بچاره گری <br />با دد و دیوو آدمی و پری .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282313, 'چاره گزیدن', '<span class=\"hlight\">چاره گزیدن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ گ ُ دَ ]</font></b> (مص مرکب ) تدبیر کردن . اتخاذ تدبیر نمودن <span class=\"hlight\">:</span> <br />ستاره شمر گفت و خسرو شنید<br />یکی کژ و ناخوب چاره گزید.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(282314, 'چاره یوز', '<span class=\"hlight\">چاره یوز.</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b> (نف مرکب ) چاره جوی . و رجوع به چاره جوی شود.<br /></font></div>'),
(282315, 'چارهشت', '<span class=\"hlight\">چارهشت .</span> <font color=\"DarkGreen\"><b>[ هََ]</font></b> (اِ مرکب ) اصطلاح قمار. اصطلاحی در بازی ورق . چهار ورق از ورقهای بازی که بر هریک هشت خال نقش شده باشد. چهار ورق هشت خال (هشت خال گلابی سیاه <font color=\"DarkGreen\"><b>[ پیک ]</font></b> و هشت خال خاج <font color=\"DarkGreen\"><b>[ گشنیز ]</font></b> و هشت خال دل و هشت خال خشت ).<br /></font></div>'),
(282316, 'چارهنگام', '<span class=\"hlight\">چارهنگام .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِ مرکب ) چهارهنگام . چهارفصل .چارموسم . بهار و تابستان و پائیز و زمستان . فصول اربعة. <BR><font color=\"Blue\">◄</font> چهار وقت صبح و ظهر و عصر و شب .<br /></font></div>'),
(282317, 'چارو', '<span class=\"hlight\">چارو.</span> (اِخ ) از منازل سر راه اهواز به اصفهان . (جغرافی تاریخی غرب ایران نگارش بهمن کریمی ص <span class=\"hlight\" dir=\"rtl\">٣١٠</span>).<br /></font></div>'),
(282318, 'چارو', '<span class=\"hlight\">چارو.</span> (اِ) ساروج . سارو.کلس . کرس . بمعنی سارو باشد. (برهان ). آهک رسیده با چیزها آمیخته است که بر آب انبار و حوض و امثال آن مالند. (برهان ) (آنندراج ). آهک است که با چیزهای دیگر یکجا خمیر کنند و در آب بندی بکار برند. (لغت محلی شوشتر خطی ). آهک و خاکستر که با یکدیگر آمیخته در عمارت بکار برند. مخلوط آهک و خاکستر و آب که بر کف و دیوار آب انبار و حمام و حوض برای استحکام و جلوگیری از نفوذ آب میمالند. مخلوطی از آب و آهک و خاکستر و چیزهای دیگر که خمیر آن در پوشش کف حوض و آب انبار و حمام یا برای آب بندی جاهای دیگر بکار میرود. در تداول عامه و در لهجه های محلی «ساروج » گویند و «صاروج » معرب آن است .<br /></font></div>'),
(282319, 'چاروا', '<span class=\"hlight\">چاروا.</span> <font color=\"DarkGreen\"><b>[ چارْ ]</font></b> (اِ رکب ) چارپا. مرکب سواری . (برهان ) (آنندراج ). مرکب چهار پا اعم از اسب یا الاغ یا اشتر. (لغت محلی شوشتر خطی ) هرحیوان که بر چهارپا رود. حیوان بارکش . ماشیة. مال . اسب . الاغ . قاطر. شتر. مرکب . ستور. بارگی . دایرة؛ چیزی که محاذی آخر خوردگاه چاروا افتد. (منتهی الارب ) <span class=\"hlight\">:</span> <br />چاروایی دوسه و یک دو غلام <br />چاروا هم به کری خواهم داشت .<br /> <font color=\"Red\">خاقانی .</font><br />نه محقق بود نه دانشمند<br />چاروایی بر او کتابی چند .<br /> <font color=\"Red\">سعدی .</font><br /><BR><font color=\"Blue\">◄</font> هر چیزی که چهارپا داشته باشد. (برهان ) (آنندراج ). <BR><font color=\"Blue\">◄</font> الاغ . حمار. درازگوش . یعفور. (غالب دهات خراسان و در تداول روستائیان آنجا). و رجوع به چارپا شود.<br /></font></div>'),
(282320, 'چاروادار', '<span class=\"hlight\">چاروادار.</span> <font color=\"DarkGreen\"><b>[ چارْ ]</font></b> (نف مرکب ) مکاری . مکری . آنکه خر و استر و یابو کرایه دهد بار و مسافر را و خود نیز همراه ستور خود باشد. کسی که اسب والاغ و قاطر برای بردن بار و مسافر کرایه دهد. خرکچی . قاطرچی . ستوربان . شخصی که چند الاغ یا اسب و قاطر دارد که بوسیله ٔ آن ها مسافران را از محلی بمحلی میبرد یا بار و مال التجاره حمل میکندو از این بابت وجهی میگیرد و امرار معاش مینماید.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">وای بوقتی که چاروادار راهدار شود</span> :<br />ریکاکه چاروادار نیه من ورا سرای نشمه .<br />هفتا قاطر قطار نیه من ورا سرای نشمه .<br /></font></div>'),
(282321, 'چارواداری', '<span class=\"hlight\">چارواداری .</span> <font color=\"DarkGreen\"><b>[ چارْ ]</font></b>(حامص مرکب ) چهارپاداری . مال به کرادهی . مسافربری . بارکشی . <BR><font color=\"Blue\">◄</font> (ص نسبی ) منسوب به چاروادار.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">فحش چارواداری </span> ؛ دشنام خیلی زشت .<br /></font></div>'),
(282322, 'چاروارایگدر', '<span class=\"hlight\">چاروارایگدر.</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) نام یکی از طوائف ترکمن ساکن خاک ایران که درمحل «کوه خالا» سکونت دارند و <span class=\"hlight\" dir=\"rtl\">١٥٠</span> خانوارند. (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span>).<br /></font></div>'),
(282323, 'چارواردوچی', '<span class=\"hlight\">چارواردوچی .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) نام تیره ٔ مهمی از ترکمن های یموت ساکن خاک ایران که <span class=\"hlight\" dir=\"rtl\">٨٠٠</span> خانوارند و در «مراوه تپه » سکونت دارند. (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">١٠٢</span> و <span class=\"hlight\" dir=\"rtl\">٣٠٩</span>).<br /></font></div>'),
(282324, 'چاروای سواری', '<span class=\"hlight\">چاروای سواری .</span> <font color=\"DarkGreen\"><b>[ چارْ ی ِ س َ]</font></b> (ترکیب وصفی، اِ مرکب ) چهارپای سواری . دابة. (ترجمان القرآن ). مرکب سواری . ستور زینی . مقابل بارکش .<br /></font></div>'),
(282325, 'چاروغ', '<span class=\"hlight\">چاروغ .</span> (ترکی، اِ) چارغ . (برهان ) (آنندراج ). پای افزار دهقانان .(برهان ) (آنندراج ). پوزار. کفش . نوعی کفش مخصوص روستائیان . و رجوع به چارغ و چارق و چاروق و کفش شود.<br /></font></div>'),
(282326, 'چاروق', '<span class=\"hlight\">چاروق .</span> (ترکی، اِ) چاروغ . چارغ . چارق . کفش مخصوص دهقانان . پای افزار مخصوص روستائیان . نوعی کفش که دهقانان و روستائیان پوشند. و رجوع به چارغ و چارق و چاروغ و کفش شود.<br /></font></div>'),
(282327, 'چاروه', '<span class=\"hlight\">چاروه .</span> <font color=\"DarkGreen\"><b>[ وَ <span class=\"hlight\" dir=\"rtl\">/</span> وِ ]</font></b> (اِ) حیله . دستان . <BR><font color=\"Blue\">◄</font> بمعنی جدایی نیز آمده است .<br /></font></div>'),
(282328, 'چارپا', '<span class=\"hlight\">چارپا.</span> (اِ مرکب ) چاروا. (برهان ) (آنندراج ). مرکب سواری . (برهان ) (آنندراج ). اسب و استر و خر و شتر و امثال آن . (برهان ) (آنندراج ). هر حیوانی که دارای چهار دست و پا باشد. (ناظم الاطباء).ستور بارکش و سواری . (ناظم الاطباء). الاغ . حمار. درازگوش . نعم . (نصاب الصبیان ). ماشیه . مال <span class=\"hlight\">:</span> <br />همه خارسانها کنم چون بهشت <br />پر از مردم و چارپایان و کشت .<br /> <font color=\"Red\">فردوسی .</font><br />همه شهر و ده گر براندازی الا<br />علفخانه ٔ چارپایی نیابی .<br /> <font color=\"Red\">خاقانی .</font><br />که هر چارپایی که آرد شتاب <br />بپای اندر آرد کسی را ز خواب .<br /> <font color=\"Red\">نظامی .</font><br />بسی برداشت از دیبا و دینار<br />ز جنس چارپایان نیز بسیار.<br /> <font color=\"Red\">نظامی .</font><br />وز آنجا سوی قصر آمد بتعجیل <br />پس او چارپایان میل در میل .<br /> <font color=\"Red\">نظامی .</font><br />نه محقق بود نه دانشمند<br />چارپائی بر او کتابی چند.<br /> <font color=\"Red\">سعدی .</font><br />چارپائی برآورد آواز<br />و آن تلذذ بر او حرام کند.<br /> <font color=\"Red\">سعدی .</font><br />دَوْکَس ْ؛ عدد بسیار از چارپایان و گوسپندان . دعثور؛ بسیار از چارپایان . (منتهی الارب ). و رجوع به چاروا و چارپای شود.<br /></font></div>'),
(282329, 'چارپاره', '<span class=\"hlight\">چارپاره .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ ]</font></b>(اِ مرکب ) نوعی گلوله ٔ تفنگ . قطعات سرب غیر منتظم بریده کوچکتر از گلوله و بزرگتر از ساچمه . گلوله ٔ تفنگ که چهار یک گلوله های عادی است . نوعی گلوله ٔ غیر مدور که از سرب میریزند و بیشتر در تفنگ های سرپر قدیم .بکار میرفت . نوعی ساچمه ٔ بزرگ . یک قسمت از چهار قسمت گلوله ٔ تفنگ . قسمی گلوله مخصوص تفنگ و توپ . گلوله را چون به چهار قسمت کنند هر قسمت آن چهارپاره است که بجای ساچمه در تفنگ بکار برند. <BR><font color=\"Blue\">◄</font> نوعی رقص . (آنندراج ). <BR><font color=\"Blue\">◄</font> نام سازی که چهار وصل دارد. (آنندراج ). <BR><font color=\"Blue\">◄</font> وصله ٔ کفش . (ناظم الاطباء). یک جفت زنگ رقاصی . (ناظم الاطباء) <span class=\"hlight\">:</span> <br />به چارپاره ٔ زنگی به باد هرزه ٔ دزد<br />به بانگ زنگل نباش و کُم کُم نقاب .<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> یک چهارم خشت و آجر که در بنایی مصطلح است . پاره های آجر.<br /></font></div>'),
(282330, 'چارپاره زن', '<span class=\"hlight\">چارپاره زن .</span> <font color=\"DarkGreen\"><b>[ رَ <span class=\"hlight\" dir=\"rtl\">/</span> رِ زَ ]</font></b> (نف مرکب ) کسی که چارپاره زند و چارپاره زدن داند.<br />نوازنده ٔ ساز مخصوص که چارپاره نام دارد <span class=\"hlight\">:</span> <br />لاجرم شاید اربه رسته ٔ بید<br />زنگی چارپاره زن شد سار.<br /> <font color=\"Red\">خاقانی .</font><br />سار به شاخسار بر، زنگی چارپاره زن <br />خنده زنان چو زنگیان، ابر ز روی اغبری .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(282331, 'چارپای', '<span class=\"hlight\">چارپای .</span> (اِ مرکب ) هر حیوانی که دارای چهار دست و پا باشد. چارپا. چاروا. ذوات الاربع <BR><font color=\"Blue\">◄</font> مرکب سواری چون اسب و استر و خر و شتر و امثال آن . ستور. نعم . بهیمه . ماشیه . مال <span class=\"hlight\">:</span> <br />سکندر بدو گفت تاریک جای <br />بدو اندرون چون رود چارپای .<br /> <font color=\"Red\">فردوسی .</font><br />تبه شد بسی مردم و چارپای <br />یکی را نبد خنگ جنگی به جای .<br /> <font color=\"Red\">فردوسی .</font><br />ز بس مردن مردم و چارپای <br />پیی را نبد بر زمین نیز جای .<br /> <font color=\"Red\">فردوسی .</font><br />بدادی ز گنج آلت و چارپای <br />نماندی که پایش برفتی ز جای .<br /> <font color=\"Red\">فردوسی .</font><br />به ره بر یکی نامور دید جای <br />بسی اندرو مردم و چارپای .<br /> <font color=\"Red\">فردوسی .</font><br />درختان شده خشک و ویران سرای <br />همه مرز بی مردم و چارپای .<br /> <font color=\"Red\">فردوسی .</font><br />کسی را کجا تخم یا چارپای <br />بهنگام ورزش نبودی بجای .<br /> <font color=\"Red\">فردوسی .</font><br />مرا تخت و گنج است و هم چارپای <br />بدینسان بمانم سزاوار جای .<br /> <font color=\"Red\">فردوسی .</font><br />همه هر چه دید اندرو چارپای <br />بیفکند و ز یشان بپرداخت جای .<br /> <font color=\"Red\">فردوسی .</font><br />به ایران نمانم بر و بوم و جای <br />نه کاخ و نه ایوان و نه چارپای .<br /> <font color=\"Red\">فردوسی .</font><br />ز خون چنان بی زبان چارپای <br />چه آمد بر آن مرد ناپاکرای .<br /> <font color=\"Red\">فردوسی .</font><br />ستایش گرفتند بر رهنمای <br />فزایش گرفت از گیا چارپای .<br /> <font color=\"Red\">فردوسی .</font><br />در و دشت گل بود و بام و سرای <br />جهان گشت پر سبزه و چارپای .<br /> <font color=\"Red\">فردوسی .</font><br />ز ایوان و خرگاه و پرده سرای <br />همان خیمه و آخور و چارپای .<br /> <font color=\"Red\">فردوسی .</font><br />با چنین چارپای لنگ بود <br />سوی هفت آسمان شدن دشوار.<br /> <font color=\"Red\">سنائی .</font><br />در این چارسو چند سازیم جای <br />شکم چارسو کرده چون چارپای .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> گوسپند و گاو <span class=\"hlight\">:</span> <br />مر او را ز دوشیدنی چارپای <br />ز هر یک هزار آمدندی بجای .<br /> <font color=\"Red\">فردوسی .</font><br />ز هر گونه از مرغ و از چارپای <br />خورش کرد و آورد یک یک بجای .<br /> <font color=\"Red\">فردوسی .</font><br /> <BR><font color=\"Blue\">◄</font> چارپایه ٔ تخت <span class=\"hlight\">:</span> <br />کعبه است حضرت او کز چارپای تختش <br />بیرون ز چارارکان، ارکان تازه بینی .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(282332, 'چارپای بند', '<span class=\"hlight\">چارپای بند.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِ مرکب ) کنایه از عناصر اربعه است که آدمی مجموعه ٔ آن است . (آنندراج ) <span class=\"hlight\">:</span> <br />با چنین چارپای بند بود <br />سوی هفت آسمان شدن دشوار.<br /><font color=\"Red\">سنائی .</font><br /></font></div>'),
(282333, 'چارپایه', '<span class=\"hlight\">چارپایه .</span><font color=\"DarkGreen\"><b>[ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (اِ مرکب ) چارپا و هر چیز که دارای چهار پایه باشد. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کرسیی که دارای چهارپایه باشد. کرسیچه . نوعی صندلی مخصوص که در کفشدوزی ها یا قهوه خانه ها برای نشستن بکار میرود.<br /></font></div>'),
(282334, 'چارپایک', '<span class=\"hlight\">چارپایک .</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِ مرکب ) نوعی شپش . شپشک . شپشه . قمقام . نوعی حشره ٔ طفیلی است که بر عانه و مژگان و زیر بغل پدید آید مانند شپش و فرق آن با شپش آن است که چارپایک را پایهای بسیار بود و سخت بر بشره چفسنده بود.<br /></font></div>'),
(282335, 'چارپایی', '<span class=\"hlight\">چارپایی .</span> (حامص ) منسوب به چارپا <span class=\"hlight\">:</span> <br />چو پاکی و پاکیزه رایی کنی <br />چرا دعوی چارپایی کنی .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282336, 'چارپخ', '<span class=\"hlight\">چارپخ .</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (اِ مرکب ) نوعی از خیمه که در هند «بی چوبه » خوانند. (آنندراج ). <BR><font color=\"Blue\">◄</font> هر چیز چهارگوشه . (ناظم الاطباء).<br /></font></div>'),
(282337, 'چارپدر', '<span class=\"hlight\">چارپدر.</span> <font color=\"DarkGreen\"><b>[ پ ِ دَ ]</font></b> (اِ مرکب ) آباء اربعه . چهارعنصر.<br /></font></div>'),
(282338, 'چارپر', '<span class=\"hlight\">چارپر.</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (اِ مرکب ) قسمی از صراحی شراب . (فرهنگ ناظم الاطباء). قسمی شیشه برای شراب یا سرکه و غیره . قسمی شیشه ٔ چهارپهلو. <BR><font color=\"Blue\">◄</font> یکنوع چماق که سری آهنین با چهارپره دارد. <BR><font color=\"Blue\">◄</font> قسمی گرز. <BR><font color=\"Blue\">◄</font> (ص مرکب ) قسمی تیر دارای چهارپر <span class=\"hlight\">:</span> <br />خدنگی بینداختی چارپر<br />از این سر بدان سر نکردی گذر.<br /> <font color=\"Red\">فردوسی .</font><br />خدنگی دگر باره هم چارپر<br />بچرخ اندرون راند و بگشاد پر.<br /> <font color=\"Red\">فردوسی .</font><br />خدنگ چارپر همچون درختان <br />برستند ازدو چشم شوربختان .<br /> <font color=\"Red\">فخرالدین اسعد (ویس و رامین ).</font><br /> <BR><font color=\"Blue\">◄</font> دارای چهار بال و پر برای پریدن . کنایه است از مرغ تیزپرواز یا مرکب تندرو <span class=\"hlight\">:</span> <br />پرگرفته نوند چارپرش <br />وز وشاقان یکی دو بر اثرش .<br /> <font color=\"Red\">نظامی .</font><br />عقابی چارپر یعنی که در زیر<br />نهنگی در میان یعنی که شمشیر.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282339, 'چارپهلو', '<span class=\"hlight\">چارپهلو.</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (اِ مرکب ) نوعی از زنجیر نفیس . (آنندراج ). <BR><font color=\"Blue\">◄</font> قسمی از زنجیر گرانبها. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (ص مرکب ) هر چیز که دارای چهار دم و چهار لبه باشد. (ناظم الاطباء) <span class=\"hlight\">:</span> <br />به میدان درآمد چو عفریت مست <br />یکی حربه ٔ چارپهلو بدست .<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> کنایه از تنومند و فربه . (آنندراج ).<br /></font></div>'),
(282340, 'چارپهلو خفتن', '<span class=\"hlight\">چارپهلو خفتن .</span> <font color=\"DarkGreen\"><b>[ پ َ خ ُ ت َ ]</font></b> (مص مرکب ) کنایه از خواب غفلت که هیچ خبر از خویشتن نباشد. (آنندراج ).<br /></font></div>'),
(282341, 'چارپهلو شدن', '<span class=\"hlight\">چارپهلو شدن .</span> <font color=\"DarkGreen\"><b>[ پ َ ش ُ دَ ]</font></b> (مص مرکب ) کنایه از چیز بسیار خوردن و بر پشت خوابیدن است . (برهان ) (آنندراج ). بسیار خوردن . سخت سیر شدن . ارتباع . تضلع <span class=\"hlight\">:</span> <br />آز را کز بدو خلقت جوع کلبی همدم است <br />چارپهلو شد شکم از سفره ٔ یغمای تو.<br /> <font color=\"Red\">ابن یمین .</font><br />به خوان نعمت تو آز چارپهلو شد<br />ز بس که خورد مربا وقلیه و کولانج .<br /><font color=\"Red\">شمس فخری (از آنندراج ).</font><br /></font></div>'),
(282342, 'چارپهلو کردن', '<span class=\"hlight\">چارپهلو کردن .</span> <font color=\"DarkGreen\"><b>[ پ َ ک َ دَ ]</font></b> (مص مرکب ) کنایه است از چاق و فربه کردن . شکم انباشتن <span class=\"hlight\">:</span> <br />شکم ز خوان عطای تو چارپهلو کرد<br />اگر چه بود گرفتار جوع کلبی آز.<br /> <font color=\"Red\">ابن یمین .</font><br />حرص را گر چه بود علت جوع کلبی <br />چارپهلو کند از خوان نوال تو شکم .<br /> <font color=\"Red\">ابن یمین .</font><br />زود در گل می نشیند کشتی سنگین در آب <br />چارپهلو میکنی خود را از آب و نان چرا؟<br /><font color=\"Red\">صائب .</font><br /></font></div>'),
(282343, 'چارپیوند', '<span class=\"hlight\">چارپیوند.</span> <font color=\"DarkGreen\"><b>[ پ َی <span class=\"hlight\" dir=\"rtl\">/</span> پ ِی وَ ]</font></b> (اِ مرکب ) چارطبع (سردی و گرمی و تری و خشکی ) <span class=\"hlight\">:</span> <br />ز خود بگذر که با این چارپیوند<br />نشایدرست از این هفت آهنین بند.<br /><font color=\"Red\">نظامی .</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(282344, 'چارچار', '<span class=\"hlight\">چارچار.</span> (اِ مرکب ) چهار روز آخر چله ٔ بزرگ (هفتم تا دهم بهمن ماه ).و چهار روز اول چله ٔ کوچک زمستان . (یازدهم تا چهاردهم بهمن ماه ) (از ناظم الاطباء). نام هشت روز از زمستان که چهار روز آن در آخر چله ٔ بزرگ و چهار روز در اول چله ٔ کوچک است . نام هشت روز از فصل زمستان که از سی و ششمین روز تا چهل و چهارمین روز را شامل است .<br /></font></div>'),
(282345, 'چارچار', '<span class=\"hlight\">چارچار.</span> (اِ مرکب ) بمعنی برابری و هم چشمی و همتائی کردن مخالفین با یکدیگر چنانکه دوچار شدن هم افاده ٔ همین معنی میکند که دو نفر از سویی و دو از سویی و هم چنین است چار از سویی و چار از سویی دیگر که مقابله ٔ مقدمه ٔمقاتله است . (آنندراج ). رجوع به چارچار کردن شود.<br /></font></div>'),
(282346, 'چارچار زدن', '<span class=\"hlight\">چارچار زدن .</span> <font color=\"DarkGreen\"><b>[ زَ دَ ]</font></b> (مص مرکب ) هرزه و پوچ گفتن . (آنندراج ). بیهوده گفتن . (ناظم الاطباء).<br /></font></div>'),
(282347, 'چارچار کردن', '<span class=\"hlight\">چارچار کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) برابری و مقابله کردن <span class=\"hlight\">:</span> <br />تا بر کسی گرفته نباشد خدای خشم <br />پیش تو ناید و نکند با تو چارچار.<br /> <font color=\"Red\">منوچهری .</font><br /><BR><font color=\"Blue\">◄</font> ملاقات کردن . (ناظم الاطباء).<br /></font></div>'),
(282348, 'چارچارگوی', '<span class=\"hlight\">چارچارگوی .</span> (نف مرکب ) کنایه از هرزه و پوچ گوی . (آنندراج ) <span class=\"hlight\">:</span> <br />ارباب سخن گرچه که پیرم دانند<br />از طبع جوان من سخن می رانند<br />خواهم که کنم فکر رباعی چندی <br />گو شاعر چارچارگویم خوانند.<br /><font color=\"Red\">قبول (از آنندراج ).</font><br /></font></div>'),
(282349, 'چارچب', '<span class=\"hlight\">چارچب .</span> <font color=\"DarkGreen\"><b>[ چ َ ]</font></b> (اِ مرکب ) تلفظی ازچادرشب . چادرشب در بعضی لهجه ها، صورتی از چادرشب .<br /></font></div>'),
(282350, 'چارچرخه', '<span class=\"hlight\">چارچرخه .</span> <font color=\"DarkGreen\"><b>[ چ َ خ َ <span class=\"hlight\" dir=\"rtl\">/</span> خ ِ ]</font></b> (اِ مرکب ) نوعی گاری است که دارای چهار چرخ است . رجوع به گاری شود.<br /></font></div>'),
(282351, 'چارچشم', '<span class=\"hlight\">چارچشم .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (ص مرکب ) کنایه از بسیار مشتاق و منتظر. (آنندراج ). نگران و مشتاق . (ناظم الاطباء) <span class=\"hlight\">:</span> <br />من چار چشمم ز آن دورخ چاری دگر میداشتم <br />میداشت چون شطرنج اگر آن شاه خوبان چار رخ .<br /> <font color=\"Red\">ملاطغرا (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> صفت سگ نیز واقع شود. (آنندراج ). سگ و یا گوسپندی که خال سیاهی بالای هر یک از دو چشم داشته باشد. (ناظم الاطباء) <span class=\"hlight\">:</span> <br />سگ نفس را رفته از کار چشم <br />تو از عینکش کرده ای چارچشم .<br /><font color=\"Red\">قدسی (از آنندراج ).</font><br />مَثَل آنکه او بود احمق <br />مردمان فیلسوف دانندش <br />همچو آن سگ بود که باشد کور <br />مردمان چارچشم خوانندش .<br /> <font color=\"Red\">دهقان علی شطرنجی (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> کسی که عینک میگذارد. (ناظم الاطباء).<br /></font></div>'),
(282352, 'چارچشم شدن', '<span class=\"hlight\">چارچشم شدن .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ش ُ دَ ]</font></b> (مص مرکب ) کنایه است از بدقت نگاه کردن . با دقت و کنجکاوی بسیار در کسی یا چیزی نگریستن .<br /></font></div>'),
(282353, 'چارچشمه', '<span class=\"hlight\">چارچشمه .</span> <font color=\"DarkGreen\"><b>[ چ َ م َ ]</font></b> (اِخ ) نیز از بلوک حمزه لوی جاپلق است و این چار چشمه شش قلعه میباشد واقع در یک محل و هر یک از قلاع رعیت نشین و آب و ملک علیحده دارد شهر جاپلق عبارت از همین چار چشمه است چنانکه در جاپلق نگاشته شد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣</span>).<br /></font></div>'),
(282354, 'چارچشمه', '<span class=\"hlight\">چارچشمه .</span> <font color=\"DarkGreen\"><b>[ چ َ م َ ]</font></b> (اِخ ) از قرای بلوک پشته ٔ جاپلق است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٣</span>).<br /></font></div>'),
(282355, 'چارچشمی', '<span class=\"hlight\">چارچشمی .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (ص نسبی ) با چهار چشم، کنایه است از مراقبت بسیار؛ چارچشمی چیزی را پائیدن، مواظب بودن که آن را ندزدند یا به آن آسیبی نرسد. رجوع به چارچشمی پائیدن شود. <BR><font color=\"Blue\">◄</font> چارچشمی گریه کردن، سخت اظهار فقر یا بی تمتعی از کاری کردن و غالباً بدروغ . نهایت اظهار فقر یا بدبختی با گریه کردن . رجوع به چارچشمی گریه کردن شود.<br /></font></div>'),
(282356, 'چارچشمی گریه کردن', '<span class=\"hlight\">چارچشمی گریه کردن .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ گ َ <span class=\"hlight\" dir=\"rtl\">/</span> گ ِرْ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ک َ دَ ]</font></b> (مص مرکب ) سخت گریستن . <BR><font color=\"Blue\">◄</font> بی اندازه اظهار فقر یا بدبختی کردن . رجوع به چارچشمی شود.<br /></font></div>'),
(282357, 'چارچمن', '<span class=\"hlight\">چارچمن .</span> <font color=\"DarkGreen\"><b>[ چ َ م َ ]</font></b> (اِخ ) در حوالی قندهار است . از وقایع مهمه که در آنجا روی داده این است که محراب خان سپهسالار شاه عباس دویم بعد از فتح قلعه ٔ بست و غیره هنگام مراجعت در روز یکشنبه شهر صفر هزار وپنجاه و هشت هجری در چارچمن غنایم و فیل و اسلحه ٔ زیادی که از دشمن گرفته بود از شأن حضور شاه عباس گذرانید. گویند اسم باغی است بزرگ در دو منزلی اورکنج که از هر خیابان آن بحوضی میرسند و باز چهار خیابان دیگر و بدینصورت تا آخر. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(282358, 'چارچند', '<span class=\"hlight\">چارچند.</span> <font color=\"DarkGreen\"><b>[ چ َ]</font></b> (اِ مرکب ) چهار تا. چهار هنگام . (ناظم الاطباء).<br /></font></div>'),
(282359, 'چارچنگولی', '<span class=\"hlight\">چارچنگولی .</span> <font color=\"DarkGreen\"><b>[ چ َ ]</font></b> (ص نسبی ) تن و دست و پای کژ و خشک شده . با دستها و پاهای خشک شده در حالی که جمع و خم شده باشد. با دست و پای جمع شده و شخ مانده چنانکه مرده ای یامغشی ٌ علیهی . خشک مانده با دستها و پاهای بسوی تنه گرد آمده چون مبتلا بفالجی یا از سرمازدگی مرده ای و غیره . <BR><font color=\"Blue\">◄</font> در تداول عامه با تمام بدن متشنج و خشک . گردآمدن ناموزون اعضای تن خفته ومصروع و مرده (با فعل «ماندن » و «شدن » صرف شود).<br /></font></div>'),
(282360, 'چارچوب', '<span class=\"hlight\">چارچوب .</span> (اِ مرکب ) هر چهارچوب دروازه یعنی هر دو چوب بالائین و فرودین و هر دو چوب بازوی در. (آنندراج ). چارچوب در. چارچوبه . حاشیه ٔ چوبین در که دو مصراع یا لت <font color=\"DarkGreen\"><b>[ ت ِ ]</font></b> در یک لته در آن جای گیرد. دریواس . (برهان ). <BR><font color=\"Blue\">◄</font> چهار قطعه چوبی که در حاشیه ٔ چیزی قرار دهند. (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چارچوب عکس </span> ؛ قاب عکس .<br /> <BR><font color=\"Blue\">◄</font> مجازاً به معنی چارستون بدن آمده است <span class=\"hlight\">:</span> <br />پیش از این کاین چارچوب جسم چون مهرم بسوخت <br />سقف نه گردون ز آه عاشقان پردود بود.<br /> <font color=\"Red\">ناصرخسرو؟ (از آنندراج ).</font><br />و رجوع به چهارچوب شود.<br /></font></div>'),
(282361, 'چارچوب فطرت', '<span class=\"hlight\">چارچوب فطرت .</span> <font color=\"DarkGreen\"><b>[ ب ِ ف ِ رَ ]</font></b> (اِ مرکب ) عناصر اربعه . (آنندراج ).<br /></font></div>'),
(282362, 'چارچوبه', '<span class=\"hlight\">چارچوبه .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) یکی از قلاع قراولخانه ای است که در سمت مشرق و شمال بجنورد مابین خاک زعفرانلو و شادلو واقع است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٤٤</span>).<br /></font></div>'),
(282363, 'چارچوبه', '<span class=\"hlight\">چارچوبه .</span> <font color=\"DarkGreen\"><b>[ ب َ <span class=\"hlight\" dir=\"rtl\">/</span> ب ِ ]</font></b> (اِ مرکب ) چارچوب . چهارچوب . چهارچوبه . چارچوبه ٔ در. چارچوبی که مصراع در یک لتی یا دو مصراع در بر آن استوار شود. <BR><font color=\"Blue\">◄</font> چهار قطعه چوبی که در حاشیه ٔ چیزی قرار دهند. (ناظم الاطباء). و رجوع بچارچوب و چهارچوب و چهارچوبه شود.<br /></font></div>'),
(282364, 'چارک', '<span class=\"hlight\">چارک .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ مرکب ) مخفف چهاریک . ربع. یک چهارم . یک حصه از چهار حصه . <BR><font color=\"Blue\">◄</font> چهاریک من (ده سیر) چهاریک ذرع . (ده گره ) ربع یک من . یک چهارم من . <BR><font color=\"Blue\">◄</font> ربع یک ذرع .یک چهارم ذرع . <BR><font color=\"Blue\">◄</font> ده سیر (در تداول عامه ). <BR><font color=\"Blue\">◄</font> پنجاه (مخفف پنجاه درم که یک چهارم من تبریز باشد). و رجوع به ربع و چاریک و چهاریک شود.<br /></font></div>'),
(282365, 'چارک', '<span class=\"hlight\">چارک .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِ مرکب ) چاووش . (برهان ). نقیب قافله . (برهان ) <span class=\"hlight\">:</span> <br />به یک دم هر دو تن از جا بجستند<br />چو چارک چوب در بیچاره بستند.<br /><font color=\"Red\">نزاری قهستانی .</font><br /></font></div>'),
(282366, 'چارک', '<span class=\"hlight\">چارک .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) قریه ای است از قرای توابع بلوک لارستان فارس در کنار بحرالعجم واقع و جزو بنادر محسوب میشود. اهالی آنجا و اکثر لارستان شافعی مذهب می باشند. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>) و مؤلف فارسنامه ذیل «ناحیه ٔ شیب کوه لارستان » نویسد: قصبه ٔ این ناحیه ٔ «بندر چارک » است بمسافت بیست و پنج فرسخ از شهر لار دور افتاده است ... و رجوع به جغرافی سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٤٨٣</span> شود.<br /></font></div>'),
(282367, 'چارکان', '<span class=\"hlight\">چارکان .</span> (اِ مرکب ) عبارت از کان آتشی که گوگرد و نوشادر کانی از آن برآید. (آنندراج ). <BR><font color=\"Blue\">◄</font> کنایه از کان لعل و یاقوت، دوم کان آبی که مروارید و مرجان ازوست، سوم کان بادی که نباتاب قیمتی از آن خیزد و چهارم کان خاکی که الماس و زر و نقره از آن پیدا شود. (آنندراج ).<br /></font></div>'),
(282368, 'چارکتاب', '<span class=\"hlight\">چارکتاب .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (اِخ ) چهارکتاب . کتب اربعة. چارکتاب مقدس که عبارتند از: زبور داود، توریة موسی، انجیل عیسی و قرآن محمد (ص ).<br /></font></div>'),
(282369, 'چارکرانه', '<span class=\"hlight\">چارکرانه .</span> <font color=\"DarkGreen\"><b>[ ک َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ مرکب ) چارگوشه ٔ مربع.<br /></font></div>'),
(282370, 'چارکرانگی', '<span class=\"hlight\">چارکرانگی .</span> <font color=\"DarkGreen\"><b>[ ک َ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (حامص مرکب ) چگونگی چهارکرانه . <BR><font color=\"Blue\">◄</font> تربیع.<br /></font></div>'),
(282371, 'چارکش', '<span class=\"hlight\">چارکش .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِ مرکب ) اصطلاح شنا.<br /></font></div>'),
(282372, 'چارکش', '<span class=\"hlight\">چارکش .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) قریه ای است از قرای قدیم النسق . از آب قنات مشروب میشود. هوایش ییلاقی است و قلیلی رعیت دارد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span>).<br /></font></div>'),
(282373, 'چارکن', '<span class=\"hlight\">چارکن .</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (ص مرکب ) چرکین . شوخگین <span class=\"hlight\">:</span> <br />هم از اینسان بعید خواهی رفت <br />شوخگن جبه چارکن دستار.<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(282374, 'چارکنار', '<span class=\"hlight\">چارکنار.</span> <font color=\"DarkGreen\"><b>[ ک ِ ]</font></b> (اِخ )قصبه ای است دلنشین در نه فرسخی و سمت شمال مقر سلطنت کابل است . جوانب اربعه ٔ آن واسع و در یک فرسخی طرف مغرب آن کوه بزرگی واقع و دامن آن کوه گشاده و در آنجا ارغوان زاری است که طول آن یک فرسخ و عرض آن نیم فرسخ باشد و در فصل بهار مانند آن ارغوان زار در هیچ دیار دیده نگردد و نگردیده و در چارکنار قریب یک هزار باب خانه است و بخوبی آب و هوا معروف خاکش طرب انگیز و حسن خیز و هوایش معتدل و اندک بسردی مایل است و قابل است که مثل گردد چنانکه من گفته ام <span class=\"hlight\">:</span> <br />شده از ارغوان دگر گلزار<br />ارغوان زار شهر چارکنار.<br /> <font color=\"Red\">(انجمن آرای ناصری ).</font><br />و رجوع به مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥٠</span> و <span class=\"hlight\" dir=\"rtl\">٥١</span> شود.<br /></font></div>'),
(282375, 'چارکه', '<span class=\"hlight\">چارکه .</span> <font color=\"DarkGreen\"><b>[ رَ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (اِ مرکب ) چهاریک آجر. نصف نیمه ٔ آجر. در اصطلاح بنایان قطعه ٔ شکسته ای از آجر است که تقریباًبرابر چهاریک آجر باشد. شکسته آجر. یک چهارم آجر.<br /></font></div>'),
(282376, 'چارکوکب', '<span class=\"hlight\">چارکوکب .</span> <font color=\"DarkGreen\"><b>[ ک َ ک َ ]</font></b> (اِخ ) نام چهارستاره از قدر چهارم که در صورت قطعة الفرس است .<br /></font></div>'),
(282377, 'چارکیف', '<span class=\"hlight\">چارکیف .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) از مزارع چارگنبد سیرجان است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥١</span>).<br /></font></div>'),
(282378, 'چارگامه', '<span class=\"hlight\">چارگامه .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (ص مرکب ) اسب رهوار خوشرفتار باشد. (برهان ). کنایه از اسب راهوار. (آنندراج ). اسب تیزرو. اسب راهوار <span class=\"hlight\">:</span> <br />ساقیا اسب چارگامه بران <br />تا رکاب سه گانه بستانیم .<br /> <font color=\"Red\">خاقانی (از آنندراج ).</font><br />ز ابلق چارگامه ٔ شب و روز<br />ران یکرانت را لگد مرساد.<br /> <font color=\"Red\">خاقانی .</font><br /><BR><font color=\"Blue\">◄</font> و کنایه از گرم کردن هنگامه ٔ عشرت هم هست . (برهان ). و رجوع به چهارگامه شود.<br /></font></div>'),
(282379, 'چارگان', '<span class=\"hlight\">چارگان .</span> (اِ مرکب ) چهارگان : ظاهراً ببهای چهار درهم یا بوزن چهار مثقال (بقیاس بیستگان و بیستگانی <font color=\"DarkGreen\"><b>[ العشرینیه ]</font></b> و کمر هزارگانی ) <span class=\"hlight\">:</span> <br />خریدی همی مرد بازارگان <br />ده آهو و گوری بها چارگان .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(282380, 'چارگاه', '<span class=\"hlight\">چارگاه .</span> (اِ مرکب ) چهارگاه . نام شعبه ای از موسیقی . (غیاث ). اصطلاحی در موسیقی . مقامی از موسیقی . اسم آهنگی از موسیقی . نام دستگاهی در موسیقی ایرانی . نام یکی از آهنگ های موسیقی ایران . <BR><font color=\"Blue\">◄</font> کنایه باشد ازکالبد عنصری که مرکب از اربعة عناصر است . (غیاث ).<br /></font></div>'),
(282381, 'چارگاه', '<span class=\"hlight\">چارگاه .</span> (اِ مرکب ) قلب چراگاه . (آنندراج ) <span class=\"hlight\">:</span> <br />به خشتی نقش صد اژدر نمودی <br />مقام چارگاه خر نمودی .<br /><font color=\"Red\">فوقی (در تعریف نقاشی فرهاد از آنندراج ).</font><br /></font></div>'),
(282382, 'چارگاهی', '<span class=\"hlight\">چارگاهی .</span> (اِخ ) تیره ای از ایل طیبی از شعبه ٔ لیراوی از ایلات کوه کیلویه ٔ فارس . (جغرافی سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٨٩</span>).<br /></font></div>'),
(282383, 'چارگل', '<span class=\"hlight\">چارگل .</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (اِ مرکب ) قسمی از داغ . (آنندراج ) <span class=\"hlight\">:</span> <br />ز تعلیمیش پخته ٔ چارجل <br />بود نزد فارس خط چارگل .<br /> <font color=\"Red\">ملاطغرا (در تعریف براق، از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> کنایه از نقش پای سگ . (آنندراج ). <BR><font color=\"Blue\">◄</font> چهارگل خودرو چون بنفشه و پنیرک و کدو و نیلوفر که جوشانده ٔ آنها جنبه ٔ داروئی دارد و بعنوان ملّین بکار میرود.<br /></font></div>'),
(282384, 'چارگنبد', '<span class=\"hlight\">چارگنبد.</span> <font color=\"DarkGreen\"><b>[ گُم ْ ب َ ]</font></b> (اِخ ) از قرای کوهستان سیرجان است . بعضی از ایلات در مزارع این قریه ییلاق مینمایند. شاه شجاع بعد از ملاقات با کلومیر حسین بفتح و فیروزی امیدوار شده عزیمت شیراز نمود و در چارگنبد نزول کرد و ازاینجا بطرف مقصود راند. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٥١</span>).<br /></font></div>'),
(282385, 'چارگهر', '<span class=\"hlight\">چارگهر.</span> <font color=\"DarkGreen\"><b>[ گ ُ هََ ]</font></b> (اِ مرکب ) چارگوهر. چار عنصر. چارآخشیج . عناصر اربعه . آب و خاک و باد و آتش <span class=\"hlight\">:</span> <br />پسری چون تو نزادند در این شش روزن <br />هفت سیاره و نه دایره و چارگهر.<br /> <font color=\"Red\">سنایی .</font><br />پیر حکمت نه پیر هفت اختر<br />پیر ملت نه پیر چارگهر.<br /> <font color=\"Red\">سنایی .</font><br />بر هفت خزانه در گشاده <br />بر چارگهر قدم نهاده .<br /> <font color=\"Red\">نظامی .</font><br />و رجوع به چارگوهر و چهارگوهر شود.<br /></font></div>'),
(282386, 'چارگوش', '<span class=\"hlight\">چارگوش .</span> (ص مرکب، اِ مرکب ) چهارگوش . چارگوشه ای .چهارضلعی . دارای چهارضلع. مربع. چارزاویه ای . دارای چهارزاویه . سطحی که اضلاع آن مساوی و زوایای آن عمود بر یکدیگر باشند. رجوع به چارگوشه و چهارگوشه شود.<br /></font></div>'),
(282387, 'چارگوشه', '<span class=\"hlight\">چارگوشه .</span> <font color=\"DarkGreen\"><b>[ ش َ <span class=\"hlight\" dir=\"rtl\">/</span> ش ِ ]</font></b> (اِ مرکب ) هر چیز را گویند که مربع باشد. (برهان ). ذو اربعة زوایا. چارگوشه ای . چارزاویه ای . <BR><font color=\"Blue\">◄</font> کنایه از تخت پادشاهان است که بعربی «سریر» خوانند. (برهان ). کنایه از تخت بود که آنرا«پات » و «گاه » نیز گویند و به تازی «سریر» خوانند. (آنندراج ). <BR><font color=\"Blue\">◄</font> چاردیواری . خانه ٔ کوچک . گوشه . زاویه <span class=\"hlight\">:</span> <br />آن را که چارگوشه ٔ عزلت میسر است <br />گو پنج نوبة زن که شه هفت کشور است .<br /> <font color=\"Red\">اثیرالدین (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> کنایه از تابوت هم هست . (برهان ) (آنندراج ).<br /> <BR><font color=\"Blue\">◄</font> چارسمت . چارطرف . چارجانب <span class=\"hlight\">:</span> <br />بفرمود تا نامور پهلوان <br />همی گشت بر چارگوشه ٔ جهان .<br /> <font color=\"Red\">فردوسی .</font><br />ندای هاتف غیبی ز چارگوشه ٔ عرش <br />صدای کوس الهی به پنج نوبت لا.<br /> <font color=\"Red\">خاقانی .</font><br />چون فرو دید چارگوشه ٔ کاخ <br />ساحتی دید چون بهشت فراخ .<br /> <font color=\"Red\">نظامی .</font><br />و رجوع به چهارگوشه شود.<br /></font></div>'),
(282388, 'چارگوشی', '<span class=\"hlight\">چارگوشی .</span> (اِ مرکب ) هر چه چهار گوشه داشته باشد. مربع. <BR><font color=\"Blue\">◄</font> صراحی . (برهان ). کنایه است از صراحی چهارپهلو. (آنندراج ). صراحی را گویند که چهارگوشه داشته باشد. (جهانگیری ) <span class=\"hlight\">:</span> <br />چارگوشی و چارگوشه ٔ باغ <br />گر بدست آیدت فرومگذار.<br /> <font color=\"Red\">شهید (از جهانگیری ).</font><br /><BR><font color=\"Blue\">◄</font> سبویی را گویند که چهار دسته داشته باشد. (برهان ).<br /></font></div>'),
(282389, 'چارگوهر', '<span class=\"hlight\">چارگوهر.</span> <font color=\"DarkGreen\"><b>[ گ َ <span class=\"hlight\" dir=\"rtl\">/</span> گ ُ هََ ]</font></b> (اِ مرکب ) چارعنصر. چارآخشیج . عناصراربعه . آخشیجان . آب و خاک و باد و آتش <span class=\"hlight\">:</span> <br />چو این چارگوهر بجای آمدند<br />ز بهر سپنجی سرای آمدند.<br /> <font color=\"Red\">فردوسی .</font><br />میراث ستان هفت کشور<br />منصوبه گشای چارگوهر.<br /> <font color=\"Red\">نظامی .</font><br />ز آن بزرگی که در سگالش اوست <br />چارگوهر چهاربالش اوست .<br /> <font color=\"Red\">نظامی .</font><br />جهت را شش گریبان در سرافکند<br />زمین را چارگوهر در برافکند.<br /> <font color=\"Red\">نظامی .</font><br />و رجوع به چارگهر و چهارگوهر شود.<br /></font></div>'),
(282390, 'چاریار', '<span class=\"hlight\">چاریار.</span> <font color=\"DarkGreen\"><b>[ چارْ ]</font></b>(اِخ ) چهاریار. خلفای اربعة. خلفای راشدین . ابوبکربن ابی قحافه، عمربن الخطاب، عثمان بن عفان، علی بن ابیطالب (ع ). ابوبکر و عمر و عثمان و علی (ع ) <span class=\"hlight\">:</span> <br />بی مهر چاریار در این پنج روزه عمر<br />نتوان خلاص یافت از این ششدر فنا.<br /> <font color=\"Red\">خاقانی .</font><br />گواهی رود از که ؟ از چاریار<br />که صد آفرین باد برهر چهار.<br /> <font color=\"Red\">نظامی .</font><br />چاریارش به اصل دان و بفرع <br />چاردیوار گنج خانه ٔ شرع .<br /> <font color=\"Red\">نظامی .</font><br />ز آن جمله محرم حرم خاص چاریار<br />هر چار، قبله ٔ حرم و کعبه ٔ وفا.<br /> <font color=\"Red\">عطار.</font><br />مونس احمد به مجلس، چاریار<br />مونس بوجهل عتبه و ذوالخمار.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(282391, 'چاریاری', '<span class=\"hlight\">چاریاری .</span> <font color=\"DarkGreen\"><b>[ چارْ ]</font></b>(ص نسبی ) چهاریاری . منسوب به چهاریار. قائل به خلافت خلفای اربعة بترتیب . سنی . از اهل سنت و جماعت . از عامه . یک تن از اهل سنت و جماعت . از اهل تسنن . عمری . چار خلیفه ای .<br /></font></div>'),
(282392, 'چاریک', '<span class=\"hlight\">چاریک .</span> <font color=\"DarkGreen\"><b>[ چارْ ی َ ]</font></b> (اِخ ) ناحیه ای است مابین هرات و بلخ . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٦٦</span>).<br /></font></div>'),
(282393, 'چاریک', '<span class=\"hlight\">چاریک .</span> <font color=\"DarkGreen\"><b>[ چارْ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (اِ مرکب ) چهاریک . یک حصه از چهار حصه هر چیز باشد. (برهان ) (آنندراج ). ربع. یک چهارم . یک قسمت از چهار قسمت هر چیز. یک بخش از چهار بخش هر چیز <span class=\"hlight\">:</span> <br />سه یک بود تا چاریک بهر شاه <br />قباد آمد و ده یک آورد راه .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(282394, 'چاریک کار', '<span class=\"hlight\">چاریک کار.</span> <font color=\"DarkGreen\"><b>[ چارْ ی َ <span class=\"hlight\" dir=\"rtl\">/</span> ی ِ ]</font></b> (نف مرکب ) چاریک کارنده . چهاریک کار. زارع که از حاصل چهاریک برمیدارد. دهقانی که طبق معمول بعضی از مناطق کشاورزی ایران از بذری که میکارد چهاریک سهم برمیدارد.<br /></font></div>'),
(282395, 'چاریک کار', '<span class=\"hlight\">چاریک کار.</span> <font color=\"DarkGreen\"><b>[ ی َ ]</font></b> (اِخ ) نام قصبه ای است از توابع کابل .(برهان ذیل معنی چاریک ) (آنندراج در معنی چاریک ).<br /></font></div>'),
(282396, 'چاسان فاسان', '<span class=\"hlight\">چاسان فاسان .</span> (اِ مرکب، اتباع ) در تداول عوام : آرایش . بزک . توالت . صدکار. آرایش زن روی را با سرخاب و سفیداب و وسمه و خطاط و غیره . آرایش زن چهره خود را بسفیداب و سرخاب و وسمه و سرمه و غیره . در تداول عوام : بزک دوزک . آرای گیرای . (در اصطلاح زنان روستایی فیض آباد بخش تربت حیدریه ).<br /></font></div>'),
(282397, 'چاسان فاسان کردن', '<span class=\"hlight\">چاسان فاسان کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) در تداول عوام از زنان بمزاح، بزک کردن . آرایش کردن . بزک دوزک کردن . آرایش کردن زن روی خود را با سفیدآب و سرخاب و وسمه و سرمه و غیره .<br /></font></div>'),
(282398, 'چاش', '<span class=\"hlight\">چاش .</span> (اِ) غله ٔ از کاه جداکرده و پاک شده را گویند. (برهان ). خرمن از کاه پاک کرده شده . (آنندراج ). خرمن کوفته را گویند. (اوبهی ). <BR><font color=\"Blue\">◄</font> ظاهرا خرمن . مطلق خرمن .توده غله یا هر چیز دیگر. انبار. صیره <span class=\"hlight\">:</span> <br />از زمین دل من چاش ثنا برگیری <br />ز آنکه تخم کرم و احسان کشتن دانی .<br /> <font color=\"Red\">سوزنی .</font><br />بر روی زمین ز کشت احسانت <br />از خرمن ماه بگذرد چاش .<br /> <font color=\"Red\">سوزنی .</font><br />مور بر دانه بدان لرزان شود<br />که ز خرمنهای خوش اعمی بود<br />میکشد آن دانه ها با حرص و بیم <br />که نمی بیند چنان چاش کریم .<br /> <font color=\"Red\">مولوی .</font><br />گر بهر دم نت بهار و خرمیست <br />هم چو چاش گل تنت انبار چیست .<br /> <font color=\"Red\">مولوی .</font><br />بی سبب مر بحر را بشکافتند<br />بی زراعت چاش گندم یافتند.<br /> <font color=\"Red\">مولوی .</font><br />و رجوع به چاچ شود.<br /></font></div>'),
(282399, 'چاشت', '<span class=\"hlight\">چاشت .</span> (اِ)یک حصه از چهار حصه ٔ روز باشد که در هندوستان پهر گویند. (برهان ). اول روز. (آنندراج ). بهره ٔ نخستین روز. صبح، بامداد. مقابل شام .<br /> <BR><font color=\"Blue\">◄</font> میانه ٔ روز را گویند. (فرهنگ ناصری ). یک پاس از چهار پاس روز که میانه ٔ روز باشد. ظهر. نیمه روز. نصف النهار. ضحی ؛ چاشتگاه . ضحاء؛ چاشت فراخ، وقتی که قریب نصف شدن رسد روز. ضاحاه ؛ آمد او را وقت چاشت . (منتهی الارب ) <span class=\"hlight\">:</span> <br />گه چاشت چون بود روز دگر<br />بیامد برهمن ز کازه بدر.<br /> <font color=\"Red\">اسدی .</font><br />از چاشت تا بشام ترا نیست ایمنی <br />گر مر تراست مملکت از چاچ تا بشام .<br /> <font color=\"Red\">ناصرخسرو</font><br />روز اگر رهزن صبوح شود<br />چاشت تا شام کن قضای صبوح .<br /> <font color=\"Red\">خاقانی .</font><br />از پس هر شامگهی چاشتی است <br />آخر برداشت فرو داشتی است .<br /> <font color=\"Red\">نظامی .</font><br />بدینگونه تا سر برآورد چاشت <br />بتیره جهان را در آشوب داشت .<br /> <font color=\"Red\">نظامی .</font><br />هم آنجا امانش بده تابچاشت <br />نشاید بلا بر دگر کس گماشت .<br /> <font color=\"Red\">سعدی .</font><br />شنیدم که نابالغی روزه داشت <br />بصد محنت آورد روزی به چاشت .<br /> <font color=\"Red\">سعدی .</font><br />و پای سوی قبله از چاشت تا نیمروز. (انیس الطالبین ص <span class=\"hlight\" dir=\"rtl\">٩٣</span>). <BR><font color=\"Blue\">◄</font> طعامی که در یک حصه از چهار حصه ٔ روزخورند. (برهان ). غذائی که در میانه ٔ روز خورند. (فرهنگ ناصری ). ناهار. غذای ظهر. طعام نیمروز. آنچه به هنگام چاشت خورند. در اصطلاح غالب روستائیان خراسان بغذایی اطلاق شود که در وسط روز میان طعام صبح (ناشتا)و طعام شب (شام ) خورند. طعامی که اول روز خورند. (آنندراج ). طعام بامداد. (زمخشری ). ناشتا. صبحانه . صبوح . زیر قلیانی ؛ غذا، طعام چاشت خلاف عشا. (منتهی الارب ) <span class=\"hlight\">:</span> <br />تا سمو سر برآورید از دشت <br />گشت زنگار گون همه لب کشت <br />هریکی کاردی ز خوان برداشت <br />تا برند از سمو طعامک چاشت .<br /> <font color=\"Red\">رودکی .</font><br />تو گر چاشت را دست یازی بجام <br />وگرنه خورند ای پسر بر تو شام .<br /> <font color=\"Red\">فردوسی .</font><br />از حرص بوقت چاشت چون کرکس <br />در چاچ و بوقت شام در شامی .<br /> <font color=\"Red\">ناصرخسرو</font><br />زیرا که هم ترا و هم او را همی بسی <br />بی شام و چاشت باید خفتن بمقبره .<br /> <font color=\"Red\">ناصرخسرو</font><br />گفت یک روز با جحی هیزی <br />کز علی و عمر بگو چیزی .<br />گفت اندوه شام و محنت چاشت <br />در دلم حب و بغض کس نگذاشت .<br /> <font color=\"Red\">سنایی .</font><br />اگر تعرض خویش از ما زایل کنی هر روز موظف یکی شکار بوقت چاشت به مطبخ ملک فرستیم . (کلیله و دمنه ). هر یک از ما گوید امروز چاشت ملک از من سازد. (کلیله و دمنه ).<br />ز تو شام و سحر خوردیم و برداشت <br />بنزد آنکه او را چاشتی رو.<br /> <font color=\"Red\">سوزنی .</font><br />چنان سوخت خاقانی از مرگ او<br />که با شام برمیزند چاشتش .<br /> <font color=\"Red\">خاقانی .</font><br />یکی مشت زن بخت روزی نداشت <br />نه اسباب شامش مهیا نه چاشت .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />مسلم کسی را بود روزه داشت <br />که درمانده ای را دهد نان چاشت .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />به خاوران ز پی چاشت خوان زر گستر<br />به باختر ز پی شام همچنان برسان .<br /> <font color=\"Red\">سلمان ساوجی .</font><br />ابودردا را چاشت و شام بهم مرسان ... هرگه که چاشت بخوردمی شامم نبودی و هرگه که شامم بود چاشتم نبودی . (جامع الستین ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">گوسفند امام رضا را تا چاشت نمی چراند</span> ؛ در مورد کسی که ناسپاس و حق ناشناس است .<br /><BR><font color=\"Blue\">◄</font> چاشت یک بنگی ؛ کنایه از خوردنی کم یا پول اندک . چاشت یک بنگی بودن یا چاشت یک بنگی نبودن، اشاره به ثروت ناچیزیا حقوق ناقابل یا غذای اندک .<br /></font></div>'),
(282400, 'چاشت خوار', '<span class=\"hlight\">چاشت خوار.</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) چاشت خوارنده . چاشت خورنده . آن که طعام چاشت خورد. (آنندراج ). غدیان . (منتهی الارب ).<br /></font></div>'),
(282401, 'چاشت خور', '<span class=\"hlight\">چاشت خور.</span> <font color=\"DarkGreen\"><b>[ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (نف مرکب ) خورنده ٔ چاشت . <BR><font color=\"Blue\">◄</font> چاشته خور. کسی که یک بار مزه ٔ چیزی را چشیده باشد و سپس همیشه در آرزوی آن بود. (ناظم الاطبا). و رجوع به چاشته خور و چاشتی خور و چشته خور شود.<br /></font></div>'),
(282402, 'چاشت خورانیدن', '<span class=\"hlight\">چاشت خورانیدن .</span> <font color=\"DarkGreen\"><b>[ خوَ <span class=\"hlight\" dir=\"rtl\">/</span> خ ُ دَ ]</font></b> (مص مرکب ) طعام دادن . غذای صبح یا ناهار کسی را خوراندن . صبحانه یا ناهار اطعام کردن . تَغدیَه ؛ چاشت خورانیدن . (منتهی الارب ).<br /></font></div>'),
(282403, 'چاشت خوردن', '<span class=\"hlight\">چاشت خوردن .</span> <font color=\"DarkGreen\"><b>[ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ دَ ]</font></b> (مص مرکب ) طعام خوردن بهنگام چاشت . صبحانه یا ناهار خوردن . هنگام چاشت غذا خوردن : تَغَدّی ؛ چاشت خوردن . تَضَحّی ؛ خورد در وقت چاشت . (منتهی الارب ) <span class=\"hlight\">:</span> <br />چون با پدرت چاشت خورد گیتی <br />ناچار خورد با تو ای پسر شام .<br /> <font color=\"Red\">ناصرخسرو.</font><br />رنجه ای تا برخت چاشت خورم <br />که فلک بر دل من چاشت خور است .<br /> <font color=\"Red\">خاقانی .</font><br />صبح تو شام گشت و فلک با تو چاشت خورد<br />تو همچنان در آرزوی شام و چاشتی .<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(282404, 'چاشت خوره', '<span class=\"hlight\">چاشت خوره .</span> <font color=\"DarkGreen\"><b>[ خ ُ رَ ]</font></b> (اِخ ) دهی از دهستان قلقل رود شهرستان تویسرکان واقع در <span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی جنوب باختری شهر تویسرکان به کرمانشاه، کنار رودخانه تویسرکان . جلگه سردسیر، مالاریائی با <span class=\"hlight\" dir=\"rtl\">٥٤٨</span> نفر سکنه . آب آن از رودخانه قلقل رود. محصول آنجا غلات، تریاک، انگور، میوجات و قلمستان زیاد و لبنیات، شغل اهالی زراعت، گله داری، صنایع دستی زنان قالی بافی، راه آن فرعی است و از فرسفج اتومبیل میتوان برد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282405, 'چاشت دادن', '<span class=\"hlight\">چاشت دادن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b>(مص مرکب ) طعام دادن بوقت چاشت را گویند که یک پاس از روز است . (برهان ). کنایه از طعام دادن گاه ظهر. (فرهنگ ناصری ) (آنندراج ). طعام چاشت به کسی دادن . غذای چاشت دادن . هنگام چاشت طعام دادن ؛ تَغدِیَه ؛ چاشت دادن . (تاج المصادر بیهقی ). <BR><font color=\"Blue\">◄</font> کنایه از سیر کردن چیزی . (فرهنگ ناصری ) (آنندراج ) <span class=\"hlight\">:</span> <br />دهی فتنه را گاهی از چشم چاشت <br />دهی مرگ را گاهی از جور شام .<br /><font color=\"Red\">مختاری (از آنندراج ).</font><br /></font></div>'),
(282406, 'چاشت فراخ', '<span class=\"hlight\">چاشت فراخ .</span> <font color=\"DarkGreen\"><b>[ ف َ ]</font></b> (اِ مرکب ) نزدیک ظهر. ضُحاء؛ چاشت فراخ، یا وقتی که قریب نصف شدن رسد روز. (منتهی الارب ). و رجوع به چاشتگاه فراخ شود.<br /></font></div>'),
(282407, 'چاشت کردن', '<span class=\"hlight\">چاشت کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) چاشت خوردن غذای چاشت خوردن . هنگام چاشت طعام خوردن <span class=\"hlight\">:</span> <br />چون چاشت کند بخویشتن پیوست <br />تو ساخته باش کار شامش را.<br /><font color=\"Red\">ناصرخسرو.</font><br /></font></div>'),
(282408, 'چاشتخوار', '<span class=\"hlight\">چاشتخوار.</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (اِخ ) نام صحرایی . بین راه اصفهان و شیراز <span class=\"hlight\">:</span> ... شاه شجاع نیز از این طرف بسر راه لشکر آمد و در صحرای چاشت خوار فریقین را ملاقات افتاد. (تاریخ گزیده چ لندن ص <span class=\"hlight\" dir=\"rtl\">٧٠٦</span>).<br /></font></div>'),
(282409, 'چاشتخواران', '<span class=\"hlight\">چاشتخواران .</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (اِخ ) نام محلی . نام صحرایی، منزلگاهی در بیابان، بین راه گرگان و ری <span class=\"hlight\">:</span> یک روز به منزلی که آن را چاشتخواران گویند خواسته بود پدر که پسر را فروگیرد. (تاریخ بیهقی چ فیاض ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282410, 'چاشتخورد', '<span class=\"hlight\">چاشتخورد.</span> <font color=\"DarkGreen\"><b>[ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ]</font></b> (ن مف مرکب، اِ مرکب ) غذای چاشت . طعامی که در هنگام چاشت خورده شود: غَدْی ؛ چاشتخورد. (منتهی الارب ).<br /></font></div>'),
(282411, 'چاشتدان', '<span class=\"hlight\">چاشتدان .</span> (اِمرکب ) ظرفی را گویند که نان و سایر خوردنی در آن گذاشته هنگام چاشت بخورند. (فرهنگ ناصری ). چاشدان . (فرهنگ ناصری ). چاشکدان . (فرهنگ ناصری ). ظرفی که نان و خوردنی در آن نهند. (ناظم الاطباء). ظرفی که غذای چاشت را در آن نهند. و رجوع به چاشدان و چاشکدان شود.<br /></font></div>'),
(282412, 'چاشته', '<span class=\"hlight\">چاشته .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ]</font></b> (اِ) ظاهراً غذای چاشت . طعام چاشت . التغدیة؛ کسی را چاشته دادن . (مصادر زوزنی ).<br /></font></div>'),
(282413, 'چاشته بند', '<span class=\"hlight\">چاشته بند.</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ب َ ]</font></b> (اِ مرکب ) سفره ای که در آن چاشت خود را بصحرا برند. (فرهنگ نظام ). و رجوع به چاشته بندی شود.<br /></font></div>'),
(282414, 'چاشته بندی', '<span class=\"hlight\">چاشته بندی .</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span>ت ِ ب َ ]</font></b> (اِ مرکب ) سفره گونه ای که مسافر خوردنی در آن با خود حمل کند. سفره ای که مسافران یا شاگردان مکتب یا چوپانان و جز آنها نان خود در آن بسته با خود برند. سفره یا چیزی مانند آن که در آن نان و دیگر پخته ها نهند بهمراه بردن را. و رجوع به چاشته بند شود.<br /></font></div>'),
(282415, 'چاشته خواب', '<span class=\"hlight\">چاشته خواب .</span><font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (اِ مرکب ) چاشت خواب . خواب چاشت . <BR><font color=\"Blue\">◄</font> به تعبیر، خواب پس از طلوع آفتاب .<br /></font></div>'),
(282416, 'چاشته خور', '<span class=\"hlight\">چاشته خور.</span> <font color=\"DarkGreen\"><b>[ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ ]</font></b> (نف مرکب ) چاشت خور. کسی که یک یا دوبار مزه چیزی را چشیده و همیشه چشیدن آن طعم را انتظار و آرزو دارد. آنکه از کسی بهره مند شده و همواره پیرامون آن شخص گردد و توقع بهره مند شدن از او را دارد. و رجوع به چاشت خور و چاشنی خور و چشته خور شود.<br /></font></div>'),
(282417, 'چاشتگاه', '<span class=\"hlight\">چاشتگاه .</span> (اِ مرکب ) هنگام چاشت . وقت چاشت . زمان چاشت . چاشتگه . چاشتگاهان . هنگام خوردن چاشت . (ناظم الاطباء) <span class=\"hlight\">:</span> هر دو سپاه با یکدیگر برآویختند از چاشتگاه تا نماز پیشین و دست مروان را بود و خلقی از سپاه عبداﷲ را بکشتند. (ترجمه طبری ).<br />بروز سیم نی بشب، چاشتگاه <br />شده پنج و ده روز از آن شهر و ماه .<br /> <font color=\"Red\">فردوسی .</font><br />بسا کسا که چو من سوی خدمتش رفتند<br />بچاشتگاه غمین، شادمان شدند بشام .<br /> <font color=\"Red\">فرخی .</font><br />دیگر روز چاشتگاه را حصار بستند. (تاریخ سیستان ). و در چاشتگاه خواجه گفت زندگانی خداوند دراز باد شرط آن است که وقت گل ساتگینی خورند که مهمانی است چهل روزه . (تاریخ بیهقی ). وقت چاشتگاه آواز کوس و طبل و بوق بخاست که تاش فراش امروز حرکت میکرد. (تاریخ بیهقی ). و دوم روز و سوم روز همچنان چاشتگاه <font color=\"DarkGreen\"><b>[ مائده عیسی ]</font></b> بیامدی و باز به هوا برشدی . (مجمل التواریخ ).<br />زر بلون کاه گشت از ترس روز جشن تو<br />از تو روز جشن آن بیند که روز از چاشتگاه .<br /> <font color=\"Red\">سوزنی .</font><br />تویی کز زلف و رخ در عالم حسن <br />ترا هم نیمشب هم چاشتگاه است .<br /> <font color=\"Red\">انوری .</font><br />هشتم ذیحجه در موقف رسیده چاشتگاه <br />شامگه خود را بهفتم چرخ مهمان دیده اند.<br /> <font color=\"Red\">خاقانی .</font><br />چند بار بوقت چاشتگاه دیده اند. (ترجمه محاسن اصفهان ). <BR><font color=\"Blue\">◄</font> جای خوردن چاشت . (ناظم الاطباء). و رجوع به چاشتگاهان و چاشتگاهی و چاشتگه شود.<br /></font></div>'),
(282418, 'چاشتگاه فراخ', '<span class=\"hlight\">چاشتگاه فراخ .</span> <font color=\"DarkGreen\"><b>[ هَِ ف َ ]</font></b>(اِ مرکب ) چاشت فراخ . نزدیک ظهر. اندک زمانی از هنگام چاشت گذشته <span class=\"hlight\">:</span> هر روز حاجب بزرگ علی برنشستی و بصحرا آمدی و بایستادی و اعیان و محتشمان درگاه ...جمله بیامدندی و سوار بایستادندی و تا چاشتگاه فراخ حدیث کردندی . (تاریخ بیهقی ). امیر چاشتگاه فراخ برنشست . (تاریخ بیهقی ). و رجوع به چاشت فراخ شود.<br /></font></div>'),
(282419, 'چاشتگاهان', '<span class=\"hlight\">چاشتگاهان .</span> (اِ مرکب ) هنگام چاشت . وقت چاشت .زمان چاشت . چاشتگاه . چاشتگاهی . چاشتگه <span class=\"hlight\">:</span> <br />بامدادان برچکک، چون چاشتگاهان بر شخج <br />نیمروزان بر لبینا، شامگاهان بر دنه .<br /> <font color=\"Red\">منوچهری .</font><br />و رجوع به چاشتگاه و چاشتگاهی شود.<br /></font></div>'),
(282420, 'چاشتگاهی', '<span class=\"hlight\">چاشتگاهی .</span> (اِ مرکب ) هنگام چاشت . زمان چاشت . چاشتگاه . چاشتگاهان . چاشتگه <span class=\"hlight\">:</span> امیر یک روز چاشتگاهی بونصررا بخواند. (تاریخ بیهقی ). روز چهارم بوقت چاشتگاهی تاریکی ظاهر شد. (قصص الانبیاء). و موسی سه شبانه روز بود که بر کنار دریا نشسته بود چون چاشتگاهی بود گرد از سوی مصر بدیدند. (قصص الانبیاء). بعد از یک هفته لشکر مغول هنگام چاشتگاهی دررسیدند. (جهانگشای جوینی ). و رجوع به چاشتگاه و چاشتگاهان و چاشتگه شود.<br /></font></div>'),
(282421, 'چاشتگه', '<span class=\"hlight\">چاشتگه .</span> <font color=\"DarkGreen\"><b>[ گ َه ْ ]</font></b> (اِ مرکب ) هنگام چاشت . زمان چاشت . وقت چاشت . چاشتگاه . چاشتگاهان . چاشتگاهی <span class=\"hlight\">:</span> <br />با سماع چنگ باش از چاشتگه تا آنزمانک <br />بر فلک پیدا شود پروین چو سیمین شفترنگ .<br /> <font color=\"Red\">عسجدی .</font><br />چرخ از سموم گرمگه زاده وبا هر چاشتگه <br />دفع وبا را جام شه یاقوت کردارآمده .<br /> <font color=\"Red\">خاقانی .</font><br />صبحدم رانده ز منزل تشنگان ناشتا<br />چاشتگه هم مقصد و هم چشمه هم خوان دیده اند.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(282422, 'چاشدان', '<span class=\"hlight\">چاشدان .</span> (اِ مرکب ) چاشتدان . چاشکدان . ظرفی باشد که نان و خوردنی در آن میان گذارند. (برهان ). ظرفی که در آن نان گذارند. (فرهنگ ناصری ). ظرفی که از طعام چاشت در آن نهند. (آنندراج ). ظرفی را گویند که نان در میان او گذارند. کرسان . (فرهنگ جهانگیری ). جوئه ؛ ظرف طعام چاشت <span class=\"hlight\">:</span> <br />وز زمین برجستمی تا چاشدان <br />خوردمی هرچ اندر او بودی ز نان .<br /> <font color=\"Red\">رودکی .</font><br /><BR><font color=\"Blue\">◄</font> بطریق مجاز طعام چاشت را نیز گویند. (فرهنگ ناصری ). و رجوع به چاشتدان و چاشکدان شود.<br /></font></div>'),
(282423, 'چاشنه کردن', '<span class=\"hlight\">چاشنه کردن .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ک َ دَ ]</font></b> (مص مرکب ) چاشنی کردن . (آنندراج ). چشیدن . (آنندراج ). طعم غذا را چشیدن . مزه طعام را امتحان کردن <span class=\"hlight\">:</span> <br />دانست چو ما هر که از او چاشنه ای کرد<br />این نان چه قدر بی نمک این آب چه شور است .<br /><font color=\"Red\">سالک یزدی (از آنندراج ).</font><br /></font></div>'),
(282424, 'چاشنی', '<span class=\"hlight\">چاشنی .</span> (اِ) اندکی از طعام و شراب را گویند که از برای تمییزکردن بچشند. (برهان ). اندک چیزی از شراب و طعام است . (آنندراج ) (غیاث ). اندکی از طعام و شراب که قبلاً چشند تا مسموم بودن یا نبودن آن دانسته شود. مقدار اندک از غذا که برای آزمودن طعم آن بچشند <span class=\"hlight\">:</span> <br />که ای شاه نیک اختردادگر<br />تو بی چاشنی دست خوردن مبر.<br /> <font color=\"Red\">فردوسی .</font><br />وبه یک ساعت جماعتی از ایشان بگرفتند و دستگیر کردندو باقی بهزیمت پیش پسران <font color=\"DarkGreen\"><b>[ علی تکین ]</font></b> رفتند <font color=\"DarkGreen\"><b>[ او کار ]</font></b> را ملامت کردند جواب داد: آن دیگ برجای است و مایک چاشنی بخوردیم هر کسرا آرزوست پیش میباید رفت . (تاریخ بیهقی ). آچارها پیش آوردند و سر خمره ها باز کردند و چاشنی میدادند. (تاریخ بیهقی ).<br />ز خمی دانگ سنگی چاشنی بس <br />اگر سرکه بود یا آبگینه .<br /> <font color=\"Red\">ناصرخسرو</font><br />این چاشنی است شربت تیغ تو هند را<br />باقی دهد که باقی بادی تو جاودان .<br /> <font color=\"Red\">مسعودسعد.</font><br />دهر اگر خوان زندگانی ساخت <br />خورد هر چاشنی که کام گراست .<br /> <font color=\"Red\">خاقانی .</font><br />بمانده ام ز نوا چون کمان حاجب راست <br />نخورده چاشنی خوان حاجب الحجاب .<br /> <font color=\"Red\">خاقانی .</font><br />ابای شعر مرا نیز چاشنی مطلب <br />که در مذاق زمانه یکیست شهد و شرنگ .<br /> <font color=\"Red\">ظهیر.</font><br /> <BR><font color=\"Blue\">◄</font> اندک از خوردنی که دهان را طعم دهد و خورنده اشتهای بکار بردن بقیه آرد. (فرهنگ خطی اسدی نسخه نخجوانی ). چشته . (فرهنگ خطی اسدی نسخه نخجوانی ). مُسته . (فرهنگ خطی اسدی نسخه نخجوانی ). <BR><font color=\"Blue\">◄</font> نمودار.(برهان ) (غیاث ). نمونه ٔ چیزی . (آنندراج ) <span class=\"hlight\">:</span> <br />از این چاشنی هست نزدیک من <br />از او تیره شد رای باریک من .<br /> <font color=\"Red\">فردوسی .</font><br />این از عجز نمیگویم که چاشنی دیده آمد و خداوند سلطان به بلخ است و لشکر دمادم میرسد.(تاریخ بیهقی ).<br />راحت و رنج از بهشت خلد و ز دوزخ <br />چاشنیی دان در این سرای معاجل .<br /> <font color=\"Red\">ناصرخسرو.</font><br />بیای تا من و تو هر دو ای درخت خدای <br />ز بار خویش یکی چاشنی فروباریم .<br /> <font color=\"Red\">ناصرخسرو.</font><br />شد سنگ صبر من کم و بی صبر گشته ام <br />یک مشت چاشنی ده از آن صبر سنگمی .<br /> <font color=\"Red\">سوزنی .</font><br />گر شعر بنده هست بدین چاشنی پسند<br />در یک دو مه به مدح دو دیوان کنم نگار.<br /> <font color=\"Red\">سوزنی .</font><br />دیدنی شد همه نوری به ظلم درشکنید<br />چاشنی همه صافی به کدر بازدهید.<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> مزه . (برهان ) (آنندراج )(غیاث ) (ناظم الاطباء). طعم <span class=\"hlight\">:</span> <br />تا لاجرم زبان من از چاشنی شکر<br />چون کام روزه دار و لب شیرخوار کرد.<br /> <font color=\"Red\">خاقانی .</font><br />دماغ از چاشنی های دگر نوش <br />ز لذت کرده شهوت را فراموش .<br /> <font color=\"Red\">نظامی .</font><br />شکر گر چاشنی درجام دارد<br />ز شیرینش حلاوت وام دارد.<br /> <font color=\"Red\">نظامی .</font><br />این یقین دان که لطیف و روشنی <br />نیست بوس کون خر بی چاشنی .<br /> <font color=\"Red\">مولوی .</font><br />و آن فزونی هم پی طمعی دگر<br />بی معانی چاشنی ندهد صور.<br /> <font color=\"Red\">مولوی .</font><br />رطب را من ندانم چاشنی چیست <br />همی بینم که خرما بر نخیل است .<br /> <font color=\"Red\">سعدی .</font><br />گرت از شهد و شکر لفظی هست <br />چیست بی چاشنی معنی هیچ .<br /> <font color=\"Red\">ابن یمین .</font><br />از چاشنی قند مگو هیچ و ز شکر<br />ز آنرو که مرا از لب شیرین تو کام است .<br /> <font color=\"Red\">حافظ.</font><br />با نیک و بد چو شیر و شکر جوش میزند<br />دریافت هر که چاشنی اتحاد را.<br /> <font color=\"Red\">صائب .</font><br /> <BR><font color=\"Blue\">◄</font> خبر. احساس . علم . اطلاع <span class=\"hlight\">:</span> <br />میزنی لاف از پی معنی ولیک <br />تو کجا آن چاشنی داری هنوز.<br /> <font color=\"Red\">عطار.</font><br />نقش اگر خود نقش سلطان یا غنی است <br />صورت است از جان خود بی چاشنی است .<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> صفت . (برهان ) و بمعنی صفت از آن جهت است که اندکی از آن در شخصی باشد چنانکه گویند فلان راچاشنی علم هست یعنی قدری از علم آموخته . <BR><font color=\"Blue\">◄</font> بمعنی قدری حلاوت هم آید. (آنندراج ). قدری حلاوت . (غیاث ). شیرینی . (غیاث ) <span class=\"hlight\">:</span> <br />از دهان یار دارد چاشنی گفتار من <br />خوانها را پی شق از شیرینی مضمون کنم .<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br />امروز رقیبانه بسویم نگران است <br />دانسته مگر چاشنی کنج لب خویش .<br /> <font color=\"Red\">نصیر همدانی (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> آنچه به طعام کنند از چیزهای ترش و شیرین مانند سرکنگبین و جز آن . آنچه در طعام کنند خوشمزگی را و بیشتر چیزی ترش و شیرین مانند سرکه قند و سکنجبین و غیره . در اصطلاح طباخان مخلوطی از ترش و شیرین است که به آش و خورش میزنند مانند سکنجبین وسرکه شیره و سرکه قند و امثال آن . مرکبی از شکر یا عسل با سرکه یا آب لیمو که بطعامها زنند خوشمزگی را. وقلیه ٔ چاشنی دار از آن گویند که قدری شیرین و ترش میباشد. (آنندراج ). <BR><font color=\"Blue\">◄</font> قوه ذائقه <span class=\"hlight\">:</span> ذائقه باز این پنج حواس که شنوائی و بینائی و بویائی و چاشنی و لمس است این همه اگر چه گوناگونند الا ازیک جان زنده اند. (بهاءالدین ولد). <BR><font color=\"Blue\">◄</font> باروت سفید که با چکانیدن ماشه ٔ تفنگ مشتعل شود. چیزی خرد که بر پستانک تفنگ نهند که در آن چیزی است که با ضرب و زخم قابل اشتعال باشد. بمعنی باروت تفنگ که درسوراخ تفنگ ریخته آتش دهند و به هندی آن را رنجک گویند. (آنندراج ). باروت و ماده ای قابل اشتعال که در اسلحه های آتشین بکار برند. <BR><font color=\"Blue\">◄</font> جای باروت که از فلز است . چیز کوچکی که در بن آن ماده منفجره ای هست که با فروافتادن چخماق بر روی پستانک منفجر شده وگلوله را میپراند. کبسولی که بر ماشه ٔ تفنگ گذارند که با فرود آمدن شیطانک بر آن مشتعل شود و باروت یا فشنگ تفنگ را مشتعل سازد. <BR><font color=\"Blue\">◄</font> عیار. (ملخص اللغات حسن خطیب کرمانی ). عیار زر و سیم، چاشنی، یا چاشنی زر. عیار. (محمودبن عمر ربنجنی ). <BR><font color=\"Blue\">◄</font> ابتدای زدن چوب را نیز گویند بر کوس و نقاره . (برهان ). چوب اولی که بر کوس و نقاره زنند. (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاشنی بهر</span> ؛ دارای چاشنی . بهره مند از چاشنی <span class=\"hlight\">:</span> <br />بسیار شراب تلخ چون زهر<br />کز عشق شده ست چاشنی بهر.<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282425, 'چاشنی بیضه', '<span class=\"hlight\">چاشنی بیضه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ب َ ض َ <span class=\"hlight\" dir=\"rtl\">/</span> ض ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) چاشنی بیضه ٔ مرغ . چاشنی تخم مرغ . قدر کم شکستن بیضه در بیضه بازی نوروز. (آنندراج ) <span class=\"hlight\">:</span> <br />ز صوت مرغ گلستان کمی نخواهد داشت <br />صدای چاشنی بیضه های نوروزی .<br /><font color=\"Red\">ملاطغرا (از آنندراج ).</font><br /></font></div>'),
(282426, 'چاشنی خوار', '<span class=\"hlight\">چاشنی خوار.</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) چاشت خوار. چاشته خوار. چشته خوار. مسته خوار. چاشنی خورنده . و رجوع بچاشت خوار و چاشته خور و چشته خور شود.<br /></font></div>'),
(282427, 'چاشنی خور', '<span class=\"hlight\">چاشنی خور.</span> <font color=\"DarkGreen\"><b>[ خوَرْ <span class=\"hlight\" dir=\"rtl\">/</span> خُرْ]</font></b> (نف مرکب ) چاشنی خورنده . و رجوع بچاشنی خوار شود.<br /></font></div>'),
(282428, 'چاشنی دل', '<span class=\"hlight\">چاشنی دل .</span> <font color=\"DarkGreen\"><b>[ ی ِ دِ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از سخنان خوب و لطیف و دلگشا. (برهان ) (فرهنگ ناصری ) (آنندراج ) <span class=\"hlight\">:</span> <br />روشنی عقل بجان داده ای <br />چاشنی دل بزبان داده ای .<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> سخن . (شرفنامه ٔ منیری ). <BR><font color=\"Blue\">◄</font> زبان فصیح . (مجموعه مترادفات ص <span class=\"hlight\" dir=\"rtl\">١٩٢</span>).<br /></font></div>'),
(282429, 'چاشنی زدن', '<span class=\"hlight\">چاشنی زدن .</span> <font color=\"DarkGreen\"><b>[ زَ دَ ]</font></b> (مص مرکب ) چیزی از ترشی یا شیرینی در طعام ریختن تا طعم میخوش آرد. ترش و شیرینی معاً به خورش زدن چون سرکه و قند یا آب لیمو و قند و مانند آن .<br /></font></div>'),
(282430, 'چاشنی صبح', '<span class=\"hlight\">چاشنی صبح .</span> <font color=\"DarkGreen\"><b>[ ی ِ ص ُ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از سپیده ٔ صبح . (آنندراج ). روشنی صبح . (ناظم الاطباء). صبح صادق . (مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">٢٣٤</span>) <span class=\"hlight\">:</span> <br />از آفتاب چاشنی صبح شد بلند<br />عمر دوباره یافت زراه گداز قند.<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> چاشنی بامداد. نهاری .لُهنَه . لقمة الصباح . صبحانه . زیر قلیانی . دهان گیره .<br /></font></div>'),
(282431, 'چاشنی فرمودن', '<span class=\"hlight\">چاشنی فرمودن .</span> <font color=\"DarkGreen\"><b>[ ف َ دَ ]</font></b> (مص مرکب ) امر به چشیدن کردن . چاشنی گیر را به چشیدن طعامی فرمان دادن . قبل از خوردن غذا کسی را به امتحان کردن طعام واداشتن <span class=\"hlight\">:</span> دیگری گفت گناه از صاحب ضیافت است که چاشنی نفرمود <font color=\"DarkGreen\"><b>[ شیر بزهر افعی آلوده را ]</font></b> و میان مضر و نافع فرق نکرد. (سندبادنامه ).<br /></font></div>'),
(282432, 'چاشنی چش', '<span class=\"hlight\">چاشنی چش .</span> <font color=\"DarkGreen\"><b>[ چ َ ]</font></b> (نف مرکب ) چاشنی چشنده . آنکه طعم طعامی یا مزه ٔ چیزی را چشد. چاشنی گیر. مزه چش <span class=\"hlight\">:</span> <br />در جهان هر که شمس دین لقبند<br />شاه ایشان تویی بحضرت کش <br />سائلان چاشنی چش لقبند<br />مزه پرسند هر کس از مزه چش .<br /> <font color=\"Red\">سوزنی .</font><br />و رجوع به چاشنی گیر شود.<br /></font></div>'),
(282433, 'چاشنی کردن', '<span class=\"hlight\">چاشنی کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b>(مص مرکب ) اندکی از مأکول یا مشروبی را چشیدن برای آزمودن طعم آن . چشیدن طعم خوردنی یا نوشیدنی را. اندکی از طعام یا شراب را خوردن و طعم آن را امتحان کردن <span class=\"hlight\">:</span> روز نوروز نخستین کسی ... مؤبد مؤبدان پیش ملک آمدی با جام زرین ... چون از آفریده بپرداختی چاشنی کردی و جام به ملک دادی . (نوروزنامه خیام ).پس ملک را در گرمابه میانگین بنشاند و آب فاتر بر او همی ریخت و شربتی که کرده بود چاشنی کرد و بدو دادتا بخورد. (چهارمقاله عروضی ). <BR><font color=\"Blue\">◄</font> امتحان کردن . آزمایش نمودن کسی یا چیزی . آزمودن اشخاص یا اشیاء برای پی بردن بصفات و خصوصیات آنها <span class=\"hlight\">:</span> <br />ور به گمان است دل تو در این <br />چاشنیم کن چت باشد حلال .<br /> <font color=\"Red\">ناصرخسرو.</font><br />ابومسلم خراسانی که پهلوان پایتخت بود در غضب رفت و کمان خود به محمد مظفر داد که این را چاشنی کن . محمد مظفر کمان آورد و با کمان خود برهم نهاد و هر دو را بکشید و کمان خود به ابومسلم داد که تو نیز این را چاشنی کن ابومسلم هر چند که کرد نتوانست کشید منفعل شد. (تاریخ جدید یزد). <BR><font color=\"Blue\">◄</font> اندازه گرفتن عیار زر و سیم . عیار کردن فلزات . (ناظم الاطباء). آزمودن عیار زر و سیم . مِعیار؛ چاشنی کردن زر و سیم . (منتهی الارب ). <BR><font color=\"Blue\">◄</font> چاشنی کردن به کسی، در اصطلاح بازاریان، چیزی بد را بجای خوب یا کم ارزی را بدل پربهاء بفریب به کسی فروختن . در تداول عوام فریفتن کسرا. متاع ارزان را به بی خبری گران فروختن . بدلی را به جای اصلی به نادانی دادن . <BR><font color=\"Blue\">◄</font> گلوله یا چوبی را به کسی زدن .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(282434, 'چاشنی گرفتن', '<span class=\"hlight\">چاشنی گرفتن .</span><font color=\"DarkGreen\"><b>[ گ ِ رِ ت َ ]</font></b> (مص مرکب ) چشیدن . چشیدن آزمون را. اندکی از طعام یا شراب چشیدن برای آزمودن طعم آن . مزه کردن <span class=\"hlight\">:</span> چون محمود فرمان یافت فرزندش محمد، این نوشتکین را برکشید بدان وقت که بغزنین آمد... و وی را چاشنی گرفتن و ساقیگری فرمود. (تاریخ بیهقی ).<br />هر شرب سرد کرده که دل چاشنی گرفت <br />با بانگ نوش نوش چشیدم بصبحگاه .<br /> <font color=\"Red\">خاقانی .</font><br />بفرمود کآرند خوانهای خورد<br />همان نقلدانهای نادیده گرد<br />نخست از همه چاشنی برگرفت <br />در آن چابکی مانده خسرو شگفت .<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> امتحان کردن . آزمودن <span class=\"hlight\">:</span> لشکر مغول بر عقب روان گشته چون نزدیک چنگیزخان رسیدند و از مردانگی ایشان چاشنی گرفته و دانسته که ... (تاریخ جهانگشای جوینی ).<br /></font></div>'),
(282435, 'چاشنی گیر', '<span class=\"hlight\">چاشنی گیر.</span> (اِخ ) حسام الدین بدر از امرای مصر که در عهد سلطنت ملک ناصر (از پادشاهان سلسله ٔ ممالیک مصر) میزیسته و مؤلف حبیب السیر در احوالات وی نوشته است که : «حسام الدین بدر چاشنی گیر با سیف الدین سالار که هر دو تن از امرای نامی مصر بودند بسال <span class=\"hlight\" dir=\"rtl\">٧٠٧</span> هَ . ق . چون عرصه ٔ مملکت مصر را خالی دیدند با المستکفی باﷲ که از طرف ملک ناصر به خلافت مصر منصوب شده بود هوس استقلال مصر را در خاطر راه دادند و اعیان و اشراف مصر را مجتمع ساختند و در تعیین پادشاهی که از عهده ٔ ضبط حوزه ٔ اسلام بیرون تواند آمد مشورت نمودند و همگی چاشنی گیر رابسلطنت انتخاب کردند و چاشنی گیر زمام امور را بدست سیف الدین سالار سپرد و منصب نیابت را به پیرعلی قیچاق تفویض کرد و خود را لقب ملک مظفر داد سپس نامه ای به ملک ناصر نوشت و پادشاهی خود را بدو اعلام نمود. ملک ناصر از طغیان چاشنی گیر آشفته خاطر شد و از حصار کرک که هواخواهان خود را در آنجا مجتمع ساخته بود با حاکم دمشق و دیگر کسانی که سلطنت ملک مظفر (چاشنی گیر)را تمکین نکرده بودند ارتباط برقرار ساخت و آنگاه از کرک به دمشق رفت و با امرای آن شهر پیمان بست و بسال <span class=\"hlight\" dir=\"rtl\">٧٠٨</span> هَ . ق . از دمشق به قصد گوشمال دادن چاشنی گیرعزیمت مصر کرد. چاشنی گیر چون عرصه را تنگ دید فرار نمود لیکن بدست قراسنقور و منکوتیمور در منزل «چاه اتابک » دستگیر شد و او را پس از دستگیری بحضور ملک ناصر بردند. ملک ناصر فرمان داد تا دو چشم او را کور کنند لیکن چاشنی گیر به التماس فرمان کشتن خود را از ملک ناصر و امرا درخواست کرد و ارکان دولت این ملتمس را پذیرفته او را <font color=\"DarkGreen\"><b>[ چاشنی گیر را ]</font></b> به زه کمان از میان برداشتند». (تاریخ حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">٢٦١</span> - <span class=\"hlight\" dir=\"rtl\">٢٦٣</span>)<br /></font></div>'),
(282436, 'چاشنی گیر', '<span class=\"hlight\">چاشنی گیر.</span> (نف مرکب ) چاشنی چش . مزه چش . آنکه طعام یا شراب را بازچشد تا طعم آن معلوم کند. ذواق <span class=\"hlight\">:</span> <br />نگویم بوسه را میری بمن ده <br />لبت را چاشنی گیری بمن ده .<br /> <font color=\"Red\">نظامی .</font><br />که ای جامگی خوار تدبیر من <br />ز جام سخن چاشنی گیر من .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> کسی که طعام را پیش از شاه خوردی تا زهرگین نبایدبودن . آنکه طعام را پیش از پادشاه میچشید. پَتِشخور. کسی که طعام یا شراب را اول بار برای تشخیص خوبی وبدی یا امتحان مسموم بودن و نبودن آن بچشد و پادشاهان پس از وی از آن مأکول یا مشروب بخورند <span class=\"hlight\">:</span><br />پراکنده فرمای شب جای خواب <br />مخور هیچ بی چاشنی گیر آب .<br /> <font color=\"Red\">اسدی .</font><br />تیغ شاه شرق باشد در مصاف خصم ملک <br />چاشنی گیرش اجل گردن کباب و خون شراب .<br /> <font color=\"Red\">سوزنی .</font><br />بدست چاشنیگیری چو مهتاب <br />فرستادش ز شربتهای جلاب .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> خوانسالار. مائده سالار. حاکم مطبخ را گویند. (برهان ). توشمال ؛ بترکی . (برهان ). کسی که کار و خدمت مطبخ بر او مقرر شده باشد. (آنندراج ). بکاول <font color=\"DarkGreen\"><b>[ در هندوستان ]</font></b> . (برهان ) (آنندراج ) <span class=\"hlight\">:</span> <br />در مجلس خوانش چاشنی گیر<br />جز جنت و نقلدان ندیده ست .<br /> <font color=\"Red\">خاقانی .</font><br />چاشنی گیران از چشمه ٔ حیوان گوئی <br />شربت شاه سکندرسیر آمیخته اند.<br /> <font color=\"Red\">خاقانی .</font><br />این بکاول نیست قطاع الطریق سفره است <br />در میان صحن بریان قلیه بادنجان برد<br />مثل او من چاشنی گیری ندیدم در جهان <br />در نظر دزدد پلاو و قاب را پنهان برد.<br /> <font color=\"Red\">فوقی یزدی (از بهار عجم ).</font><br /><BR><font color=\"Blue\">◄</font> طعام قسمت کننده را نیز گفته اند. (برهان ). سفره چی . (برهان ). <BR><font color=\"Blue\">◄</font> مجازاً بمعنی راتبه خوار. (آنندراج ). <BR><font color=\"Blue\">◄</font> عیارگیر. عیارسنج . چاشنی گیر زر و سیم، آنکه عیار سیم وزر را بسنجد.<br /></font></div>'),
(282437, 'چاشنی گیری', '<span class=\"hlight\">چاشنی گیری .</span> (حامص مرکب ) مزه چشی . طعم چشی . امتحان طعم مأکول یا مشروب . <BR><font color=\"Blue\">◄</font> مزه چشی طعام یا شراب برای پی بردن به مسموم بودن و نبودن آن <span class=\"hlight\">:</span> <br />چاشنی گیریش بجان کردم <br />وآنگهی بر تو جان فشان کردم .<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> اندازه گیری عیار زر و سیم .<br /></font></div>'),
(282438, 'چاشکدان', '<span class=\"hlight\">چاشکدان .</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِ مرکب ) چاشتدان . ظرفی باشد که نان و طعام در آن گذارند. ناندان . (برهان ). ظرف و سفره ای که طعام روز را در آن گذارند و به وقت چاشت بکار برند. (فرهنگ ناصری ). چاشدان . (آنندراج ) <span class=\"hlight\">:</span> <br />ای چاشکدانت چرخ ازرق <br />وی شادروانت چرخ اطلس .<br /> <font color=\"Red\">جمال الدین عبدالرزاق (از فرهنگ ناصری ).</font><br /><BR><font color=\"Blue\">◄</font> صندوقچه زنان را نیز گفته اند. (برهان ). و رجوع به چاشدان و چاشتدان شود.<br /></font></div>'),
(282439, 'چاغ', '<span class=\"hlight\">چاغ .</span> (ترکی، اِ) چاق . وقت و هنگام . (ناظم الاطباء) <span class=\"hlight\">:</span> در چاغ هولاکوخان و اباقاخان وجه آش اوردوها و خوانین بر شیوه و عادت مغول بود. (تاریخ غازانی ذیل ص <span class=\"hlight\" dir=\"rtl\">٣٢٩</span>). <BR><font color=\"Blue\">◄</font> فصل . <BR><font color=\"Blue\">◄</font> یک ساعت از <span class=\"hlight\" dir=\"rtl\">١٢</span> ساعت روز. <BR><font color=\"Blue\">◄</font> عنکبوت . (ناظم الاطباء).<br /></font></div>'),
(282440, 'چاغاله', '<span class=\"hlight\">چاغاله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) چاقاله . چغاله . اَخکوک . بادام و زردآلو و هلوی سبز نارسیده . چاغاله بادام . بادام نارس . زرد آلوی نارس . هلوی نارس .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاغاله مجتهد</span> ؛ بمزاح، مجتهدی جوان .<br />و رجوع بچاقاله و چغاله و اخکوک شود.<br /></font></div>'),
(282441, 'چاغان', '<span class=\"hlight\">چاغان .</span> (اِخ )نام محله یا کوچه ای به مرو. صاغان (معرب آن است ).<br /></font></div>'),
(282442, 'چاغانیغ', '<span class=\"hlight\">چاغانیغ.</span> (اِخ ) تلفظ ترکی چاگانیگ و رجوع به چاگانیگ شود.<br /></font></div>'),
(282443, 'چاغداول', '<span class=\"hlight\">چاغداول .</span> <font color=\"DarkGreen\"><b>[ وُ ]</font></b> (ترکی، ص، اِ) چغداول . چغدل . چغدول . گروهی که از پس لشکر براه روند و راننده ٔ لشکر باشند. <BR><font color=\"Blue\">◄</font> چنداول نیز گویند. (ناظم الاطباء). و رجوع به چغداول شود.<br /></font></div>'),
(282444, 'چاغر', '<span class=\"hlight\">چاغر.</span> <font color=\"DarkGreen\"><b>[ غ َ ]</font></b> (اِ) جاغر . چینه دان . چینه دان مرغان . (آنندراج ) (غیاث ). به عربی حوصله گویند. (آنندراج ) (غیاث ). و رجوع به ژاغر شود.<br /></font></div>'),
(282445, 'چاغر بلاغ', '<span class=\"hlight\">چاغر بلاغ .</span> <font color=\"DarkGreen\"><b>[ غ َ ب ُ ]</font></b> (اِخ ) دهی از دهستان اسفندآباد بخش قروه ٔ شهرستان سنندج واقع در <span class=\"hlight\" dir=\"rtl\">٣٨</span> هزارگزی باختر قروه و یکهزار گزی راه فرعی قروه سنقر. کوهستانی سردسیر با <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن سکنه آب آن از چشمه سراب شیخ حسن، محصول آنجا غلات و لبنیات، شغل اهالی زراعت و گله داری و راه آن مالرو است . صنایع دستی زنان، قالیچه و جاجیم و گلیم بافی است . (فرهنگ جغرافیائی ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282446, 'چاغرلو', '<span class=\"hlight\">چاغرلو.</span> <font color=\"DarkGreen\"><b>[ غ َ ]</font></b> (اِخ ) دهی از دهستان گل تپه فیض اﷲبیگی شهرستان سقز واقع در <span class=\"hlight\" dir=\"rtl\">٣٧</span> هزارگزی شمال خاوری سقز و چهار هزارگزی خاور قلعه کهنه . کوهستانی سردسیر با <span class=\"hlight\" dir=\"rtl\">٤٥٠</span> تن سکنه . آب آن از چشمه و قنات، محصول آنجا غلات و توتون و لبنیات و قلمستان، شغل اهالی زراعت و گله داری و راه مالرو است و در فصل خشکی از قلعه کهنه اتومبیل میتوان برد. (فرهنگ جغرافیائی ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282447, 'چاغون گونش', '<span class=\"hlight\">چاغون گونش .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) دهی از بخش نمین شهرستان اردبیل واقع در <span class=\"hlight\" dir=\"rtl\">٢٢</span> هزارگزی شمال اردبیل و <span class=\"hlight\" dir=\"rtl\">١٣</span> هزارگزی شوسه خیاواردبیل . کوهستانی، معتدل با <span class=\"hlight\" dir=\"rtl\">١٥٥</span> تن سکنه آب آن از چشمه، محصول آنجا غلات و حبوبات، شغل اهالی زراعت و گله داری و راه آن مالرو است . (فرهنگ جغرافیائی ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(282448, 'چاف', '<span class=\"hlight\">چاف .</span> (اِخ ) دهی جزء دهستان رودبنه بخش مرکزی شهرستان لاهیجان واقع در<span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی شمال خاوری لاهیجان و <span class=\"hlight\" dir=\"rtl\">١٠</span> هزارگزی لنگرود، کنار رودخانه ٔ لنگرود. جلگه، معتدل، مرطوب با <span class=\"hlight\" dir=\"rtl\">١٤٢٧</span> تن سکنه . آب آن از حشمت رود، محصول آنجا برنج و ابریشم و کنف و غلات، شغل اهالی صید مرغابی و زراعت و پارچه بافی است . راه مالرو و از لنگرود با قایق میتوان رفت . (فرهنگ جغرافیائی ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282449, 'چاف چیر', '<span class=\"hlight\">چاف چیر.</span> (اِخ ) دهی جزء دهستان حومه ٔ بخش رودسر شهرستان لاهیجان، واقع در <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی شمال باختری رودسر نزدیک دریا. جلگه، مرطوب . با <span class=\"hlight\" dir=\"rtl\">٨٣٨</span> تن سکنه . آب آن از نهر پلرود، محصول آنجا برنج و غلات و کنف و بنشن و ابریشم، شغل اهالی زراعت است و راه فرعی دارد. (فرهنگ جغرافیائی ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282450, 'چافو چاه', '<span class=\"hlight\">چافو چاه .</span> (اِخ ) دهی جزء دهستان حومه ٔ بخش لشت نشاء، شهرستان رشت واقع در <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی جنوب لشت نشاء و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی باختر شوسه لشت نشاء به کوچصفهان، جلگه، مرطوب، با <span class=\"hlight\" dir=\"rtl\">٣٢٠</span> تن سکنه، آب آن از نورود از سفید رود، محصول آنجا برنج و ابریشم و چای . شغل اهالی زراعت و راه آن مالرو است . (فرهنگ جغرافیائی ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282451, 'چاق', '<span class=\"hlight\">چاق .</span> (ترکی، ص ) سمین . درشت . فربی . بسیار گوشت . مقابل لاغر. سطبر. (غیاث ). فربه و کلفت از انسان و حیوان . (فرهنگ نظام ). فربه . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> بمعنی صحت باشد. (برهان ). صحیح و تندرست . (آنندراج ). تندرست . (غیاث ) (فرهنگ نظام ). تندرست و سلامت . (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دماغ کسی چاق بودن </span> ؛ در تداول عامه کنایه از درآمد کافی داشتن . دولتمند و صاحب ثروت بودن . از داشتن ثروت یا بسبب دیگر تردماغ و خوشحال و بانشاط بودن، چنانکه گویند: دماغش چاق است <span class=\"hlight\">:</span> <br />ز بوی خامه ٔ نرگس دماغ من چاق است <br />شکفتن دل من هم چو گل به اوراق است .<br /> <font color=\"Red\">ملاطغرا (از آنندراج ).</font><br />و به معانی بالا با فعل شدن نیز مصطلح است و گویند: دماغش چاق شد؛ تازگی ها دماغش چاق شده و غیره <span class=\"hlight\">:</span> <br />شود ز حاصل خود هر کسی دماغش چاق <br />که هست شربت خشخاش باغبان زنجیر.<br /> <font color=\"Red\">(از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">دماغ چاقی کردن </span> ؛ در اصطلاح عامه بمعنی احوالپرسی کردن است .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">زیر چاق بودن یا زیر چاق نبودن </span> ؛ در اصطلاح عوام بمعنی ماهر بودن و مسلط بودن یا نبودن و متمایل بودن یا تمایل نداشتن به انجام کاری یا امری است . و رجوع به فربه و تندرست شود.<br /><BR><font color=\"Blue\">◄</font> تر و تازه . (آنندراج ). (فرهنگ نظام ). تازه . (غیاث ). <BR><font color=\"Blue\">◄</font> قوی . (غیاث ). توانا. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> نغز، در ترکی . (فرهنگ نظام ). <BR><font color=\"Blue\">◄</font> چست . (غیاث ). <BR><font color=\"Blue\">◄</font> خوش . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> اندک، در ترکی . (فرهنگ نظام ). <BR><font color=\"Blue\">◄</font> (اِ)بمعنی زمان هم هست، چنانکه گویند در چاق آدم یعنی در زمان آدم و بعضی گویند به این معنی ترکی است . (برهان ) (آنندراج ). در ترکی بمعنی وقت . (فرهنگ نظام ). هنگام و وقت، مأخوذ از ترکی . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> آواز رحم، در ترکی . (فرهنگ نظام ). <BR><font color=\"Blue\">◄</font> امر به گزیدن و نیش زدن و چغلی کردن است ؛ در ترکی . (فرهنگ نظام ).<br /></font></div>'),
(282452, 'چاق شدن', '<span class=\"hlight\">چاق شدن .</span> <font color=\"DarkGreen\"><b>[ ش ُدَ ]</font></b> (مص مرکب ) فربه گشتن . فربی شدن . تنومند شدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">سگ که چاق شد قورمه اش نمیکنند</span>، یا سگ که چاق شد گوشتش را نباید خورد، مثلی عامیانه است در مورد سفله ای که خداوند هستی شود و نااهلی یا نالایقی که بمقام و منزلتی رسد.<br /> <BR><font color=\"Blue\">◄</font> شفا یافتن . تندرست شدن . سالم شدن .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاق شدن کمانچه </span> ؛ خشک شدن و کوک شدن آن است به مجاز <span class=\"hlight\">:</span> <br />کمانش چو ماه نو از آب و تاب <br />شده چاق بر آتش آفتاب .<br /><font color=\"Red\">ملاطغرا (از آنندراج ).</font><br /></font></div>'),
(282453, 'چاق و چله', '<span class=\"hlight\">چاق و چله .</span> <font color=\"DarkGreen\"><b>[ ق ُ چ ِل ْ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (ص مرکب ) (از اتباع ) تنومند. فربه . فربی . سمین . <BR><font color=\"Blue\">◄</font> سالم . صحیح . تندرست . و رجوع به چاق و فربه و سمین شود.<br /></font></div>'),
(282454, 'چاق و چله شدن', '<span class=\"hlight\">چاق و چله شدن .</span> <font color=\"DarkGreen\"><b>[ ق ُ چ ِل ْ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ش ُ دَ ]</font></b> (مص مرکب ) فربه شدن . سمین شدن . پروار شدن . پرگوشت و پر چربی شدن . تنومند شدن . <BR><font color=\"Blue\">◄</font> شفا یافتن . معالجه شدن . تندرست شدن . بهبود یافتن . و رجوع به چاق شدن و فربه شدن شود.<br /></font></div>'),
(282455, 'چاق و چله کردن', '<span class=\"hlight\">چاق و چله کردن .</span><font color=\"DarkGreen\"><b>[ ق ُ چ ِل ْ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ک َ دَ ]</font></b> (مص مرکب ) فربه کردن . پروار کردن . تنومند کردن . <BR><font color=\"Blue\">◄</font> معالجه کردن . مداوا کردن . شفا دادن . درمان کردن . سالم و تندرست کردن . خوب کردن . و رجوع به چاق کردن و فربه کردن شود.<br /></font></div>'),
(282456, 'چاق چاق', '<span class=\"hlight\">چاق چاق .</span> (اِ صوت مرکب ) چاقاچاق . تاق تاق . طراق طراق . صدایی که از خورد شدن و شکستن چیزی برخیزد <span class=\"hlight\">:</span> <br />بِسرِ شَد گاهیش نرم و گه درشت <br />زو برآرد چاقچاقی زیر مشت .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(282457, 'چاق کردن', '<span class=\"hlight\">چاق کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) فربه کردن . فربی کردن . تسمین . <BR><font color=\"Blue\">◄</font> سالم کردن . تندرست کردن . معالجه کردن . درمان کردن . شفا دادن . خوب کردن . درست و تیار کردن . <BR><font color=\"Blue\">◄</font> قلیان و چپق و سیگار و غیره چاق کردن . قلیان تنباکو را آماده کردن . آب و تنباکو و آتش در قلیان کردن تا آماده کشیدن شود. چپق را توتون کردن و آتش زدن که مهیا برای کشیدن شود. سیگار آتش زدن . در تداول عامه خراسان و برخی مردم نقاط دیگر ایران : آتش زدن چپق و پیپ و سیگار.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کمانچه را چاق کردن </span> ؛ اصطلاحی است برای کوک کردن یا گرم و خشک کردن کمانچه آنچنانکه آماده نواختن شود <span class=\"hlight\">:</span> <br />بچنگش کمانگر نیاید به پیش <br />کند چاقش از آتش صوت خویش .<br /><font color=\"Red\">ملاطغرا (از آنندراج ).</font><br /></font></div>'),
(282458, 'چاقاله', '<span class=\"hlight\">چاقاله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) چاغاله . چغاله . بادام با پوست سبز نارس، اَخکوک، بعضی میوه های سبز و نارس، چون بادام و زردآلو و شفتالو ولی بیشتر در بادام گفته میشود و گاه کلمه بادام را نیز بر آن افزایند و «چاقاله بادام » گویند و رجوع به اخکوک و چاغاله و چغاله شود.<br /></font></div>'),
(282459, 'چاقالو', '<span class=\"hlight\">چاقالو.</span> (ص مرکب ) چاق . فربه . پرگوشت . گوشتالو. چاق و چله . خپله . گرد و قنبلی . چاق و چقل .<br /></font></div>'),
(282460, 'چاقاچاق', '<span class=\"hlight\">چاقاچاق .</span> (اِ صوت مرکب ) طراق طراق . شراق شراق . چاق چاق . صدایی که از شکستن چیزی برخیزد <span class=\"hlight\">:</span> <br />می شکست آن بند ز آن بانگ بلند<br />هر طرف میرفت چاقاچاق بند.<br /> <font color=\"Red\">مولوی .</font><br />و رجوع به چاق چاق شود.<br /></font></div>'),
(282461, 'چاقر', '<span class=\"hlight\">چاقر.</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) دهی از دهستان فعله کری بخش سنقر کلیائی شهرستان کرمانشاهان . در <span class=\"hlight\" dir=\"rtl\">٢٩</span> هزارگزی شمال خاوری سنقر و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی خاور هزارخانی پائین . کوهستانی، سردسیر با <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه .آب آن از چشمه، محصول آنجا غلات و حبوبات و تریاک و توتون، شغل اهالی زراعت و راه آن مالرو، صنایع دستی قالیچه و جاجیم بافی . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282462, 'چاقر', '<span class=\"hlight\">چاقر.</span> <font color=\"DarkGreen\"><b>[ ق ِ ]</font></b> (اِخ ) دهی جزء دهستان فراهان بالا بخش فرمهین شهرستان اراک . واقع در <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزارگزی شمال فرمهین و <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزارگزی راه مالرو عمومی . دامنه، سردسیر با <span class=\"hlight\" dir=\"rtl\">٢٢٣</span> تن سکنه . آب آن از قنات و رود محلی، محصول آنجا بنشن و ارزن و انگور و بادام . شغل اهالی زراعت و گله داری . و کرباس و جاجیم بافی و راه آن مالرو است و از فرمهین اتومبیل میتوان برد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282463, 'چاقر احمد', '<span class=\"hlight\">چاقر احمد.</span> <font color=\"DarkGreen\"><b>[ ق ِ اَ م َ ]</font></b> (اِخ ) دهی از دهستان آجرلوبخش مرکزی شهرستان مراغه واقع در <span class=\"hlight\" dir=\"rtl\">٦١/٥</span> هزارگزی جنوب خاوری مراغه و <span class=\"hlight\" dir=\"rtl\">١٨/٥</span> هزارگزی شمال خاوری شوسه شاهین دژ به میاندوآب . دره، معتدل، مالاریایی با <span class=\"hlight\" dir=\"rtl\">١٠٦</span> تن سکنه، آب آن از دره ٔ جان آقا و چشمه، محصول آنجا غلات، بادام و حبوبات، شغل اهالی زراعت، صنایع دستی جاجیم بافی و راه آن مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(282464, 'چاقشر', '<span class=\"hlight\">چاقشر.</span> <font color=\"DarkGreen\"><b>[ ش ُ ]</font></b> (اِ) چاقشور. (ناظم الاطباء). و رجوع به چاقشور شود.<br /></font></div>'),
(282465, 'چاقشور', '<span class=\"hlight\">چاقشور.</span> (اِ) چاخچور. چاقچور. دولاغ . (ناظم الاطباء). مبدل چاقچور است . (فرهنگ نظام ). چاقشر. (ناظم الاطباء). قسمی از جوراب که از نوک انگشتان پا تا کمر را میپوشاند. (ناظم الاطباء). چیزی است از عالم موزه که پشمین و سقرلاتی باشد. (آنندراج ).<br /></font></div>'),
(282466, 'چاقشوردوز', '<span class=\"hlight\">چاقشوردوز.</span> (نف مرکب ) چاخچوردوز. چاقچوردوز. آنکه شغل وی دوختن چاقشور است <span class=\"hlight\">:</span> <br />در رشته ٔ چاقشوردوزان <br />ماهی بینی چو مهر تابان .<br /> <font color=\"Red\">طاهر وحید (در صفت صفاهان از آنندراج ).</font><br />در ذکر توابین صاحب جمع مذکور: خیاط، جوراب دوز، چاقشوردوز، ... (تذکرة الملوک چ <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">٣٠</span>).<br /></font></div>'),
(282467, 'چاقلو', '<span class=\"hlight\">چاقلو.</span> (اِخ ) تیره ای از ایل اینانلوکه این ایل یکی از ایلات خمسه ٔ فارس میباشد که از قشقایی ها هستند و محل اقامتشان بیشتر در مشرق و جنوب شرقی ایالت فارس است . (جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">٨٦</span>).<br /></font></div>'),
(282468, 'چاقنده', '<span class=\"hlight\">چاقنده .</span> <font color=\"DarkGreen\"><b>[ ق ِ دَ ]</font></b> (ترکی، اِ) هنگام چریدن . در وقت چریدن . در وقت چرا. (آنندراج ) (غیاث ).<br /></font></div>'),
(282469, 'چاقه', '<span class=\"hlight\">چاقه .</span> <font color=\"DarkGreen\"><b>[ ق َ ]</font></b> (اِخ ) دهی است از دهستان پائین ولایت مشهد جزءبخش فریمان که در <span class=\"hlight\" dir=\"rtl\">٧٢</span> هزارگزی شمال خاوری فریمان و در <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی مشرق راه شوسه سرخس به مشهد واقع شده است . منطقه ای است کوهستانی و سردسیر که <span class=\"hlight\" dir=\"rtl\">٧٦</span> تن سکنه دارد. اراضیش از آب قنات مشروب میشود و محصولش غلات، بنشن و تریاک است . شغل مردم آنجا زراعت و مالداری است وراهش مالرو میباشد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282470, 'چاقه', '<span class=\"hlight\">چاقه .</span> <font color=\"DarkGreen\"><b>[ ق َ ]</font></b> (اِخ ) دهی از دهستان درزاب، بخش حومه ٔ شهرستان مشهد است که در <span class=\"hlight\" dir=\"rtl\">٤٤</span> هزارگزی شمال باختری مشهد بر سر راه مشهد به درزاب که مالرو عمومی است واقع شده است . هوایش معتدل و زمین آن جلگه است . <span class=\"hlight\" dir=\"rtl\">٦٨</span> تن سکنه دارد اراضی آن از آب قنات مشروب میشود و محصولش غلات و چغندر میباشد. شغل اهالی آنجا زراعت و مالداری است و راهش ماشین رو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>). و رجوع به مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٢</span> شود.<br /></font></div>'),
(282471, 'چاقه بلوچها', '<span class=\"hlight\">چاقه بلوچها.</span> <font color=\"DarkGreen\"><b>[ ق َ ب َ ]</font></b> (اِخ ) دهی است از دهستان زاوه بخش حومه ٔ شهرستان تربت حیدریه که در <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی شمال خاوری تربت واقع شده است و <span class=\"hlight\" dir=\"rtl\">٥٤٠</span> تن سکنه دارد. هوایش معتدل و زمین آن که در دامنه کوه واقع است از آب قنات مشروب میشود. محصولش غلات و شغل مردم زراعت و گله داری است . در آنجا قالیچه و چادر هم میبافند و طایفه ٔ بلوچ قرایی در این آبادی سکونت دارند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282472, 'چاقه محمدجان', '<span class=\"hlight\">چاقه محمدجان .</span> <font color=\"DarkGreen\"><b>[ق َ م ُ ح َم ْ م َ ]</font></b> (اِخ ) دهی از دهستان زاوه بخش حومه ٔ شهرستان تربت حیدریه است که در <span class=\"hlight\" dir=\"rtl\">٣٦</span> هزارگزی شمال خاوری تربت در دامنه ٔ کوه واقع شده هوایش معتدل است و دوازده تن سکنه دارد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282473, 'چاقو', '<span class=\"hlight\">چاقو.</span> (اِخ ) ده کوچکی است از بخش زرند شهرستان ساوه . سکنه <span class=\"hlight\" dir=\"rtl\">١٤</span> تن . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282474, 'چاقو', '<span class=\"hlight\">چاقو.</span> (اِ) چقو. (آنندراج ). آلت بریدن چیزها که دارای دسته و تیغه است و تیغه اش تاه شده در میان دسته جا میگیرد. (نظام ). کارد کوچک که غالباًتیغه ٔ آن به دسته تا می شود. (ناظم الاطباء). نوعی از کارد و مانند به استره و سرش در شکم میباشد. (آنندراج ). قلم تراش . چاکو. (ناظم الاطباء). چیقو. (آنندراج ). <BR><font color=\"Blue\">◄</font> قسمتی از کارد است . (فرهنگ نظام ).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">چاقو دسته خودش را نبرد</span> ؛ در مورد اینکه شخص خویشان و یاران خود را حمایت کند و به آنان آسیب و گزند نرساند.<br /> <span class=\"hlight\">صد تا چاقو میسازد که یکیش هم دسته ندارد</span> ؛ مثل است در مقام بیان دروغگویی کس . (فرهنگ نظام ).<br /><span class=\"hlight\">قول او و چاقوی جیب سگ </span> ؛ در مورد بدقولی و گزافه گویی اشخاص به کار رود.<br /></font></div>'),
(282475, 'چاقو تیزکن', '<span class=\"hlight\">چاقو تیزکن .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (نف مرکب ) تیزگر. تیزکننده ٔ چاقو. <BR><font color=\"Blue\">◄</font> (اِ مرکب ) فسان . سنگ فسان . سنگ ساو. آلتی که بوسیله ٔ آن چاقو و کارد و غیره را تیز کنند. سنگی باشد که چاقو را بر آن کشند تا برنده و تیز شود. آلتی از سنگ یا چرم که تیز کردن چاقو را بکار آید.<br /></font></div>'),
(282476, 'چاقو دسته کردن', '<span class=\"hlight\">چاقو دسته کردن .</span> <font color=\"DarkGreen\"><b>[ دَ ت َ <span class=\"hlight\" dir=\"rtl\">/</span> ت ِ ک َ دَ ]</font></b> (مص مرکب ) بیکار بودن . کار نداشتن . سر بجیب فرو بردن . (آنندراج ). غنچه خسپ بودن . (آنندراج ). <BR><font color=\"Blue\">◄</font> در سرما گرم شدن را چمباتمه و بر پاشنه نشستن . (امثال و حکم دهخدا) <span class=\"hlight\">:</span> <br />سر نهاده میان زانوها<br />هر زمان ساخت دسته چاقوها.<br /> <font color=\"Red\">(از امثال و حکم دهخدا).</font><br /><BR><font color=\"Blue\">◄</font> کنایه از جماع و لواط کردن . اغتلام . و به اصطلاح کنایه از اغلام است . (آنندراج ). <br /></font></div>'),
(282477, 'چاقو کش', '<span class=\"hlight\">چاقو کش .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (نف مرکب ) چاقوکشنده . بازکننده ٔ تیغه چاقو برای زدن . کسی که مردم را با چاقو تهدید و گاهی مجروح و مقتول میکند تا نقدینه ٔ آنان را بگیرد یا برباید. ولگرد. هرزه گرد. عربده جو. بدمست . باج گیر. لات . شریر. فردی از افراد اراذل و اوباش . بیکاره ٔ ولگردی که از راه ارعاب و تهدید و با چاقو و عربده جویی از اهل بازار و کسبه جنس یا نقدینه میطلبد و میگیرد. آنکه به اندک بهانه ای چاقو میکشد و چاقو میزند. بچاق چی . پیچاق چی .ولگردی که برای دزدی و بیم دادن مردم چاقوی بلند ضامن دار با خود دارد و چاقوکشی را حرفه ٔ خود میداند.<br /></font></div>'),
(282478, 'چاقوساز', '<span class=\"hlight\">چاقوساز.</span> (نف مرکب ) کسی که چاقوسازی داند و چاقوسازی کند. سازنده ٔ چاقو.<br /></font></div>'),
(282479, 'چاقوکشی', '<span class=\"hlight\">چاقوکشی .</span> <font color=\"DarkGreen\"><b>[ ک َ <span class=\"hlight\" dir=\"rtl\">/</span> ک ِ ]</font></b> (حامص مرکب ) عمل چاقوکش . هرزگی . عربده جویی . ولگردی . باج خواهی . بچاقچی گری . پیچاقچی گری .<br /></font></div>'),
(282480, 'چاقچور', '<span class=\"hlight\">چاقچور.</span> (اِ) چاخچور. چاقشور. دولاغ . شلواری فراخ و دو پاچه بهم پیوسته که از کمر تا نوک انگشتان پای را مستور میداشت و زنان هنگام بیرون رفتن از خانه میپوشیدند. نوعی جامه ٔ زنانه مخصوص پوشانیدن هردو پای از بالای ران تا نوک انگشتان . لباسی است مخصوص پای زنان که از پنجه ٔ پا تا کمر یا تا وسط ساق پا را میپوشاند و در مفصل پا و ساق چین دارد. (فرهنگ نظام ). و رجوع به چاخچور و چادرچاخچور و چاقشور شود.<br /></font></div>'),
(282481, 'چاقی', '<span class=\"hlight\">چاقی .</span> (حامص ) فربهی . تنومندی . گندگی . سنگینی . پرگوشتی . سمن . <BR><font color=\"Blue\">◄</font> صحت . سلامت . عافیت . تندرستی . بهبود.<br /></font></div>'),
(282482, 'چال', '<span class=\"hlight\">چال .</span> (اِخ ) دهی است از ولایت قزوین که سربلوک رامند است . (برهان ) (جهانگیری ). مؤلف انجمن آراء نویسد: نام قریه ای ازقزوین، و معروف است . شال .<br /></font></div>'),
(282483, 'چال', '<span class=\"hlight\">چال .</span> (اِ) چاله . گودال . مغاک . حفره . گودی . گوی و مغاکی را گویند که درآن توان ایستاد یعنی زیاده بر دو گز نباشد. (برهان ). گودال بود و آن را چاله نیز گویند. گودال و چاه کوچک که چاله گویند. (انجمن آرا). (آنندراج ). گودال، مانند چاه کم عمق که عموماً خشک باشد. (فرهنگ نظام ). <BR><font color=\"Blue\">◄</font> گوی که جولاهگان پاهای خود را در آن آویزند. (برهان ) (جهانگیری ) (انجمن آرا) (آنندراج ). گودال جای پای جولاهه . (فرهنگ نظام ). پاچال . <BR><font color=\"Blue\">◄</font> گوی تاریک که مجرمان را در آن محبوس سازند. سیاه چال . (جهانگیری ) (انجمن آرا) (آنندراج ) (فرهنگ نظام ).<br /> <BR><font color=\"Blue\">◄</font> اصل کلمه ٔ «سیلو». آنجا که جو و گندم در آن فروریزند نگاه داشتن را. انبار غله <span class=\"hlight\">:</span> <br />ستوروار بدین سان گذاشتم همه عمر<br />دو چشم سوی جو و دل به خنبه و زی چال .<br /> <font color=\"Red\">؟ (فرهنگ اسدی در لغت خنبه ص <span class=\"hlight\" dir=\"rtl\">٤٧٠</span>).</font><br />کله در چول و غله اندر چال <br />نتوان داشت چله از سرحال .<br /><font color=\"Red\">اوحدی (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> گوی که در آن یخ گذارند. یخ چال . (انجمن آرا) (آنندراج ) (فرهنگ نظام ). <BR><font color=\"Blue\">◄</font> گروی که دو سه کس در قمار با هم بندند و برند و گویند «فلانی چال کرد» یعنی گرو را برد. (برهان )(جهانگیری ) <span class=\"hlight\">:</span> <br />هیچ میدانی که اینجا با حریف مهره دزد<br />جان همی بازی بخصلی تو به هر چال قمار.<br /> <font color=\"Red\">جمال الدین عبدالرزاق (از جهانگیری ).</font><br />چال قمار. چال قمارخانه . (انجمن آرا) (آنندراج ) <span class=\"hlight\">:</span> <br />فلک تخته ٔ نرد و سیاره مُهره <br />زمین جمله چال قمار است گویی .<br /> <font color=\"Red\">شرف شفروه (از انجمن آرا).</font><br /> <BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چال قمار</span> ؛ گودال محل قماربازی . چال قمار هم در قدیم بوده که قماربازان در آن پنهان قمار میباختند. (فرهنگ نظام ).<br /> <BR><font color=\"Blue\">◄</font> بمعنی آشیان مرغ هم آمده است (برهان ). آشیانه . (جهانگیری ) (انجمن آرا) (آنندراج ). آشیانه ٔ مرغان . (فرهنگ نظام ) <span class=\"hlight\">:</span> <br />سیه مست مرغی درآمد بچال <br />زرین بیضه بنهفت در زیر بال .<br /> <font color=\"Red\">ملک قمی (در وصف آمدن شب، از جهانگیری ).</font><br /> <BR><font color=\"Blue\">◄</font> مرغی بود چند زاغی و طعم گوشتش چون گوشت بط باشد. (فرهنگ اسدی ). نوعی از مرغابی باشد و آن دو قسم است بزرگ و کوچک ؛ بزرگ آن را که در جثه بمقدار غاز است «خرچال » و کوچک آن را که ببزرگی زاغ است «چال » گویند . و به ترکی هوبره است که بعربی حباری و بترکی توغدری خوانند. (برهان ). کبک و کبگک گویند و بعربی حباری و بترکی توغدری . (جهانگیری ). و کبک دری را نیز گفته اند. (برهان ). کبک دری باشد. (جهانگیری ) (انجمن آرا) (آنندراج ). مرغی است که نام دیگرش کبک است و قسم بزرگ آن کبک دری و خرچال گفته میشود. (فرهنگ نظام ). چرز. (حاشیه ٔ احوال و اشعار رودکی ص <span class=\"hlight\" dir=\"rtl\">١٠٦٧</span>) <span class=\"hlight\">:</span> <br />و گر ببلخ زمانی شکار چال کند<br />بیاکند همه وادیش را ببط و بچال .<br /> <font color=\"Red\">عماره (از فرهنگ اسدی ).</font><br />چو باز را بکند بازدار مخلب و پر<br />بروز صید برو کبک راه گیرد و چال .<br /> <font color=\"Red\">شاهسار (از فرهنگ اسدی ).</font><br />چو پیروز دید آنچنان چال را<br />نشان ظفر یافت آن فال را.<br /> <font color=\"Red\">نظامی (ازانجمن آرا).</font><br />یگانه خسرو صاحبقران که از عدلش <br />رود به پرسش، شاهین بخانه ٔ بط و چال .<br /> <font color=\"Red\">شمس فخری (ازجهانگیری ).</font><br /> <BR><font color=\"Blue\">◄</font> گودی زنخ . چال زنخ . چاه زنخدان <span class=\"hlight\">:</span> <br />شد دل خسته ٔ من بسته ٔ چال زنخت <br />ز آنکه انباشته شد تا به لب آن چال بمشک .<br /> <font color=\"Red\">ابن یمین (از جهانگیری ).</font><br /> <BR><font color=\"Blue\">◄</font> هر چیز دو موی را گویند. (برهان ). دوموی را گویند عموماً. (جهانگیری ). سیاه و سفید. سرخ و سفید. <BR><font color=\"Blue\">◄</font> اسبی که موی آن سرخ و سفید و درهم آمیخته باشد. (برهان ) (جهانگیری ) (انجمن آرا) (آنندراج ) <span class=\"hlight\">:</span> <br />در سر گرفته با نقط کلک اصفرت <br />گلگون آسمان هوس چال و ابرشی .<br /> <font color=\"Red\">اخسیکتی (از انجمن آرا).</font><br />از بوی مشک تبت کان صحن صیدگه راست <br />آغشته بود با خاک از نعل بور و چالش .<br /> <font color=\"Red\">خاقانی (دیوان چ سجادی ص <span class=\"hlight\" dir=\"rtl\">٢٢٨</span>).</font><br /> <BR><font color=\"Blue\">◄</font> بمعنی اسب عموماً. (انجمن آرا) (آنندراج ). <BR><font color=\"Blue\">◄</font> دو فرسنگ . بزبان علمی اهل هند هر چهار گروه راه، یک چال است و هردو گروه یک فرسنگ پس چالی دو فرسنگ باشد. <BR><font color=\"Blue\">◄</font> بزبان متعارف اهل هند بمعنی رفتار است . (برهان ) (جهانگیری ) (انجمن آرا) (آنندراج ). گام و رفتار. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (فعل امر) امر برفتن یعنی راه رو. (برهان ) (انجمن آرا) (آنندراج ). <BR><font color=\"Blue\">◄</font> (اِ) نام نوعی از ماهی . (برهان ) (انجمن آرا) (آنندراج ). <BR><font color=\"Blue\">◄</font> بصورت مزید مؤخر امکنه آید همچون :<br />اترک چال . احمدچال . انارچال . آهک چال . انار مرزچال . باف چال . پاچال . پامچال . پشمه چال . پیاز چال . ترک چال . توچال . جوزچال . خرمنده چال . خشه چال . دیوچال . زردی چال . زرشک چال . زغال چال . زندان چال . سرخه چال . سنگ چال . سیاه چال . سه پشته چال . سیب چال . فنگ چال . کپورچال . کردی چال . کرکره چال . کنگرچال . کنگله چال . کافرچال . کبودچال . مرادچال . منکی چال . نفت چال . گله چال . مازیه چال . مسجدچال . نرگس چال . ونده چال . ولیک چال . وینه چال . هفت چال . هلوچال . هلی چال . هزارچال . یخ چال .<br /></font></div>'),
(282484, 'چال', '<span class=\"hlight\">چال .</span> (اِخ ) نام قلعه ای است بین فراهان و قزوین و حصار محکمی داشته است . (زندیه غفاری ).<br /></font></div>'),
(282485, 'چال', '<span class=\"hlight\">چال .</span> (اِخ ) دهی است جزء دهستان طارم بالا بخش سیروان شهرستان زنجان که در <span class=\"hlight\" dir=\"rtl\">٥٤٠٠</span> گزی شمال باختری سیروان و <span class=\"hlight\" dir=\"rtl\">١٨٠٠٠</span> گزی راه مالرو عمومی واقع شده . کوهستانی و سردسیر است .<span class=\"hlight\" dir=\"rtl\">٢٠٥</span> تن سکنه دارد که بشغل زراعت، گله داری و بافتن قالیچه و گلیم و جاجیم اشتغال دارند. آبش از رودخانه نصرآباد و محصولش غلات و عسل و گردو است . راهش مالرو و صعب العبور میباشد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282486, 'چال', '<span class=\"hlight\">چال .</span> (اِخ ) مؤلف مرآت البلدان از قول صاحب معجم البلدان نویسد: «یکی از دهات آذربایجان است در چهار فرسخی مداین که ابن حجاج آن را «کال » گفته و شعری در مذمت آن سروده ». (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٢</span>).<br /></font></div>'),
(282487, 'چال', '<span class=\"hlight\">چال .</span> (اِخ ) دهی است از دهستان ززو ماهرو بخش الیگودرز شهرستان بروجرد که در <span class=\"hlight\" dir=\"rtl\">٧٦</span> هزارگزی جنوب باختری الیگودرز کنار راه مالرو آثار به چالگرد واقع شده . کوهستانی و معتدل است . <span class=\"hlight\" dir=\"rtl\">٣٢٦</span> تن سکنه دارد. آبش از چشمه و قنات و محصولش غلات و تریاک و لبنیات است . شغل اهالی زراعت و گله داری است و راهش مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282488, 'چال', '<span class=\"hlight\">چال .</span> (اِخ ) دهی است ازبدخشان که در آن نمک کانی بهمرسد. (فرهنگ رشیدی ).<br /></font></div>'),
(282489, 'چال ابه', '<span class=\"hlight\">چال ابه .</span> <font color=\"DarkGreen\"><b>[ اُب ْ ب َ ]</font></b> (اِخ ) قریه ای است از قرای ورامین . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>).<br /></font></div>'),
(282490, 'چال استران', '<span class=\"hlight\">چال استران .</span> <font color=\"DarkGreen\"><b>[ اَ ت َ ]</font></b> (اِخ ) ده کوچکی است از دهستان ترکه دز بخش مسجدسلیمان شهرستان اهواز که در <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارگزی شمال باختری مسجدسلیمان کنار راه شوسه ٔ مسجد سلیمان به لالی واقع شده و <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه دارد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282491, 'چال اشتر', '<span class=\"hlight\">چال اشتر.</span> <font color=\"DarkGreen\"><b>[اُت ُ ]</font></b> (اِخ ) نام قریه ای است در چهارمحال اصفهان .<br /></font></div>'),
(282492, 'چال افتادن', '<span class=\"hlight\">چال افتادن .</span> <font color=\"DarkGreen\"><b>[ اُ دَ ]</font></b> (مص مرکب ) گودافتادن . گود شدن . <BR><font color=\"Blue\">◄</font> گود شدن چشم ها، در تداول عوام گویند: چشمهاش یک بند انگشت چال افتاده .<br /></font></div>'),
(282493, 'چال ترخان', '<span class=\"hlight\">چال ترخان .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) نام محلی است در شمال تهران و چند هزارگزی جنوب غربی شهر ری .<br /></font></div>'),
(282494, 'چال حصار', '<span class=\"hlight\">چال حصار.</span> <font color=\"DarkGreen\"><b>[ ح ِ ]</font></b> (اِخ ) نام محله ای در شهر تهران . نام یکی از محلات تهران . مؤلف مرآت البلدان نویسد: «نام کوچه ای است در محله سنگلج تهران ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٤</span>). و رجوع به عنوان بعد شود.<br /></font></div>'),
(282495, 'چال حصار', '<span class=\"hlight\">چال حصار.</span> <font color=\"DarkGreen\"><b>[ ح ِ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «در قدیم گودال بزرگی بوده است در محله ٔ سنگلج تهران به این اسم که همه ساله ایام عاشورا اهالی تهران در آنجا ازدحام کرده شبیه حادثه ٔ کربلا را در می آورده اند و در غیر آن ایام از نقاط کثیف تهران بوده و جناب آقای مستوفی الممالک <font color=\"DarkGreen\"><b>[ میرزا یوسف ]</font></b> اطراف آن گودال را ستونهای آجری نصب کرده محوطه ٔ وسط را تبدیل بباغ عمومی کرد که در نتیجه از نقاط باصفای تهران شد و هوای سنگلج را سالم و لطیف ساخت ». (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span> - <span class=\"hlight\" dir=\"rtl\">٧٤</span>).<br /></font></div>'),
(282496, 'چال خشک', '<span class=\"hlight\">چال خشک .</span> <font color=\"DarkGreen\"><b>[ خ ُ ]</font></b> (اِخ ) دهی از دهستان زردلان بخش مرکزی شهرستان کرمانشاه است که در <span class=\"hlight\" dir=\"rtl\">٧١</span> هزارگزی جنوب خاوری کرمانشاهان و <span class=\"hlight\" dir=\"rtl\">٢٩</span> هزارگزی سراب فیروزآباد واقع شده . کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">١٢٥</span> تن سکنه دارد. آبش از چشمه و محصولش غلات، لبنیات و تریاک میباشد. شغل اهالی زراعت و گله داری و تهیه هیزم و ذغال است . اهالی آنجا از طایفه ٔ کوشوند هستند و در تابستان به حدود کوه میروند.راهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282497, 'چال خواجه', '<span class=\"hlight\">چال خواجه .</span><font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ج َ ]</font></b> (اِخ ) دهی مخروبه است از بخش سمیرم شهرستان شهرضا. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282498, 'چال روزآبخوره', '<span class=\"hlight\">چال روزآبخوره .</span> <font color=\"DarkGreen\"><b>[ ل ِ رَ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «چال » و «روز آبخوره » هر یک علیحده قریه ای است از قراء محال طارم که در میان کوه واقع شده و هشتاد خانوار سکنه دارد، زراعتش دیمی و هوایش معتدل است ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٨</span>).<br /></font></div>'),
(282499, 'چال زمین', '<span class=\"hlight\">چال زمین .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) دهی است از دهستان کوهستان کلاردشت شهرستان نوشهر که در <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی جنوب باختری مرزان آباد و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی باختر شوسه چالوس به تهران واقع شده . کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آبش از چشمه و محصولش غلات و لبنیات است . شغل اهالی زراعت و گله داری است و راهش مالرو میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(282500, 'چال سرا', '<span class=\"hlight\">چال سرا.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) دهی است از بخش صالح آباد شهرستان ایلام که در <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی باختر ایلام نزدیک شوسه ٔ ایلام به تهران واقع شده . دامنه و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٤٧٥</span> تن سکنه دارد. آبش از چشمه ها و محصولش غلات و توتون و لبنیات و ذرت و مختصر برنج است . شغل اهالی زراعت و گله داری است ساکنین اینجا چادرنشین و از طایقه پنج ستون هستند که در زمستان برای تعلیف احشام خود به حدود مرز ایران و عراق (ارتفاعات کولک ) میروند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282501, 'چال سیاه', '<span class=\"hlight\">چال سیاه .</span> (اِخ ) نام قریه ای نزدیک اصفهان که در شمال غربی اصفهان و نزدیک سلطان آباد واقعاست .<br /></font></div>'),
(282502, 'چال سیاه', '<span class=\"hlight\">چال سیاه .</span> (اِخ ) دهی است از بخش ایزه شهرستان اهواز. که در <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی باختر ایزه واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">١١٠</span> تن سکنه دارد. آبش از چشمه و قنات و محصولش غلات و تریاک است . شغل اهالی زراعت و گله داری و صنایع دستی زنان کرباس بافی است و راهش مالرو میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282503, 'چال سیلابی', '<span class=\"hlight\">چال سیلابی .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) نام محله ای از محلات قدیم تهران <span class=\"hlight\">:</span> <br />لیلا را بردند چال سیلابی <br />براش خریدند سیب و گلابی .<br />(از تصنیفی که رنود تهران برای لیلا دختر کنت دمونت فر اولین رئیس نظمیه (شهربانی ) در دوران ناصرالدین شاه ساختند).<br /></font></div>'),
(282504, 'چال شتر', '<span class=\"hlight\">چال شتر.</span> <font color=\"DarkGreen\"><b>[ ش ُ ت ُ ]</font></b> (اِمرکب ) دوغی که از شیر اشتر سازند. (ناظم الاطباء).<br /></font></div>'),
(282505, 'چال شتری', '<span class=\"hlight\">چال شتری .</span> <font color=\"DarkGreen\"><b>[ ش ُت ُ ]</font></b> (اِ مرکب ) قسمی قفل . <BR><font color=\"Blue\">◄</font> نوعی پیچ .<br /></font></div>'),
(282506, 'چال شدن', '<span class=\"hlight\">چال شدن .</span> <font color=\"DarkGreen\"><b>[ ش ُ دَ ]</font></b> (مص مرکب ) چاله شدن . گود شدن . <BR><font color=\"Blue\">◄</font> دفن شدن . مدفون شدن . در زیر خاک گذاشته شدن کسی یا چیزی .<br /></font></div>'),
(282507, 'چال فخره', '<span class=\"hlight\">چال فخره .</span> <font color=\"DarkGreen\"><b>[ ف َ رَ ]</font></b> (اِخ ) دهی است جز دهستان بیات بخش نوبران شهرستان ساوه که در <span class=\"hlight\" dir=\"rtl\">٢٧</span>هزارگزی شمال باختر نوبران و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی راه عمومی واقع شده . <span class=\"hlight\" dir=\"rtl\">٩٠</span> تن سکنه دارد، کوهستانی و سردسیر است . آبش از چشمه سار و محصولش غلات و شغل اهالی زراعت و گله داری میباشد. راهش مالرو است و از طریق خان آباد ماشین هم میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282508, 'چال قصابان', '<span class=\"hlight\">چال قصابان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ق َ ]</font></b> (اِخ ) نام کوهی است در اصفهان .<br /></font></div>'),
(282509, 'چال قنبر', '<span class=\"hlight\">چال قنبر.</span> <font color=\"DarkGreen\"><b>[ ل ِ قَم ْ ب َ]</font></b> (اِخ ) دهی است از دهستان درو فرامان بخش مرکزی شهرستان کرمانشاهان که در <span class=\"hlight\" dir=\"rtl\">٢٥</span> هزارگزی خاور کرمانشاه و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی خاور قلعه ٔ قباد واقع شده . تپه ماهور و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٨٠</span> تن سکنه دارد. آبش از چاه و محصولش غلات دیم لبنیات و نخود میباشد شغل اهالی زراعت و گله داری است و راهش مالرو است ولی در تابستان از کرانی اتومبیل میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282510, 'چال ممسنی', '<span class=\"hlight\">چال ممسنی .</span> <font color=\"DarkGreen\"><b>[ م َ م َ س َ ]</font></b>(اِخ ) دهی است از دهستان باغ ملک بخش جانکی گرمسیر شهرستان اهواز که در <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی جنوب باختری باغ ملک و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی جنوب راه اتومبیل رو هفتگل به ایزه واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن سکنه دارد. آبش از چشمه و محصولش غلات و شغل اهالی زراعت میباشد. راهش اتومبیل رو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282511, 'چال موره', '<span class=\"hlight\">چال موره .</span><font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) نام رودخانه ای در ناحیه ٔ «کهکیلویه » که آبی شیرین و گوارا دارد. (فارسنامه ٔ ناصری ص <span class=\"hlight\" dir=\"rtl\">٣٢٤</span>) و مؤلف فارسنامه ٔ ناصری در این باره نویسد: رودخانه پرتاب <font color=\"DarkGreen\"><b>[ یا «پریاب » به قراری که در صفحه ٔ دیگر این کتاب آمده ]</font></b> چون به «چال موره » رسد آن را رودخانه «چال موره » گویند. و جای دیگر ذیل نام رودخانه ٔ «پریاب »نوشته است : ... از بلوک ممسنی از چشمه ٔ سوده گان ناحیه ٔ رستم برخاسته از کناره ٔ قلعه طوس گذشته به آب چشمه ٔ «اسری » و آب چشمه ٔ «حاجت » پیوسته رودخانه ٔ «چال موره » گردد... (از فارسنامه ناصری صص <span class=\"hlight\" dir=\"rtl\">٣٢٤</span> - <span class=\"hlight\" dir=\"rtl\">٣٢٣</span>).<br /></font></div>'),
(282512, 'چال میدان', '<span class=\"hlight\">چال میدان .</span> <font color=\"DarkGreen\"><b>[ ل ِ م ِ ]</font></b> (اِخ ) نام یکی از محله های تهران . نام محله ای معروف در شهر تهران .<br />مؤلف مرآت البلدان ذیل نام چالمیدان نویسد: «...معروف است که شاه طهماسب اول از سلاطین صفویه چون خواست بنای باره و حصار تهران را بگذارد از دو موضع از زمین این شهر خاک برداشتند و آن دو موضع دو چاله عمیق و وسیعشد که یکی از آندو به «چاله میدان » معروف و بعد مخفف شده «چالمیدان » گردید و این چالمیدان تا پانزده سال قبل جایی بسیار کثیف و مزبله ٔ شهر و محل ریختن کثافات بود. بعداً مرحوم فرخ خان امین الدوله که از وزرای این عهد بود و میلی تمام به ایجاد آثار خیریه داشت در آنجا مساجدی عالی بنا کرد و اگر چه بنای مسجد در حیات امین الدوله بوجه منظور بپایان نرسید لیکن آن مرحوم، حاجی ملامحمدجعفر مجتهد معروف به «چالمیدانی » را که در جوار همین مسجد مسکن داشت به امامت و تولیت مسجد انتخاب نمود... مشهد امامزاده سید اسماعیل ... در قرب چالمیدان واقع است و دیگر از ابنیه ٔ خیریه ای که در حوالی این محله است آب انباری است که مرحوم میرزاموسی مستوفی تفرشی وزیر دارالخلافه تهران بنا کرده است و کمال عظمت را دارد...». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٩</span>).<br /></font></div>'),
(282513, 'چال میرحسین', '<span class=\"hlight\">چال میرحسین .</span> <font color=\"DarkGreen\"><b>[ ل ِ ح ُ س ِ ]</font></b> (اِخ ) دهی است از دهستان کرگاه بخش ویسیان شهرستان خرم آباد که در <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی شمال خاور ماسورکنار و خاور راه شوسه ٔ خرم آباد به اندیمشک واقع شده . جلگه ای است معتدل و مالاریایی که <span class=\"hlight\" dir=\"rtl\">٧٠</span> تن سکنه فارس و لر دارد.آبش از رودخانه خرم آباد و محصولش غلات و لبنیات است .شغل اهالی زراعت و گله داری و صنایع دستی زنان نخ ریسی است . راهش اتومبیل رو و ساکنین این محل از طائفه میر، و چادرنشینند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282514, 'چال هما', '<span class=\"hlight\">چال هما.</span> <font color=\"DarkGreen\"><b>[ هَُ ]</font></b> (اِخ ) دهی است جزء دهستان سربند پائین بخش سربند شهرستان اراک که در <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارگزی جنوب باختر آستانه واقع شده، دامنه و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٦٤٦</span> تن سکنه ترک و فارس دارد. آبش از قنات و چشمه و محصولش غلات، بنشن و انگور و شغل اهالی زراعت و قالیچه بافی است . راهش مالرو میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282515, 'چال پشت', '<span class=\"hlight\">چال پشت .</span> <font color=\"DarkGreen\"><b>[ پ ُ]</font></b> (ص مرکب ) ستوری که شانه و کفلش برآمده و کمرش فرورفته باشد. (ناظم الاطباء). و رجوع به چاک پشت شود.<br /></font></div>'),
(282516, 'چال چرانه', '<span class=\"hlight\">چال چرانه .</span> <font color=\"DarkGreen\"><b>[ چ َ ن َ ]</font></b> (اِخ ) دهی است از دهستان موگونی بخش آخوره شهرستان فریدن که در <span class=\"hlight\" dir=\"rtl\">٤٥</span> هزارگزی باختر آخوره واقع شده . جلگه و سردسیر است و <span class=\"hlight\" dir=\"rtl\">١٥٧</span> تن سکنه دارد. آبش از چشمه و محصولش غلات و گردو است . شغل اهالی زراعت و راهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282517, 'چال چنار', '<span class=\"hlight\">چال چنار.</span> <font color=\"DarkGreen\"><b>[ چ َ ]</font></b> (اِخ ) دهی است از دهستان زلقی بخش الیگودرز شهرستان بروجرد که در <span class=\"hlight\" dir=\"rtl\">٦٦</span> هزارگزی جنوب باختری الیگودرز و کنار راه مالرو چال به آثار واقع شده . کوهستانی و ییلاقی است و <span class=\"hlight\" dir=\"rtl\">٦١</span> تن سکنه دارد. آبش از قنات و چاه و محصولش غلات و لبنیات و تریاک و پنبه و چغندر است . شغل اهالی زراعت و گله داری است . صنایع دستی زنان جاجیم بافی وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282518, 'چال کردن', '<span class=\"hlight\">چال کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) چاله کردن . گودال کردن . گود گردن . گود کردن زمین و مانند آن . <BR><font color=\"Blue\">◄</font> دفن کردن . بخاک سپردن . در زیر خاک نهفتن چیزی را؛ چنانکه گردویی را برای روئیدن یا لاشه مرده ای را برای پراکنده نشدن بوی گند آن . جسد آدمی را در گور نهادن . در زیر خاک کردن .<br /></font></div>'),
(282519, 'چال کش', '<span class=\"hlight\">چال کش .</span> <font color=\"DarkGreen\"><b>[ ک ُ ]</font></b> (اِخ ) دهی است از دهستان گلیجان شهرستان شهسوار که در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی باختر شهسوار و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی جنوب راه قدیم شهسوار به رامسر واقع شده . دامنه ای است معتدل و مرطوب و مالاریایی که <span class=\"hlight\" dir=\"rtl\">٥٥٥</span> تن سکنه دارد. آبش از رودخانه لنگرود و محصولش برنج و مرکبات و چای میباشد. شغل اهالی زراعت است و این محل دارای دبستان و کارخانه برنج کوبی و چند باب دکان میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(282520, 'چال کیاده', '<span class=\"hlight\">چال کیاده .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) دهی است از دهستان بالا خیابان بخش مرکزی شهرستان آمل که در <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی جنوب باختری آمل واقع شده . دشتی است معتدل و مرطوب و مالاریایی و <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آبش از نهر شلیت هراز و محصولش مختصر برنج و غلات و لبنیات است . شغل اهالی زراعت و گله داری است . صنایع دستی زنان شالبافی و راهش مالرو است . در تابستان عده ای از سکنه به ییلاق کزناسرا میروند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(282521, 'چال گودون', '<span class=\"hlight\">چال گودون .</span> <font color=\"DarkGreen\"><b>[ گ ُ دُ ]</font></b> (اِخ ) دهی است از دهستان طیبی گرمسیری بخش کهکیلویه شهرستان بهبهان که در <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی جنوب باختر لنده (مرکز دهستان ) و <span class=\"hlight\" dir=\"rtl\">٦٩</span> هزارگزی شمال راه شوسه بهبهان به آغاجاری واقع شده . کوهستانی و گرمسیر و مالاریائی است . <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن سکنه لر و فارس دارد. آبش از چشمه و محصولش غلات و برنج و پشم و لبنیات است . شغل اهالی زراعت و گله داری و صنایع دستی قالی، قالیچه، جوال، گلیم و پارچه بافی میباشد. راهش مالرو است و ساکنین این محل از طایقه طیبی هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282522, 'چال یحیی آباد', '<span class=\"hlight\">چال یحیی آباد.</span> <font color=\"DarkGreen\"><b>[ ل ِ ی َ یا ]</font></b> (اِخ ) صاحب مرآت البلدان نویسد: «دهکده ای است قدیم النسق در طارم ... که در سطح دره واقع شده و اطرافش کوه است . چهل خانوار سکنه دارد و زراعتش دیمی است . رودخانه ای هم از پائین دره میگذرد که برای اهل قریه قابل استفاده زراعتی نیست ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٨٥</span>).<br /></font></div>'),
(282523, 'چالاب', '<span class=\"hlight\">چالاب .</span> (اِ مرکب ) گودالی که آب باران یا آب سیل و غیره در آن مانده و جمع شده باشد. چاله آب . گودال آب .<br /></font></div>'),
(282524, 'چالاب', '<span class=\"hlight\">چالاب .</span> (اِخ ) دهی است از دهستان کرانی شهرستان بیجار که در <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی شمال باختری حسن آباد سوگند و کنار راه مالرو سلطان آباد به ده ویران واقع شده . کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن سکنه دارد. آبش از چشمه و محصولش غلات میباشد. شغل اهالی زراعت و صنایع دستی زنان قالیچه و جاجیم بافی و راهش مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282525, 'چالاب', '<span class=\"hlight\">چالاب .</span> (اِخ ) دهی است از دهستان ماهیدشت بالا بخش مرکزی شهرستان کرمانشاهان که در <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی خاور گلیم کبود واقع شده و فعلاً مخروبه است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282526, 'چالاب', '<span class=\"hlight\">چالاب .</span>(اِخ ) دهی است از دهستان دینور بخش صحنه شهرستان کرمانشاهان که در <span class=\"hlight\" dir=\"rtl\">٣٣</span> هزارگزی شمال باختری صحنه و در <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی باختر شوسه کرمانشاهان به سنقر واقع شده . دامنه و سردسیر است . <span class=\"hlight\" dir=\"rtl\">٨٥</span> تن سکنه دارد. آبش از چشمه و محصولش غلات دیمی و توتون و تریاک است . شغل اهالی زراعت و راهش مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282527, 'چالاب', '<span class=\"hlight\">چالاب .</span> (اِخ ) دهی است از دهستان کزران رود شهرستان تویسرکان که در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی باختر شهرستان تویسرکان و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی راه شوسه تویسرکان به کرمانشاه واقع شده . کوهستانی و سردسیر است . <span class=\"hlight\" dir=\"rtl\">٣٣٧</span> تن سکنه دارد. آبش از قنات و محصولش غلات دیم، کتیرا و لبنیات است . شغل اهالی زراعت و گله داری است . مختصری انگوردارد و صنایع دستی زنان قالی بافی میباشد. راه مالروفرعی به شوسه دارد. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282528, 'چالاب', '<span class=\"hlight\">چالاب .</span> (اِخ ) نام محلی است در کنار راه همدان و کرمانشاه میان سیه کله و نوکان که در <span class=\"hlight\" dir=\"rtl\">٥٤٨٥٠٠</span> گزی تهران واقع شده .<br /></font></div>'),
(282529, 'چالاب بکر', '<span class=\"hlight\">چالاب بکر.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) نام مزرعه ای است از دهستان گواور بخش گیلان شهرستان شاه آباد که هوای آن سردسیر و ییلاقی است . بین مزرعه ٔ سیدا یازو گاوسور و در که واقع شده . هنگام تابستان در حدود <span class=\"hlight\" dir=\"rtl\">١٠٠</span> خانوار چادرنشین از ایل کلهر برای تعلیف احشام و زراعت دیم به این محل میایند و در زمستان به حدود گرمسیربخش سوسمار میروند. (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282530, 'چالاب دالان', '<span class=\"hlight\">چالاب دالان .</span> (اِخ ) مؤلف مرآت البلدان نویسد: «اسم کوهی است مخروطی و بسیار مرتفع در مملکت غور افغانستان و یکی از قلل کوه «سیاهکوه » میباشد و در قدیم این کوهستان موسوم به «پاروزیانا» و شعبه ای از هندوکش بوده است . در خطوط میخی الواح بیستون اسمی از این کوه برده شده . قله چالاب دالان درحوالی زرنی که پایتخت قدیم غور بوده واقع است و همیشه این قله مسطور از برف میباشد. مسافر فرانسوی که چهل سال قبل بدانجا سفر نموده مینویسد، دوره این کوه از نصف ببالا دوازده فرسخ است که اصل ریشه یقیناً دو مقابل خواهد بود. دهات و مراتع زیاد «اویماقات » در همین دامنه است . بعضی قلعه جات هم آنجا از قدیم و جدید بجهت سقناق ساخته اند. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>).<br /></font></div>'),
(282531, 'چالاب زرد', '<span class=\"hlight\">چالاب زرد.</span> (اِخ )دهی است از دهستان بیجنوند بخش شیروان چرداول شهرستان ایلام که در <span class=\"hlight\" dir=\"rtl\">٢٣</span> هزارگزی جنوب خاوری چرداول کنار راه مالرو بیجنوند به چرداول واقع شده . کوهستانی و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٤٠</span> تن سکنه دارد. آبش از چاه و محصولش غلات، لبنیات و تریاک میباشد. شغل اهالی زراعت و گله داری و راهش مالرو است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282532, 'چالابه', '<span class=\"hlight\">چالابه .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش مرکزی شهرستان کرمانشاهان که در <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی خاور کرمانشاه از طریق طاق بستان، و از راه قدیم در <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی کنار شوسه کرمانشاه بتهران واقع شده . دامنه و معتدل است و <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آبش از چاه و محصولش غلات دیمی و لبنیات و تریاک میباشد. شغل اهالی زراعت و گله داری و راهش مالرواست . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282533, 'چالابه', '<span class=\"hlight\">چالابه .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اخ ) دهی است از دهستان ماهیدشت بخش مرکزی شهرستان کرمانشاه که در <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی جنوب ماهیدشت، کنار رودخانه مرک واقع شده . زمینش دشت و هوایش سردسیری است . <span class=\"hlight\" dir=\"rtl\">٣٢٥</span> تن سکنه دارد. آبش ازرودخانه مرک و قنات کوچک، محصولش غلات حبوبات و لبنیات و شغل اهالی زراعت است . تابستان راهش اتومبیل رو میباشد. در دو محل بفاصله <span class=\"hlight\" dir=\"rtl\">٢/٥</span> کیلومتر به علیا و سفلی مشهور است که سفلی در کنار رود مرک و نزدیک به ده سید نقی واقع شده است . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282534, 'چالاق', '<span class=\"hlight\">چالاق .</span> (ص ) چابک بود.(فرهنگ اسدی ص <span class=\"hlight\" dir=\"rtl\">٢٤٩</span>). چالاک . چست . جَلد. تند و تیز.<br /></font></div>'),
(282535, 'چالان', '<span class=\"hlight\">چالان .</span>(اِ) بیجک و فهرست . (ناظم الاطباء) بارنامه . نقل و انتقال از جایی به جایی . حمل بخارج . (ناظم الاطباء).<br /></font></div>'),
(282536, 'چالان چولان', '<span class=\"hlight\">چالان چولان .</span> (اِخ ) نام یکی از دهستانهای چهارگانه بخش حومه ٔ شهرستان بروجرد است . این دهستان در جنوب بروجرد واقع و حدود آن بشرح زیر است : از شمال به بروجرد، از جنوب به تنگ رازان، از خاور به دهستان ژان، از باختر به خرم آباد. مراکز این دهستان جلگه ولی قسمت خاور و باختر آن کوهستانی است و اغلب از قراء این دهستان در دامنه ٔ کوهستان واقع شده و هوای آن معتدل است . آب آن از قنوات و چشمه تأمین میگردد. محصولاتش غلات، تریاک، لبنیات و صیفی است . شغل مردان زراعت و گله داری و صنایع دستی زنان کرباس بافی میباشد راههای مورد استفاده ٔ این دهستان مالرو میباشد. این دهستان از <span class=\"hlight\" dir=\"rtl\">٣١</span> آبادی بزرگ و کوچک تشکیل میگردد و جمعیت آن در حدود <span class=\"hlight\" dir=\"rtl\">٧</span> هزار تن است . قراء مهم آن عبارتند از ده حاجی و پهلوانکل . (فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282537, 'چالانچولان', '<span class=\"hlight\">چالانچولان .</span> (اِخ )دهی که مرکز دهستان بخش حومه ٔ شهرستان بروجرد است ودر <span class=\"hlight\" dir=\"rtl\">٣٤</span> هزارگزی جنوب بروجرد کنار راه شوسه ٔ بروجرد بدرود واقع شده . زمینش جلگه و هوایش معتدل است و <span class=\"hlight\" dir=\"rtl\">٨٧١</span> تن سکنه دارد. آبش از قنات و چاه و محصولش غلات، تریاک و لبنیات است . شغل اهالی زراعت و گله داری میباشد وراه اتومبیل رو دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>). <BR><font color=\"Blue\">◄</font> نام محلی در کنار راه بروجرد و خرم آباد میان «قروق » و «میراحمد» در <span class=\"hlight\" dir=\"rtl\">٤٧٠٦٠٠</span> گزی تهران .<br /></font></div>'),
(282538, 'چالانچی', '<span class=\"hlight\">چالانچی .</span> (اِخ ) دهی از دهستان ایوان بخش گیلان شهرستان شاه آباد که در <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی جنوب باختری جوی رز و یک هزارگزی شوسه شاه آباد به ایلام واقع شده زمینش دشت و هوایش سردسیر است و <span class=\"hlight\" dir=\"rtl\">١٧٥٠</span> تن سکنه دارد. آبش از سراب ایوان و محصولش غلات و برنج و حبوبات و توتون و لبنیات میباشد. شغل اهالی زراعت و گله داری است و چادرنشین هستند. زمستان گرمسیر را به حدود باخترایوان و سومار میروند. در دو محل نزدیک بهم به علیاو سفلی مشهورند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282539, 'چالانچی', '<span class=\"hlight\">چالانچی .</span> (ترکی، ص مرکب ) سازنده . نوازنده . ساززن .<br /></font></div>'),
(282540, 'چالاک', '<span class=\"hlight\">چالاک .</span> (ص ) چابک . (فرهنگ اسدی ). (برهان ) (انجمن آرا) (آنندراج ) جَلد. (فرهنگ اسدی ) (برهان ) (انجمن آرا) (آنندراج ). چست . (آنندراج ) (ناظم الاطباء) (فرهنگ نظام ). تیز. (ناظم الاطباء). تند در کار. (فرهنگ نظام ). جَلد کار. (ناظم الاطباء). تند. فرز. سبک . قیچاق . قچاق <span class=\"hlight\">:</span> <br />ای میر نوازنده و بخشنده و چالاک <br />ای نام تو بنهاده قدم بر سر افلاک .<br /> <font color=\"Red\">عنصری (از فرهنگ اسدی ).</font><br />امسال که جنبش کند این خسرو چالاک <br />روی همه گیتی کند از خارجیان پاک .<br /> <font color=\"Red\">منوچهری .</font><br />آهسته تر ای سوار چالاک <br />بر دیده ٔ ما متاز چندین .<br /> <font color=\"Red\">خاقانی .</font><br />بدین دو خادم چالاک رومی و حبشی <br />درم خرید دو خاتون خرگه سنجاب .<br /> <font color=\"Red\">خاقانی .</font><br />ز آن جمله ٔ آهوان چالاک <br />بود آهوکی عجب شغبناک .<br /> <font color=\"Red\">نظامی .</font><br />چو نام هم شنیدند آن دو چالاک <br />فتادند از سر زین بر سر خاک .<br /> <font color=\"Red\">نظامی .</font><br />جوانی خردمند و فرزانه بود<br />که در وعظ چالاک و مردانه بود.<br /> <font color=\"Red\">سعدی (بوستان ).</font><br /> <BR><font color=\"Blue\">◄</font> دزد مردکش . (فرهنگ اسدی ). دزد و خونی . (برهان ) (انجمن آرا) (آنندراج ). دزد و راهزن و خونی . (ناظم الاطباء). دزد آدم کش . (فرهنگ نظام ) <span class=\"hlight\">:</span> <br />گفت کاین مردمان بی باکند<br />همه همواره دزد و چالاکند.<br /> <font color=\"Red\">عنصری (از فرهنگ اسدی ).</font><br /> <BR><font color=\"Blue\">◄</font> جای بلند. (حاشیه ٔ فرهنگ اسدی چ اقبال ). بمعنی جای بلند. (برهان ) (ناظم الاطباء). منزل مرتفع. (ناظم الاطباء). بلند. رسا. بالا بلند. مرتفع <span class=\"hlight\">:</span> <br />بدو بر یکی قلعه چالاک بود <br />گذشته سرش بر ز افلاک بود.<br /> <font color=\"Red\">اسدی (از فرهنگ اسدی ).</font><br />بسکه سربسته چو غنچه دردسر دارم چو بید<br />چون شکوفه نشکفم کز سر و چالاک توام .<br /> <font color=\"Red\">خاقانی .</font><br />ای قدر عنبر کم شده ز آن زلف سردرهم شده <br />وی قد خوبان خم شده پیش قد چالاک تو.<br /> <font color=\"Red\">خاقانی .</font><br />جز آن چاره ندیدآن سرو چالاک <br />کز آن دعوی کند دیوان خود پاک .<br /> <font color=\"Red\">نظامی .</font><br />شنیدم کآب خفتد زر شود خاک <br />چرا سیماب گشت آن سرو چالاک .<br /> <font color=\"Red\">نظامی .</font><br />ای که از سرو روان قد تو چالاکتر است <br />دل بروی تو ز روی تو طربناکتر است .<br /> <font color=\"Red\">سعدی (بدایع).</font><br />ای کسوت زیبایی بر قامت چالاکت <br />زیبا نتواند بود الا نظر پاکت .<br /> <font color=\"Red\">سعدی .</font><br />صد آشوب از قفای قد چالاک تو می آید<br />شکست قلب دل از چشم بی باک تو می آید.<br /> <font color=\"Red\">دانش (از آنندراج ).</font><br /> <BR><font color=\"Blue\">◄</font> مرد بزرگوار. (حاشیه ٔ فرهنگ اسدی چ اقبال ص <span class=\"hlight\" dir=\"rtl\">٢٥٠</span>) (فرهنگ نظام ) <span class=\"hlight\">:</span> <br />ای میر نوازنده و بخشنده و چالاک <br />ای نام تو بنهاده قدم بر سر افلاک .<br /> <font color=\"Red\">عنصری (از فرهنگ نظام ).</font><br /> <BR><font color=\"Blue\">◄</font> در اردو بمعنی «فریب دهنده » است که از این معنی فارسی گرفته شده . (فرهنگ نظام ). فریبا. زیبا <span class=\"hlight\">:</span> <br />روز و شب جان سوزی و آنگاه از ناپختگی <br />روز چون نیلوفری چالاک و شب چون زعفران .<br /> <font color=\"Red\">خاقانی .</font><br />گوزن از حسرت این چشم چالاک <br />ز مژگان زهر پالاید نه تریاک .<br /> <font color=\"Red\">نظامی .</font><br />بس میوه ٔ آبدار چالاک <br />کز چشم بد اوفتاددر خاک .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> سعدی شیرازی در شعر ذیل مجازاً آن را به معنی موزون و آراسته و متناسب آورده است <span class=\"hlight\">:</span> <br />ای بر تو قبای حسن چالاک <br />صد پیرهن از جدائیت چاک .<br /> <font color=\"Red\">سعدی (ترجیعات ).</font><br /><BR><font color=\"Blue\">◄</font> زیرک و هوشیار و آگاه . تیزفهم . <BR><font color=\"Blue\">◄</font> با جد و جهد. زحمتکش . <BR><font color=\"Blue\">◄</font> خودرای . (ناظم الاطباء). و رجوع به چست و فرز و جَلد شود.<br /></font></div>'),
(282541, 'چالاک شدن', '<span class=\"hlight\">چالاک شدن .</span> <font color=\"DarkGreen\"><b>[ ش ُ دَ ]</font></b> (مص مرکب ) چست و چابک شدن . جلد و فرز شدن . تند و تیز شدن . <BR><font color=\"Blue\">◄</font> مجازاً بمعنی بر سر شوق آمدن . خوش و خرم شدن . بانشاط شدن <span class=\"hlight\">:</span> <br />جسم خاک از عشق بر افلاک شد<br />کوه در رقص آمد و چالاک شد.<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(282542, 'چالاک پوی', '<span class=\"hlight\">چالاک پوی .</span> (نف مرکب ) پوینده ٔ چست و چالاک . تندرو. سریعالسیر. آنکه بتندی و چالاکی راه درنوردد <span class=\"hlight\">:</span> <br />چو بادند پنهان و چالاک پوی <br />چو سنگند خاموش و تسبیح گوی .<br /><font color=\"Red\">سعدی (بوستان ).</font><br /></font></div>'),
(282543, 'چالاک چنگ', '<span class=\"hlight\">چالاک چنگ .</span> <font color=\"DarkGreen\"><b>[ چ َ ]</font></b>(ص مرکب ) قوی چنگ . قویدست . ماهر. تردست <span class=\"hlight\">:</span> <br />شتابنده ملاح چالاک چنگ <br />به کشتی درآمد چو پویان نهنگ .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282544, 'چالاکی', '<span class=\"hlight\">چالاکی .</span> (حامص ) چابکی و جلدی . (ناظم الاطباء). سرعت . (ناظم الاطباء). چستی . فرزی . تیزی و تندی <span class=\"hlight\">:</span> <br />در مذهب طریقت خامی نشان کفر است <br />آری طریق دولت چالاکی است و چستی .<br /> <font color=\"Red\">حافظ.</font><br />دع التکاسل تغنم، فقد جری مثلی <br />که زاد راهروان چستی است و چالاکی .<br /> <font color=\"Red\">حافظ.</font><br /> <BR><font color=\"Blue\">◄</font> نشاط و شوق . (ناظم الاطباء). طربناکی . شادمانی <span class=\"hlight\">:</span> <br />سال امسالین نوروز طربناکتر است <br />پارو پیرار همی دیدم اندوهگنا<br />این طربناکی و چالاکی او هست کنون <br />از موافق شدن دولت، با بوالحسنا.<br /> <font color=\"Red\">منوچهری .</font><br /><BR><font color=\"Blue\">◄</font> سرکشی . <BR><font color=\"Blue\">◄</font> بصیرت و آگاهی . <BR><font color=\"Blue\">◄</font> تیزفهمی و کیاست و هوشیاری . (ناظم الاطباء).<br /></font></div>'),
(282545, 'چالباش', '<span class=\"hlight\">چالباش .</span> (اِخ ) مؤلف مرآت البلدان نویسد: «قریه ای است از قرای بجنورد که محل عبور ترکمان است و معابر طائفه مزبور از شمال تا جنوب خاک بجنورد امتداد یافته، قراول خانه های مغربی و جنوب غربی آن معابر در صحرای مابین بجنورد و جاجرم و زدین است . عبور تراکمه بسمت استرآباد و عباس آبادو غیره لابد باید از این قراولخانه ها باشد و طایفه یموت را عبور از این معابر ممکن نگردد مگر هنگامی که با ککلان همراه باشند. (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>).<br /></font></div>'),
(282546, 'چالبطان', '<span class=\"hlight\">چالبطان .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) دهی است از دهستان جانکی بخش لردگان شهرستان شهرکرد که در <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی باختر لردگان و یک هزارگزی راه لردگان به پل کره واقع شده، جنگل بلوط دارد هوایش معتدل است و <span class=\"hlight\" dir=\"rtl\">١٦٣</span> تن سکنه آنجاست . آبش از چشمه و دریاچه ٔ لردگان و محصولش غلات و ارزن و تنباکو و تریاک و برنج است . شغل اهالی زراعت و گله داری وزغال سوزی است . صنایع دستی محلی جاجیم و قالی بافی و راهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282547, 'چالبقا', '<span class=\"hlight\">چالبقا.</span><font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) دهی است از دهستان سردرود بخش رزن شهرستان همدان که در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی شمال باختر قصبه ٔ رزن کنار راه اتومبیل رو رزن به دمق واقع شده . کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">١٠٢</span> تن سکنه دارد. آبش از چشمه و محصولش غلات دیمی و مختصر انگور و لبنیات است . شغل اهالی زراعت و گله داری است . صنایع دستی زنان قالی بافی و راهش اتومبیل رو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282548, 'چالتاسیان', '<span class=\"hlight\">چالتاسیان .</span> (اِخ ) دهی است جزء دهستان بهنام سوخته بخش ورامین شهرستان تهران که در <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی شمال خاوری ورامین و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی شمال راه آهن واقع شده . <span class=\"hlight\" dir=\"rtl\">٢٢١</span> تن سکنه دارد. هوایش معتدل و زمینش جلگه است . آبش از قنات و محصولش غلات و صیفی و چغندر میباشد. شغل اهالی زراعت و راهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span> استان مرکزی ).<br /></font></div>'),
(282549, 'چالتاغ', '<span class=\"hlight\">چالتاغ .</span> (اِ) در اصطلاح اهالی «خوار» ورامین نام یکنوع اسباب بازی کودکانه است که آن را در «تهران » جغجغه نامند.<br /></font></div>'),
(282550, 'چالحق', '<span class=\"hlight\">چالحق .</span> <font color=\"DarkGreen\"><b>[ ح َ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «از قراء و مزارع قدیم النسق زنجان و ملک اهالی ابهر است که سی خانوار رعیت دارد و زراعتش آبی و دیمی است . آبش از رود دولت آباد است و محصولش بیشتر غله میباشد. هوایش ییلاقی است و ایل شاهسون قورت بیکلو در آنجا ییلاق میکنند». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٣</span>).<br /></font></div>'),
(282551, 'چالحوض', '<span class=\"hlight\">چالحوض .</span> <font color=\"DarkGreen\"><b>[ ل ِ ح َ <span class=\"hlight\" dir=\"rtl\">/</span> حُو ]</font></b> (اِ مرکب ) چاله حوض . حوض بزرگ از آب سرد در درون حمام که در آن شنا کنند. حوض بزرگی که در گرمابه های خزینه ای سابق میساختند و پر از آب سرد میکردند تا جوانان در آنجا شنا کردن آموزند و آنان که شناگری میدانند در آنجا شنا کنندو در حقیقت این حوض بزرگ یکنوع استخر سرپوشیده بود که اهالی محل از آن برای آموختن یا تمرین کردن شناگری استفاده میکردند و در سالهای اخیر با تبدیل حمام خزینه به حمام دوش این حوض ها نیز تعطیل و متروک شدند . و رجوع بچاله حوض شود.<br /></font></div>'),
(282552, 'چالدران', '<span class=\"hlight\">چالدران .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) نام یکی از دهستان های دوگانه بخش سیه چشمه شهرستان ماکو در حومه ٔ بخش، که از شمال به دهستان قلعه ٔ دره سی و آواچیق و از جنوب به دهستان سگمن آباد و الند و از خاور به دهستان به به جیگ و از باختر به مرز ایران و ترکیه محدود میباشد. موقع طبیعی، کوهستانی و هوایش بواسطه وجود سلسله جبال ساری چمن که مرز ایران و ترکیه است متغیر میباشد. قسمت های مرزی سردسیر و ییلاقی و سایر قسمت های آن معتدل است . آب قراء این دهستان از رودخانه های قزل چای و چالدران و قنات و چشمه سار تأمین میشود. محصول عمده اش غلات و حبوبات و شغل سکنه اش زراعت و گله داری است و صنایع دستی جاجیم بافی و جوراب بافی میباشد. صادراتش غلات و پشم و لبنیات و در قراء مرزی تربیت زنبور عسل متداول است . دهستان چالدران از <span class=\"hlight\" dir=\"rtl\">٨٤</span> آبادی بزرگ و کوچک تشکیل شده و جمع نفوس آن در حدود <span class=\"hlight\" dir=\"rtl\">١٣٢٤٠</span> تن است .قریه های مهم آن عبارت است از قصبه ٔ سیه چشمه (مرکز بخش و دهستان ) و قرخ بلاغ، بابالو، سعدل، امامقلی کندی، زیوه و خذرلی . (از فرهنگ جعرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">جنگ چالدران </span>؛ از حوادث مهمی که در این محل روی داده و بدین مناسبت نام «چالدران » در تاریخ سیاسی ایران ضبط شده است، واقعه ٔ جنگ چالدران است که میان شاه اسماعیل صفوی و سلطان سلیم پادشاه عثمانی در این محل بوقوع پیوست و پرفسور ادوارد برون در کتاب تاریخ ادبیات ایران (ترجمه ٔ رشید یاسمی ) به این جنگ اشاره کرده و نوشته است : «... اوایل رجب <span class=\"hlight\" dir=\"rtl\">٩٢٠</span> هَ . ق . (<span class=\"hlight\" dir=\"rtl\">٢٣</span> اوت <span class=\"hlight\" dir=\"rtl\">١٥١٤</span> م .) میان عثمانیان و ایرانیان در چالدران حربی عظیم واقع گشت . در این محل که قریب بیست فرسخ از تبریز مسافت دارد سه هزار عثمانی و دو هزار ایرانی کشته شدند لیکن توپخانه ٔ عثمانیان جنگ را بنفع ترکها ختم کرد و شاه اسماعیل با وجود شجاعتی که خود و همراهانش ابراز داشتند مجبور شد از میدان رو برگردانده و عقب نشسته حتی تبریز را هم بجا گذارد... «و مؤلف مرآت البلدان در این باره نویسد: «... سلطان سلیم در سنه <span class=\"hlight\" dir=\"rtl\">٩١٨</span> هَ . ق . با لشکری فراوان رو به آذربایجان نهاد و شاه اسماعیل که مترقب چنین جنگی نبود با عده ٔ معدودی که همراه داشت در عشر اول رجب از همدان عزیمت نموده با بیست هزار قشون در صحرای چالدران با لشکر عثمانی مصاف داد... در آن معرکه شاه اسماعیل خود بنفسه رشادت تمامی بروز داده جنگ میکرد... خیلی از امرای شاه اسماعیل در آن جنگ کشته شدند یا اسیر گردیدند و اگر چه شکست بقشون شاه اسماعیل وارد آمد اما جلادت و شجاعتی که شخصاًاز او در این معرکه ظاهر گردید سبب اشتهار کلی او شد». مؤلف مرآت البلدان سپس درباره ٔ شکست شاه اسماعیل و فتح تبریز بوسیله ٔ سلطان سلیم و حوادثی که بعد از جنگ چالدران روی داده است بتفصیل سخن میگوید و مخصوصاً فتحنامه ای را که سلطان سلیم خان در باب «فتح چالدران » بحاکم ادرنه نوشته است نقل میکند. (از کتاب تاریخ ادبیات ایران تألیف ادوارد برون، ترجمه ٔ رشید یاسمی ص <span class=\"hlight\" dir=\"rtl\">٦٠</span>، <span class=\"hlight\" dir=\"rtl\">٦١</span>، <span class=\"hlight\" dir=\"rtl\">٦٥</span>) و (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> صص <span class=\"hlight\" dir=\"rtl\">٧٤</span> - <span class=\"hlight\" dir=\"rtl\">٧٨</span>).<br /></font></div>'),
(282553, 'چالدره', '<span class=\"hlight\">چالدره .</span> <font color=\"DarkGreen\"><b>[ دَ رَ]</font></b> (اِخ ) دهی است از دهستان دیده بخش گیلان شهرستان شاه آباد که در <span class=\"hlight\" dir=\"rtl\">٣٨</span> هزارگزی شمال باختری گیلان ؛ کنار راه شوسه ٔ گیلان به سرپل ذهاب واقع شده . کوهستانی، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٧٥</span> تن سکنه دارد. آبش از رودخانه دیده و محصولش غلات و پنبه و ذرت و لبنیات است . شغل اهالی زراعت وگله داری است . در تابستان به حدود هوکانی و درکه میروند و باصطلاح اهل محل به این ده «چاله وریسکه » میگویند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282554, 'چالسبار', '<span class=\"hlight\">چالسبار.</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِخ ) دهی است از دهستان جاپلق بخش الیگودرز شهرستان بروجرد که در <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی شمال خاوری الیگودرز و کنار راه مالرو فرج آباد به خاکوار واقع شده . جلگه و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٠٠٣</span> تن سکنه دارد. آبش از قنات و چاه و محصولش غلات وتریاک و صیفی است . شغل اهالی زراعت و گله داری است وصنایع دستی زنان قالی بافی و جاجیم بافی میباشد و راهش اتومبیل رو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282555, 'چالش', '<span class=\"hlight\">چالش .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِمص ) (اسم مصدر از چالشمق ترکی ) به معنی زد و خورد . جدال . تلاش . <BR><font color=\"Blue\">◄</font> کشتی . مصارعت .<br /></font></div>'),
(282556, 'چالش', '<span class=\"hlight\">چالش .</span> <font color=\"DarkGreen\"><b>[ ل ِ ]</font></b> (اِمص ) چالیش . رفتاری که از روی ناز و تکبر و عجب کنند. (برهان ) (جهانگیری ) (ناظم الاطباء). رفتار کسی از روی تکبر و نخوت و ناز است در برابر حریف کارزار. (انجمن آرا) (آنندراج ) (فرهنگ نظام ). حرکت زیبا و ظریف و از روی عجب و خرامش و بزرگواری . (ناظم الاطباء). خرام خوش . حرکت و رفتاری از روی فیس و افاده . مؤلف فرهنگ نظام نویسد: احتمال میرود لفظ چالاک و چالش هر دو مأخوذ از لفظ چال بمعنی رفتار باشد که استعمال خود چال بمعنی رفتار متروک شده و مشتقاتش مانده است چه در سنسکریت که ریشه ٔ بسیاری از الفاظ فارسی را نشان میدهد لفظ چَل َ بمعنی رفتار موجود است ...» و رجوع به چالیش شود <span class=\"hlight\">:</span> <br />چون مهر کند فلک سواری <br />از چالش لاشه خر چه خیزد.<br /> <font color=\"Red\">کمال الدین اسماعیل (از انجمن آرا).</font><br />وای اگر صد را یکی بیند ز دور<br />تا بچالش اندر آید ازغرور.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> بمعنی جنگ و جدال . (برهان ) (ناظم الاطباء). حمله . یورش <span class=\"hlight\">:</span> <br />بفرمود شه تا دلیران روم <br />نمایند چالش در آن مرز و بوم .<br /> <font color=\"Red\">نظامی .</font><br />ز بس پیل کآمد بچالش برون <br />شد از پای پیلان زمین نیلگون .<br /> <font color=\"Red\">نظامی .</font><br />از آن سهمگین تر سپاهی قوی <br />عنان تافت بر چالش خسروی .<br /> <font color=\"Red\">نظامی .</font><br />برآشفت زنگی ز گفتار شاه <br />بچالش درآمد چو دود سیاه .<br /> <font color=\"Red\">نظامی .</font><br />در میان آندو لشکر گاه زفت <br />چالش و پیکار آنچه رفت رفت .<br /> <font color=\"Red\">مولوی .</font><br />چالش است این، لوت خوردن نیست این <br />تا تو بر مالی بخوردن آستین .<br /> <font color=\"Red\">مولوی .</font><br />با سگان بر استخوان در چالشی <br />چون نی اشکم تهی در نالشی .<br /> <font color=\"Red\">مولوی .</font><br />بمیدان شد و چالش آغاز کرد<br />به تحسین خسرو زبان باز کرد.<br /> <font color=\"Red\">امیرخسرو دهلوی (از انجمن آرا).</font><br /><BR><font color=\"Blue\">◄</font> مباشرت و جماع را نیز گویند. (برهان ). (ناظم الاطباء). کسی که در جماع حریص باشد.<br /></font></div>'),
(282557, 'چالش محله', '<span class=\"hlight\">چالش محله .</span> <font color=\"DarkGreen\"><b>[ ل ِ م َ ح َل ْ ل َ ]</font></b> (اِخ ) موضعی است از «یخ کش » در «اشرف ». (سفرنامه ٔ مازندران تألیف لوی رابینو ص <span class=\"hlight\" dir=\"rtl\">١٢٥</span>).<br /></font></div>'),
(282558, 'چالش کردن', '<span class=\"hlight\">چالش کردن .</span> <font color=\"DarkGreen\"><b>[ ل ِ ک َ دَ ]</font></b> (مص مرکب ) جدال کردن . نبرد کردن . هم آورد جنگ طلبیدن . برای پیروزی در جنگ یا امری دیگر تلاش و کوشش کردن <span class=\"hlight\">:</span> <br />بیا تا در این شیوه چالش کنیم <br />سر خصم را سنگ بالش کنیم .<br /> <font color=\"Red\">سعدی .</font><br /><BR><font color=\"Blue\">◄</font> کشتی گرفتن . مصارعت کردن . کوشیدن برای غلبه کردن بر حریف در کشتی .<br /></font></div>'),
(282559, 'چالش کنان', '<span class=\"hlight\">چالش کنان .</span> <font color=\"DarkGreen\"><b>[ ل ِ ک ُ ]</font></b>(نف مرکب، ق مرکب ) رزم کنان . نبردکنان، هماوردجویان .در جنگ مبارزخواهان و رجزخوانی کنان در میدان نبرد جولان کنان و بداشتن زور و نیرو تظاهرکنان <span class=\"hlight\">:</span> <br />عنان بر شه افکند چالش کنان <br />به صد خاریش بخت نالش کنان .<br /> <font color=\"Red\">نظامی .</font><br />درآمد به ناورد چالش کنان <br />بخون مخالف سگالش کنان .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282560, 'چالشتر', '<span class=\"hlight\">چالشتر.</span> <font color=\"DarkGreen\"><b>[ ش ُ ت ُ ]</font></b> (اِخ ) مؤلف مرآت البلدان در شرح نواحی «چارمحال » نویسد: از قرای ناحیه «رار» یکی قریه «چالشتر» است که قلعه ای آجری است و <span class=\"hlight\" dir=\"rtl\">٢٢</span>برج دارد و هر دهنه برج را هشتاد ذرع با برج دیگر فاصله است . از بناهای مرحوم حاجی محمد رضاخان میباشد و در آنجا بناهای عالی و عمارتهای بسیار خوب است که بیش از <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزار تومان خرج عمارات شده . دویست خانوار جمعیت و یک رشته قنات دارد که هشت سنگ میرابی آب از آن جاری است و هر سال صد خروار زمین بذرافشان را مشروب مینماید. حمام و مسجد و تیمچه و بازارچه و دکاکین و آسیا دارد و <span class=\"hlight\" dir=\"rtl\">٣٩٠</span> تومان مالیات دیوانی آنجاست و شش نفر سرباز هم میدهد. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> صص <span class=\"hlight\" dir=\"rtl\">٥١</span> - <span class=\"hlight\" dir=\"rtl\">٥٢</span>). و در فرهنگ جغرافیائی ایران نوشته شده است : «... دهی است از دهستان لار (رار) بخش حومه ٔ شهرستان شهرکرد که در <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی شمال باختر شهرکرد و یک هزارگزی راه عمومی شهرکرد به چالشترواقع شده . جلگه و کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">٣٢٦١</span> تن سکنه دارد. آبش از قنات و چشمه و محصولش غلات میباشد. شغل اهالی زراعت و گله داری و صنایع دستی قالی بافی و قفل سازی است . یک باب دبستان و یک عمارت سرپوشیده و قلعه قدیمی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282561, 'چالشم', '<span class=\"hlight\">چالشم .</span> <font color=\"DarkGreen\"><b>[ ل ِ ش ُ ]</font></b> (اِخ ) دهی جزء دهستان سیاهکل بخش سیاهکل دیلمان شهرستان لاهیجان که در <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی جنوب باختر سیاهکل واقع شده جلگه و معتدل ومرطوب است و <span class=\"hlight\" dir=\"rtl\">٢١١</span> تن سکنه دارد. آبش از نهر ملک رود ومحصولش برنج، لبنیات و عسل است و شغل اهالی زراعت وگله داری میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282562, 'چالشگر', '<span class=\"hlight\">چالشگر.</span> <font color=\"DarkGreen\"><b>[ ل ِ گ َ ]</font></b> (ص مرکب ) شخصی را گویند که خرامان و از روی ناز و عجب و تکبر براه رود. (برهان ) (ناظم الاطباء). خرامنده . (انجمن آرا) (آنندراج ). <BR><font color=\"Blue\">◄</font> مبارز و دلاور و جنگ جوی را نیز گفته اند. (برهان ) (ناظم الاطباء). مبارز و دلاور. (انجمن آرا) (آنندراج ). مبارزی که خرامان بجنگ رود. (انجمن آرا) (آنندراج ). مبارزطلب . هماوردطلب . رزم جوی <span class=\"hlight\">:</span> <br />ز گرز گرانسنگ چالشگران <br />شده ماهی و گاو را سر گران .<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> و بمعنی حریص و طماع هم آمده است . (برهان ). <BR><font color=\"Blue\">◄</font> شخص کثیرالجماع . (انجمن آرا) (آنندراج ). حریص در جماع و مباشرت . (ناظم الاطباء).<br /></font></div>'),
(282563, 'چالشگری', '<span class=\"hlight\">چالشگری .</span> <font color=\"DarkGreen\"><b>[ ل ِ گ َ ]</font></b> (حامص مرکب ) جنگجویی . (ناظم الاطباء). مبارزطلبی . هماوردطلبی . رزم خواهی <span class=\"hlight\">:</span> <br />بچالشکری سوی او راند رخش <br />برابر سیه خنده زد چون درخش .<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> آرامش با زنان . هم خوابگی با جفت . و رجوع بچالشکر شود <span class=\"hlight\">:</span> <br />همه کارشان شرب و مالشگری <br />نگشته شبی گرد چالشگری .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282564, 'چالقان', '<span class=\"hlight\">چالقان .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «بعقیده صاحب معجم البلدان از شهرهای سجستان است و بعقیده ٔ بعضی این شهر در قلمرو بُست واقع میباشد، پرجمعیت و معمور است و دو بازارمعتبر دارد». (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٨</span>). و رجوع به «جالقان » <font color=\"DarkGreen\"><b>[ با جیم ]</font></b> در معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٣٩</span> شود.<br /></font></div>'),
(282565, 'چالقه', '<span class=\"hlight\">چالقه .</span> <font color=\"DarkGreen\"><b>[ ق َ <span class=\"hlight\" dir=\"rtl\">/</span> ق ِ ]</font></b> (اِ) نوعی درختچه شیرخشت است که در «ارسباران » یافت میشود و اهالی ارسباران آن را بدین نام خوانند. (جنگل شناسی کریم ساعی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">٢٧٨</span>). و رجوع به شیرخشت شود.<br /></font></div>'),
(282566, 'چالقوچ', '<span class=\"hlight\">چالقوچ .</span> (اِخ ) دهی است جزء دهستان قاقازان بخش ضیأآباد شهرستان قزوین که در <span class=\"hlight\" dir=\"rtl\">٦٤</span> هزارگزی ضیأآباد و <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی راه شوسه واقع شده و <span class=\"hlight\" dir=\"rtl\">١٥١</span> تن سکنه ٔ کرد و فارس دارد. سردسیر است و آبش از چشمه سار میباشد و محصولش غلات و عدس و یونجه و لبنیات است . شغل اهالی زراعت و گله داری وبافتن جوال و گلیم میباشد. سکنه ٔ این محل از طائفه درویشوند هستند و در تابستان بحدود چشمه کره میروند.راهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282567, 'چاللو بادیانلو', '<span class=\"hlight\">چاللو بادیانلو.</span> (اِخ ) دهی است از دهستان قوریچای بخش قره آغاج شهرستان مراغه که در <span class=\"hlight\" dir=\"rtl\">٣٩</span> هزارگزی شمال باختر قره آغاج و <span class=\"hlight\" dir=\"rtl\">٥</span> هزار و <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> گزی جنوب شوسه مراغه به میانه واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٨٥</span>تن سکنه دارد. آبش از رود جیران و محصولش غلات و نخود میباشد. شغل اهالی زراعت و صنایع دستی جاجیم بافی وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(282568, 'چاللو جیانلو', '<span class=\"hlight\">چاللو جیانلو.</span> (اِخ ) دهی است از دهستان قوریچای بخش قره آغاج شهرستان مراغه که در <span class=\"hlight\" dir=\"rtl\">٤٧</span> هزارگزی باختر قره آغاج و <span class=\"hlight\" dir=\"rtl\">١٤</span> هزارگزی جنوب شوسه مراغه بمیانه واقع شده . دره ای است معتدل و مالاریایی که <span class=\"hlight\" dir=\"rtl\">٥٩</span> تن سکنه ترک زبان دارد، آبش از رودخانه جیران و محصولش غلات و نخوداست . شغل اهالی زراعت و صنایع دستی، جاجیم بافی و راهش مالرو میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(282569, 'چالماخورخور', '<span class=\"hlight\">چالماخورخور.</span> <font color=\"DarkGreen\"><b>[ خ ُ خ ُ ]</font></b> (اِخ ) دهی از دهستان مغان بخش گرمی شهرستان اردبیل که در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی باختر بیله سوار و <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی راه شوسه بیله سوار به اصلاندوز واقع شده . جلگه ای گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه ٔ ترک زبان دارد. آبش از چشمه و محصولش غلات و حبوبات است . شغل اهالی زراعت و گله داری و راهش مالرو میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(282570, 'چالمه', '<span class=\"hlight\">چالمه .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (ترکی، اِ) دلوگونه ای از چرم که در آن یخ ریزند و شیشه های شربت یا شیشه های شراب و دیگر مسکرات را در وی نهندتا سرد شود و خنک بماند. ظرفی دلو مانند که غالباً از چرم بلغار و گاه از چرم عادی سازند و مورد استعمالش آن است که ریزه های یخ در آن ریزند و شیشه های شربت یا مسکرات را درون وی گذارند تا سرد شوند. نوعی ظرف چرمی بزرگ بشکل دلو که در آن یخ کنند و شیشه هایی راکه محتوی انواع مشروبات هستند برای سرد شدن و سرد ماندن درون وی نهند. ظرفی چون دلوی بزرگ، از چرم بلغار یا چرم عادی مخصوص نگاه داشتن یخ، که شیشه های محتوی آشامیدنیهای مختلف را برای سرد شدن و سرد ماندن درون آن گذارند. جایخی . جای یخ . ظرف مخصوص نگه داشتن یخ . یخچال دستی . <BR><font color=\"Blue\">◄</font> قسمی عمامه که هندیان دارند. نوعی عمامه که بعضی از مردم هند بر سر نهند.<br /></font></div>'),
(282571, 'چالمیان', '<span class=\"hlight\">چالمیان .</span> <font color=\"DarkGreen\"><b>[م ِ ]</font></b> (اِخ ) دهی است از دهستان وفس عاشقلو بخش رزن شهرستان همدان که در <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی جنوب خاوری قصبه رزن و<span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی شمال خاور کمیجان اراک واقع شده، کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٤٣١</span> تن سکنه دارد که بشغل زراعت وگله داری مشغولند و صنایع دستی زنان قالی بافی میباشد. آبش از قنات و چشمه و محصولش غلات و لبنیات است . راهش مالرو میباشد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282572, 'چالندر', '<span class=\"hlight\">چالندر.</span> <font color=\"DarkGreen\"><b>[ ل َ دَ]</font></b> (اِخ ) نام ولایتی معروف در هندوستان . نام ولایتی در هندوستان که «مسعودسعد» شاعر نامدار ایرانی چند سالی از دوران آزادی خود را در آن محل میزیسته و چندی نیز سمت حکمرانی آنجا را داشته است . مرحوم رشید یاسمی در مقدمه ای که بر دیوان مسعودسعد نگاشته است . در ذیل کلمه ٔ «چالندر» چنین مینویسد: «از ناحیه ٔ دهگان شبی خبر به لاهور رسید که سابری نام با ده هزار سوار و پیاده به عزم جنگ پیش می آید. ابونصر فارسی شخصاً به مقابله ٔ او رفت ... در این جنگ مسعودسعد با ابونصر همراه بوده و وصفی بدیع از میدان جنگ کرده است در نتیجه این فتح، ولایت چالندر که تا آن وقت به اختیار دولت لاهور نیامده بود مسخر شدو ابونصر حکمرانی آنجا را به مسعود سپرد» و بعد مینویسد، «چالندر یا چالهندر شهری در پنجاب و سابقاً دارالملک آن ولایت بوده، ... از وصف هائی که مسعود راجع به راه چالندر کرده است همچنین پیداست که ولایتی کوهستانی و صعب العبور بوده است ». (دیوان مسعودسعد، مقدمه ٔرشید یاسمی ص لدوله ). نام ناحیتی از ولایت لاهور هندوستان که «مسعودسعد» پس از رهایی از حبس قلعه نای، ازطرف «بونصر فارسی » به مرزبانی و حکمرانی آن ناحیت نامزد شده و در قصاید خود چند جا نام «چالندر» را آورده است . نام ولایتی به سومنات (فرهنگ اسدی ). شهری است بر سر کوهی اندر، سردسیر و از او مخمل و جامه های بسیار خیزد ساده و منقش و اندر میان رامیان و چالهندر پنج روزه راه است و همه ٔ راه درختان هلیله و بلیله وآمله و داروهاست که بهمه ٔ جهان ببرند و این شهر از حدود رای قنوج است . (حدود العالم چ تهران چ سید جلال الدین تهرانی ص <span class=\"hlight\" dir=\"rtl\">٤٤</span> ذیل نام جالهندر). صاحب انجمن آرا و مؤلف آنندراج شرحی افسانه مانند ذیل لغت «چالندر»نوشته اند که اگر چه اعتبار تاریخی ندارد لیکن از آن جهت که نموداری از داستانهای باستانی ایران است عیناً نقل میشود و آن شرح چنین است : «شهری است در ولایت پنجاب که در زمان ضحاک در تصرف گماشتگان او بوده به امر فریدون، رستم زال (؟!) مسخر کرده آنجا را که چالندر باشد دارالملک پنجاب کرد... و پیروز رای بن کیشو راج بن مهاراج پادشاه هندوستان در زمان منوچهر لشکر کشیده پنجاب را گرفته «چالندر» را دارالملک کرده پیروز پور را بنام خود بساخت آخرالامر رستم زال او را بیرون کرده پنجاب و ملتان و سند را ضمیمه ٔ ولایت سیستان نمود...». (فرهنگ انجمن آرا) (آنندراج ) <span class=\"hlight\">:</span> <br />چه ده، دهی که بد و نیک وقف بود بدو<br />به زنگبار و به هند و پسند و چالندر.<br /> <font color=\"Red\">عنصری (از فرهنگ اسدی ).</font><br />یکشب از دهگان بچالندر کشیدی لشکری <br />چون زمانه زورمند و چون قضا کینه گذار.<br /> <font color=\"Red\">مسعودسعد.</font><br />بوم چالندر است مرتع من <br />مار و رنگم در این نقاب و ثغور.<br /> <font color=\"Red\">مسعودسعد (دیوان ص <span class=\"hlight\" dir=\"rtl\">٢٦٨</span>).</font><br />چو بنگریم همیدون پس از قضای خدا<br />بلای ما همه «قزدار» بود و چالندر.<br /><font color=\"Red\">مسعودسعد.</font><br /></font></div>'),
(282573, 'چاله', '<span class=\"hlight\">چاله .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) دهی است جزء دهستان کوهپایه بخش آبیک شهرستان قزوین که در <span class=\"hlight\" dir=\"rtl\">٤٨</span> هزارگزی شمال باختر آبیک و <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی حصار خروان واقع شده و <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد. هوایش معتدل و آبش ازچشمه سار و محصولش غلات و بنشن و گردو و آلوچه میباشد. شغل اهالی زراعت و کرباس بافی است و تنی چند از مردان برای کار به تهران و <span class=\"hlight\" dir=\"rtl\">٢٠</span> خانوار به تنکابن میروند.راهش مالرو است . (از فرهنگ جعرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282574, 'چاله', '<span class=\"hlight\">چاله .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ )صاحب مرآت البلدان می نویسد: «از مزارع قدیم النسق کاشان است که گرمسیری است و محصولش تنباکو و خربوزه وجوزق و غلات میباشد». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٨٤</span>).<br /></font></div>'),
(282575, 'چاله', '<span class=\"hlight\">چاله .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) دهی است از دهستان سرمشک بخش ساردوئیه شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">٤٥</span> هزارگزی شمال باختر ساردوئیه و <span class=\"hlight\" dir=\"rtl\">١٤</span> هزارگزی شمال راه مالرو بافت به جیرفت واقع شده، کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آبش از قنات و محصولش غلات و حبوبات و تریاک میباشد. شغل اهالی زراعت وگله داری و راهش مالرو است و ساکنین این محل از طایقه سلیمانی هستند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282576, 'چاله', '<span class=\"hlight\">چاله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) چال . چالو. بمعنی چالو باشد که گودال است . (برهان )(آنندراج ). چال کوچک . فرورفتگی و گودی . (ناظم الاطباء). چاه کوچک . چاهک . حفره . مغاک . کریش . کریشک . گو.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br />در اصطلاح عامه گویند:<br /> <span class=\"hlight\">از چاله درآمد و بچاه افتاد</span> ؛ در مورد کسی که از بدی رهایی یافت و به بدتری دچار شد.<br /> <span class=\"hlight\">پیش رو خاله پشت سر چاله </span> ؛ درباره ٔ کسی که پیش رو دم از دوستی میزند و پشت سر خصومت و دشمنی میکند.<br /> <span class=\"hlight\">پای خر یکبار بچاله میرود</span> ؛ در مورد آنکه شخص چون از کاری زیان بیند و صدمت و خسارت برد نباید که بار دیگر به همان کار اقدام کند و دوباره خود را در زحمت و مرارت افکند.<br /> <BR><font color=\"Blue\">◄</font> ظاهراً موقع برداشت حاصل را نیز گویند. خرمنگاه . وقت برداشت خرمن <span class=\"hlight\">:</span> <br />بزرگوارا دانی که بنده را هر سال <br />بُده ست بر کرم تو مبرتی موسوم <br />ز چاله پنج مه اندر گذشت و جرم من است <br />که قصه رفع نکردم چو کهتران خذوم .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>'),
(282577, 'چاله باغ', '<span class=\"hlight\">چاله باغ .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) ده کوچکی است از بخش حومه ٔ شهرستان ساوه که دارای <span class=\"hlight\" dir=\"rtl\">١٠</span> تن سکنه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282578, 'چاله باقر', '<span class=\"hlight\">چاله باقر.</span> <font color=\"DarkGreen\"><b>[ ل َ ق ِ ]</font></b> (اِخ ) صاحب مرآت البلدان می نویسد: «از مزارع قریه ٔ بزرگ کاشان است که تیول منشی الممالک میباشد». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٨٥</span>).<br /></font></div>'),
(282579, 'چاله بهاره', '<span class=\"hlight\">چاله بهاره .</span> <font color=\"DarkGreen\"><b>[ ل َ ب َ رَ ]</font></b>(اِخ ) ده مخروبه ای است از دهستان موگونی بخش آخوره ٔشهرستان فریدن . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282580, 'چاله حوض', '<span class=\"hlight\">چاله حوض .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ح َ <span class=\"hlight\" dir=\"rtl\">/</span> حُو ]</font></b> (اِمرکب ) چال حوض . حوض های بزرگ با آب سرد در حمام برای شناوری . خزانه ای از آب سرد در حمام مخصوص چاله حوض بازها. حوض بزرگی در حمام های خزینه ای پر از آب سرد که شناگران و چاله حوض بازان در آنجا شنا کنند. دریاچه . و رجوع به چال حوض شود.<br /></font></div>'),
(282581, 'چاله حوض باز', '<span class=\"hlight\">چاله حوض باز.</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ح َ <span class=\"hlight\" dir=\"rtl\">/</span> حُو ]</font></b> (نف مرکب ) کسی که در چاله حوض شنا میکند. آنکه شنا کردن میداند و میتواند در چاله حوض شناوری نماید. شناگر ماهر. آنکه در آب بازی و شناگری مهارت دارد.<br /></font></div>'),
(282582, 'چاله حوض بازی', '<span class=\"hlight\">چاله حوض بازی .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ح َ <span class=\"hlight\" dir=\"rtl\">/</span> حُو ]</font></b> (حامص مرکب ) شناگری در چاله حوض . شنا کردن در حوض های بزرگ و خزینه های مخصوص اینکار. درون چاله حوض رفتن و شناکردن و عملیات مخصوص شناگران ماهر را انجام دادن .<br /></font></div>'),
(282583, 'چاله خلیل', '<span class=\"hlight\">چاله خلیل .</span> <font color=\"DarkGreen\"><b>[ ل َ خ َ ]</font></b> (اِخ ) ده مخروبه ای است از دهستان موگونی بخش آخوره شهرستان فریدن . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282584, 'چاله خور', '<span class=\"hlight\">چاله خور.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) ده کوچکی است از دهستان خنج بخش مرکزی شهرستان لار که در <span class=\"hlight\" dir=\"rtl\">١٤٦</span> هزارگزی شمال باختر لار در دماغه ٔ کوه فلات دنک واقع شده و <span class=\"hlight\" dir=\"rtl\">١٧</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282585, 'چاله خوس', '<span class=\"hlight\">چاله خوس .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (نف مرکب ) در لهجه طبری، کسی را گویند که در چاله خسبد. چاله خسب . <BR><font color=\"Blue\">◄</font> (اِ) طرقه . ترقه . پرنده ای معروف . مرغی سیاهرنگ .<br /></font></div>'),
(282586, 'چاله دشت', '<span class=\"hlight\">چاله دشت .</span> <font color=\"DarkGreen\"><b>[ ل َ دَ ]</font></b> (اِخ ) دهی است جزء دهستان مرکزی بخش لنگرود شهرستان لاهیجان که در <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی جنوب لنگرود واقع شده، کوهستانی، معتدل مرطوب و مالاریائی است . <span class=\"hlight\" dir=\"rtl\">١٠٩</span>تن سکنه دارد. آبش از رودخانه ٔ لیل و محصولش لبنیات و عسل است . شغل اهالی زراعت گله داری و شالبافی و راهش مالرو میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282587, 'چاله زمین', '<span class=\"hlight\">چاله زمین .</span> <font color=\"DarkGreen\"><b>[ ل َزَ ]</font></b> (اِخ ) دهی است از دهستان علی آباد بخش مرکزی شهرستان شاهی که در <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی خاور شهر شاهی واقع شده .آبش از رودخانه سیاهرود و از چاه و محصولش برنج و غلات است . شغل اهالی زراعت و کارگری در کارخانه ها و راهش مالرو میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282588, 'چاله سرا', '<span class=\"hlight\">چاله سرا.</span> <font color=\"DarkGreen\"><b>[ ل َ س َ ]</font></b> (اِخ ) دهی است جزء دهستان شاندرمن بخش ماسال شاندرمن شهرستان طوالش که در <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی شمال باختری بازار شاندرمن و <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی شمال باختر ماسال واقع شده، جلگه، معتدل مرطوب و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١١٠٠</span> تن سکنه دارد. آبش از رودخانه ٔ شاندرمن و محصولش برنج، لبنیات و ابریشم است . شغل اهالی زراعت و گله داری و راهش مالرو میباشد و محل ییلاق سکنه اینجا دره رودخانه آلکام است . طوایف «چپه زاد» و «خساره زاد» و «شکاری » در ییلاق به چاله سرا نزدیک بوده و زمستان در محل قشلاقی چاله سرا و اطراف این آبادی مسکن میگیرند ومختصر زراعتی در این محل مینمایند و اداره ٔ آمار اشتباهاً نام این طوایف را اسم آبادی پنداشته و جزء آبادیها نوشته است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282589, 'چاله سیاه', '<span class=\"hlight\">چاله سیاه .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) دهی از دهستان برخوار بخش حومه ٔ شهرستان اصفهان که در <span class=\"hlight\" dir=\"rtl\">٣٥</span> هزارگزی شمال باختر اصفهان و <span class=\"hlight\" dir=\"rtl\">١٤</span> هزارگزی شوسه اصفهان به تهران واقع شده . جلگه ای است معتدل که <span class=\"hlight\" dir=\"rtl\">٦١٦</span> تن سکنه دارد. آبش از قنات و محصولش غلات و پنبه و صیفی و پشم و روغن است . شغل اهالی زراعت و گله داری وصنایع دستی زنان کرباس بافی میباشد. راهش ماشین رو است و کاروانسرای شاه عباسی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>). و رجوع بمرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٨٥</span> شود.<br /></font></div>'),
(282590, 'چاله غازان', '<span class=\"hlight\">چاله غازان .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) دهی است جزء دهستان بهنام وسط بخش ورامین شهرستان تهران که در <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی جنوب باختر ورامین و یک هزارگزی کبیرآباد واقع شده . آبش از قنات و محصولش غلات و صیفی است و <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه دارد که بشغل زراعت مشغولند. جلگه و معتدل است و راهش مالرو میباشد و از طریق کبیرآبادماشین هم میرود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282591, 'چاله قره', '<span class=\"hlight\">چاله قره .</span> <font color=\"DarkGreen\"><b>[ ل َ ق َ رَ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش مرکزی شهرستان کاشان که در <span class=\"hlight\" dir=\"rtl\">٣٦</span> هزارگزی جنوب خاوری کاشان کنار راه شوسه کاشان به نطنز واقع شده . دامنه و معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٦٠</span> تن سکنه دارد. آبش از قنات و محصولش غلات و پنبه و تنباکو و صیفی است . شغل اهالی زراعت و خارکشی و صنایع دستی زنان قالی بافی میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(282592, 'چاله مجار', '<span class=\"hlight\">چاله مجار.</span> <font color=\"DarkGreen\"><b>[ ل َ م َ ]</font></b> (اِخ ) صاحب مرآت البلدان نویسد: «مزرعه ای است از مزارع صاین قلعه که ایلات شاهسون قورت بیکلو در اینجا ییلاق مینمایند...». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٨٥</span>).<br /></font></div>'),
(282593, 'چاله مورد', '<span class=\"hlight\">چاله مورد.</span> <font color=\"DarkGreen\"><b>[ ل َ م ُ ]</font></b> (اِخ ) دهی جزء دهستان بهنام بخش ورامین شهرستان تهران که در <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی خاور ورامین متصل به راه ورامین به جلیل آباد واقعشده . جلگه ای است معتدل که <span class=\"hlight\" dir=\"rtl\">٥٥</span> تن سکنه دارد. آبش از قنات و محصولش غلات و صیفی و چغندر قند میباشد. شغل اهالی زراعت و راهش مالرو است و از راه جلیل آباد ماشین هم میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282594, 'چاله میدان', '<span class=\"hlight\">چاله میدان .</span> <font color=\"DarkGreen\"><b>[ ل َ م ِ ]</font></b> (اِخ ) نام محله ای در تهران . نام برزنی در تهران . و رجوع به چالمیدان شود.<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(282595, 'چاله هرز', '<span class=\"hlight\">چاله هرز.</span> <font color=\"DarkGreen\"><b>[ ل َ هََ ]</font></b> (اِخ ) دهی است جزء بخش شمیران شهرستان تهران که در <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی جنوب تجریش کنار راه شوسه تهران به تجریش واقع شده . دامنه و سردسیراست و <span class=\"hlight\" dir=\"rtl\">٨٠</span> تن سکنه دارد. آبش از قنات و از رودخانه دربند و محصولش غلات بنشن و صیفی است . شغل اهالی زراعت و باغبانی و راهش ماشین رو است و چند مزرعه و باغچه جدید الاحداث در اراضی این ده واقع شده و قنات کوچکی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>). و صاحب مرآت البلدان ذیل نام چال میدان نویسد: «... از دهات بلوک شمیران تهران است که در طرف غربی ضرابخانه دولتی واقع شده هوایش گرم و آبش کم و دارای چهار خانوار رعیت است و باغی هم دارد». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٨٥</span>).<br /></font></div>'),
(282596, 'چاله چاله', '<span class=\"hlight\">چاله چاله .</span> <font color=\"DarkGreen\"><b>[ ل َ ل َ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش مرکزی شهرستان کرمانشاه که در <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی شمال کرمانشاه و یک هزارگزی باختر شوسه ٔ کرمانشاه بطاق بستان واقع شده . دشتی سردسیر است و <span class=\"hlight\" dir=\"rtl\">٢٤٥</span>تن سکنه دارد. آبش از چاه و از فاضل آب شوران و محصولش غلات و حبوبات و صیفی و چغندر قند میباشد. شغل اهالی زراعت است و چند تن از مردان کارگر تصفیه خانه ٔ نفت کرمانشاهند. راه فرعی دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>). و رجوع به مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٨٥</span> شود.<br /></font></div>'),
(282597, 'چاله چاله', '<span class=\"hlight\">چاله چاله .</span><font color=\"DarkGreen\"><b>[ ل َ ل َ ]</font></b> (اِخ ) دهی است از دهستان کولیوند بخش سلسله ٔ شهرستان خرم آباد که در <span class=\"hlight\" dir=\"rtl\">٣٧</span> هزارگزی باختر الشتر و<span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی باختر راه شوسه ٔ خرم آباد به کرمانشاه واقع شده . تپه ماهور و سردسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد. آبش از چشمه ها و محصولش غلات و تریاک و حبوبات و لبنیات است . شغل اهالی زراعت و گله داری است وراهش مالرو میباشد. عده ای از ساکنین این محل از طایفه کولیوند هستند. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282598, 'چاله چوله', '<span class=\"hlight\">چاله چوله .</span> <font color=\"DarkGreen\"><b>[ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ مرکب، از اتباع ) جوی و جر. گودال پودال . جائی که گودالها و فرورفتگی های بسیار دارد. زمین ناهموار و پرنشیب و فراز.<br /></font></div>'),
(282599, 'چاله کلاغ', '<span class=\"hlight\">چاله کلاغ .</span> <font color=\"DarkGreen\"><b>[ ل َ ک َ ]</font></b> (اِخ ) ده کوچکی است از دهستان طیبی سرحدی بخش کهکیلویه شهرستان بهبهان که در <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی شمال خاوری قلعه ٔ رئیسی واقع شده و <span class=\"hlight\" dir=\"rtl\">٣٥</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282600, 'چاله کند', '<span class=\"hlight\">چاله کند.</span> <font color=\"DarkGreen\"><b>[ ل َ ک َ ]</font></b> (اِخ ) دهی است از دهستان خدابنده لو بخش قروه شهرستان سنندج که در <span class=\"hlight\" dir=\"rtl\">١١</span> هزارگزی شمال خاور گل تپه و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی شمال خاور سراب واقع شده . کوهستانی وسردسیر است و <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن سکنه ترک دارد. آبش از چشمه ها و محصولش غلات، حبوبات و کمی انگور است . شغل اهالی زراعت و گله داری و راهش مالرو میباشد و از سراب اتومبیل هم میتوان برد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282601, 'چاله گنبد', '<span class=\"hlight\">چاله گنبد.</span> <font color=\"DarkGreen\"><b>[ ل َ گُم ب َ ]</font></b> (اِخ ) دهی است جزء دهستان قهستان بخش کهک شهرستان قم که در <span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی باختر کهک و <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی خاور راه شوسه قم به اصفهان واقع شده . هوایش معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه دارد که از طایفه زندی لک هستند. آبش از قنات و محصولش غلات و لبنیات و شغل اهالی زراعت، گله داری و شترداری است .راهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282602, 'چالو', '<span class=\"hlight\">چالو.</span> (اِخ ) دهی است از دهستان هزارجریب بخش چهاردانگه ٔ شهرستان ساری که در <span class=\"hlight\" dir=\"rtl\">٤٨</span>هزارگزی شمال خاوری کیاسر واقع شده . جنگل و کوهستانی است و هوایش معتدل و مرطوب و دارای <span class=\"hlight\" dir=\"rtl\">١٢٠</span> تن سکنه میباشد. آبش از چشمه و محصولش غلات و ارزن است . شغل اهالی زراعت و صنایع دستی زنان، بافتن شال و کرباس و راهش مالرو میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(282603, 'چالو', '<span class=\"hlight\">چالو.</span> (اِخ ) دهی است از دهستان مهربان بخش کبودرآهنگ شهرستان همدان که در <span class=\"hlight\" dir=\"rtl\">٥٤</span> هزارگزی شمال باختری قصبه کبودرآهنگ و <span class=\"hlight\" dir=\"rtl\">١٢</span>هزارگزی باختر راه قدیم کاروانی همدان بزنجان واقع شده . تپه ماهور و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٨٠٠</span> تن سکنه دارد. آبش از قنات و چشمه ها و محصولش غلات لبنیات، انگور، میوه جات و صیفی است شغل اهالی زراعت و گله داری و صنایع دستی زنان قالی بافی میباشد. راهش مالرو است و در تابستان از کبودرآهنگ اتومبیل میتوان برد. در بالای دره کوه مجاور این آبادی آثار خرابه قلعه ای مشهور به «قزقلعه » وجود دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282604, 'چالو', '<span class=\"hlight\">چالو.</span> (اِخ ) دهی از دهستان پشتکوه سورتیجی بخش چهار دانگه ٔ شهرستان ساری که در <span class=\"hlight\" dir=\"rtl\">١٣</span> هزارگزی خاور کیاسر واقع شده، کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٣٦٠</span> تن سکنه دارد. آبش از رودخانه چرگت و چشمه و محصولش غلات و برنج است . شغل اهالی زراعت و گله داری میباشد وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(282605, 'چالو', '<span class=\"hlight\">چالو.</span> (اِ) گوی را گویند که زیاده از دو سه گز عمق نداشته باشد. (برهان ) (آنندراج ). گودالی که یک دو گز بیشتر گودی آن نباشد. (ناظم الاطباء). مصغر چال، یعنی چال کوچک . (ناظم الاطباء). و رجوع به چال و چاله شود.<br /></font></div>'),
(282606, 'چالوس', '<span class=\"hlight\">چالوس .</span> (اِخ ) نام آبادی یا بندری در کنار دریای خزر که اسم آن در کتب جغرافی و فرهنگ های قدیم ضبط شده و بتدریج رو به ویرانی نهاده و در زمان سلطنت رضاشاه دوباره آباد شده و فعلاً مرکز بخش «چالوس » میباشد و بر کنار رودخانه ای بنام «چالوس » واقع است . یاقوت نام این آبادی را ذیل کلمه «شالوس » (که معرب چالوس است ) ضبط کرده و نوشته است :«شهری است که در جبال طبرستان واقع شده و یکی از مرزهای طبرستان است ... و بین شالوس و آمل از ناحیه جبال دیلمیه بیست فرسخ فاصله است ». (از معجم البلدان ج <span class=\"hlight\" dir=\"rtl\">٦</span> ص <span class=\"hlight\" dir=\"rtl\">٢١٦</span>). صاحب مرآت البلدان می نویسد: «... بعضی از علمای جغرافی چالوس را از آبادی های معتبر طبرستان دانسته اند زیرا معتصم خلیفه محمدبن اویس را که از امرابود به حکومت طبرستان نامزد کرد و مشارالیه خود در رویان قرار گرفت و چالوس را به احمد پسر خود سپرد» وبعد می نویسد: «چالوس حالا اسم شهر و آبادی مخصوصی نیست بلکه اسم رودخانه ٔ بزرگی است ... و دره ای که مجرا و بستر این رودخانه میباشد نیز چالوس نامیده میشود...» سپس شرحی درباره ٔ دره ٔ چالوس نگاشته و آنگاه می نویسد: «... و در این زمان آبادی بسیار مختصری نزدیک بدریا هست که موسوم به چالوس است ...» و آنگاه زیر عنوان «ذکر وقایع متعلقه به چالوس » شرح مبسوطی راجع به وقایعی که در چالوس روی داده نگاشته است . نام شهر کوچک و نوسازی است که مرکز بخش چالوس میباشد و بر سر سه راهی تهران گیلان و مازندران در <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی ساحل دریای خزر و کنار رودخانه ٔ چالوس واقع شده است . این آبادی قبل از سال <span class=\"hlight\" dir=\"rtl\">١٣١٠</span> هَ . ش . ده کوچکی بیش نبود و از آن تاریخ ببعد با اسلوبی صحیح بنا گردید. احداث راه شوسه ٔ چالوس به کرج که نزدیک ترین راه تهران بساحل دریای خزر است و ایجاد کارخانه ٔ حریربافی که در حدود <span class=\"hlight\" dir=\"rtl\">١٥٠٠</span> تن کارگر دارد در وضع اقتصادی این محل تأثیر فراوان داشت . در این آبادی مهمانخانه ها و پلاژها و ویلاهای متعدد تأسیس گردیده و پل مهمی که روی رودخانه ٔ چالوس بنا شده است از جمله ساختمانهای زیبای این شهر است . راه کناره از وسط این شهر میگذرد و جمعیت آن درحدود ده هزار تن میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>). نام شهری که مرکز بخشی از شهرستان نوشهر مازندران است و بر کنار رودی به همین نام در منطقه ای جنگلی در <span class=\"hlight\" dir=\"rtl\">٣٦</span> درجه و <span class=\"hlight\" dir=\"rtl\">١</span> دقیقه عرض جغرافیایی و <span class=\"hlight\" dir=\"rtl\">٧</span> متر ارتفاع از سطح دریا واقع شده دارای بزرگترین کارخانه ٔ حریربافی ایران و ییلاقهای زیبایی از قبیل کلاردشت میباشد. این شهر بوسیله ٔ راه شوسه ای که از تونل مصنوعی کندوان میگذرد به تهران مربوط میگردد. (از فرهنگ امیرکبیر). و رجوع به مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> صص <span class=\"hlight\" dir=\"rtl\">٧٩</span> - <span class=\"hlight\" dir=\"rtl\">٨٥</span> شود.<br /></font></div>'),
(282607, 'چالوس', '<span class=\"hlight\">چالوس .</span> (اِخ ) نام رودخانه ای که بطول <span class=\"hlight\" dir=\"rtl\">٨٠</span> هزارگز در مازندران جاری است و به دریای خزر میریزد. صاحب مرآت البلدان نویسد: «... چالوس حالا اسم شهر و آبادی مخصوصی نیست بلکه اسم رودخانه ٔ بزرگی است که فاصله ٔ مابین بلوک مرزن آباد کجور و کلارستاق میباشد. منبع این رودخانه از نقاط مختلفه است و سرچشمه ٔ عمده ٔ آن از طالقان و کندوان و دونا و ناتل میباشد، به این معنی که رودخانه ای که از طرف دونا جریان دارد در زیر گردنه ای موسوم به هزارچم به رودخانه ای که از سمت طالقان جاری است داخل میشود و در این موضع که دو رودخانه بهم وصل میشود موسوم به چالوس میگردد و تا انتهای سیر آن که <span class=\"hlight\" dir=\"rtl\">١٢</span> فرسخ است و بدریای خزرمی ریزد همین اسم را دارد...». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span>ص <span class=\"hlight\" dir=\"rtl\">٧٩</span> و <span class=\"hlight\" dir=\"rtl\">٨٠</span>). رودخانه بزرگی مابین مرزن آباد کجور و کلارستاق و منبع آن از طالقان و کندوان و دونا و جز آن که بدریای آبسکون منتهی میشود. (از ناظم الاطباء).<br /></font></div>'),
(282608, 'چالوس', '<span class=\"hlight\">چالوس .</span> (اِخ ) یکی از بخش های شهرستان نوشهر است و حدود بخش از شمال بدریای خزر، از جنوب به اولین رشته ارتفاعات جنگلی، از خاور بدهستان کران بخش حومه ٔ نوشهر و از باختر به دهستان لنگااز شهرستان تنکابن محدود میباشد. هوای این بخش مانند سایر نقاط ساحلی معتدل و مرطوب بوده در تابستان گرم و بواسطه ٔ ازدیاد پشه ناسالم است و اکثر سکنه تابستان را به دهستانهای کلاردشت، بیرون بشم و کوهستان که هوای آنجا سردسیر است میروند. قسمت های شمال خاور و باختر دشت تا ساحل دریا اراضی زراعتی است و قسمت جنوبی کوهستانی و پوشیده از جنگل انبوه و به میان بند مشهور میباشد. از جنگل های اینجا زغال و چوب بسیار به تهران حمل میشود. مرکز این بخش شهر چالوس و قراء تابعه آن <span class=\"hlight\" dir=\"rtl\">٣٦</span> آبادی بزرگ و کوچک است که عموماً در قسمت باختری رودخانه ٔ چالوس واقع و به دهستان قشلاق کلارستاق مشهورند. جمعیت این بخش با سکنه شهر <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارنفر است .قراء این بخش از رودخانه های چالوس و سرداب رود مشروب میشوند و محصول عمده اش برنج و لبنیات و مرکبات و مختصر ابریشم است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(282609, 'چالوسیه', '<span class=\"hlight\">چالوسیه .</span> <font color=\"DarkGreen\"><b>[ سی ی َ ]</font></b> (اِخ ) صاحب مرآت البلدان نویسد: «نام محلی است در عراق عرب که در چهار فرسخی خان نجّار در سمت راست آثار مخروبه ای از قلعه و باره و عمارت این محل بنظر میرسد. این ابنیه از بناهای خلیفه هرون الرشید است ودر نزدیکی خرابه های این قلعه بر روی شط آثار پل قدیمی پیداست و این قبیل آثار که غالباً از عهد بنی عباس مانده بفاصله های مختلف چالوسیه (یا چالسیه ) را به سامره متصل مینماید». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٨٤</span>).<br /></font></div>'),
(282610, 'چالوپل', '<span class=\"hlight\">چالوپل .</span> <font color=\"DarkGreen\"><b>[ پ ُ ]</font></b> (اِخ ) دهی از دهستان قره طقان بخش بهشهر شهرستان ساری که در <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی خاورنکا، کنار راه شوسه نِکا به بهشهر واقع شده . دامنه ای است معتدل مرطوب و مالاریائی که <span class=\"hlight\" dir=\"rtl\">١٩٠</span> تن سکنه دارد. آبش از رودخانه نکا و محصولش برنج، غلات، پنبه و صیفی است و شغل اهالی زراعت میباشد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(282611, 'چالپاپاخ', '<span class=\"hlight\">چالپاپاخ .</span> (اِخ ) قهرمان بازی و قصه ای ترکی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br />(مثل ترکی )<br /> <span class=\"hlight\">چالپاپاخ منی نینم من </span> .<br /></font></div>'),
(282612, 'چالپوس', '<span class=\"hlight\">چالپوس .</span> (ص )مقلوب چاپلوس . (برهان ) (جهانگیری ) (انجمن آرا) (آنندراج ). فریب دهنده . (برهان ). و رجوع به چاپلوس شود.<br /></font></div>'),
(282613, 'چالچوق', '<span class=\"hlight\">چالچوق .</span> (اِخ ) دهی است از دهستان ابهررود بخش ابهر شهرستان زنجان که در <span class=\"hlight\" dir=\"rtl\">١١</span> هزارگزی جنوب باختری ابهر و <span class=\"hlight\" dir=\"rtl\">٢٥</span>هزارگزی راه مالرو عمومی واقع شده . کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٣٩٤</span> تن سکنه دارد. آبش از چشمه علی بلاغی و رودخانه ٔ چشین و محصولش غلات، انگور و قلمستان است . شغل اهالی زراعت و صنایع دستی قالیچه جاجیم و پلاس بافی میباشد وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282614, 'چالک ده', '<span class=\"hlight\">چالک ده .</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) دهی است از دهستان یخکش، بخش بهشهر شهرستان ساری که در <span class=\"hlight\" dir=\"rtl\">٢١٠</span> هزارگزی جنوب خاوری بهشهر واقع شده . کوهستانی و دارای جنگل است و هوایش معتدل و مرطوب و مالاریایی میباشد. <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آبش از چشمه و رودخانه محلی است محصولش برنج، غلات و ارزن است . شغل اهالی زراعت و صنایع دستی زنان شالبافی و کرباس بافی میباشد وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(282615, 'چالکان', '<span class=\"hlight\">چالکان .</span> (اِخ ) مؤلف مرآت البلدان نویسد: «از قراء و توابع طارم خمسه است که قدیم النسق میباشد و مالکین متعدد دارد... سکنه اش هشتاد خانوارند و زراعت عمده اش دیمی و کمی هم آبی است . رودخانه ای از زیر دست قلعه میگذرد که منتهی بقزل اوزن میشود و این محل در تابستان ییلاق ایل قشقایی است . (از مرآت البلدان ج ص <span class=\"hlight\" dir=\"rtl\">٧٨</span>).<br /></font></div>'),
(282616, 'چالکرود', '<span class=\"hlight\">چالکرود.</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) دهی است از دهستان گلیجان شهرستان شهسوار که در <span class=\"hlight\" dir=\"rtl\">١١</span> هزارگزی شمال باختر شهسوار کنار شوسه شهسوار برامسر واقع شده . زمینش دشت و هوایش معتدل، مرطوب و مالاریایی است . <span class=\"hlight\" dir=\"rtl\">١٦٠</span> تن سکنه دارد. آبش از رودخانه چالکرود و محصولش برنج و مرکبات است . شغل اهالی زراعت میباشد و چند باب دکان در کنار راه شوسه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(282617, 'چالکسر', '<span class=\"hlight\">چالکسر.</span> <font color=\"DarkGreen\"><b>[ ل َ س َ ]</font></b> (اِخ ) دهی جزء دهستان مرکزی بخش صومعه سرا شهرستان فومن که در <span class=\"hlight\" dir=\"rtl\">١٤٠٠٠</span> گزی باختر صومعه سرا واقع شده . دامنه و مرطوب است . <span class=\"hlight\" dir=\"rtl\">٢٣٣</span> تن سکنه دارد. آبش از نهر ملک رود و محصولش برنج و توتون و سیگار و ابریشم و چای میباشد. شغل اهالی زراعت و مکاری وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282618, 'چالکسرا', '<span class=\"hlight\">چالکسرا.</span> <font color=\"DarkGreen\"><b>[ ل َ س َ ]</font></b>(اِخ ) دهی است جزء دهستان سیاهکل بخش سیاهکل دیلمان شهرستان لاهیجان که در شمال سیاهکل واقع شده . جلگه ومرطوب است و <span class=\"hlight\" dir=\"rtl\">١٥٨</span> تن سکنه دارد. آبش از استخر بوسیله شمرود و محصولش برنج، چای و ابریشم و شغل اهالی زراعت و کسب میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282619, 'چالکسرا', '<span class=\"hlight\">چالکسرا.</span> <font color=\"DarkGreen\"><b>[ ل َ س َ ]</font></b> (اِخ ) دهی است جزء دهستان رحیم آباد بخش رودسر شهرستان لاهیجان که در <span class=\"hlight\" dir=\"rtl\">١١٠٠٠</span> گزی جنوب رودسر و <span class=\"hlight\" dir=\"rtl\">٢٥٠٠</span> گزی باختر رحیم آباد واقع شده . جلگه و مرطوب است و <span class=\"hlight\" dir=\"rtl\">٩٣</span> تن سکنه دارد. آبش از نهر ملپرود و محصولش برنج و شغل اهالی زراعت میباشد راهش مالرو است و زیارتگاه قدیمی دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282620, 'چالکش', '<span class=\"hlight\">چالکش .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) دهی جزءدهستان حومه ٔ بخش لشت نشاء شهرستان رشت که در <span class=\"hlight\" dir=\"rtl\">٢٠٠٠</span> گزی شمال لشت نشاء واقع شده جلگه ای است مرطوب و مالاریائی، <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد. آبش از نورود و توشاجوی سفیدرود و محصولش برنج و صیفی و شغل اهالی زراعت میباشد وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282621, 'چالکه', '<span class=\"hlight\">چالکه .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) موضعی نزدیک پاطاق نزدیک کرمانشاه . مؤلف مرآت البلدان نویسد: «از منزل «پاطاق » که بعقیده ٔ بعضی «عقبه ٔ حلوان » همان است، چون مسافر به طرف عراق عرب رود یکی از دهات دست راست، نزدیک به «پاطاق » همین چالکه است ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٨</span>).<br /></font></div>'),
(282622, 'چالکی', '<span class=\"hlight\">چالکی .</span> (اِخ ) دهی است از بخش ایزه شهرستان اهواز که در <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارگزی باختر ایزه واقع شده . جلگه ای است گرمسیر و <span class=\"hlight\" dir=\"rtl\">١١٧</span> تن سکنه دارد. آبش از چاه و قنات و محصولش غلات و تریاک و حبوبات است و شغل اهالی زراعت و گله داری میباشد. صنایع دستی زنان کرباس بافی وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282623, 'چالکی', '<span class=\"hlight\">چالکی .</span> (اِخ ) دهی است از دهستان سدن رستاق بخش مرکزی شهرستان گرگان که در <span class=\"hlight\" dir=\"rtl\">١١</span> هزارگزی باختر گرگان واقع شده .دشتی است معتدل و مرطوب و مالاریائی که <span class=\"hlight\" dir=\"rtl\">٢١٥</span> تن سکنه دارد. آبش از قنات و محصولش برنج، غلات، لبنیات و توتون سیگار میباشد. شغل اهالی زراعت و گله داری است و صنایع دستی زنان بافتن پارچه های نخی و کرباس است و راهش مالرو میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(282624, 'چالکی', '<span class=\"hlight\">چالکی .</span> (اِخ ) دهی است از دهستان مزرج بخش حومه ٔ شهرستان قوچان که در <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی شمال خاور قوچان و <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی خاور شوسه ٔ عمومی قوچان به باجگیران واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">٣٤٥</span> تن سکنه مخلوط از ترک و کرد و فارس دارد. آبش از رود اترک و محصولش غلات، تریاک و میوجات است . شغل اهالی زراعت میباشد و راهی فرعی به جاده شوسه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>). و مؤلف مرآت البلدان ذیل «چالکی » نویسد: «... و از قراری که در سفرنامه ٔ خراسان همایونی مسطور است «چالکی » یکی از قرای آباد مابین منزل علی آباد و قوچان است که در جانب یمین جاده در جلگه ٔ آباد خوش آب و هوای حاصلخیزی واقع است ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٨</span>) و ظاهراً این چالکی با آنکه در فرهنگ جغرافیائی آمده یکی است .<br /></font></div>'),
(282625, 'چالکی', '<span class=\"hlight\">چالکی .</span> (اِخ ) مؤلف مرآت البلدان نویسد: «قریه ای است اربابی از قرای استرآباد که اراضیش از آب دو رشته قنات مشروب میشود و نیز از رود بارسدن که مشهور به رودخانه ٔ شصت کلاته است قریب یک سنگ آب سهم دارد و جمعیتش <span class=\"hlight\" dir=\"rtl\">١٨٢</span> تن میباشد». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">٧٨</span>).<br /></font></div>'),
(282626, 'چالکیاسر', '<span class=\"hlight\">چالکیاسر.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) دهی است جزء دهستان مرکزی بخش لنگرود شهرستان لاهیجان که در یک هزارگزی خاور لنگرود در شمال جاده ٔ شوسه، متصل به لنگرود واقع شده . جلگه ای است معتدل و مرطوب که <span class=\"hlight\" dir=\"rtl\">١٥٧</span> تن سکنه دارد. آبش از استخر کیاکلایه و محصولش برنج، ابریشم، صیفی و کنف میباشد. شغل اهالی زراعت و راهش شوسه است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282627, 'چالگاه', '<span class=\"hlight\">چالگاه .</span> (اِخ ) دهی از دهستان تیکوه بخش دیواندره ٔ شهرستان سنندج که در <span class=\"hlight\" dir=\"rtl\">٤٢</span> هزارگزی شمال باختر دیواندره و یک هزارگزی شمال شوسه دیواندره به سقز واقع شده . کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٨٤</span> تن سکنه دارد. آبش از چشمه و محصولش غلات و حبوبات و پشم میباشد. شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282628, 'چالگاه', '<span class=\"hlight\">چالگاه .</span> (اِخ ) نام محلی کنار راه تهران به شاهی میان زیر آب و چاکسر و در <span class=\"hlight\" dir=\"rtl\">٢٠٧٧٠٠</span> گزی تهران واقع شده است .<br /></font></div>'),
(282629, 'چالگر', '<span class=\"hlight\">چالگر.</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِخ ) دهی از دهستان خان اندیل بخش مرکزی شهرستان هروآباد که در یازده هزارگزی باختر هروآباد و <span class=\"hlight\" dir=\"rtl\">٦</span> هزار و پانصدگزی شوسه هروآباد به میانه واقع شده . کوهستانی و هوایش مایل به گرمی است و مالاریاخیز میباشد. <span class=\"hlight\" dir=\"rtl\">٣٤٤</span> تن سکنه دارد که بشغل زراعت و گله داری مشغولند و صنایع دستی آنها جاجیم بافی و گلیم بافی است . آبش از چشمه و محصولش غلات، حبوبات و سردرختی میباشد. این ده دارای معدن آب گرم است و بنام «جرلی » نیز نامیده میشود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(282630, 'چالگرد', '<span class=\"hlight\">چالگرد.</span> <font color=\"DarkGreen\"><b>[ گ ِ ]</font></b> (اِخ ) دهی است از دهستان بربرود بخش الیگودرز شهرستان بروجرد که در <span class=\"hlight\" dir=\"rtl\">١٠٠</span> هزارگزی جنوب باختری الیگودرز واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٣١</span> تن سکنه دارد. آبش از چشمه و قنات و محصولش غلات و تریاک و لبنیات است . شغل اهالی زراعت و گله داری و راهش مالرو میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282631, 'چالگروه', '<span class=\"hlight\">چالگروه .</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (اِخ ) ده کوچکی است از دهستان طیبی سرحدی بخش کهکیلویه شهرستان بهبهان که در <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی خاور قلعه رئیسی واقع شده و <span class=\"hlight\" dir=\"rtl\">٤٠</span> تن سکنه دارد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282632, 'چالگه', '<span class=\"hlight\">چالگه .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِخ ) دهی است از دهستان بربرود بخش الیگودرز شهرستان بروجرد. که در <span class=\"hlight\" dir=\"rtl\">١٦</span> هزارگزی خاور الیگودرز، کنار راه مالرو خاکوار به فرح آباد واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٢٨</span> تن سکنه دارد. آبش از چشمه و قنات و محصولش غلات و تریاک و لبنیات میباشد. شغل اهالی زراعت و گله داری وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282633, 'چالی', '<span class=\"hlight\">چالی .</span> (اِخ ) دهی است از دهستان گاودول بخش مرکزی شهرستان مراغه که در <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارگزی جنوب خاور مراغه و <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی جنوب خاور شوسه مراغه به میاندواب واقع شده، کوهستانی، معتدل و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١١١</span> تن سکنه ترک زبان دارد. آبش از قنوات و محصولش غلات، چغندر و حبوبات میباشد. شغل اهالی زراعت و صنایع دستی جاجیم بافی وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(282634, 'چالی', '<span class=\"hlight\">چالی .</span> (اِ) پرنده ای است بشکل گنجشک که از گنجشکهای معمولی درشت تر و فربه تر است . چولی . <BR><font color=\"Blue\">◄</font> به لهجه گیلکی اردک . (ناظم الاطباء).<br /></font></div>'),
(282635, 'چالی', '<span class=\"hlight\">چالی .</span> (اِ) گودی . گودال . فرورفتگی . عمق . ژرفا.<br /></font></div>'),
(282636, 'چالی', '<span class=\"hlight\">چالی .</span> (اِخ ) دهی از دهستان شیرگاه بخش سوادکوه شهرستان شاهی که در <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی شمال شیرگاه و کنارشوسه و راه آهن واقع شده، دامنه ای، معتدل، مرطوب و مالاریائی است <span class=\"hlight\" dir=\"rtl\">٤٥٠</span> تن سکنه دارد. آبش از رودخانه کسلیان و محصولش برنج، غلات و نیشکر است و شغل اهالی زراعت و گله داری است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(282637, 'چالی سور', '<span class=\"hlight\">چالی سور.</span> (اِخ ) دهی است ازدهستان سرشیوه بخش مریوان شهرستان سنندج که در <span class=\"hlight\" dir=\"rtl\">٣٤</span> هزارگزی شمال خاوری دژ شاهپور و <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی شمال خاوری ویله واقع شده، کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد. آبش از چشمه ها و محصولش غلات، توتون و لبنیات است . شغل اهالی زراعت و گله داری و راهش مالرو، و صعب العبور میباشد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282638, 'چالیان', '<span class=\"hlight\">چالیان .</span> (اِخ ) دهی است از دهستان سورمق بخش مرکزی شهرستان آباده که در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی جنوب خاور آباده و دو هزارگزی جنوب شوسه ٔسورمق به ابرقو واقع شده، جلگه ای و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٠٠</span>تن سکنه دارد. آبش از قنات و محصولش غلات، پنبه، انگور و بادام است و شغل اهالی زراعت و باغداری میباشد و راهش فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282639, 'چالیان', '<span class=\"hlight\">چالیان .</span>(اِخ ) دهی است از دهستان قطور بخش حومه ٔ شهرستان خوی که در <span class=\"hlight\" dir=\"rtl\">٤٠</span> هزارگزی جنوب باختر خوی و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی جنوب راه ارابه رو خوی به قطور واقع شده، دره ای، سردسیر وسالم است که محل سکنای ایل شکاک میباشد و <span class=\"hlight\" dir=\"rtl\">٤٠</span> تن سکنه کرد دارد. آبش از چشمه و محصولش غلات و شغل اهالی زراعت و گله داری و صنایع دستی آنان جاجیم بافی است . راهش مالرو میباشد. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(282640, 'چالیر', '<span class=\"hlight\">چالیر.</span> (اِ) گو عمیق مخوف . (آنندراج ). چاه . (ناظم الاطباء).<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">از چاه درآمدم و در چالیر بافتادم </span> . (از آنندراج ).<br /><BR><font color=\"Blue\">◄</font> گودی کم عمق . (ناظم الاطباء).<br /></font></div>'),
(282641, 'چالیش', '<span class=\"hlight\">چالیش .</span> (اِمص ) مزیدٌفیه لفظِ چالش . (فرهنگ نظام ). رفتاری باشد از روی تکبر و ناز. (برهان ) (آنندراج ). خرامیدن . (غیاث ). رفتار از روی عجب و ناز. (ناظم الاطباء). ناز و نخوت . تکبر و غرور <span class=\"hlight\">:</span> <br />این نظر با آن نظر چالیش کرد<br />ناگهانی از خرد خالیش کرد.<br /> <font color=\"Red\">مولوی .</font><br /> <BR><font color=\"Blue\">◄</font> چالش . سعی و کوشش در جنگ . جنگ و جدال . رزم و پیکار <span class=\"hlight\">:</span> <br />روز و شب در جنگ و اندر کشمکش <br />کرده چالیش اولش با آخرش .<br /> <font color=\"Red\">مولوی .</font><br />چون خیالی در دل شه یا سپاه <br />کرد در چالیش ایشان را تباه .<br /> <font color=\"Red\">مولوی .</font><br />گر نبودی نفس و شیطان و هوا<br />گر نبودی زخم و چالیش و وغا.<br /> <font color=\"Red\">مولوی .</font><br />جوشن و خود است مر چالیش را<br />وین حریر و برد، مر تعریش را.<br /> <font color=\"Red\">مولوی .</font><br />و رجوع به چالش شود.<br /></font></div>'),
(282642, 'چالیق', '<span class=\"hlight\">چالیق .</span> (اِخ ) نام شخصی از اهالی ترکیه که در زمان سلطان مصطفی خان ثانی حاکم یگیچری بود و با آن پادشاه در واقعه ٔ ناگوار «اوک ایاق » همکاری نمود و در زمان سلطان احمدخان ثالث جرأت یافت و از وی تقاضای شغل صدارت کرد لیکن بفاصله ٔ یک ماه کیفر جسارت خود دیده از حکومت یگیچری معزول و بعد اعدام شد. (از قاموس الاعلام ترکی ).<br /></font></div>'),
(282643, 'چالیک', '<span class=\"hlight\">چالیک .</span> (اِ) نوعی بازی طفلان . نوعی وسیله ٔ بازی مخصوص اطفال . نوعی بازی اطفال که در هر استان ایران بنامی معروف است و اسم مخصوص دارد. نام دو پاره چوب که در بازی مخصوص اطفال بکار میرود. دو پارچه چوب است که اطفال بدان بازی کنند یکی دراز بقدر سه وجب و دیگری کوتاه بمقدار یک قبضه و هر دو سر چوب کوچک تیزمیباشد، و چوب دراز را بدست گیرند و چوب کوتاه را بر زمین نهند بنوعی که یک سر آن از زمین بلند باشد و چوب دراز بر آن زنند به میزانی که بر هوا جهد و باز در هوا ضربتی بدان زنند چنان که دور افتد. (برهان ) (جهانگیری ) (ناظم الاطباء). دوپاره چوب یکی بلندتر و یکی کوتاه تر که اطفال با آنها بازی کنند و در فرهنگ تفصیلی گفته که ضرورت ندارد زیرا کسی نیست که این بازی را نکرده . (انجمن آرا) (آنندراج ). عرب چوب بزرگ را«مقله » و چوب کوچک را «قله » گویند. (برهان ). به هندی گلی وندا گویند. (آنندراج ). چلک . (انجمن آراء) (آنندراج ). دسته چلک . (انجمن آرا) (آنندراج ) (جهانگیری ). در بعضی بلاد آن را لاوه گویند. (جهانگیری ). الک دولک، به لهجه مردم تهران . (ناظم الاطباء) (فرهنگ نظام ). پل چفته . (فرهنگ نظام ). لاو. کال چنبه . لُوچُنبَه . پله . پله چوب . الک جنبش . دو داله . دودله . دسته پل .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چالیکی </span> ؛ که چالیک بازی کند <span class=\"hlight\">:</span> <br />طفلی است سخن گفتن مردیست خمش کردن <br />تو رستم چالاکی نه کودک چالیکی .<br /> <font color=\"Red\">مولوی .</font><br />گه تاج سلطانان شوم گه مکر شیطانان شوم <br />گه عقل چالاکی شوم گه طفل چالیکی شوم .<br /><font color=\"Red\">مولوی .</font><br /></font></div>'),
(282644, 'چام', '<span class=\"hlight\">چام .</span> (اِ) بمعنی چم و خم باشد. (برهان ) (آنندراج ) (جهانگیری ) (ناظم الاطباء) (فرهنگ نظام ). <BR><font color=\"Blue\">◄</font> قر و غربیله . رفتاری از روی ناز. مؤلف آنندراج نویسد: «... و از این روی رفتار بناز و وقار را چمیدن و چامیدن نیز گویند» و مؤلف فرهنگ نظام نویسد: «... خرامیدن بناز را از این جهت چامیدن و چمیدن گویند که شخص در حالت ناز، چم و خم میرود». <BR><font color=\"Blue\">◄</font> گردونی که کاه از غله بدان جدا کنند. رشیدی گفته : «از این جاست که گردونی را که کاه را از غله بدان جدا کنند چام گویند چه بواسطه ٔ حرکت دوری گویا چم و خم دارد و گاهی می چمد. (آنندراج ). گردونی که زارعان با آن غله را از کاه جدا میکنند. (فرهنگ نظام ). <BR><font color=\"Blue\">◄</font> کژی . <BR><font color=\"Blue\">◄</font> دانه . <BR><font color=\"Blue\">◄</font> گره . <BR><font color=\"Blue\">◄</font> دگمه . <BR><font color=\"Blue\">◄</font> چین . <BR><font color=\"Blue\">◄</font> نورد. <BR><font color=\"Blue\">◄</font> روش و طریقه . <BR><font color=\"Blue\">◄</font> دره . <BR><font color=\"Blue\">◄</font> زمین پست . (ناظم الاطباء).<br /></font></div>'),
(282645, 'چامان', '<span class=\"hlight\">چامان .</span> (نف، ق ) در حال چامیدن . در حال چمیدن و بناز و عشوه خرامیدن . رجوع به جام شود.<br /></font></div>'),
(282646, 'چاماهه', '<span class=\"hlight\">چاماهه .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) در زبان هندی و در اصطلاح هندیان نام روز مخصوصی است که در آن روز از ماه «پوش » استقبال میکنند و بدین مناسبت بر جاهای بلند آتش می افروزند. (از کتاب تحقیق ماللهند ص <span class=\"hlight\" dir=\"rtl\">٢٩٠</span> س <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282647, 'چامر', '<span class=\"hlight\">چامر.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (هندی، اِ) در زبان هندی اصطلاحی است در عروض و شعر. (از کتاب تحقیق ماللهند ص <span class=\"hlight\" dir=\"rtl\">٦٧</span> س <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282648, 'چامز', '<span class=\"hlight\">چامز.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِ) چامین . (ناظم الاطباء). بول . غایط. و رجوع به چامین شود.<br /></font></div>'),
(282649, 'چامغ', '<span class=\"hlight\">چامغ.</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِ) چاه عمیق . (غیاث ).<br /></font></div>'),
(282650, 'چاملق', '<span class=\"hlight\">چاملق .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) ناحیه ای در جنوب کشور آلبانی که اهالی آن بنام «چام » نامیده میشوند و به جرأت و ذکاوت مشهورند. (از قاموس الاعلام ترکی ج <span class=\"hlight\" dir=\"rtl\">٣</span>).<br /></font></div>'),
(282651, 'چامه', '<span class=\"hlight\">چامه .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b>(اِ) شعر بود. (فرهنگ اسدی ). بمعنی شعر باشد عموماً. (برهان ). مطلق شعر را گفته اند. چکامه نیز آمده . (انجمن آرا) (آنندراج ). هر کلام موزون و شعر عموماً. (ناظم الاطباء). شعر در مقابل نثر که «چانه » باشد. منظومه . نشید. سخن منظوم و موزون . کلام مقفی <span class=\"hlight\">:</span> <br />یک شبانروز اندر آن خانه <br />گاه چامه سرود و گه چانه .<br /> <font color=\"Red\">(از فرهنگ اسدی ).</font><br /> <BR><font color=\"Blue\">◄</font> غزل را گویند خصوصاً و آن مطلعی است با ابیات متوازنه متشارکه در قافیه و ردیف کمتر از هفده بیت . (برهان ). غزل را گویند. (انجمن آرا) (آنندراج ). غزل خصوصاً. (ناظم الاطباء). (فرهنگ نظام ). <BR><font color=\"Blue\">◄</font> سرود. (نسخه ای از فرهنگ اسدی ) (ناظم الاطباء). نغمه . (ناظم الاطباء). آهنگ . آواز. دستگاه موسیقی <span class=\"hlight\">:</span> <br />چو آن چامه بشنید بهرام گور<br />بخورد آن گرانسنگ جام بلور.<br /> <font color=\"Red\">فردوسی .</font><br />همان چامه و چنگ ما را بس است <br />نثار زنان بهر دیگر کس است .<br /> <font color=\"Red\">فردوسی .</font><br />بگوش زن جادو آمد سرود<br />همان چامه ٔ رستم و زخم رود.<br /> <font color=\"Red\">فردوسی .</font><br />برآورد رامشگر زابلی <br />زده چنگ بر چامه ٔ کابلی .<br /> <font color=\"Red\">فردوسی .</font><br />یکی چامه گوی و دگر چنگ زن <br />یکی پای کوبد شکن بر شکن .<br /> <font color=\"Red\">فردوسی (از فرهنگ اسدی ).</font><br />سرمایه ٔ عشقند چوبر چامه سرایند<br />پیرایه ٔ نازند چو در خدمت یارند.<br /> <font color=\"Red\">سنایی .</font><br />بزد دست و طنبور در بر گرفت <br />سرائیدن چامه اندر گرفت .<br /> <font color=\"Red\">؟ (از فرهنگ اوبهی ).</font><br /> بمعنی سخن هم آمده است . چه چامه دان سخندان را گویند. (برهان ). سخن و قول . (ناظم الاطباء).<br /></font></div>'),
(282652, 'چامه برساختن', '<span class=\"hlight\">چامه برساختن .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ب َ ت َ]</font></b> (مص مرکب ) سرود ساختن . نغمه ساز کردن . آهنگی از دستگاههای موسیقی را بوسیله سازی نواختن <span class=\"hlight\">:</span> <br />بتان چامه و چنگ برساختند<br />ز بیگانه ایوان بپرداختند.<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> شعر ساختن . کلام موزون در رشته ٔ نظم کشیدن . چکامه ساختن . منظومه ساختن .<br /></font></div>'),
(282653, 'چامه دان', '<span class=\"hlight\">چامه دان .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (نف مرکب ) سخندان . بلیغ. زبان آور. <BR><font color=\"Blue\">◄</font> واعظ. خطیب . (ناظم الاطباء).<br /></font></div>'),
(282654, 'چامه زدن', '<span class=\"hlight\">چامه زدن .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ زَ دَ ]</font></b> (مص مرکب ) سرود گفتن . نغمه نواختن . تصنیف مخصوص را در دستگاههای موسیقی خواندن یا نواختن . شعری را با آهنگ خواندن یا بوسیله ٔ یکی از آلات موسیقی نواختن <span class=\"hlight\">:</span> <br />همه چامه ٔ رزم خسرو زدند<br />زمان تا زمانی ره نو زدند.<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(282655, 'چامه زن', '<span class=\"hlight\">چامه زن .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ زَ ]</font></b> (نف مرکب ) ساززن . موسیقی دان . آهنگ نواز. نغمه زن . آنکه سرود ونغمه در دستگاه موسیقی ساز کند و بوسیله ٔ یکی از آلات موسیقی بنوازد یا بخواند. کسی که خواندن یا زدن نغمه و سرود را در دستگاههای موسیقی داند <span class=\"hlight\">:</span> <br />بدان چامه ٔ زن گفت کای ماهروی <br />بپرداز دل چامه ٔ شاه گوی .<br /><font color=\"Red\">فردوسی .</font><br /></font></div>'),
(282656, 'چامه سرا', '<span class=\"hlight\">چامه سرا.</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ س َ ]</font></b> (نف مرکب )شاعر. منظومه ساز. چامه گوی . چکامه سرا. سراینده ٔ سخن منظوم . آنکه شعر سراید و سخن موزون و مقفی گوید. سخن سرا. قافیه سنج . تصنیف ساز. <BR><font color=\"Blue\">◄</font> آوازخوان . کسی که شعری را با آواز بخواند. آنکه غزل یا تصنیف را در دستگاه موسیقی بخواند. و رجوع به چامه سرای شود.<br /></font></div>'),
(282657, 'چامه سرای', '<span class=\"hlight\">چامه سرای .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ س َ ]</font></b> (نف مرکب ) شعرگوی . شاعر. غزل سرای . تصنیف ساز. آنکه سخن منظوم گوید و کلام موزون و مقفی برشته ٔ نظم کشد. <BR><font color=\"Blue\">◄</font> آوازخوان . خواننده ٔ شعر و غزل در آهنگ موسیقی . کسی که موسیقی داند و خواندن شعر و سرود را در دستگاههای موسیقی داند. رجوع به چامه سرا شود.<br /></font></div>'),
(282658, 'چامه سرایی', '<span class=\"hlight\">چامه سرایی .</span> <font color=\"DarkGreen\"><b>[م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ س َ ]</font></b> (حامص مرکب ) رجوع به چامه سرائی شود.<br /></font></div>'),
(282659, 'چامه گفتن', '<span class=\"hlight\">چامه گفتن .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ گ ُ ت َ ]</font></b> (مص مرکب ) شعر گفتن . شعر و غزل گفتن . سخن منظوم سرائیدن . کلام با وزن و قافیه ساختن . تصنیف ساختن . چکامه و غزل برای ممدوح یا بنام شخص مخصوص بنظم درآوردن <span class=\"hlight\">:</span> <br />همه چامه گفتند بهرام را<br />شهنشاه بادانش و کام را.<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> سرود گفتن . نغمه ساز کردن . شعر و غزل در آهنگ موسیقی خواندن . و رجوع به چامه سرائیدن شود.<br /></font></div>'),
(282660, 'چامه گو', '<span class=\"hlight\">چامه گو.</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (نف مرکب ) چامه گوی . گوینده ٔ شعر. شاعر. سخنسرا. آنکه سخن منظوم سراید و کلام با وزن و قافیه سازد. سرودگوی . تصنیف ساز. <BR><font color=\"Blue\">◄</font> سرودخوان . غزل خوان . تصنیف خوان، آنکه شعر و غزل به آواز خواند. کسی که سرود و تصنیف و غزل با آهنگ موسیقی خواند. ترانه خوان <span class=\"hlight\">:</span> <br />همه چامه گو سوفرا را ستود<br />ببربط همی رزم توران سرود.<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به چامه گوی شود.<br /></font></div>'),
(282661, 'چامه گوی', '<span class=\"hlight\">چامه گوی .</span> <font color=\"DarkGreen\"><b>[ م َ <span class=\"hlight\" dir=\"rtl\">/</span> م ِ ]</font></b> (نف مرکب ) شاعر. گوینده ٔ شعر و سخن منظوم . شاعر و سخنگوی باشد. (برهان ) (آنندراج ) (ناظم الاطباء). مدیحه سرا. غزل سرا. سرودساز. تصنیف ساز. <BR><font color=\"Blue\">◄</font> سرودگوی . آوازه خوان . کسی را نیز گویند که غزلی را به آواز خوش بخواند. (برهان ) (آنندراج ). کسی که غزلی را به آواز نیک بخواند. (ناظم الاطباء). آنکه شعر و غزل را با آهنگ موسیقی و در دستگاههای موسیقی بخواند. موسیقیدان <span class=\"hlight\">:</span> <br />هلا چامه پیش آور ای چامه گوی <br />تو چنگ آور ای دختر ماهروی .<br /> <font color=\"Red\">فردوسی .</font><br />یکی چامه گوی و دگر چنگ زن <br />یکی پای کوبد شکن بر شکن .<br /> <font color=\"Red\">فردوسی .</font><br />همو میگسار وهمو چنگ زن <br />همو چامه گوی است و انده شکن .<br /> <font color=\"Red\">فردوسی .</font><br />نخستین شهنشاه را چامه گوی <br />چنین گفت کای خسرو ماهروی .<br /> <font color=\"Red\">فردوسی .</font><br />و رجوع به چامه سرا و چامه گو شود.<br /></font></div>'),
(282662, 'چاموش', '<span class=\"hlight\">چاموش .</span> (اِ) نوعی از کفش و پای افزار باشد. (برهان ) (آنندراج ) (ناظم الاطباء). چموش . کفش . پاپوش . پوزار. نوعی کفش روستایی . و رجوع به کفش شود.<br /></font></div>'),
(282663, 'چامگیر', '<span class=\"hlight\">چامگیر.</span> (ص ) خوشنما. <BR><font color=\"Blue\">◄</font> ملایم . <BR><font color=\"Blue\">◄</font> آگاه . (ناظم الاطباء).<br /></font></div>'),
(282664, 'چامیدن', '<span class=\"hlight\">چامیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) شاشیدن . (برهان ) (آنندراج ) (ناظم الاطباء). بول کردن . (برهان ) (آنندراج ) (ناظم الاطباء). کمیز انداختن . (ناظم الاطباء). ادرار کردن . و رجوع به چامین شود. <BR><font color=\"Blue\">◄</font> دمیدن . <BR><font color=\"Blue\">◄</font> وزیدن . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> رفتار بناز. چمیدن مخفف چامیدن است . (فرهنگ نظام ).<br /></font></div>'),
(282665, 'چامیر', '<span class=\"hlight\">چامیر.</span> (اِ) چامیز. چامین . بول و کمیز. <BR><font color=\"Blue\">◄</font> غایط. (ناظم الاطباء). و رجوع به چامین و چامیز شود.<br /></font></div>'),
(282666, 'چامیز', '<span class=\"hlight\">چامیز.</span> (اِ) چامیر. چامین . بول و کمیز. <BR><font color=\"Blue\">◄</font> غایط. (ناظم الاطباء). و رجوع به چامین و چامیر شود.<br /></font></div>'),
(282667, 'چامین', '<span class=\"hlight\">چامین .</span> (اِ) چامیر. چامیز.شاش . (برهان ). بول . (برهان ) (انجمن آرا) (آنندراج ) (ناظم الاطباء) (فرهنگ نظام ). کمیز. (ناظم الاطباء). ادرار. پیش آب . و رجوع به شاش شود. <BR><font color=\"Blue\">◄</font> غایط.(برهان ) (انجمن آرا) (آنندراج ) (ناظم الاطباء) (فرهنگ نظام ). و رجوع به غایط شود. <BR><font color=\"Blue\">◄</font> سرگین حیوانات را نیز گفته اند. (انجمن آرا) (آنندراج ) (فرهنگ نظام ). و آن را چمین نیز گفته اند. (انجمن آرا) (آنندراج ). چمین مخفف آن است . (فرهنگ نظام ) <span class=\"hlight\">:</span> <br />بس کن که هر مرغ ای پسر<br />کی خوش خورد انجیر تر<br />شد طعمه طوطی شکر<br />وان زاغ را چامین خر.<br /> <font color=\"Red\">مولوی (از آنندراج ).</font><br />و رجوع به چمین و سرگین شود.<br /></font></div>'),
(282668, 'چامین کردن', '<span class=\"hlight\">چامین کردن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) شاش کردن . بول کردن . ادرار کردن . <BR><font color=\"Blue\">◄</font> غایط کردن .<br /></font></div>'),
(282669, 'چامیوز', '<span class=\"hlight\">چامیوز.</span> (اِ) قلابی باشد که با آن دلو از چاه بیرون آورند. (اما کلمه دگرگون شده ٔ چاهیوز است ).<br /></font></div>'),
(282670, 'چان', '<span class=\"hlight\">چان .</span> (اِخ ) دهی از دهستان زلقی بخش الیگودرز شهرستان بروجرد که در <span class=\"hlight\" dir=\"rtl\">٥١</span> هزارگزی جنوب باختر الیگودرز، کنار راه مالرو پرچل به سربادوش واقع شده، کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">١٠٩</span> تن سکنه لر و فارس دارد. آبش از قنات و چشمه ها و محصولش غلات، لبنیات و پنبه میباشد. شغل اهالی زراعت و گله داری وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282671, 'چان دراگوپتا', '<span class=\"hlight\">چان دراگوپتا.</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) نام یکی از پادشاهان بزرگ هند که بنام (سان دراکت توس ) نیز در تاریخ نام وی آمده است و به شرحی که مؤلف ایران باستان نوشته است، این شخص بعد از بیرون آمدن اسکندر از هند و یاغی شدن مردم بر ولات مقدونی، با قشونی نیرومند تمامی هند را در نوردید و بحکمرانی مقدونیها در پنجاب هند خاتمه داد و خود مالک الرقاب هند تا گنک و ماوراء آن گردید و پادشاه هند شد و سلسله ٔ پادشاهان دودمان او را سلسله ٔ موریاس نامند. این پادشاه شهری بنا کرد که پاتالی پوترا نام نهاد و دور آن حصاری محکم ساخت وآن را پایتخت خود قرار داد. از حوادث تاریخی دوران سلطنت این پادشاه در هند یکی آن است که چون سلکوس (بنیانگزار سلطنت سلوکی ها در ایران که در <span class=\"hlight\" dir=\"rtl\">٣٠٦</span> ق .م . رسماً خود را پادشاه خوانده است ) از طرف مشرق ایران تا سرزمین هند پیش رفت با این پادشاه مصادف شد و جنگ و ستیزه با وی را مصلحت ندانست و ناچار با او از در صلح و صفا درآمد و بعقیده ٔ بعضی مورخین تمامی صفحاتی را که در طرف راست رود سند بود به پادشاه هند (چان دراگوپتا) داد و بلوچستان و افغانستان جنوبی و شمالی را هم به وی واگذار نمود و در ازای این واگذاری <span class=\"hlight\" dir=\"rtl\">٥٠٠</span> فیل از این پادشاه گرفت و بعضی از مورخین نوشته اند که سلکوس برای اینکه وثیقه ای بپادشاه هند داده باشد دختر خود را به حباله ٔ نکاح او درآورد ولی همه ٔ تاریخ نویسان بر این قول متفق نیستند و برخی عقیده دارند که پادشاه هند در ضمن عهدنامه اجازه داده است که مقدونیها با هندیها وصلت کنند اما خود او دختری از سلکوس بزنی نگرفته یا دختری به وی نداده است . (از تاریخ ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">٢٠٥٥</span> - <span class=\"hlight\" dir=\"rtl\">٢٠٥٩</span> و صص <span class=\"hlight\" dir=\"rtl\">٢٠٦٦</span> - <span class=\"hlight\" dir=\"rtl\">٢٢١٤</span>).<br /></font></div>'),
(282672, 'چاناکیا', '<span class=\"hlight\">چاناکیا.</span> (اِخ ) نام وزیر چاندرا گوپتا امپراطور هندوستان «کلمه شاناق باید معرب از اسم هندی چاتاکیا وزیر معروف چاندرا گوپتا امپراطور هندوستان باشد که در حدود <span class=\"hlight\" dir=\"rtl\">٣٢١</span> الی <span class=\"hlight\" dir=\"rtl\">٢٩٨</span> ق م . سلطنت میکرده است این چاناکیا مردی دانشمند و صاحب تألیفاتی بود و بعید نیست که کتاب السموم نیز از وی باشد».(از کتاب علوم عقلی در تمدن اسلامی کتر صفا ص <span class=\"hlight\" dir=\"rtl\">٨٨</span>).<br /></font></div>'),
(282673, 'چانش', '<span class=\"hlight\">چانش .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (اِ) رفتار با کرّ و فرّ و با حشمت . <BR><font color=\"Blue\">◄</font> جنگ و کارزار. (ناظم الاطباء). اما احتمالاً چانش دگرگون شده ٔ «چالش » باشد. رجوع به چالش شود.<br /></font></div>'),
(282674, 'چانف', '<span class=\"hlight\">چانف .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) یکی از دهستانهای پنجگانه ٔبخش بمپور شهرستان ایرانشهر که در جنوب بمپور واقع شده و از شمال بدهستان مرکزی، از خاور به کوهان سرباز از جنوب به بخش قصرقند و نیکشهر از شهرستان چاه بهار و از باختر بدهستان لاشار محدود میباشد. منطقه ای است کوهستانی و مالاریائی که هوای آن با وجود گرمی از سایر نقاط شهرستان سردتر و بهتر است . این دهستان دارای یک رودخانه بنام رود خواجه میباشد و این رودخانه از ارتفاعات اهوران که بیشتر آبادیهای این دهستان در دره های آن قرار دارد سرچشمه میگیرد و پس از مشروب نمودن آبادیهای اطراف خود وارد بخش قصرقند میشود و این رودخانه در بعض نقاط بی آب و در بیشتر جاها دارای آب است . گله داران دهستان که در حدود دوهزار نفرند بطورسیار در اینجا زندگی می کنند. آب مشروبش از رودخانه، چشمه و قنات تأمین میشود. محصول عمده اش خرما و غلات و لبنیات و ذرت است و شغل اهالی زراعت و گله داری است . این دهستان از <span class=\"hlight\" dir=\"rtl\">٢٥</span> آبادی کوچک و بزرگ تشکیل شده و جمعیت آن در حدود پنج هزار تن میباشد که بزبان بلوچی سخن میگویند و مذهب تسنن دارند. راههای این دهستان عموماً مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282675, 'چانه', '<span class=\"hlight\">چانه .</span> <font color=\"DarkGreen\"><b>[ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (اِ) فک اسفل . (برهان ) (آنندراج ) (ناظم الاطباء). موضع ریش برآوردن . (برهان ) (آنندراج ). محل ریش برآوردن باشد. (ناظم الاطباء). بعربی ذقن گویند. (برهان ) (آنندراج ). مَنَه . زَفَر. استخوان زنخ . (جهانگیری ) (انجمن آرا). <BR><font color=\"Blue\">◄</font> غبغب . (برهان ) (آنندراج ) (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> گرداگرد دهان . (غیاث ) (ناظم الاطباء). زنخ .زنخدان . چونه (به لهجه ٔ تهرانیان و مردم بعض ولایات ایران ). چَنَه (در تداول اهالی خراسان ) <span class=\"hlight\">:</span> <br />شکر حق گوید ترا ای پیشوا<br />آن لب و چانه ندارم وآن نوا.<br /> <font color=\"Red\">مولوی (از انجمن آرا).</font><br /> <BR><font color=\"Blue\">◄</font> گلوله خمیری که یک نان از آن پخته شود. (برهان ). گلوله آرد خمیرکرده بود که از آن نان پزند.(انجمن آرا) (آنندراج ) (جهانگیری ) (ناظم الاطباء). وآن را زَوالَه نیز گویند. (جهانگیری ). خمیری که برای نان پختن یا رشته بریدن گلوله کنند. گنده . چونه . <BR><font color=\"Blue\">◄</font> سخن منش بود. (فرهنگ اسدی ). کنایه از حرف و سخن هم هست . (برهان ) (انجمن آرا) (آنندراج ). حرف . (ناظم الاطباء). نثر در مقابل نظم <span class=\"hlight\">:</span> <br />یک شبانروز اندر آن خانه <br />گاه چامه سرود و گه چانه .<br /> <font color=\"Red\">؟ (از فرهنگ اسدی ).</font><br /><BR><font color=\"Blue\">◄</font> سخن یاوه و سخن بی جا. <BR><font color=\"Blue\">◄</font> جام و پیاله . <BR><font color=\"Blue\">◄</font> تقطیر و چکانیدگی . (ناظم الاطباء).<br /></font></div>'),
(282676, 'چانه انداختن', '<span class=\"hlight\">چانه انداختن .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ اَ ت َ ]</font></b> (مص مرکب ) حرکت آخرین که در زنخ محتضر پدید آید. تشنج آخرین شخص محتضردر فک اسفل . آخرین حرکت تشنجی چانه ٔ محتضر. کنایه است از مردن . کنایه است از دم درکشیدن و جان سپردن .<br /></font></div>'),
(282677, 'چانه بند', '<span class=\"hlight\">چانه بند.</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ب َ ]</font></b> (نف مرکب ) باشماق . زنخ بند. یاشماق . خمار. چیزی از اقسام پارچه ٔ نخی، پشمی یا ابریشمی که بعض مردان یا زنان چانه را بدان وسیله بندند. چیزی شبیه به یاشماق زنان را. چیزی که غالباً زنان ترک یا بعض زنان ایلاتی بچانه بندند <span class=\"hlight\">:</span> <br />واعظ این سنت تحت الحنکت دانی چیست ؟<br />چانه بندیست که پر چانه ٔ بیجا نزنی .<br /><font color=\"Red\">تأثیر (از آنندراج ).</font><br /></font></div>'),
(282678, 'چانه زدن', '<span class=\"hlight\">چانه زدن .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ زَ دَ ]</font></b> (مص مرکب ) مُکاس . مُماکَسَة. تشویش کردن در بیع. سخن بیجا و زیاد گفتن در خریدو فروش . (ناظم الاطباء). اصرار مشتری در کم کردن بهای جنس . تقاضای خریدار کم کردن بهای متاعی را از فروشنده به اصرار. پرگوئی فروشنده با خریدار درباره ٔ قیمت جنس . تخفیف خواستن مشتری از بایع و زیاده خواهی بایع از مشتری . چانه زدن در معامله . پرگوئی در امر خریدو فروش . <BR><font color=\"Blue\">◄</font> زنخ زدن . پر گفتن . سخن گفتن نه بقصد نتیجه ای . ورّاجی کردن . ور زدن . شروور گفتن .<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(282679, 'چانه سخن', '<span class=\"hlight\">چانه سخن .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ س ُ خ َ ]</font></b> (ص مرکب ) زنخ زن . چارچارگوی . (مجموعه ٔ مترادفات ص <span class=\"hlight\" dir=\"rtl\">٣٧٠</span>). حرف مفت زن . بیهوده گو.<br /></font></div>'),
(282680, 'چانه کردن', '<span class=\"hlight\">چانه کردن .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ک َ دَ ]</font></b> (مص مرکب ) خمیر رابه اندازه ٔ یک نان گلوله کردن . (ناظم الاطباء). چونه کردن (در تداول عامه ). و رجوع به چانه گرفتن شود.<br /></font></div>'),
(282681, 'چانه گرفتن', '<span class=\"hlight\">چانه گرفتن .</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ گ ِرِ ت َ ]</font></b> (مص مرکب ) گلوله کردن خمیر برای نان . گلوله کردن خمیر برای پختن نان یا رشته کردن . زواله کردن خمیر. زواله گرفتن خمیر. و رجوع به چانه کردن شود.<br /></font></div>'),
(282682, 'چانه گیر', '<span class=\"hlight\">چانه گیر.</span> <font color=\"DarkGreen\"><b>[ ن َ <span class=\"hlight\" dir=\"rtl\">/</span> ن ِ ]</font></b> (نف مرکب ) آنکه خمیر گلوله کند پختن نان یا رشته کردن را. آنکه خمیر را چانه کند. کسی که خمیر را برای نان پختن یا برای رشته کردن گلوله کند. گردکننده ٔ خمیر.<br /></font></div>'),
(282683, 'چانپ', '<span class=\"hlight\">چانپ .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) نام طایفه ای از طوایف ناحیه مکران که مرکب از <span class=\"hlight\" dir=\"rtl\">٢٠٠٠</span> خانوار است . (از جغرافیای سیاسی کیهان ص <span class=\"hlight\" dir=\"rtl\">١٠٠</span>).<br /></font></div>'),
(282684, 'چانچو', '<span class=\"hlight\">چانچو.</span> (اِ مرکب ) قطعه چوب مقعر شکافدار که مخصوص بدوش بردن دو سطل آب است . قطعه چوب خمیده ای که بر شانه می نهند و از هر سر آن سطل آبی می آویزند و بدان وسیله دو سطل پر آب را از محلی به محلی میبرند . کُندَز در لهجه اهالی جنوب ایران .<br /></font></div>'),
(282685, 'چانگ نگان', '<span class=\"hlight\">چانگ نگان .</span> <font color=\"DarkGreen\"><b>[ ن ِ ]</font></b> (اِخ ) نام شهری بوده است در کشور چین . فیروز (یا پیروز) پسر یزدگرد چون تازیان بر وی حمله بردند و او به چین پناهنده شد و در چین عنوان فرمانده قراولان دست راست را به وی دادند و از سرداران مستحفظ مخصوص امپراطور گردید، مدتها در این شهر متوقف بود و بسال <span class=\"hlight\" dir=\"rtl\">٦٧٧</span> م . معبدی برای زردشتیان در این شهر ساخت که آن را «معبد ایران » نام نهاد و ظاهراً در همین سال در این شهر مرد. (از کتاب احوال و اشعار رودکی ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٩٨</span>) (از دیباچه ٔ مزدیسنا تألیف دکتر معین ).<br /></font></div>'),
(282686, 'چانگ کی ین', '<span class=\"hlight\">چانگ کی ین .</span> <font color=\"DarkGreen\"><b>[ی ِ ]</font></b> (اِخ ) نام یک تن از اهالی چین که فغفور چین اورا به نمایندگی از طرف خود نزد یوئه چیها فرستاد که بمساکن قدیمشان برگردند ولی یوئه چیها که از مساکن تازه خود راضی بودند این تکلیف را نپذیرفتند و چانگ کی ین بی انجام مقصود بچین بازگشت (بسال <span class=\"hlight\" dir=\"rtl\">١٢٦</span> ق .م .) و در طریق مراجعت دو دفعه دچار هونها گردید. این شخص اطلاعاتی درباره ٔ پارتها داده که برای روشن شدن تاریخ پارت اهمیت داشته است . (از ایران باستان ج <span class=\"hlight\" dir=\"rtl\">٣</span> ص <span class=\"hlight\" dir=\"rtl\">٢٢٦٣</span>).<br /></font></div>'),
(282687, 'چاه', '<span class=\"hlight\">چاه .</span> (اِ) معروف و به عربی بئر خوانند. (برهان ). ترجمه بئر. (آنندراج ). گودی دایره ای عمیقی که در زمین جهت بیرون آوردن آب و جز آن کنند. مغاک . چال . (ناظم الاطباء). گودالی که در آن آب زاینده باشد. و مجازاً آب آن را هم گویند. (فرهنگ نظام ). بِئر. جُب . جُرموز. خَفیة. رَجَم . رَکیّة. عاثور. عَجوز. قَلیب . کَر. وَرطَه . (منتهی الارب ) <span class=\"hlight\">:</span> <br />چاه پر کرباسه و پر کژدمان <br />خورد ایشان پوست روی مردمان .<br /> <font color=\"Red\">رودکی .</font><br />چاه دم گیر و بیابان و سموم <br />تیغ آهخته سوی مرد نوان .<br /> <font color=\"Red\">خسروانی .</font><br />بچاه سیصد باز اندرم من از غم او<br />عطای میررسن ساختم ز سیصدباز.<br /> <font color=\"Red\">شاکر بخاری (از فرهنگ اسدی ).</font><br />بر آن رای واژونه ٔ دیو نژند<br />یکی ژرف چاهی بره برفکند<br />پس ابلیس واژونه این ژرف چاه <br />بخاشاک پوشید و بسپرد راه .<br /> <font color=\"Red\">فردوسی .</font><br />چنین پاسخش داد بیژن که شو<br />پست چاه باد، اهرمن پیشرو.<br /> <font color=\"Red\">فردوسی .</font><br />به رودابه گفت ای گرانمایه ماه <br />چرا برگزیدی تو بر گاه چاه .<br /> <font color=\"Red\">فردوسی .</font><br />زیرا که برین راه تاختنتان <br />بس ژرف یکی چاه بی فغانست <br />این ژرف و قوی چاه را ببینی <br />گر بر سر تو عقل دیده بان است <br />ز آن می نرود بر سر تو حجت <br />کز چاه برون راه بیگمان است .<br /> <font color=\"Red\">ناصرخسرو.</font><br />چاهی است جهان ژرف و سر نهفته <br />وز چاه نهفته بتر نباشد.<br /> <font color=\"Red\">ناصرخسرو.</font><br />گرت مراد است کزین ژرف چاه <br />خویشتن ای پور برون افکنی .<br /> <font color=\"Red\">ناصرخسرو.</font><br />نگه کن که در پیشت آب است و چاه <br />کلیچه میفکن که نرسی براه .<br /> <font color=\"Red\">اسدی .</font><br />کرا بخت فرخ دهد تاج و گاه <br />چوخرسند نبود درافتد بچاه .<br /> <font color=\"Red\">اسدی .</font><br />دست در دو شاخ زد که بر بالای چاه رسته بود. (کلیله و دمنه )... چنانکه دو مرد در چاه افتند یکی بینا یکی نابینا اگر چه هلاک میان هر دو مشترک است اما عذر نابینا بنزدیک اهل خرد و بصرمقبولتر باشد. (کلیله و دمنه ).<br />بر سر چاه بختم آمد چرخ <br />مدد جوی عمر از آن بگسست .<br /> <font color=\"Red\">خاقانی .</font><br />چاه داری در بن چاهش فکن <br />ای نیابت دار پور آبتین .<br /> <font color=\"Red\">خاقانی .</font><br />یوسفان را به چاه میفکند<br />وز جفا روی چاه میپوشد.<br /> <font color=\"Red\">خاقانی .</font><br />همه بر چاه همی ترسم و برجان که مباد<br />چاه و جانی که تن آسان شدنم نگذارند.<br /> <font color=\"Red\">خاقانی .</font><br />از چاه غمم برآوریدی <br />در نیمه ٔ ره رسن گسستی .<br /> <font color=\"Red\">خاقانی .</font><br />هر کجا تو با منی من خوشدلم <br />ور بود در قعر چاهی منزلم .<br /> <font color=\"Red\">مولوی .</font><br />چون ز چاهی میکنی هر روز خاک <br />عاقبت اندررسی در آب پاک .<br /> <font color=\"Red\">مولوی .</font><br />چو می بینی که نابینا و چاه است <br />اگر خاموش بنشینی گناه است .<br /> <font color=\"Red\">سعدی .</font><br />نه چشم طامع از دنیا شود سیر<br />نه هرگز چاه پر گردد ز شبنم .<br /> <font color=\"Red\">سعدی .</font><br />کر وکور ار نیی ز چاه مترس <br />راست باش و ز میر و شاه مترس .<br /> <font color=\"Red\">اوحدی .</font><br />بی کشش نتوان برون از قید دنیا آمدن <br />بی رسن از چاه هیهات است بالا آمدن .<br /> <font color=\"Red\">صائب .</font><br />زینهار از کنج عزلت پای خودبیرون منه <br />کز بها افتاد یوسف تا برون آمد ز چاه .<br /> <font color=\"Red\">صائب .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">از چاه درآمده در چاله افتاد</span> .<br /> <span class=\"hlight\">این چاه و این ریسمان </span> .<br /> <span class=\"hlight\">چاه از کوه آب میخورد</span> .<br /> <span class=\"hlight\">چاه را چه زیان کون دلو دریده میشود</span> .<br /> <span class=\"hlight\">چاه کن همیشه در ته چاه است </span> . چاه کن تک چاه است .<br /><span class=\"hlight\">چاه مینماید و راه نمی نماید</span> .<br /> <span class=\"hlight\">چاه نکنده منار میدزدد</span> .<br /> <span class=\"hlight\">چند ناگاهان بچاه اندرفتاد</span> <br />آنکه او مر دیگران را چاه کند.<br /> <font color=\"Red\">ناصرخسرو.</font><br /> <span class=\"hlight\">گر چاه کند که من در آن چاه افتم </span> <br />آن چاه کننده را همان چاه بس است .<br /> <font color=\"Red\">(از قرةالعیون ).</font><br /> <span class=\"hlight\">درفتاد اندرچهی کو کنده بود</span> <br />ز آنکه ظلمی بر سرش آینده بود.<br /> <font color=\"Red\">مولوی .</font><br /><span class=\"hlight\">ای که تو از ظلم چاهی میکنی </span> <br />از برای خویش دامی می تنی .<br /> <font color=\"Red\">مولوی .</font><br /> <span class=\"hlight\">خوش آن چاهی که آب از خود برآرد</span> .<br /> <span class=\"hlight\">گر آب چاه نصرانی نه پاک است </span> <br />جهود مرده می شویم چه باک است .<br /> <font color=\"Red\">سعدی .</font><br /> <span class=\"hlight\">هر جا چاهی است یوسفی در وی نیست </span> .<br /> <span class=\"hlight\">همیشه دلواز چاه سالم بیرون نمی آید</span> .<br /> <BR><font color=\"Blue\">◄</font> با مزید مؤخر امکنه : کله چاه . کنگل چاه . فیروزچاه .سفیدچاه . روبانچاه . <BR><font color=\"Blue\">◄</font> گوی زنخدان خوبان را بطریق استعاره گفته اند. (برهان ). و چاه گوی زنخدان خوبان را بطریق استعاره گفته اند. (آنندراج ). چاه زنخ و چاه زنخدان که مراد گودی چانه است . رجوع به چاه زنخدان شود. <BR><font color=\"Blue\">◄</font> زندان و دام . (ناظم الاطباء). کنایه از محبس و زندان <span class=\"hlight\">:</span> <br />چنین بود تا بود چرخ بلند<br />گهی ناز و شادی گهی چاه و بند.<br /> <font color=\"Red\">فردوسی .</font><br />ببردند زن را ز درگاه شاه <br />ز شمشیر گفتند و از بند و چاه .<br /> <font color=\"Red\">فردوسی .</font><br />یوسفانم بسته ٔ چاه زمینند ارنه من <br />چشمه های خون ز رگهای زمین بگشودمی .<br /> <font color=\"Red\">خاقانی .</font><br />اوست فریدون ظفر بلکه دماوندحلم <br />عالم ضحاک فعل بسته ٔ چاهش سزد.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(282688, 'چاه آب', '<span class=\"hlight\">چاه آب .</span> (اِخ ) دهی از دهستان دوغائی بخش حومه ٔ شهرستان قوچان که در <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی جنوب خاوری قوچان و <span class=\"hlight\" dir=\"rtl\">١٤</span> هزارگزی جنوب شوسه ٔ عمومی قوچان به مشهد واقع شده، کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">٥٣</span> تن سکنه ترک و کرد و فارس دارد.آبش از چشمه، محصولش غلات و شغل اهالی زراعت است . راهش مالرو میباشد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282689, 'چاه آبی کنود', '<span class=\"hlight\">چاه آبی کنود.</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) چاهی است در طرابلس که هر کس آب از آن چاه بخورد احمق گردد و این مثل است . (برهان )(آنندراج ). <BR><font color=\"Blue\">◄</font> و آبی کبود هم بنظر آمده است که بجای نون بای ابجد باشد. (برهان ) (آنندراج ).<br /></font></div>'),
(282690, 'چاه آخر', '<span class=\"hlight\">چاه آخر.</span> <font color=\"DarkGreen\"><b>[ خ َ ]</font></b> (اِخ ) دهی است از دهستان نهارجانات بخش حومه ٔ شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی جنوب خاوری بیرجند واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١١</span> تن سکنه دارد. شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282691, 'چاه آهن', '<span class=\"hlight\">چاه آهن .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از دهستان نیکنان بخش بشرویه شهرستان فردوس که در <span class=\"hlight\" dir=\"rtl\">٥٠</span> هزارگزی شمال بشرویه و <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی نیکنان واقع شده، کوهستانی و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٥</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282692, 'چاه ابوطالب', '<span class=\"hlight\">چاه ابوطالب .</span> <font color=\"DarkGreen\"><b>[ هَِ اَ ل ِ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «موسوم به دروازه است واقع در خاک سیستان بر سر راه فراه به مالاخان یا سیاه کوه، در طرف غربی رود هیرمند». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣١</span>).<br /></font></div>'),
(282693, 'چاه ابوعتبه', '<span class=\"hlight\">چاه ابوعتبه .</span> <font color=\"DarkGreen\"><b>[ هَِ اَ ع َ ب َ ]</font></b> (اِخ ) ظاهراً چاهی بوده در نزدیکی شهر «مدینه ». مؤلف حبیب السیر نویسد: «... القصه حضرت مقدس نبوی صلوات اﷲ و سلامه علیه بعد از ترتیب لشکر و تهیه مایحتاج سفر ابن مکتوم را با ابورهم غفاری در مدینه، خلیفه گذاشته بقولی در دهم ماه مبارک رمضان رایت بجانب مکه مبارکه برافراخت و بر سر «چاه ابوعتبه » بعرض لشکر هدایت اثر اشتغال نموده از مهاجر هفتصد مرد در حیز شمار آمد...». (از حبیب السیر جزو سیم از ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(282694, 'چاه احمد', '<span class=\"hlight\">چاه احمد.</span> <font color=\"DarkGreen\"><b>[ اَ م َ ]</font></b> (اِخ ) دهی است از دهستان دژگان بخش بستگ شهرستان لار که در <span class=\"hlight\" dir=\"rtl\">١٤٤</span> هزارگزی جنوب خاوری بستک و در جنوب کوه خمیر واقع شده، دامنه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢٢٣</span> تن سکنه دارد. آبش از چاه و باران، محصولش غلات و خرما و شغل اهالی زراعت است . راه فرعی دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282695, 'چاه ارژنگ', '<span class=\"hlight\">چاه ارژنگ .</span> <font color=\"DarkGreen\"><b>[هَِ اَ ژَ ]</font></b> (اِخ ) چاهی در توران زمین که افراسیاب بیژن را در آن چاه زندانی کرد. چاه بیژن <span class=\"hlight\">:</span> <br />به پیلان گردنکش آن سنگ را<br />که پوشد سر چاه ارژنگ را.<br /> <font color=\"Red\">فردوسی .</font><br />رجوع به ارژنگ و چه ارژنگ شود.<br /></font></div>'),
(282696, 'چاه اسماعیل', '<span class=\"hlight\">چاه اسماعیل .</span> <font color=\"DarkGreen\"><b>[ اِ ]</font></b> (اِخ ) ده کوچکی است از دهستان شهوار بخش میناب شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی شمال میناب بر سر راه فرعی کهنوج به میناب واقع شده، <span class=\"hlight\" dir=\"rtl\">٤٥</span> تن سکنه دارد و دو مزرعه چاه شیرین و «قنبری »جزء این ده است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282697, 'چاه افضل', '<span class=\"hlight\">چاه افضل .</span> <font color=\"DarkGreen\"><b>[ اَ ض َ ]</font></b> (اِخ ) ده کوچکی است از دهستان عقدا بخش شهر بابک شهرستان یزد که در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی شمال باختر اردکان و <span class=\"hlight\" dir=\"rtl\">٦</span> هزار و پانصدگزی شوسه ٔ اردکان به عقدا واقع شده، جلگه، معتدل و مالاریایی است و <span class=\"hlight\" dir=\"rtl\">٤٥</span> تن سکنه دارد. آبش از قنات، محصولش غلات و شغل اهالی زراعت است . صنایع دستی زنان این ده کرباس بافی وراهش فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282698, 'چاه انجیر', '<span class=\"hlight\">چاه انجیر.</span> <font color=\"DarkGreen\"><b>[ اَ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش سروستان شهرستان شیراز که در <span class=\"hlight\" dir=\"rtl\">٢٣</span> هزارگزی باختر سروستان و <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی شوسه ٔ شیراز به سروستان واقع شده، جلگه، معتدل و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢٨٥</span> تن سکنه دارد. آبش از چاه، محصولش غلات و تنباکو، شغل اهالی زراعت و قالی بافی و راهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282699, 'چاه انکرسنه', '<span class=\"hlight\">چاه انکرسنه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «دهکده ای است در جلگه هرون آباد، دو منزلی کرمانشاهان . و از هرون آباد که به کرند میروند در طرف دست راست راه واقع است ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br /></font></div>'),
(282700, 'چاه اوگز', '<span class=\"hlight\">چاه اوگز.</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِخ ) ده کوچکی است از دهستان منوچان بخش کهنوج شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">٨٤</span> هزارگزی جنوب کهنوج بر سر راه فرعی کهنوج به میناب واقع شده و دارای <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282701, 'چاه بابل', '<span class=\"hlight\">چاه بابل .</span> <font color=\"DarkGreen\"><b>[ هَِ ب ِ <span class=\"hlight\" dir=\"rtl\">/</span> ب ُ ]</font></b> (اِخ ) چاهی در بابل که هاروت و ماروت در آن محبوس اند. (آنندراج ). چاهی در بابل که دو ملک هاروت و ماروت در آن حبس میباشند. (ناظم الاطباء). چاهی که در آن هاروت و ماروت محبوسند. (فرهنگ نظام ).<br /></font></div>'),
(282702, 'چاه بار', '<span class=\"hlight\">چاه بار.</span> (اِخ ) دهی است جزء دهستان رزقچای بخش پوبران شهرستان ساوه، در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی باختر نوبران و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی راه عمومی . کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٢٣٨</span> تن سکنه دارد. محصولش غلات، بادام و انگور، شغل اهالی زراعت، گله داری و بافتن قالیچه و جاجیم و راهش مالرو است و از طریق راه شوسه ٔ همدان به نوبران ماشین میتوان برد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282703, 'چاه بار', '<span class=\"hlight\">چاه بار.</span> (اِخ ) مؤلف مرآت البلدان نویسد: «چند آبادی است بناحیه ای از توابع بلوچستان ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br /></font></div>'),
(282704, 'چاه باز', '<span class=\"hlight\">چاه باز.</span> (اِخ ) دهی است از دهستان سوسن بخش ایزه شهرستان اهواز، در <span class=\"hlight\" dir=\"rtl\">٤٨</span> هزارگزی شمال خاوری ایزه . کوهستانی و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٩٠</span> تن سکنه فارس و بختیاری دارد. آبش از چشمه، محصولش گندم و جو، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282705, 'چاه بالو', '<span class=\"hlight\">چاه بالو.</span> (اِخ ) دهی است از دهستان گله دار، بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٦٩</span> هزاروپانصد گزی جنوب خاور کنگان و <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی شمال راه عمومی پسرودک به بیرم واقع شده . جلگه، گرمسیر و مالاریائی و <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آبش از چاه، محصولش غلات و تنباکو، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282706, 'چاه بردی', '<span class=\"hlight\">چاه بردی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b>(اِخ ) ده کوچکی است از دهستان علا مرودشت، بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١٠٥</span> هزارگزی جنوب خاوری کنگان و یک هزارگزی راه عمومی اشکنان به پسرودک واقع شده و<span class=\"hlight\" dir=\"rtl\">٦</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282707, 'چاه بردی', '<span class=\"hlight\">چاه بردی .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) دهی از دهستان حیات داود بخش گناوه شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی شمال گناوه و <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی شوسه گچساران به گناوه واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه دارد. آبش از چاه، محصولش غلات و خرما، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>). مؤلف مرآت البلدان نویسد: «قریه ای است از متعلقات بندر بوشهر و مضافات ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br /></font></div>'),
(282708, 'چاه برف', '<span class=\"hlight\">چاه برف .</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ )دهی است جزء دهستان خرقان شرقی بخش آوج شهرستان قزوین که در <span class=\"hlight\" dir=\"rtl\">٣٦</span> هزارگزی خاور آوج و <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی راه عمومی واقع شده . هوایش معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٤٣</span> تن سکنه دارد. آبش از قنات، محصولش غلات، بنشن و سیب زمینی، شغل اهالی زراعت و بافتن قالی و جاجیم و راهش مالرو است و ماشین هم میتوان برد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282709, 'چاه برم', '<span class=\"hlight\">چاه برم .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «قریه ای است از قراء توابع لارستان فارس ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br /></font></div>'),
(282710, 'چاه بلو', '<span class=\"hlight\">چاه بلو.</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) دهی است از دهستان یخاب بخش طبس شهرستان فردوس که در <span class=\"hlight\" dir=\"rtl\">١٦٣</span> هزارگزی شمال خاوری طبس واقع شده . کوهستانی و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٥</span> تن سکنه دارد و باصطلاح محلی «شاه بلو»نیز نامیده شود. (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282711, 'چاه بلک', '<span class=\"hlight\">چاه بلک .</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «قریه ای است در جلگه هرون آباد دو منزلی کرمانشاهان و از هرون آباد به کرند که میروند در طرف راست راه واقع است ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br /></font></div>'),
(282712, 'چاه بن', '<span class=\"hlight\">چاه بن .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِ مرکب ) تک چاه . (آنندراج ). بن چاه . ته چاه <span class=\"hlight\">:</span> <br />بدین چاه در آب سرد است و خوش <br />بفرمای تا من بوم آبکش <br />که هستند با من پرستنده مرد<br />کزین چاه بن برکشند آب سرد.<br /> <font color=\"Red\">فردوسی .</font><br />پس آن به که غوکان در این چاه بن <br />نگویند از موج دریا سخن .<br /><font color=\"Red\">میرخسرو.</font><br /></font></div>'),
(282713, 'چاه بنارد', '<span class=\"hlight\">چاه بنارد.</span> <font color=\"DarkGreen\"><b>[ ب ُ رَ ]</font></b> (اِخ ) دهی از دهستان گوره بخش بستک شهرستان لار که در <span class=\"hlight\" dir=\"rtl\">٢٨</span> هزارگزی شمال خاوربستک در دامنه شمالی کوه لاور واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢٥٩</span> تن سکنه دارد. آبش از آب باران، محصولش غلات و خرما، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282714, 'چاه بهار', '<span class=\"hlight\">چاه بهار.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) بندر و مرکز شهرستان چاه بهار که در <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> هزارگزی جنوب ایرانشهر، کنار دریای عمان واقع شده مشخصات جغرافیایی آن بشرح زیر است : طول جغرافیایی <span class=\"hlight\" dir=\"rtl\">٦٠</span> درجه و <span class=\"hlight\" dir=\"rtl\">٣١</span> دقیقه و <span class=\"hlight\" dir=\"rtl\">٢٥</span> ثانیه، عرض جغرافیایی <span class=\"hlight\" dir=\"rtl\">٢٥</span> درجه و <span class=\"hlight\" dir=\"rtl\">١٢</span> دقیقه و <span class=\"hlight\" dir=\"rtl\">٤٥</span> ثانیه . اختلاف ساعت تهران با چاه بهار <span class=\"hlight\" dir=\"rtl\">٣٧</span> دقیقه (ساعت <span class=\"hlight\" dir=\"rtl\">١٢</span> تهران مطابق است با ساعت <span class=\"hlight\" dir=\"rtl\">١٢</span> و <span class=\"hlight\" dir=\"rtl\">٣٧</span> دقیقه چاه بهار). مسافت از چاه بهار به تهران از طریق کرمان <span class=\"hlight\" dir=\"rtl\">٢٤٠٦</span> هزارگز و مسافت از چاه بهار به کرمان <span class=\"hlight\" dir=\"rtl\">١٢٧٣</span> هزارگز و فاصله چاه بهار تا زاهدان <span class=\"hlight\" dir=\"rtl\">٧٥٦</span> هزارگز است . چاه بهار در کنار دریای عمان واقع شده و طول آن در حدود <span class=\"hlight\" dir=\"rtl\">٢</span> و عرض آن یک هزارگز است . این بندر قبل از سال <span class=\"hlight\" dir=\"rtl\">١٣١٠</span> هَ . ش . بعلت وجود بازرگانان خارجی وداخلی آباد بوده و هر هفته یک کشتی تجارتی در این بندر لنگر می انداخته ولی از آن زمان که بازرگانان مزبور از چاه بهار بیرون رفتند این بندر اهمیت خود را ازدست داده است . هوای چاه بهار در تابستان زیاد گرم و مرطوب است و در سایر فصول معتدل میباشد. آب مصرفی چاه بهار فقط از دو حلقه چاه (آب چاهها شور مزه است ) تأمین میشود و جز ایندو چاه چاههای دیگری هم حفر شده که طعم آب آنها نزدیک به تلخی است . ساختمانهای چاه بهار قدیمی است و دو عمارت جدید برای فرهنگ و بهداری در آنجا ساختمان شده . سربازخانه ٔ پادگان چاه بهار در جنوب قصبه واقع است و ساختمان آن که قبل از <span class=\"hlight\" dir=\"rtl\">١٣١٠</span> بنا شده مستحکم است . زبان مادری اهالی قصبه بلوچی و مذهبشان سنی است و شامل دو هزار تن سکنه است . ادارات دولتی چاه بهار عبارت است از پادگان نظامی، مرزبانی، فرمانداری، گروهان ژاندارمری، دارائی، نماینده ٔ فرهنگ، آمار، گمرک، گارد مسلح و دو دبستان دولتی هم دارد. از راه شوسه ٔ چاه بهار به ایرانشهر قبل از سال <span class=\"hlight\" dir=\"rtl\">١٣٢٠</span> هرهفته دو مرتبه پست با ماشین آمد و رفت میکرده ولی بعد از <span class=\"hlight\" dir=\"rtl\">١٣٢٠</span> روز بروز خرابتر شده است بطوری که اگر اتومبیلی از ایرانشهر به چاه بهار حرکت کند بواسطه خرابی راه و معطلی دیرتر از شتر به چاه بهار میرسد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>). فرهنگ امیرکبیر ذیل چاه بهار نوشته : «بندر جنوب ایران در کنار دریای عمان که با ناحیه دشتیاری و نیکشهر (قصرقند سابق ) یک حوزه حکومتی تشکیل داده است ». (از فرهنگ امیرکبیر ص <span class=\"hlight\" dir=\"rtl\">٥٧٩</span>).<br /></font></div>'),
(282715, 'چاه بهار', '<span class=\"hlight\">چاه بهار.</span> <font color=\"DarkGreen\"><b>[ ب َ ]</font></b> (اِخ ) یکی از شهرستان های استان هشتم کشور است که از طرف شمال به شهرستان ایرانشهر، از طرف خاور به مرز پاکستان، از طرف جنوب بدریای عمان و از طرف باختر ببخش جاسک از شهرستان بندرعباس محدود میباشد. بطور کلی هوای شهرستان گرمسیر و مالاریائی است و قسمت جنوب شهرستان چون مجاور دریاست گرمتر و مرطوبتر است . آب قسمت جنوبی وبخش دشتیاری از چاه تأمین میشود و آب قسمت شمالی شهرستان از رودخانه و چشمه و چند قنات است . محصول عمده شهرستان غلات، خرما، ذرت، حبوبات، لبنیات و پنبه است و مخصوصاً غلات و پنبه در ناحیه ٔ جنوب شهرستان (بخش دشتیاری و دهستان کنارک ) دیمی بعمل میاید و اگر باران بموقع ببارد این قسمت از حاصلخیزترین نقاط شهرستان است . این شهرستان دارای چهار رودخانه است به این شرح : <span class=\"hlight\" dir=\"rtl\">١</span>- رود باهو کلات که از کوهستان سرباز سرچشمه گرفته در شمال خاوری شهرستان وارد دهستان باهو کلات میشود این رودخانه در قسمت بالا دارای آب و از محلی که وارد شهرستان میشود خشک و بی آب است . <span class=\"hlight\" dir=\"rtl\">٢</span>- رودخانه ٔ خواجه که از کوهستان قصرقند و اهوران سرچشمه میگیرد و پس از مشروب ساختن آبادیهای بخش قصرقند وارد دشتیاری میشود ولی در ناحیه ٔ اخیر بدون آب است . <span class=\"hlight\" dir=\"rtl\">٣</span>- رودخانه ٔ گه که از ارتفاعات نیکشهر وپیچان و تنگ سرخه سرچشمه گرفته پس از مشروب ساختن آبادیهای اطراف خود وارد دهستان کنارک می گردد. <span class=\"hlight\" dir=\"rtl\">٤</span>- رودخانه ٔ رایچ که از ارتفاعات قنوج و بنت سرچشمه گرفته پس از مشروب کردن آبادیهای اطراف به دریای عمان میریزد. شهرستان چاه بهار از بخشهای زیر تشکیل شده است :<br /><span class=\"hlight\" dir=\"rtl\">١</span>- بخش مرکزی شامل دهستانهای کنارک و تنگ . <span class=\"hlight\" dir=\"rtl\">٢</span>- بخش قصرقند شامل دهستان قصرقند. <span class=\"hlight\" dir=\"rtl\">٣</span>- بخش دشتیاری شامل دهستانهای باهو کلات، دشتیاری میرعبدی و دشتیاری دلاور. <span class=\"hlight\" dir=\"rtl\">٤</span>- بخش نیکشهر شامل دهستانهای نیکشهر و بنت . جمعیت شهرستان بشرح زیر است : چاه بهار یک آبادی و دو هزارتن سکنه . بخش مرکزی <span class=\"hlight\" dir=\"rtl\">٥٤</span> آبادی و <span class=\"hlight\" dir=\"rtl\">١٧</span> هزار تن سکنه که جمعاً <span class=\"hlight\" dir=\"rtl\">٥٥</span> آبادی و <span class=\"hlight\" dir=\"rtl\">١٩</span> هزار تن سکنه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282716, 'چاه بوقیر', '<span class=\"hlight\">چاه بوقیر.</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) چاهی است که افراسیاب بیژن را در آن چاه محبوس کرده بود. (برهان ). نام چاهی که افراسیاب بیژن را در آن بند کرده بود. (آنندراج ). چاه ارژنگ . رجوع به چاه بیجن و چاه بیژن شود.<br /></font></div>'),
(282717, 'چاه بک', '<span class=\"hlight\">چاه بک .</span> <font color=\"DarkGreen\"><b>[ ب ُ ]</font></b> (اِخ ) دهی است ازدهستان نهبندان بخش شوسف شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٤٤</span> هزارگزی خاور شوسف واقع است . کوهستانی و گرمسیر است و<span class=\"hlight\" dir=\"rtl\">٦</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282718, 'چاه بیجن', '<span class=\"hlight\">چاه بیجن .</span> <font color=\"DarkGreen\"><b>[ هَِ ج َ ]</font></b> (اِخ ) نام چاهی که افراسیاب بیژن را در آن بند کرده بود. (آنندراج ). چاه ارژنگ . چاه بیژن <span class=\"hlight\">:</span> <br />این چاه بیجن است مسیحا خموش باش <br />چندان نشین که صبح برآید ز شام تو.<br /> <font color=\"Red\">مسیح کاشی (از آنندراج ).</font><br />رجوع به چاه بوقیر و چاه بیژن شود.<br /></font></div>'),
(282719, 'چاه بیدو', '<span class=\"hlight\">چاه بیدو.</span> (اِخ ) دهی از دهستان گله دار بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٦٢</span> هزار و پانصدگزی جنوب خاور کنگان، کنار راه فرعی لار بگله دار واقع شده است . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١٧٧</span> تن سکنه دارد. آبش از چاه، محصولش غلات و تنباکو و شغل اهالی زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282720, 'چاه بیژن', '<span class=\"hlight\">چاه بیژن .</span> <font color=\"DarkGreen\"><b>[ هَِ ژَ ]</font></b> (اِخ ) نام چاهی که افراسیاب بیژن را در آن بند کرده بود. (آنندراج ). چاهی در توران که افراسیاب بیژن پهلوان ایرانی را در آن حبس کرده بود و رستم او را نجات داد. (فرهنگ نظام ) <span class=\"hlight\">:</span> <br />ز ظلمت گشته پنهان خانه ٔ خاک <br />چو چاه بیژن و زندان ضحاک .<br /> <font color=\"Red\">؟(از آنندراج ).</font><br />تا لب نانی بدست آرم چه خونهامیخورم <br />دست کوته را تنور رزق چاه بیژن است .<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br />رجوع به چاه بوقیر و چاه بیجن شود.<br /></font></div>'),
(282721, 'چاه تر', '<span class=\"hlight\">چاه تر.</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) از متعلقات لارستان است . (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br /></font></div>'),
(282722, 'چاه تغاری', '<span class=\"hlight\">چاه تغاری .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) ده کوچکی است از بخش ماهان شهرستان کرمان که در <span class=\"hlight\" dir=\"rtl\">٤٢</span> هزارگزی جنوب ماهان و <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزارگزی راه شوسه ٔ کرمان به بم واقع شده و <span class=\"hlight\" dir=\"rtl\">١٥</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282723, 'چاه تل', '<span class=\"hlight\">چاه تل .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «قریه ای است از قرای تنگستان از بلوکات فارس ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br /></font></div>'),
(282724, 'چاه تلخ', '<span class=\"hlight\">چاه تلخ .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) دهی است از دهستان لیراوی بخش دیلم شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی جنوب دیلم و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی خاور دریا و شمال کوه بنگ واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٣٨٠</span> تن سکنه دارد. آبش از چاه، محصولش غلات شغل اهالی زراعت و راهش فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282725, 'چاه تلخ', '<span class=\"hlight\">چاه تلخ .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) دهی است از دهستان ساحلی بخش اهرم شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی باختر اهرم و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی خاور خلیج فارس واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٦٩٠</span> تن سکنه دارد. آبش از چاه، محصولش غلات، خرما و تنباکو، شغل اهالی زراعت و راهش شوسه ٔ سابق بوشهر به لنگه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282726, 'چاه تلخ', '<span class=\"hlight\">چاه تلخ .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) جزء تنگستان است . (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>) قریه ای است نیم فرسنگی جنوبی تنگستان . (از فارسنامه ناصری ).<br /></font></div>'),
(282727, 'چاه تلخ', '<span class=\"hlight\">چاه تلخ .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «قریه ای است از توابع کوهکیلویه ٔ فارس ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br /></font></div>'),
(282728, 'چاه تک', '<span class=\"hlight\">چاه تک .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) دهی است از دهستان زیر کوه بخش قاین شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی جنوب خاوری قاین واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٣</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282729, 'چاه جلال', '<span class=\"hlight\">چاه جلال .</span> <font color=\"DarkGreen\"><b>[ ج َ ]</font></b> (اِخ ) دهی است از دهستان پاریز بخش مرکزی شهرستان سیرجان، که در <span class=\"hlight\" dir=\"rtl\">٤٨</span> هزارگزی شمال خاوری سعیدآباد بر سر راه زیدآباد به پاریزواقع شده . جلگه و سردسیر است و <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد. آبش از قنات، محصولش غلات و حبوبات، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282730, 'چاه جمال', '<span class=\"hlight\">چاه جمال .</span> <font color=\"DarkGreen\"><b>[ ج َ ]</font></b> (اِخ ) دهی از بخش حومه ٔ شهرستان ایرانشهر است که در <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی شمال ایرانشهر و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی خاور شوسه ٔ ایرانشهر به خاش واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٨٠</span> تن سکنه بلوچ سنی دارد. آبش از قنات، محصولش غلات، خرما، ذرت و لبنیات، شغل اهالی زراعت و گله داری و راهش فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282731, 'چاه حاجی', '<span class=\"hlight\">چاه حاجی .</span> (اِخ ) دهی است از دهستان طبس بخش در میان شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٥٧</span> هزارگزی خاور در میان واقع شده جلگه و گرمسیر است و جمعیتی ندارد. چاه آب شیرین دارد که در فصل بهار مالدارها از آن آب استفاده میکنند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282732, 'چاه حاجی ابل', '<span class=\"hlight\">چاه حاجی ابل .</span> <font color=\"DarkGreen\"><b>[ اَ ب ُ ]</font></b> (اِخ ) دهی است از دهستان تراکمه بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١٦</span> هزارگزی جنوب خاور کنگان و یک هزارگزی شمال خاور راه فرعی لار به گله دار واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> تن سکنه فارس و ترک دارد. آبش از قنات و چاه، محصولش غلات، انار، خرما و تنباکو، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282733, 'چاه حد', '<span class=\"hlight\">چاه حد.</span> <font color=\"DarkGreen\"><b>[ ح َ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «از مزارع قدیم النسق طبس است، آبش از قنات و هوای آن معتدل میباشد». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br /></font></div>'),
(282734, 'چاه حسین جمال', '<span class=\"hlight\">چاه حسین جمال .</span> <font color=\"DarkGreen\"><b>[ هَِ ح ُ س ِ ج َ ]</font></b> (اِخ ) دهی است از دهستان لاور کنگان بخش خورموج شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٤٨</span> هزارگزی جنوب خورموج در خاور کوه کلات سبز و <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی باختر رودمند واقعشده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٣١١</span> تن سکنه دارد. آبش از چاه محصولش غلات و خرما، شغل اهالی زراعت و راهش فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282735, 'چاه حسین جمال', '<span class=\"hlight\">چاه حسین جمال .</span> <font color=\"DarkGreen\"><b>[ هَِ ح ُ س ِ ج َ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «قریه ای است از قرای بلوک دشتستان ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br /></font></div>'),
(282736, 'چاه حوض', '<span class=\"hlight\">چاه حوض .</span> <font color=\"DarkGreen\"><b>[ ح َ ]</font></b> (اِخ ) دهی است از دهستان شهاباد بخش حومه ٔ شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی شمال باختر بیرجند واقع شده، دامنه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٧٦</span> تن سکنه دارد. آبش از قنات، محصولش غلات، میوه باغات، لبنیات و ابریشم، شغل اهالی زراعت و مالداری و راهش مالرو است . کلاته های رباط و چشمه رباط و مزرعه ٔ پشت گدارجزء این ده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282737, 'چاه خاری', '<span class=\"hlight\">چاه خاری .</span> (اِخ ) دهی از دهستان نهبندان بخش شوسف شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">١٦٢</span> هزارگزی جنوب خاوری شوسف واقع شده . دامنه و گرمسیر است و<span class=\"hlight\" dir=\"rtl\">٦</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282738, 'چاه خاصه', '<span class=\"hlight\">چاه خاصه .</span> <font color=\"DarkGreen\"><b>[ خاص ْ ص َ ]</font></b> (اِخ ) دهی است از دهستان شاندیز بخش طرقبه شهرستان مشهد که در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی شمال خاوری طرقبه بر سر راه شوسه ٔ قدیمی مشهد بقوچان واقع شده . جلگه و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٢٥</span> تن سکنه دارد. آبش از قنات، محصولش غلات، بنشن و میوجات است، شغل اهالی زراعت و مالداری و راهش مالرو است . از طرقبه اتومبیل هم میتوان برد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282739, 'چاه خالوها', '<span class=\"hlight\">چاه خالوها.</span> (اِخ ) دهی است از دهستان گله دار بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٧٦</span> هزارگزی جنوب خاور کنگان، کنار راه فرعی لار به گله دار واقع شده، جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١٠٥</span> تن سکنه دارد. آبش از چاه محصولش غلات و تنباکو و شغل اهالی زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282740, 'چاه خانی', '<span class=\"hlight\">چاه خانی .</span> (اِخ ) قریه ای است در بلوک برازجان از اعمال بندربوشهر و در حوالی این قریه بین مهرعلیخان شجاع الملک و قشون انگلیس در سال هزار و دویست و هفتاد و سه نزاع اتفاق افتاد. اراضی اینجا رمل است و هندوانه ٔ دیمی بعمل می آورد، اهالی عبای شتری میبافند. طول جلگه برازجان چهار فرسخ و عرض نیز همین قدر است . (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br /></font></div>'),
(282741, 'چاه خرک', '<span class=\"hlight\">چاه خرک .</span> <font color=\"DarkGreen\"><b>[ خ َ رَ ]</font></b> (اِخ ) دهی است از دهستان شمیل بخش مرکزی شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">٨٤</span> هزارگزی شمال خاوری بندرعباس بر سر راه فرعی میناب به کهنوج واقع شده . جلگه و گرمسیر است و<span class=\"hlight\" dir=\"rtl\">٢٨٩</span> تن سکنه دارد. آبش از رودخانه، محصولش خرما و غلات، شغل اهالی زراعت و راهش فرعی است . مزرعه ٔ میرآقاجزء این ده است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282742, 'چاه خس پوش', '<span class=\"hlight\">چاه خس پوش .</span> <font color=\"DarkGreen\"><b>[ هَِ خ َ ]</font></b> (اِ مرکب ) چاهی که سرش بخس و خاشاک پنهان گردیده باشد. (آنندراج ) <span class=\"hlight\">:</span> <br />بدور خط از آن چاه زنخدان بیش میلرزم <br />ز آسیب چه خس پوش بر جان بیش میلرزم .<br /><font color=\"Red\">صائب (از آنندراج ).</font><br /></font></div>'),
(282743, 'چاه خو', '<span class=\"hlight\">چاه خو.</span> (اِخ ) دهی است از دهستان مؤمن آباد بخش درمیان شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٨٤</span> هزارگزی باختر درح واقع شده . کوهستانی و گرمسیر است و<span class=\"hlight\" dir=\"rtl\">١٣</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282744, 'چاه خو', '<span class=\"hlight\">چاه خو.</span> (اِخ ) دهی است از دهستان مرکزی بخش خوسف شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٥٤</span> هزارگزی شمال باختری خوسف واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٤</span> تن سکنه دارد. آبش از قنات، محصولش غلات، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282745, 'چاه دراز', '<span class=\"hlight\">چاه دراز.</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b>(اِخ ) دهی است از دهستان لادیز بخش میر جاوه شهرستان زاهدان که در <span class=\"hlight\" dir=\"rtl\">٣٧</span> هزارگزی باختر راه فرعی میر جاوه به خاش واقع شده . کوهستانی، گرمسیر و معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٠٠</span>تن سکنه دارد که از طائفه ٔ ریگی هستند. آبش از قنات، محصولش غلات و لبنیات، شغل اهالی زراعت و گله داری وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282746, 'چاه دراز', '<span class=\"hlight\">چاه دراز.</span> <font color=\"DarkGreen\"><b>[ دِ ]</font></b> (اِخ ) دهی است از دهستان نهبندان بخش شوسف شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٢٥</span> هزارگزی شمال خاوری شوسف و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی خاور شوسه ٔ عمومی مشهد بزاهدان واقع شده . دشت و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٧١</span> تن سکنه دارد. آبش از قنات، محصولش غلات و لبنیات، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282747, 'چاه دران', '<span class=\"hlight\">چاه دران .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (اِخ ) ده کوچکی است از دهستان حومه ٔ شهرستان سراوان که در <span class=\"hlight\" dir=\"rtl\">٢٨</span> هزارگزی جنوب خاوری سراوان و یک هزارگزی جنوب شوسه ٔ سراوان به کوهک واقع شده و <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282748, 'چاه دره', '<span class=\"hlight\">چاه دره .</span> <font color=\"DarkGreen\"><b>[ دَ رِ ]</font></b> (اِخ ) دهی است از دهستان چناران بخش حومه ٔ شهرستان مشهد که در <span class=\"hlight\" dir=\"rtl\">٦٥</span> هزارگزی شمال باختری مشهد و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی شمال شوسه ٔ عمومی مشهد بقوچان واقع شده . جلگه و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٦٤</span>تن سکنه فارس و کرد دارد آبش از قنات، محصولش غلات، چغندر و سیب زمینی، شغل اهالی زراعت و مالداری و راهش اتومبیل رو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282749, 'چاه دزد', '<span class=\"hlight\">چاه دزد.</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) از دهات جلگه ٔهرون آباد است و در صورتیکه از هرون آباد به کرند بروند این هر سه ده <font color=\"DarkGreen\"><b>[ چاه زر. چاه زرد و چاه دزد ]</font></b> در طرف راست راه واقعند. (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282750, 'چاه دزدان', '<span class=\"hlight\">چاه دزدان .</span> <font color=\"DarkGreen\"><b>[ دُ ]</font></b> (اِخ ) دهی است از دهستان گوده بخش بستک شهرستان لار که در <span class=\"hlight\" dir=\"rtl\">٤٨</span> هزارگزی شمال خاوربستک و در خاور کوه سیاه واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن سکنه دارد. آبش از چاه و باران، محصولش غلات و خرما، شغل اهالی زراعت و بافتن عبا و راهش فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282751, 'چاه دلو', '<span class=\"hlight\">چاه دلو.</span> <font color=\"DarkGreen\"><b>[ دَل ْوْ ]</font></b> (اِ مرکب ) کنایه از دنیا باشد. (برهان ). دنیا. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> کنایه از برج دلو هم هست که یکی از دوازده برج فلکی است . (برهان ). برج دلو که برج یازدهم از بروج دوازده گانه بود. (ناظم الاطباء).<br /></font></div>'),
(282752, 'چاه ده شیخ', '<span class=\"hlight\">چاه ده شیخ .</span><font color=\"DarkGreen\"><b>[ دِ ش ِ ]</font></b> (اِخ ) دهی است از دهستان حشون بخش بافت شهرستان سیرجان که در <span class=\"hlight\" dir=\"rtl\">٣٤</span> هزارگزی جنوب باختری بافت و <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی جنوب راه فرعی بافت به سیرجان واقع شده و <span class=\"hlight\" dir=\"rtl\">١٢</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282753, 'چاه دول', '<span class=\"hlight\">چاه دول .</span> (اِخ ) مؤلف مرآت البلدان نویسد: «قریه ای است از بلوک شبانکاره ٔ دشتستان و طول بلوک شبانکاره شش فرسخ و عرض آن نیز همین قدر است . (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282754, 'چاه دوک', '<span class=\"hlight\">چاه دوک .</span> (اِخ ) دهی است از دهستان طبس بخش درمیان شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی شمال باختری درمیان بر سر راه شوسه ٔ بیرجند به درمیان واقع شده . دامنه و گرمسیر است و<span class=\"hlight\" dir=\"rtl\">٢٧</span> تن سکنه دارد. آبش از قنات، محصولش غلات و شلغم وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282755, 'چاه ذقن', '<span class=\"hlight\">چاه ذقن .</span> <font color=\"DarkGreen\"><b>[ هَِ ذَ ق َ ]</font></b> (ترکیب اضافی، اِ مرکب ) چاه زنخ و چاه زنخدان و چاه غبغب . (آنندراج ). چاه زنخ و چاه زنخدان . (فرهنگ نظام ). کنایه از گوی خرد که در زنخدان و غبغب خوبان میباشد.(آنندراج ). مجازاً گود کوچکی که در چانه ٔ کسی باشد.(فرهنگ نظام ). رجوع به چاه زنخ و چاه زنخدان شود.<br /></font></div>'),
(282756, 'چاه رحمان', '<span class=\"hlight\">چاه رحمان .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) دهی است از دهستان پائین ولایت بخش فریمان شهرستان مشهد که در <span class=\"hlight\" dir=\"rtl\">٣٩</span> هزارگزی شمال باختر فریمان واقع شده .دامنه ومعتدل است و <span class=\"hlight\" dir=\"rtl\">٧٠</span> تن سکنه دارد. آبش از چشمه، محصولش غلات و چغندر، شغل اهالی زراعت و قالیچه بافی وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282757, 'چاه رستم', '<span class=\"hlight\">چاه رستم .</span> <font color=\"DarkGreen\"><b>[ رُ ت َ ]</font></b> (اِخ ) ده کوچکی است از دهستان خنج بخش مرکزی شهرستان لار که در <span class=\"hlight\" dir=\"rtl\">٩١</span> هزارگزی شمال باختر لار و در جنوب کوه گوکردی واقع شده وده تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282758, 'چاه رستم', '<span class=\"hlight\">چاه رستم .</span> <font color=\"DarkGreen\"><b>[ رُ ت َ ]</font></b> (اِخ ) ده کوچکی است از بخش راین شهرستان بم که در <span class=\"hlight\" dir=\"rtl\">١١</span> هزارگزی شمال راین و<span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی راه مالرو کرمان به راین واقع شده و یک خانوار سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282759, 'چاه رستم', '<span class=\"hlight\">چاه رستم .</span> <font color=\"DarkGreen\"><b>[ هَِ رُ ت َ ]</font></b> (اِخ ) چاهی که رستم را شغاد برادرش بلطائف الحیل در آن انداخته بود و آن چاه را بشمشیر و سنانها پرساخته . (آنندراج ) <span class=\"hlight\">:</span> <br />مسکن دیو سفید آمد بخاریها ز برف <br />چاهها چون چاه رستم شد ز یخ شمشیردار.<br /> <font color=\"Red\">اشرف (از آنندراج ).</font><br />آن زنخدانی که باشد چاه یوسف از صفا<br />پرسنان آخر ز خط چون چاه رستم میشود.<br /><font color=\"Red\">اشرف (از آنندراج ).</font><br /></font></div>'),
(282760, 'چاه روستایی', '<span class=\"hlight\">چاه روستایی .</span> (اِخ ) دهی است از دهستان حیات داود بخش گناوه ٔ شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی خاور گناوه بر کنار راه فرعی برازجان و بوشهر به گناوه واقع شده، جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١٠٠٠</span> تن سکنه دارد. آبش از چاه، محصولش غلات و خرما و شغل اهالی زراعت است .دبستان هم دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282761, 'چاه ریکان', '<span class=\"hlight\">چاه ریکان .</span> (اِخ ) دهی است از دهستان رودبار بخش کهنوج شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">٢٥</span> هزارگزی باختر کهنوج بر سر راه مالرو کهنوج به گلاشکرد واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه دارد. آبش از چاه، محصولش غلات و شغل اهالی مالداری است . مزارع چاه گز و نهر سیرجزء این ده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282762, 'چاه زبر', '<span class=\"hlight\">چاه زبر.</span> <font color=\"DarkGreen\"><b>[ زَ ب َ ]</font></b> (اِخ ) از دهات جلگه ٔ هرون آباد دومنزلی کرمانشهان است . (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282763, 'چاه زرد', '<span class=\"hlight\">چاه زرد.</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش خوسف شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٥٦</span> هزارگزی شمال باختری خوسف و <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی شمال خور واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٥٥</span> تن سکنه دارد. آبش از قنات، محصولش غلات، شغل اهالی زراعت، مکاری، هیزم فروشی و مالداری است وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282764, 'چاه زرد', '<span class=\"hlight\">چاه زرد.</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) از دهات جلگه ٔ هرون آباد است . (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282765, 'چاه زمزم', '<span class=\"hlight\">چاه زمزم .</span> <font color=\"DarkGreen\"><b>[ هَِ زَ زَ ]</font></b> (اِخ ) چاه معروفی است در شهر مکه . بئر زمزم . رَواء. (منتهی الارب ). رجوع به زمزم شود.<br /></font></div>'),
(282766, 'چاه زنخ', '<span class=\"hlight\">چاه زنخ .</span> <font color=\"DarkGreen\"><b>[ زَ ن َ ]</font></b> (ص مرکب ) کسی که گودی درزنخ دارد. آنکه چاله ای در زنخ وی باشد <span class=\"hlight\">:</span> <br />به گرد عارض آن ماه روی چاه زنخ <br />سپاه زنگ درآمد بسان مور و ملخ .<br /><font color=\"Red\">سوزنی .</font><br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(282767, 'چاه زنخ', '<span class=\"hlight\">چاه زنخ .</span> <font color=\"DarkGreen\"><b>[ هَِ زَ ن َ ]</font></b> (ترکیب اضافی، اِ مرکب ) چاه ذقن . چاه زنخدان . چاه غبغب . (آنندراج ). گودی چانه . (ناظم الاطباء). چاه ذقن و چاه زنخدان . (فرهنگ نظام ). گوی که بر زنخ باشد. گودی در زنخ <span class=\"hlight\">:</span> <br />در خم زلف تو آویخت دل از چاه زنخ <br />آه کز چاه برون آمد و در دام افتاد.<br /> <font color=\"Red\">حافظ.</font><br />رجوع به چاه ذقن و چاه زنخدان و چاه غبغب شود.<br /></font></div>'),
(282768, 'چاه زنخدان', '<span class=\"hlight\">چاه زنخدان .</span> <font color=\"DarkGreen\"><b>[ هَِ زَ ن َ ]</font></b> (ترکیب اضافی، اِ مرکب ) چاه ذقن و چاه زنخ و چاه غبغب . (آنندراج ). چاه زنخ . گودی چانه . (ناظم الاطباء). چاه ذقن و چاه زنخ . (فرهنگ نظام ). گو زنخ . گوی که در زنخ بعضی خوبان باشد. فرورفتگی کوچکی که در زنخ بعضی خوبرویان است <span class=\"hlight\">:</span> <br />ای دل گر از آن چاه زنخدان بدرآیی <br />هر جا که روی زود پشیمان بدرآیی .<br /> <font color=\"Red\">حافظ.</font><br />ای فروغ ماه حسن از روی رخشان شما<br />آبروی خوبی از چاه زنخدان شما.<br /> <font color=\"Red\">حافظ.</font><br />یوسف من زیر لب تا کی گذاری خال هند<br />این کبوتر در خور چاه زنخدان تو نیست .<br /> <font color=\"Red\">صائب (از آنندراج ).</font><br />رجوع به چاه ذقن، چاه زنخ و چاه غبغب شود.<br /></font></div>'),
(282769, 'چاه زندی', '<span class=\"hlight\">چاه زندی .</span> <font color=\"DarkGreen\"><b>[ زَ ]</font></b> (اِخ ) دهی است از دهستان نهارجانات بخش حومه ٔ شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٥٦</span> هزارگزی جنوب خاوری بیرجند واقعشده . کوهستانی و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد. آبش از قنات، محصولش غلات، شغل اهالی زراعت و مالداری وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282770, 'چاه زیرود', '<span class=\"hlight\">چاه زیرود.</span> (اِخ ) دهی است از دهستان نهبندان بخش شوسف شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٥٠</span> هزارگزی شمال خاوری شوسف و <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی شمال چاهگل واقع شده . دره ای است گرمسیر و <span class=\"hlight\" dir=\"rtl\">٢٤٦</span> تن سکنه دارد. آبش از چشمه و قنات، محصولش غلات و لبنیات، شغل اهالی زراعت و مالداری وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282771, 'چاه زیچ', '<span class=\"hlight\">چاه زیچ .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِ مرکب ) زمین <font color=\"DarkGreen\"><b>[ در زمین ]</font></b> همواری که در نشیب و فراز نباشد بعمق شصت گز بلند <font color=\"DarkGreen\"><b>[ کنند ]</font></b> و آن را مشبک سازند و در آن نشینند تا کیفیت افلاک و نجوم دریابند. چاه ستاره جو، مرادف این است . (آنندراج ). جای زیج نشستن ستاره شناس <span class=\"hlight\">:</span> <br />از شرم ارتفاع فرو رو به چاه زیچ <br />اخترشناس طالع واژون خویش باش .<br /> <font color=\"Red\">استاد (از آنندراج ).</font><br />رجوع به چاه ستاره جو شود.<br /></font></div>'),
(282772, 'چاه سالار', '<span class=\"hlight\">چاه سالار.</span> (اِخ ) دهی است از دهستان عشق آباد بخش فدیشه ٔشهرستان نیشابور که در <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی جنوب خاوری فدیشه واقع شده . دامنه و معتدل است و <span class=\"hlight\" dir=\"rtl\">٣٣٤</span> تن سکنه ٔ فارس وبلوچ دارد. آبش از قنات محصولش غلات، شغل اهالی زراعت و راهش مالرو است . (فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282773, 'چاه سالم', '<span class=\"hlight\">چاه سالم .</span> (اِخ ) ده کوچکی است از دهستان آسیاب بخش هندیجان شهرستان خرمشهر که در <span class=\"hlight\" dir=\"rtl\">٥٣</span> هزارگزی شمال باختری هندیجان کنار راه اتومبیل رو بهبهان به خلف آباد واقع شده و <span class=\"hlight\" dir=\"rtl\">٤٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282774, 'چاه سبز', '<span class=\"hlight\">چاه سبز.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) ده کوچکی است از دهستان حاجی آباد ایزد خواست بخش داراب شهرستان فسا که در <span class=\"hlight\" dir=\"rtl\">١٤٤</span> هزارگزی جنوب داراب واقع شده و <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282775, 'چاه ستاره', '<span class=\"hlight\">چاه ستاره .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ )دهی است از دهستان همائی بخش ششتمد شهرستان سبزوار که در <span class=\"hlight\" dir=\"rtl\">٧٠</span> هزارگزی جنوب خاوری ششتمد واقع شده . کوهستانی و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٣٨</span> تن سکنه دارد. آبش از قنات، محصولش غلات، پنبه و زیره . شغل اهالی زراعت و کرباس بافی و راهش مالرو است . (فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282776, 'چاه ستاره جو', '<span class=\"hlight\">چاه ستاره جو.</span> <font color=\"DarkGreen\"><b>[ هَِ س ِ رَ <span class=\"hlight\" dir=\"rtl\">/</span>رِ ]</font></b> (اِ مرکب ) نوعی از رصد است که به عمق شصت گز چاهی کاوند و بالای آن بامی برآرند شصت گز بلند و آن را مشبک ساخته نشینند و کیفیت نجوم و افلاک دریابند. (آنندراج ) (غیاث ). و این مرادف چاه زیچ باشد. (آنندراج ) <span class=\"hlight\">:</span> جدولش رصدبانان را از چاه ستاره جوی بی نیاز ساخته . طغرا (آنندراج ). رجوع به چاه زیچ شود.<br /></font></div>'),
(282777, 'چاه سر', '<span class=\"hlight\">چاه سر.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِ مرکب ) چاه . چاهسار <span class=\"hlight\">:</span> <br />منیژه بیامد بدان چاه سر<br />دوان، خوردنیها گرفته ببر.<br /> <font color=\"Red\">فردوسی .</font><br />از آن چاه سر با دلی پر ز درد<br />دویدم بنزد تو ای نیکمرد.<br /> <font color=\"Red\">فردوسی .</font><br /><BR><font color=\"Blue\">◄</font> سرچاه . لب چاه . دهانه ٔ چاه . <BR><font color=\"Blue\">◄</font> گودالی عمیق . گودی ژرف .<br /></font></div>'),
(282778, 'چاه سرخ', '<span class=\"hlight\">چاه سرخ .</span> <font color=\"DarkGreen\"><b>[ س ُ ]</font></b> (اِخ ) دهی از دهستان احمدی بخش سعادت آباد شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">١٢٠</span> هزارگزی خاور حاجی آباد و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی باختر راه مالرو گلاشکرد به شمیل واقع شده . کوهستانی و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٥٩</span> تن سکنه دارد.آبش از چشمه، محصولش خرما و غلات، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282779, 'چاه سرخی', '<span class=\"hlight\">چاه سرخی .</span> <font color=\"DarkGreen\"><b>[ س ُ ]</font></b> (اِخ ) از متعلقات تون یا طبس است . (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282780, 'چاه سردو', '<span class=\"hlight\">چاه سردو.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔبخش بمپور شهرستان ایرانشهر که در <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزارگزی باخترراه شوسه ٔ بمپور به چاه بهار واقع شده . جلگه، گرمسیرو مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١٢٥</span> تن سکنه دارد. آبش از رودخانه ٔ بمپور، محصولش غلات، ذرت و خرما، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282781, 'چاه سرگاهی', '<span class=\"hlight\">چاه سرگاهی .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) دهی است از دهستان گله دار بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٨١</span> هزارگزی جنوب خاور کنگان، کنار راه فرعی لار به گله دار واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢٢٠</span> تن سکنه دارد. آبش از چاه، محصولش غلات و تنباکو و شغل اهالی زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282782, 'چاه سعید', '<span class=\"hlight\">چاه سعید.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) دهی است از دهستان عشق آباد بخش فدیشه ٔ شهرستان نیشابور که در<span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی جنوب فدیشه واقع شده . دامنه و معتدل است و <span class=\"hlight\" dir=\"rtl\">١١</span> تن سکنه دارد. آبش از قنات، محصولش غلات، شغل اهالی زراعت و مالداری وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282783, 'چاه سفید', '<span class=\"hlight\">چاه سفید.</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) دهی است از دهستان نهارجانات بخش حومه ٔ شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٦٠</span> هزارگزی جنوب خاوری بیرجند واقع شده . دامنه و معتدل است و <span class=\"hlight\" dir=\"rtl\">١١</span> تن سکنه دارد که بشغل زراعت مشغولند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282784, 'چاه سفید', '<span class=\"hlight\">چاه سفید.</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) ده مخروبه ای است از بخش حومه ٔ شهرستان نائین . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282785, 'چاه سمی', '<span class=\"hlight\">چاه سمی .</span> <font color=\"DarkGreen\"><b>[ س ِ ]</font></b> (اِخ ) دهی است از دهستان بهمئی بخش کهکیلویه ٔ شهرستان بهبهان که در <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی شمال باختری لک لک و <span class=\"hlight\" dir=\"rtl\">٥٤</span> هزارگزی خاور راه شوسه ٔ آغاجاری واقع شده و <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282786, 'چاه سهاق', '<span class=\"hlight\">چاه سهاق .</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) دهی است از دهستان رودبار بخش کهنوج شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">١٣٥</span> هزارگزی خاور کهنوج برسر راه بمپور به کهنوج واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه دارد. آبش از قنات، محصولش خرما و غلات است و ساکنین این ده از طایفه ٔ هوت میباشند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282787, 'چاه سوارآقا', '<span class=\"hlight\">چاه سوارآقا.</span> <font color=\"DarkGreen\"><b>[ س َ ]</font></b> (اِخ ) ده کوچکی است از دهستان آباده طشک بخش نی ریز شهرستان فسا که در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی شمال باختر نی ریز واقع شده و <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه دارد که از طایفه ٔ قرائی میباشند و ییلاق و قشلاق میکنند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282788, 'چاه سوخته', '<span class=\"hlight\">چاه سوخته .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) دهی است از دهستان کیذقان بخش ششتمدشهرستان سبزوار که در <span class=\"hlight\" dir=\"rtl\">٢٥</span> هزارگزی جنوب خاوری ششتمد واقع شده . کوهستانی و سردسیر است و<span class=\"hlight\" dir=\"rtl\">١١٥</span> تن سکنه دارد.آبش از قنات، محصولش غلات و پنبه، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282789, 'چاه سون', '<span class=\"hlight\">چاه سون .</span> <font color=\"DarkGreen\"><b>[ س ُ ]</font></b> (اِخ ) دهی است از دهستان زاوه ٔ بخش حومه ٔ شهرستان تربت حیدریه که در <span class=\"hlight\" dir=\"rtl\">٧٢</span> هزارگزی شمال خاوری تربت حیدریه واقع شده . دامنه و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٨٧</span> تن سکنه دارد. آبش از قنات، محصولش غلات و بنشن، شغل اهالی زراعت، گله داری، قالیچه و کرباس بافی وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282790, 'چاه سگک', '<span class=\"hlight\">چاه سگک .</span> <font color=\"DarkGreen\"><b>[ س َ گ َ ]</font></b> (اِخ )دهی است از دهستان طبس مسینا بخش درمیان شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">١٥٤</span> هزارگزی جنوب خاوری درمیان و <span class=\"hlight\" dir=\"rtl\">٤٢</span> هزارگزی خاور درح واقع شده . جلگه و گرمسیر است و جمعیتی ندارد. آبش از چشمه و چاه است و مالداران از آن آب استفاده مینمایند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282791, 'چاه سیاه', '<span class=\"hlight\">چاه سیاه .</span> (اِخ ) «منزلگاهی فیمابین نیشابور و ترشیز <font color=\"DarkGreen\"><b>[ کاشمر ]</font></b>». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282792, 'چاه سید محمد', '<span class=\"hlight\">چاه سید محمد.</span> <font color=\"DarkGreen\"><b>[ س ِی ْ ی ِ م ُ ح َم ْ م َ ]</font></b> (اِخ ) دهی است از دهستان کوهدشت بخش طرهان شهرستان خرم آباد که در <span class=\"hlight\" dir=\"rtl\">١٨</span>هزارگزی جنوب خاوری کوهدشت و <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی جنوب راه شوسه ٔ خرم آباد به کوهدشت واقع شده . کوهستانی، معتدل و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٣٧٠</span> تن سکنه دارد. آبش از چاه، محصولش غلات و لبنیات، شغل اهالی زراعت و گله داری، صنایع دستی زنان بافتن سیاه چادر و راهش مالرو است . ساکنین این ده عموماً از طایفه ٔ قره لیوند هستند و در سیاه چادر زندگی میکنند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282793, 'چاه سیفو', '<span class=\"hlight\">چاه سیفو.</span> (اِخ ) ده کوچکی است از دهستان رودخانه بخش میناب شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">١٠٠</span> هزارگزی شمال باختری میناب و <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی باختر راه مالرو گلاشکرد به میناب واقع شده است و <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282794, 'چاه سیماب', '<span class=\"hlight\">چاه سیماب .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از چاهی که از آنجا سیماب (جیوه، زیبق ) برمی آید. (از آنندراج ) <span class=\"hlight\">:</span> <br />شهسواری از بر ما گشت عنان گردان که شد<br />چاه سیماب، آستین از اشک بی آرام ما.<br /><font color=\"Red\">فطرت (از آنندراج ).</font><br /></font></div>'),
(282795, 'چاه شریف', '<span class=\"hlight\">چاه شریف .</span> <font color=\"DarkGreen\"><b>[ ش َ ]</font></b> (اِخ ) ده کوچکی است از دهستان منوجان بخش کهنوج شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">١٣٠</span> هزارگزی جنوب کهنوج بر سر راه مالرو کهنوج به یابان واقع شده و <span class=\"hlight\" dir=\"rtl\">١٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282796, 'چاه شقوق', '<span class=\"hlight\">چاه شقوق .</span> <font color=\"DarkGreen\"><b>[هَِ ش َ ]</font></b> (اِخ ) چاهی در راه مکه . (آنندراج ). محلی در راه مکه . نام چاهی از چاههای راه مکه <span class=\"hlight\">:</span> <br />بر سر چاه شقوق از تشنگان صف صف چنانک <br />پیش یوسف گرسنه چشمان کنعان دیده اند.<br /><font color=\"Red\">خاقانی .</font><br /></font></div>'),
(282797, 'چاه شور', '<span class=\"hlight\">چاه شور.</span> (اِخ ) ده کوچکی است از دهستان حیات داود بخش گناوه ٔ شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزارگزی شمال گناوه واقع شده و <span class=\"hlight\" dir=\"rtl\">١٥</span> هزار تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282798, 'چاه شور', '<span class=\"hlight\">چاه شور.</span> (اِخ ) دهی است از دهستان دلکان بخش بزمان شهرستان ایرانشهر که در <span class=\"hlight\" dir=\"rtl\">٥٥</span> هزارگزی جنوب باختری بزمان، کنار راه مالرو بمپور به کهنوج واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه دارد. آبش از چاه، محصولش غلات، خرما و لبنیات، شغل اهالی زراعت وگله داری و راهش مالرو است . (از فرهنگ جغرافیایی ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282799, 'چاه شور', '<span class=\"hlight\">چاه شور.</span> (اِخ ) دهی است از دهستان طبس مسینا بخش درمیان شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٨٧</span>هزارگزی خاور درمیان واقع شده . جلگه و گرمسیر است وجمعیتی ندارد. آبش از آب شور چاه است و مالدارها به این محل می آیند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282800, 'چاه شوره', '<span class=\"hlight\">چاه شوره .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) دهی است از دهستان کوهدشت بخش طرهان شهرستان خرم آباد که در <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی جنوب باختری کوهدشت و<span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی جنوب باختری راه فرعی خرم آباد به کوهدشت واقع شده . دامنه، معتدل و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٩٠</span> تن سکنه دارد. آبش از چشمه، محصولش غلات و لبنیات، شغل اهالی زراعت، و گله داری و سیاه چادربافی و راهش مالرو است .ساکنین این ده از طایفه ٔ نورعلی میباشند و در سیاه چادر بسر میبرند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282801, 'چاه شیخ', '<span class=\"hlight\">چاه شیخ .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (اِخ ) دهی است از دهستان تراکمه بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١٣٦</span> هزارگزی جنوب خاور کنگان، کنار راه فرعی لار به گله دار واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٩٨</span> تن سکنه ٔ فارس و ترک دارد. آبش از قنات، محصولش غلات و انار، شغل اهالی زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282802, 'چاه شیرین', '<span class=\"hlight\">چاه شیرین .</span> (اِخ ) دهی است از دهستان لیراوی بخش دیلم شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی جنوب خاور دیلم و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی راه فرعی گچساران به دیلم واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٨٦</span> تن سکنه دارد. آبش از چاه، محصولش غلات، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282803, 'چاه شیرین', '<span class=\"hlight\">چاه شیرین .</span> (اِخ ) دهی است از دهستان حومه ٔ بخش مرکزی شهرستان شیراز که در <span class=\"hlight\" dir=\"rtl\">٢٩</span> هزارگزی جنوب خاور شیراز، کنار راه فرعی شیراز به گشکان واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٨٨</span> تن سکنه دارد. آبش از چاه، محصولش غلات، تنباکو و صیفی شغل اهالی زراعت . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282804, 'چاه طرخ', '<span class=\"hlight\">چاه طرخ .</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ )دهی است از دهستان دستگردان بخش طبس شهرستان فردوس که در <span class=\"hlight\" dir=\"rtl\">٩٠</span> هزارگزی شمال طبس واقع شده . دشت و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٦٨</span> تن سکنه دارد. آبش از قنات، محصولش غلات و خرما، شغل اهالی زراعت است و راه فرعی به شوسه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282805, 'چاه طلا', '<span class=\"hlight\">چاه طلا.</span> <font color=\"DarkGreen\"><b>[ طَ ]</font></b> (اِخ ) دهی است از دهستان خنج بخش مرکزی شهرستان لار که در <span class=\"hlight\" dir=\"rtl\">١٢٦</span> هزارگزی شمال باختر لار، کنار راه فرعی خنج به سیف آباد واقع شده . جلگه، گرمسیرو مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٥٩</span> تن سکنه دارد. آبش از چاه، محصولش غلات و لبنیات، شغل اهالی زراعت گله داری و بافتن قالی و گلیم است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282806, 'چاه طوس', '<span class=\"hlight\">چاه طوس .</span> (اِخ ) دهی است از دهستان خنج بخش مرکزی شهرستان لار که در <span class=\"hlight\" dir=\"rtl\">٩٦</span> هزارگزی باختر لار درجنوب کوه گوکردی واقع شده . دامنه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢٧٦</span> تن سکنه دارد. آبش از قنات و چاه، محصولش غلات، خرما و پنبه، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282807, 'چاه ظلمانی', '<span class=\"hlight\">چاه ظلمانی .</span> <font color=\"DarkGreen\"><b>[ هَِ ظُ ]</font></b> (ترکیب اضافی، اِ مرکب ) کنایه از دنیا.(برهان ) (آنندراج ). دنیا. (انجمن آرا) <span class=\"hlight\">:</span> <br />دلا تا کی در این زندان ظلمت این و آن بینی <br />یکی زین چاه ظلمانی گذر کن تا جهان بینی .<br /> <font color=\"Red\">؟ (از انجمن آرا).</font><br /><BR><font color=\"Blue\">◄</font> کنایه است از قالب آدمی . (برهان ) (آنندراج ). قالب آدمی . (انجمن آرا).<br /></font></div>'),
(282808, 'چاه ظلی', '<span class=\"hlight\">چاه ظلی .</span> <font color=\"DarkGreen\"><b>[ ظِل ْ لی ]</font></b> (اِخ ) دهی است از دهستان پائین ولایت بخش فریمان شهرستان مشهد که در <span class=\"hlight\" dir=\"rtl\">٢٧</span> هزارگزی شمال باختری فریمان واقع شده . دامنه و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٧</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282809, 'چاه عباس', '<span class=\"hlight\">چاه عباس .</span><font color=\"DarkGreen\"><b>[ ع َب ْ با ]</font></b> (اِخ ) ده کوچکی است از دهستان منوجان بخش کهنوج شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">٤٥</span> هزارگزی جنوب باختری کهنوج بر سر راه مالرو کهنوج به رودان واقع شده و <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282810, 'چاه عبدالرحمن', '<span class=\"hlight\">چاه عبدالرحمن .</span> <font color=\"DarkGreen\"><b>[ هَِ ع َ دُرْ رَ ما ]</font></b>(اِخ ) مؤلف فارسنامه ٔ ناصری در فصل «چشمه های مشهورمملکت فارس » چشمه ای را بدین نام اسم برده و نوشته است : «در بلوک آباده ٔ طشتک بمسافت یک فرسخ و نیم شمال قریه ٔ خواجه جمالی در دامنه ٔ کوه خُم چاهی است از سنگ سجیلی که در شیراز سنگ کرشکی گویند و معلوم نیست که خدا آفریده است یا تراشیده اند نزدیک پنج ذرع درازا و چهار ذرع گودی آن است . در نزدیکی نوروز در سالهای خشک به اندازه ٔ پنج سنگ آسیاب گردان آب از دهن چاه درآید و در سالهای تر گاهی آب این چاه به اندازه ٔ پنج شش ذرع جستن کند و آب آن آنچه از زراعت زیاد آید بدریاچه ٔ بختگان رود. (از فارسنامه ٔ ناصری ص <span class=\"hlight\" dir=\"rtl\">٣١٩</span>).<br /></font></div>'),
(282811, 'چاه عرب', '<span class=\"hlight\">چاه عرب .</span> <font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) منزلی در ناحیه ٔ خوارزم که سلطان تکش در آن محل بمرض خناق درگذشت . مؤلف حبیب السیر نویسد: «... و کیفیت فوت تکش خان چنان بود که در شهور سنه ٔ ست و ستین وخمسمائه بمرض خناق گرفتار گشته بسعی اطباء بلکه بمشیت ایزد تعالی جل جلاله آن مرض زایل شده سلطان تکش درایام نقاهت بخیال استیصال ملاحده از خوارزم نهضت فرمود و هر چند طبیبان و نیک اندیشان گفتند چند روز دیگرحرکت نمیباید کرد تا صحت کامل شامل حال وجود شریف پادشاه عادل شود بسمع رضا نشنود و چون به منزل چاه عرب رسید مرض تکش عود کرده پادشاه طبیعت دست تصرف از تدبیر امور بدن کوتاه ساخته تکش خان روی بجهان جاودانی آورد...» (از تاریخ حبیب السیر جزو چهارم ص <span class=\"hlight\" dir=\"rtl\">٤٢٤</span>).<br /></font></div>'),
(282812, 'چاه عربی', '<span class=\"hlight\">چاه عربی .</span><font color=\"DarkGreen\"><b>[ ع َ رَ ]</font></b> (اِخ ) دهی است از دهستان عیسوند بخش برازجان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی جنوب باختر برازجان و یک هزارگزی شوسه ٔ برازجان به بوشهر واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢٠٢</span> تن سکنه دارد. آبش از چاه، محصولش غلات، تنباکو و خرما، شغل اهالی زراعت و راهش فرعی است . (فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282813, 'چاه عزیزخان', '<span class=\"hlight\">چاه عزیزخان .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) یکی از منازل عرض راه فراه است در خاک سیستان، بسمت برج عالمدار که آن را شیرده هم مینامند در طرف شرقی دریاچه ٔ سیستان واقع است . (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282814, 'چاه علی', '<span class=\"hlight\">چاه علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) ده کوچکی است از دهستان بنت بخش نیکشهر شهرستان چاه بهار که در <span class=\"hlight\" dir=\"rtl\">٤٥</span> هزارگزی باختر نیکشهر بر کنار راه مالرو نیکشهر به بنت واقع شده و <span class=\"hlight\" dir=\"rtl\">٤٥</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282815, 'چاه علی', '<span class=\"hlight\">چاه علی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از دهستان تراکمه بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١١٥</span> هزارگزی جنوب خاور کنگان و یک هزارگزی جنوب خاور راه فرعی لار بگله دار واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آبش از چشمه محصولش غلات و انار، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282816, 'چاه عینی', '<span class=\"hlight\">چاه عینی .</span> <font color=\"DarkGreen\"><b>[ ع َ ]</font></b> (اِخ ) دهی است از دهستان علامرودشت بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٩٥</span> هزارگزی جنوب خاور کنگان بر کنار راه مالرو اشکنان به پس رودک واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٥٤٨</span> تن سکنه دارد. آبش از چاه، محصولش غلات، خرما و تنباکو و شغل اهالی زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282817, 'چاه غبغب', '<span class=\"hlight\">چاه غبغب .</span> <font color=\"DarkGreen\"><b>[ هَِ غ َ غ َ ]</font></b> (ترکیب اضافی، اِ مرکب ) چاه ذقن و چاه زنخ و چاه زنخدان . (آنندراج ). کنایه از گوی خرد که در زنخدان و غبغب خوبان می باشد. (آنندراج ). رجوع به چاه ذقن و چاه زنخ و چاه زنخدان شود.<br /></font></div>'),
(282818, 'چاه غلامعلی', '<span class=\"hlight\">چاه غلامعلی .</span> <font color=\"DarkGreen\"><b>[ غ ُ ع َ ]</font></b> (اِخ ) دهی است از دهستان حصن بخش زرند شهرستان کرمان که در <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزارگزی جنوب باختری زرند و <span class=\"hlight\" dir=\"rtl\">٢</span>هزارگزی باختر راه مالرو زرند به رفسنجان واقع شده .جلگه و معتدل است و <span class=\"hlight\" dir=\"rtl\">٨٣</span> تن سکنه دارد. آبش از قنات، محصولش غلات، حبوبات، پسته و پنبه، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282819, 'چاه فالیز', '<span class=\"hlight\">چاه فالیز.</span> (اِخ ) دهی است از دهستان لب کویر بخش بجستان شهرستان گناباد که در <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارگزی شمال گناباد بر سر راه مالرو عمومی مرندیز به بجستان واقعشده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٩٢</span> تن سکنه دارد، آبش از قنات، محصولش غلات، پنبه و زعفران، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282820, 'چاه قاسم', '<span class=\"hlight\">چاه قاسم .</span> <font color=\"DarkGreen\"><b>[س ِ ]</font></b> (اِخ ) قریه ای از توابع بلوک گله دار فارس، طول این بلوک از مشرق به مغرب تقریباً بیست و پنج فرسخ عرض بتفاوت یعنی از شش فرسخ است و در اکثر قرای این بلوک مسجد ساخته اند. (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282821, 'چاه قدمان', '<span class=\"hlight\">چاه قدمان .</span> <font color=\"DarkGreen\"><b>[ ق َدَ ]</font></b> (اِخ ) دهی است از دهستان گله دار بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٧١</span> هزارگزی جنوب خاور کنگان و <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی شمال راه مالرو پس رودک به بیرم واقع شده . جلگه، گرمسیر و مالاریائی است و صد تن سکنه دارد. آبش ازچاه، محصولش غلات، تنباکو و پیاز، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282822, 'چاه قربان', '<span class=\"hlight\">چاه قربان .</span> <font color=\"DarkGreen\"><b>[ ق ُ ]</font></b> (اِخ ) دهی از دهستان دلکان بخش بزمان شهرستان ایرانشهر که در <span class=\"hlight\" dir=\"rtl\">٥٥</span> هزارگزی جنوب بزمان بر کنار راه مالرو بمپور به دلکان واقع شده . کوهستانی، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٧٥</span>تن سکنه دارد. آبش از چشمه، محصولش لبنیات، شغل اهالی گله داری و راهش مالرو است . اهالی این ده از طایفه ٔ بامری میباشند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282823, 'چاه قلعه', '<span class=\"hlight\">چاه قلعه .</span> <font color=\"DarkGreen\"><b>[ ق َ]</font></b> (اِخ ) دهی است از دهستان شمیل بخش مرکزی شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">٤٨</span> هزارگزی شمال خاوری بندرعباس بر سر راه فرعی میناب به بندرعباس واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٦٢</span> تن سکنه دارد. آبش از چاه، محصولش خرماو غلات و شغل اهالی زراعت است . مزارع چاه فلاه و مشکی جزء این ده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282824, 'چاه قلعه زری', '<span class=\"hlight\">چاه قلعه زری .</span> <font color=\"DarkGreen\"><b>[ ق َ ع َ زَ]</font></b> (اِخ ) شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">١١٤</span> هزارگزی باختر شوسف و <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارگزی جنوب باختری بصیران واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٣</span> تن سکنه دارد. شغل اهالی زراعت و مالداری و راهش مالرو است و در فصل بهار مالدارها به این محل می آیند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282825, 'چاه لاکی', '<span class=\"hlight\">چاه لاکی .</span> (اِخ ) ده کوچکی است از دهستان سیریک بخش میناب شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">٩٣</span> هزارگزی جنوب میناب واقع شده و <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282826, 'چاه لب گاه', '<span class=\"hlight\">چاه لب گاه .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) ده کوچکی است از دهستان زیر کوه بخش قاین شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">١٨٢</span> هزارگزی جنوب خاوری قاین واقع شده . جلگه و گرمسیر است و<span class=\"hlight\" dir=\"rtl\">٩</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282827, 'چاه لیگان', '<span class=\"hlight\">چاه لیگان .</span> (اِخ )ده کوچکی است از دهستان سبزواران بخش مرکزی شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">٤٨</span> هزارگزی جنوب خاوری سبزواران و یک هزارگزی باختر راه عمومی دوساری به کهنوج واقع شده و <span class=\"hlight\" dir=\"rtl\">٣٥</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282828, 'چاه مبارک', '<span class=\"hlight\">چاه مبارک .</span> <font color=\"DarkGreen\"><b>[ م ُ رَ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد «قریه ای است از توابع بلوک لارستان فارس » (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(282829, 'چاه مبارک', '<span class=\"hlight\">چاه مبارک .</span> <font color=\"DarkGreen\"><b>[ م ُ رَ ]</font></b> (اِخ ) دهی است از دهستان تمیمی بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٩٣</span> هزارگزی جنوب خاور کنگان، کنار راه شوسه ٔ سابق کنگان به لنگه واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٤٢٨</span> تن سکنه دارد. آبش از چاه، محصولش غلات، خرما و تنباکو و شغل اهالی زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282830, 'چاه مبرز', '<span class=\"hlight\">چاه مبرز.</span> <font color=\"DarkGreen\"><b>[ هَِ م َ رَ ]</font></b> (ترکیب اضافی، اِ مرکب ) نوعی از مستراح که آن را در هند «متداس » گویند. (آنندراج ). چاه مستراح . چاه مبال <span class=\"hlight\">:</span> <br />از بهر اخ و تف تو چاه مبرز<br />چون چاه زنخ پیش دهن میباید.<br /><font color=\"Red\">سلیم (از آنندراج ).</font><br /></font></div>'),
(282831, 'چاه متک', '<span class=\"hlight\">چاه متک .</span> <font color=\"DarkGreen\"><b>[ م َ ت َ ]</font></b> (اِخ ) دهی است از دهستان رباطات بخش خرانق شهرستان یزد که در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی باختر خرانق و <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی راه خرانق به اشکذر واقعشده . کوهستانی، معتدل و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١٢٨</span> تن سکنه دارد. آبش از قنات، محصولش غلات، شغل اهالی زراعت و راهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282832, 'چاه محمد حاجی', '<span class=\"hlight\">چاه محمد حاجی .</span> <font color=\"DarkGreen\"><b>[ م ُ ح َم ْ م َ ]</font></b> (اِخ ) دهی است از دهستان گله دار بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٧٠</span> هزارگزی جنوب خاور کنگان، کنار راه فرعی لار به گله دار واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١٤٠</span> تن سکنه دارد. آبش از چاه، محصولش غلات و تنباکو و شغل اهالی زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282833, 'چاه مرغ', '<span class=\"hlight\">چاه مرغ .</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (اِخ ) دهی است از دهستان احمدی بخش سعادت آباد شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">١٠٨</span> هزارگزی خاور حاجی آباد و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی شمال راه میناب به فارغان واقع شده . کوهستانی و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٥٩</span> تن سکنه دارد.آبش از قنات، محصولش خرما و غلات، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282834, 'چاه مزر', '<span class=\"hlight\">چاه مزر.</span> <font color=\"DarkGreen\"><b>[ م َ زَ ]</font></b> (اِخ ) دهی است از دهستان نهارجانات بخش حومه ٔ شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٤٧</span> هزارگزی جنوب خاوری بیرجند واقع شده . دامنه و گرمسیر است و<span class=\"hlight\" dir=\"rtl\">٦</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282835, 'چاه مزنگان', '<span class=\"hlight\">چاه مزنگان .</span> <font color=\"DarkGreen\"><b>[ م َ زَ ]</font></b> (اِخ ) ده کوچکی از دهستان سبزواران بخش مرکزی شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">٣٢</span> هزارگزی شمال باختری سبزواران و <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی باختر راه دلفارد به سبزواران واقع شده و <span class=\"hlight\" dir=\"rtl\">٢٩</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282836, 'چاه مزنگان', '<span class=\"hlight\">چاه مزنگان .</span> <font color=\"DarkGreen\"><b>[ م َ زَ ]</font></b> (اِخ ) دهی است از دهستان دلفرد بخش ساردوئیه شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">٩٨</span> هزارگزی جنوب خاوری ساردوئیه و <span class=\"hlight\" dir=\"rtl\">١٠</span>هزارگزی باختر راه مالرو جیرفت به ساردوئیه واقع شده، کوهستانی و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٤٥</span> تن سکنه دارد. آبش ازقنات، محصولش غلات، حبوبات و خرما شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282837, 'چاه مسلم', '<span class=\"hlight\">چاه مسلم .</span> <font color=\"DarkGreen\"><b>[ م ُ ل ِ ]</font></b> (اِخ ) دهی است از دهستان مرزوقی بخش لنگه ٔ شهرستان لار که در <span class=\"hlight\" dir=\"rtl\">٤٢</span> هزارگزی شمال باختر لنگه واقع شده . دامنه، گرمسیر و مالاریایی است و <span class=\"hlight\" dir=\"rtl\">١٠٢٩</span> تن سکنه دارد. آبش از چاه و باران، محصولش غلات، خرما و سبزیجات، شغل اهالی زراعت و راهش فرعی است . پاسگاه ژاندارمری هم دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282838, 'چاه مسیله', '<span class=\"hlight\">چاه مسیله .</span> <font color=\"DarkGreen\"><b>[ م َ ل َ ]</font></b> (اِخ ) دهی است از دهستان جلگه ٔ زوزن بخش خواف شهرستان تربت حیدریه که در <span class=\"hlight\" dir=\"rtl\">١٣٠</span> هزارگزی جنوب باختری خواف و <span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی جنوب راه مالرو عمومی زوزن به چاه باغ بخشی واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٣٤٠</span> تن سکنه دارد. آبش از قنات و چاه، محصولش غلات، شغل اهالی زراعت، گله داری و قالیچه بافی وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282839, 'چاه مشک', '<span class=\"hlight\">چاه مشک .</span> <font color=\"DarkGreen\"><b>[ م ُ ]</font></b> (اِخ ) دهی است از دهستان نیم بلوک بخش قاین شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٤٠</span> هزارگزی شمال قاین واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٨</span> تن سکنه دارد. آبش از چاه محصولش غلات، شغل اهالی زراعت و مالداری وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282840, 'چاه مضراب', '<span class=\"hlight\">چاه مضراب .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) دهی است از دهستان طبس مسینا بخش درمیان شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٤٠</span> هزارگزی خاور دستگرد واقع شده .جلگه و گرمسیر است و جمعیتی ندارد و مالدارها از آن استفاده میکنند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282841, 'چاه مطار', '<span class=\"hlight\">چاه مطار.</span> <font color=\"DarkGreen\"><b>[ م َ ]</font></b> (اِخ ) دهی است از دهستان جلگه زوزن بخش خواف شهرستان تربت حیدریه که در <span class=\"hlight\" dir=\"rtl\">٩٠</span> هزارگزی جنوب باختری قصبه رود و <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی باختر راه شوسه ٔ عمومی قصبه رود بقاین واقع شده . دامنه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٢٢</span> تن سکنه دارد. آبش از قنات، محصولش غلات، شغل اهالی زراعت، گله داری و قالیچه بافی وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282842, 'چاه مغ', '<span class=\"hlight\">چاه مغ.</span> <font color=\"DarkGreen\"><b>[ هَِ م َ ]</font></b> (ترکیب وصفی، اِ مرکب ) چاه عمیق . (آنندراج ). چاه گود. چاه دورتک . چاه ژرف .<br /></font></div>'),
(282843, 'چاه مقنع', '<span class=\"hlight\">چاه مقنع.</span> <font color=\"DarkGreen\"><b>[ هَِ م ُ ق َن ْ ن َ ]</font></b>(اِخ ) چاهی است که ابن مقنع بعلم سحر از آنجا ماهی برمی آورد که چهار فرسخ پرتو می افکند. (برهان ). چاهی که ابن مقنع حکیم در شهر کش به نیرنجات راست کرده بود و هر شب ماهی از آن چاه برمی آمد و روشنایی آن تا چار فرسخ میرسید. (آنندراج ). چاه نخشب . (آنندراج ) (فرهنگ نظام ) <span class=\"hlight\">:</span> «مقنع بیرون آمد بماوراءالنهر <font color=\"DarkGreen\"><b>[ بزمان خلافت مهدی عباسی ]</font></b> و دعویی کرد که اندر مسلمانی کس نکرده بود، و نام او هاشم بن الحکیم <font color=\"DarkGreen\"><b>[ در متن : الحکم ]</font></b> بود و جادوی عظیم داشت، مقنعی بر روی بسته داشتی و دعوی خدایی کردی ... و از این سبب او را مقنع خواندندی و آن است که چاه ساخت بحکمت و سیماب در آن ریخت با اخلاطهایی که داشت، تا عکس آن بر هوا چنان مینمود که ماهی بر آسمان همی تابد، و شرح کار و شعبده های او دراز است » (مجمل التواریخ والقصص ص <span class=\"hlight\" dir=\"rtl\">٣٣٤</span>-<span class=\"hlight\" dir=\"rtl\">٣٣٥</span>). رجوع به چاه نخشب شود.<br /></font></div>'),
(282844, 'چاه ملا', '<span class=\"hlight\">چاه ملا.</span> <font color=\"DarkGreen\"><b>[ م ُل ْ لا ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد «از مزارع میان ولایت حول و حوش شهر مشهد مقدس است که از آب قنات مشروب میشود و هوایی معتدل و شش خانوار سکنه دارد. (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>) و درفرهنگ جغرافیایی آمده است : «دهی است از دهستان میان ولایت بخش حومه ٔ شهرستان مشهد که در <span class=\"hlight\" dir=\"rtl\">٤٠</span> هزارگزی شمال باختری مشهد بین کشف رود و راه شوسه ٔ مشهد به قوچان واقع شده . جلگه و معتدل است و <span class=\"hlight\" dir=\"rtl\">٤٥</span> تن سکنه دارد. آبش از چشمه، محصولش غلات، شغل اهالی زراعت و مالداری و راهش مالرو است ». (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282845, 'چاه ملا احمد', '<span class=\"hlight\">چاه ملا احمد.</span> <font color=\"DarkGreen\"><b>[ م ُل ْ لا اَ م َ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش مسجد سلیمان شهرستان اهواز که در <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی باختر مسجد سلیمان، کنار راه اهواز به مسجد سلیمان واقع شده . کوهستانی و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه دارد. آبش از چشمه وآب لوله ای که شرکت نفت از رود کارون کشیده، محصولش غلات، شغل اهالی کارگری شرکت نفت، زراعت و گله داری و راهش اتومبیل رواست . ساکنین این ده از طایفه ٔ هفت لنگ بختیاری میباشند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282846, 'چاه ملک', '<span class=\"hlight\">چاه ملک .</span> <font color=\"DarkGreen\"><b>[ م َ ل ِ ]</font></b> (اِخ ) ده کوچکی است از دهستان جندق و بیابانک بخش خور بیابانک شهرستان نائین که در <span class=\"hlight\" dir=\"rtl\">٣٥</span> هزارگزی باختر خور، کنار راه جندق بخور واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٨٦</span> تن سکنه دارد. آبش از چشمه، محصولش غلات، شغل اهالی زراعت، صنایعدستی زنان کرباس بافی و راهش فرعی است . دبستان و صندوق پست هم دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282847, 'چاه مورتین', '<span class=\"hlight\">چاه مورتین .</span> (اِخ ) ده کوچکی است از دهستان حومه بخش مهریز شهرستان یزد که در <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی جنوب باختر مهریزو <span class=\"hlight\" dir=\"rtl\">١</span> هزارگزی خاور راه فخرآباد به سریزد واقع شده . جلگه و معتدل است و <span class=\"hlight\" dir=\"rtl\">٦٣</span> تن سکنه دارد. آبش از قنات، محصولش غلات، شغل اهالی زراعت، صنایع دستی زنان نساجی وراهش فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282848, 'چاه موشی', '<span class=\"hlight\">چاه موشی .</span> (اِخ ) دهی است از دهستان شبانکاره بخش برازجان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٢٤</span> هزارگزی شمال باختر برازجان و <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی باختر رودخانه ٔ شاپور واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن سکنه دارد. آبش از چاه، محصولش غلات و خرما، شغل اهالی زراعت و راهش فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282849, 'چاه موک', '<span class=\"hlight\">چاه موک .</span> (اِخ ) ده کوچکی است از دهستان فنوج بخش بمپور شهرستان ایران شهر که در <span class=\"hlight\" dir=\"rtl\">١٣٢</span> هزارگزی جنوب باختری بمپور و<span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی جنوب راه مالرو فنوج به رمشک واقع شده و <span class=\"hlight\" dir=\"rtl\">٤٥</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282850, 'چاه میله', '<span class=\"hlight\">چاه میله .</span> <font color=\"DarkGreen\"><b>[ ل َ ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش قاین شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٧١</span> هزارگزی شمال خاور قاین واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٩١</span> تن سکنه دارد. آبش از قنات، محصولش غلات و شلغم، شغل اهالی زراعت، مالداری و قالیچه بافی وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282851, 'چاه مینا', '<span class=\"hlight\">چاه مینا.</span> (اِخ ) ده کوچکی است از دهستان خنج بخش مرکزی شهرستان لار که در <span class=\"hlight\" dir=\"rtl\">١٠٨</span> هزارگزی باختر لار و جنوب فلات دنک واقع شده و <span class=\"hlight\" dir=\"rtl\">١٦</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282852, 'چاه نخشب', '<span class=\"hlight\">چاه نخشب .</span> <font color=\"DarkGreen\"><b>[هَِ ن َ ش َ ]</font></b> (اِخ ) چاه مقنع. (آنندراج ). چاهی که از آن المقنع ماه مصنوعی بیرون می آورده . (فرهنگ نظام ). رجوع به چاه مقنع شود.<br /></font></div>'),
(282853, 'چاه نرم', '<span class=\"hlight\">چاه نرم .</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) ده مخروبه ای است از بخش حومه ٔشهرستان نائین . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282854, 'چاه نسر', '<span class=\"hlight\">چاه نسر.</span> <font color=\"DarkGreen\"><b>[ن َ ]</font></b> (اِخ ) دهی است از دهستان عشق آباد بخش فدیشه ٔ شهرستان نیشابور که در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی جنوب فدیشه واقع شده . جلگه و معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٧٧</span> تن سکنه دارد. آبش از قنات . محصولش غلات و تریاک، شغل اهالی زراعت و مالداری وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282855, 'چاه نسیان', '<span class=\"hlight\">چاه نسیان .</span> <font color=\"DarkGreen\"><b>[ هَِ ن ِ ]</font></b> (ترکیب اضافی، اِ مرکب ) چاه خراب و بی آب . (آنندراج ) (غیاث ). چاه خموشان . (آنندراج ). چاه فراموشان . (آنندراج ) <span class=\"hlight\">:</span> <br />از مروت نیست تا لب تشنگان را سوختن <br />آخر آن چاه زنخدان چاه نسیان میشود.<br /><font color=\"Red\">صائب (از آنندراج ).</font><br /></font></div>'),
(282856, 'چاه نفت', '<span class=\"hlight\">چاه نفت .</span> <font color=\"DarkGreen\"><b>[ هَِ ن َ ]</font></b> (ترکیب اضافی، اِ مرکب ) چاهی که از آن نفت بیرون آید. چاهی که از آن نفت استخراج شود. چشمه ٔ نفت . معدن نفت . چاه نفت خیز.<br /></font></div>'),
(282857, 'چاه نمک', '<span class=\"hlight\">چاه نمک .</span> <font color=\"DarkGreen\"><b>[ ن َ م َ ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش قاین شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٥٩</span> هزارگزی شمال قاین واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٠٧</span> تن سکنه دارد. آبش از قنات، محصولش غلات و شلغم، شغل اهالی زراعت، مالداری و قالیچه بافی وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282858, 'چاه نهر', '<span class=\"hlight\">چاه نهر.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) دهی است از دهستان حاجی آباد ایزدخواست بخش داراب شهرستان فسا که در <span class=\"hlight\" dir=\"rtl\">١٤٤</span> هزارگزی جنوب خاور داراب، در دشت ایزدخواست واقعشده . گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه ٔ فارس و عرب دارد. آبش از چاه، محصولش غلات، لبنیات و پشم و پوست، شغل اهالی زراعت و گله داری، صنعتشان قالی بافی وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282859, 'چاه نو', '<span class=\"hlight\">چاه نو.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) نام محلی کنار راه نائین و یزد، میان بم بیز و عقدا در <span class=\"hlight\" dir=\"rtl\">٥٥٢١٠٠</span> گزی تهران .<br /></font></div>'),
(282860, 'چاه نو بالا', '<span class=\"hlight\">چاه نو بالا.</span> <font color=\"DarkGreen\"><b>[ ن َ ]</font></b> (اِخ ) دهی است از دهستان تراکمه بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١١٧</span> هزارگزی جنوب خاور کنگان و<span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی شمال راه فرعی لار به گله دار واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٧٧</span> تن سکنه دارد. آبش از قنات، محصولش غلات، انار و پیاز، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282861, 'چاه نیمه', '<span class=\"hlight\">چاه نیمه .</span> <font color=\"DarkGreen\"><b>[ م ِ ]</font></b> (اِخ ) دهی است از دهستان فاروئی بخش شیب آب شهرستان زابل که در <span class=\"hlight\" dir=\"rtl\">٢١</span> هزارگزی خاور سکوهه، نزدیک مرز افغانستان واقع شده . جلگه و معتدل است و <span class=\"hlight\" dir=\"rtl\">٩٠</span> تن سکنه دارد. آبش از رودخانه ٔ هیرمند، محصولش غلات، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282862, 'چاه هیزمی', '<span class=\"hlight\">چاه هیزمی .</span> <font color=\"DarkGreen\"><b>[ زُ ]</font></b> (اِخ ) دهی است از دهستان عشق آباد بخش فدیشه ٔ شهرستان نیشابور که در <span class=\"hlight\" dir=\"rtl\">١٤</span> هزارگزی جنوب فدیشه واقع شده . جلگه و معتدل است و <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد. آبش از قنات، محصولش غلات، شغل اهالی زراعت و مالداری و راهش مالرو است . اهالی این ده چادرنشین اند و گاهی باطراف ییلاق قشلاق میکنند. (از فرهنگ جغرافیایی ایران، ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282863, 'چاه وشی جنوبی', '<span class=\"hlight\">چاه وشی جنوبی .</span> <font color=\"DarkGreen\"><b>[ وُ ج ُ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش خورموج شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی باختر خورموج، در خاور کوه مند واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٦٠</span> تن سکنه دارد.آبش از چاه، محصولش غلات و تنباکو، شغل اهالی زراعت و راهش فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282864, 'چاه وشی شمالی', '<span class=\"hlight\">چاه وشی شمالی .</span> <font color=\"DarkGreen\"><b>[ وُ ش ِ ]</font></b> (اِخ ) دهی است از دهستان حومه ٔ بخش خورموج شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی باختر خورموج، در خاور کوه مند واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٤٠٠</span> تن سکنه دارد. آبش از چاه محصولش غلات و تنباکو، شغل اهالی زراعت و راهش فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282865, 'چاه پانو', '<span class=\"hlight\">چاه پانو.</span> (اِخ ) دهی از دهستان مرکزی بخش قاین شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٥٠</span> هزارگزی شمال خاوری قاین، بر سر راه مالرو عمومی بزن آباد بجنگل واقع شده است . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٦٣</span> تن سکنه دارد. آبش آب شورچاه، محصولش غلات، شغل اهالی زراعت و قالیچه بافی و راهش مالرو است . در فصل بهار مالدارها از اطراف به این محل میایند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282866, 'چاه پست', '<span class=\"hlight\">چاه پست .</span> <font color=\"DarkGreen\"><b>[ هَِ پ َ ]</font></b> (اِ مرکب ) کنایه از دنیا باشد. (برهان ) (آنندراج ). عالم . (ناظم الاطباء).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(282867, 'چاه پهن', '<span class=\"hlight\">چاه پهن .</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (اِخ ) دهی است از دهستان بردخون بخش خورموج شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١٠٨</span> هزارگزی جنوب خورموج، کنار شوسه ٔ سابق بوشهر به لنگه واقع شده است . از نقاط ساحلی، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٦٢</span> تن سکنه دارد. آبش از چاه، محصولش غلات و خرما و شغل اهالی زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282868, 'چاه پهن', '<span class=\"hlight\">چاه پهن .</span> <font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (اِخ ) دهی است از دهستان لاور کنگان بخش خورموج شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٦٦</span> هزارگزی جنوب باختر خورموج، در باختر کوه مند واقع شده است . از نقاط ساحلی دریا، گرمسیر و مالاریائی است و<span class=\"hlight\" dir=\"rtl\">١٤٢</span> تن سکنه دارد. آبش از چاه، محصولش غلات و خرما، شغل اهالی زراعت و ماهیگیری و راهش راه شوسه سابق بوشهر به لنگه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282869, 'چاه پهن', '<span class=\"hlight\">چاه پهن .</span><font color=\"DarkGreen\"><b>[ پ َ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: قریه ای است از قرای دشتی فارس . (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٢</span>).<br /></font></div>'),
(282870, 'چاه پوخان', '<span class=\"hlight\">چاه پوخان .</span> (اِخ ) ده کوچکی است از دهستان خانکوک بخش حومه ٔ شهرستان فردوس که در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی باختر فردوس واقع شده، جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٨</span> تن سکنه دارد. آبش از چاه و آب چاه آن شور است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282871, 'چاه پوز', '<span class=\"hlight\">چاه پوز.</span> (اِ مرکب ) قلابی باشد که بدان چیزی که بچاه افتد برآرند. (برهان ) (آنندراج ). مؤلف برهان و صاحب آنندراج ذیل این لغت نویسند: «بجای بای فارسی یای حطی نیز آمده است و این اصح است چه یوز بمعنی تفحص و تجسس باشد. (برهان ) (آنندراج ). رجوع به چاهیوز شود.<br /></font></div>'),
(282872, 'چاه پیر', '<span class=\"hlight\">چاه پیر.</span> (اِخ ) دهی است از دهستان حومه ٔبخش اهرم شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١٤</span> هزارگزی شمال اهرم و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی خاور کوه قلعه دختر واقع شده است . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٣٧٤</span> تن سکنه دارد. آبش ازچاه، محصولش غلات، خرما و تنباکو، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282873, 'چاه پیز', '<span class=\"hlight\">چاه پیز.</span> (اِخ ) ده کوچکی است از دهستان حومه بخش بمپور شهرستان ایرانشهر که در <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی جنوب بمپور و<span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی جنوب شوسه ٔ بمپور به چاه بهار واقع شده و <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282874, 'چاه چاخو', '<span class=\"hlight\">چاه چاخو.</span> (اِخ ) ده کوچکی است از دهستان مؤمن آباد بخش درمیان شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٣٨</span> هزارگزی جنوب باختری در میان و <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی باختر شوسه ٔ عمومی بیرجند بزاهدان واقع شده . جلگه و گرمسیر است و<span class=\"hlight\" dir=\"rtl\">٩</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282875, 'چاه چاه ورد', '<span class=\"hlight\">چاه چاه ورد.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِخ ) ده کوچکی است از دهستان بیرم بخش گاوبندی شهرستان لار که در <span class=\"hlight\" dir=\"rtl\">٨٧</span> هزارگزی شمال خاور گاوبندی واقع شده و <span class=\"hlight\" dir=\"rtl\">٤٧</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282876, 'چاه چراغ', '<span class=\"hlight\">چاه چراغ .</span> <font color=\"DarkGreen\"><b>[ چ ِ ]</font></b> (اِخ ) دهی است از دهستان سراب دره بخش چگنی شهرستان خرم آباد که در<span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی خاور سراب دره و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی شمال راه شوسه ٔ خرم آباد به کوهدشت واقع شده، جلگه، معتدل و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٧٢</span> تن سکنه لر و فارس دارد. آبش از چشمه ها، محصولش غلات، حبوبات و لبنیات، شغل اهالی زراعت و گله داری و صنایع دستی زنان بافتن سیاه چادر است . راهش اتومبیل رو است و ساکنین ده از طایفه بهرامی بوده عموماً چادرنشین اند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282877, 'چاه چهل گزی', '<span class=\"hlight\">چاه چهل گزی .</span> <font color=\"DarkGreen\"><b>[ چ ِ هَِ گ َ ]</font></b> (اِخ ) ده کوچکی است از دهستان گندمان، بخش بروجن شهرستان شهرکرد که در <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی راه پل کره به بروجن واقع شده، کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282878, 'چاه چو چو', '<span class=\"hlight\">چاه چو چو.</span> (اِخ ) دهی است از دهستان نهبندان بخش شوسف شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی خاور شوسف و <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی جنوب حسین آباد واقع شده، دامنه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه دارد. آبش از قنات، محصولش لبنیات و راهش مالرو است . در فصل بهار مالدارها به این محل میایند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282879, 'چاه کج', '<span class=\"hlight\">چاه کج .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش قاین شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٥٣</span> هزارگزی شمال خاوری قاین برسر راه بزن آباد به جنگل واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٥٤</span> تن سکنه دارد. آبش از قنات، محصولش غلات، شلغم و چغندر، شغل اهالی زراعت، مالداری و قالیچه بافی وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282880, 'چاه کجی', '<span class=\"hlight\">چاه کجی .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) دهی است از دهستان جلگه ٔ زوزن بخش خواف شهرستان تربت حیدریه که در <span class=\"hlight\" dir=\"rtl\">١١٨</span> هزارگزی جنوب باختری قصبه رود و <span class=\"hlight\" dir=\"rtl\">١٤</span> هزارگزی جنوب راه مالرو عمومی زوزن به چاه باغ بخشی واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٥٦</span>تن سکنه دارد. آبش از قنات و چاه، محصولش غلات، پنبه و لبنیات، شغل اهالی زراعت، مالداری و قالیچه بافی وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282881, 'چاه کجی', '<span class=\"hlight\">چاه کجی .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش قاین شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٨١</span> هزارگزی شمال خاوری قاین و <span class=\"hlight\" dir=\"rtl\">٣٧</span>هزارگزی شمال خاوری راه اتومبیل رو قاین به رشخوار واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٨٩</span> تن سکنه دارد. آبش از قنات، محصولش غلات، شغل اهالی زراعت، مالداری و قالیچه بافی و راهش مالرو است . در تابستان مالدارها به این محل می آیند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282882, 'چاه کز', '<span class=\"hlight\">چاه کز.</span> <font color=\"DarkGreen\"><b>[ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد «یکی از منازل عرض راه هرات به قندهار است که در خاک افغانستان، در چهارده فرسخی فراه و سمت جنوب شرقی آن واقع شده . آبادانی ندارد، هوایش در تابستان بشدت گرم میشود و در سنوات خشکسالی شدت حرارت هوا و وزش باد سام مسافرین را تلف میکند وآبش تلخ و شور است » (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282883, 'چاه کز', '<span class=\"hlight\">چاه کز.</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ )ده کوچکی است از دهستان آباده ٔ طشتک بخش نی ریز شهرستان فسا که در <span class=\"hlight\" dir=\"rtl\">٣٦</span> هزارگزی شمال باختری نی ریز واقع شده و <span class=\"hlight\" dir=\"rtl\">١٨</span> تن سکنه دارد که از طایفه ٔ قرائی میباشند و ییلاق قشلاق میکنند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282884, 'چاه کش', '<span class=\"hlight\">چاه کش .</span> <font color=\"DarkGreen\"><b>[ هَِ ک َ ]</font></b> (اِخ ) چاهی به نخشب که حکیم بن عطا از آن ماهی برآورد. رجوع به حکیم بن عطا و ماه سیام و ماه کاشغر و ماه کش و کش شود.<br /></font></div>'),
(282885, 'چاه کفتری', '<span class=\"hlight\">چاه کفتری .</span> <font color=\"DarkGreen\"><b>[ ک َ ت َ ]</font></b> (اِخ ) دهی است از دهستان فریمان بخش فریمان شهرستان مشهد که در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی شمال خاوری فریمان و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی خاور شوسه ٔ قدیمی مشهد به تربت جام واقع شده . کوهپایه و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٢٣٦</span> تن سکنه دارد.آبش از قنات، محصولش غلات و بنشن، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282886, 'چاه کمال', '<span class=\"hlight\">چاه کمال .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) دهی است از دهستان تراکمه بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١١٤</span> هزارگزی جنوب خاور کنگان و یک هزارگزی باختر راه فرعی لار بگله دار واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٣٩٩</span> تن سکنه دارد.آبش از قنات، محصولش غلات و انار، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282887, 'چاه کن', '<span class=\"hlight\">چاه کن .</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (نف مرکب ) مقنی و چاخو. (ناظم الاطباء). کسی که کارش چاه کندن است . (فرهنگ نظام ). حفار. کموش . کَن کَن . چاه کننده . کننده ٔ چاه . آنکه چاه میکند. غارّ. (منتهی الارب ) <span class=\"hlight\">:</span> <br />ببرد از میان لشکری چاه کن <br />کجا نام بردند از آن انجمن .<br /> <font color=\"Red\">فردوسی .</font><br />پی چاهکن در ته چاه زن <br />سر راهزن بر سر راه زن .<br /> <font color=\"Red\">ظهوری (از آنندراج ).</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">امثال </span> :<br /> <span class=\"hlight\">چاهکن ته چاه است </span> .<br /><BR><font color=\"Blue\">◄</font> ظالم و مکار. (آنندراج ) (غیاث ). مجازاً کسی که برای آزار دیگری مکر یا ظلم میکند. (فرهنگ نظام ). <BR><font color=\"Blue\">◄</font> (اِ مرکب ) آلتی جهت کندن چاه . (ناظم الاطباء).<br /></font></div>'),
(282888, 'چاه کنان بالا', '<span class=\"hlight\">چاه کنان بالا.</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) دهی است از دهستان شهاباد بخش حومه ٔ شهرستان بیرجند که <span class=\"hlight\" dir=\"rtl\">٩</span> هزارگزی جنوب باختری بیرجند واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">٧٩</span> تن سکنه دارد. آبش از قنات، محصولش غلات، شغل اهالی زراعت و مزدوری و راهش مالرو است . مزارع تک خار و چشمه ٔ ملامحمدجزء این ده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282889, 'چاه کندا', '<span class=\"hlight\">چاه کندا.</span> <font color=\"DarkGreen\"><b>[ ک َ ]</font></b> (اِخ ) ده کوچکی است از دهستان احمدی بخش سعادت آباد شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">١٤٥</span> هزارگزی خاورحاجی آباد بر سر راه مالرو گلاشکرد به شمیل واقع شده .این آبادی دارای <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه است و مزرعه ٔ چاه مازگرجزء این ده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282890, 'چاه کندن', '<span class=\"hlight\">چاه کندن .</span> <font color=\"DarkGreen\"><b>[ ک َ دَ ]</font></b> (مص مرکب ) ایجاد چاه نمودن . گودی استوانه شکل عمیق کردن در زمین . گودال عمیق کندن . چه کندن . نَجخ . اعتفام . (منتهی الارب ) <span class=\"hlight\">:</span> <br />ای که تو از ظلم چاهی میکنی <br />از برای خویش دامی می تنی .<br /> <font color=\"Red\">مولوی .</font><br />تو ما را همی چاه کندی به راه <br />بسر لاجرم درفتادی به چاه .<br /> <font color=\"Red\">سعدی (بوستان ).</font><br />با دیگران بگوی که ظالم به چَه فتاد<br />تا چاه دیگران نکنند از برای خویش .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(282891, 'چاه کنعان', '<span class=\"hlight\">چاه کنعان .</span> <font color=\"DarkGreen\"><b>[ هَِ ک َ ]</font></b> (اِخ ) چاهی در کنعان که یوسف فرزند یعقوب را برادرانش در آن چاه افکندند <span class=\"hlight\">:</span> <br />تو با این مردم کوته نظر در چاه کنعانی <br />به مصر آ تا پدید آیند یوسف را خریداران .<br /> <font color=\"Red\">سعدی .</font><br />ز مصرش بوی پیراهن شنیدی <br />چرا در چاه کنعانش ندیدی .<br /><font color=\"Red\">سعدی .</font><br /></font></div>'),
(282892, 'چاه کنویه', '<span class=\"hlight\">چاه کنویه .</span> <font color=\"DarkGreen\"><b>[ ]</font></b>(اِخ ) مؤلف مرآت البلدان نویسد «قریه ای است از قراء بلوک لارستان فارس » (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(282893, 'چاه کوتاه', '<span class=\"hlight\">چاه کوتاه .</span> (اِخ ) مؤلف مرآت البلدان نویسد «بلوکی است از توابع و مضافات بندر بوشهر که در شش فرسخی شهر و در سمت مشرق آن واقع شده . اراضیش شوره زار و رمل است و هندوانه ٔ دیمی بسیار خوب در اینجا بعمل می آید. طول مضافات بوشهر از مغرب بمشرق بیست فرسخ و عرض آن از هشت تا شش فرسخ است و در این بلوک حاصل عمده اش غله و خرماست و شکار آهو دارد. قصبه ٔ این بلوک را نیز چاه کوتاه نامند» (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(282894, 'چاه کوتاه', '<span class=\"hlight\">چاه کوتاه .</span> (اِخ ) دهی است از بخش برازجان شهرستان بوشهر. این ده مرکز دهستان چاه کوتاه است و در <span class=\"hlight\" dir=\"rtl\">٣٨</span> هزارگزی جنوب برازجان و <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی شوسه ٔ شیراز به بوشهر واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١٢٢٩</span> تن سکنه دارد. آبش از چاه، محصولش غلات، خرما و صیفی، شغل اهالی زراعت و راهش فرعی است ودبستان هم دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282895, 'چاه کوتاه', '<span class=\"hlight\">چاه کوتاه .</span> (اِخ ) نام یکی از دهستانهای یازده گانه ٔ بوشهر میباشد و محدود است از شمال به دهستان عیسوند، از باختر به دهستان انگالی، از جنوب به دهستان باغک و از خاور به دهستان سمل . این دهستان تقریباً در جنوب خاوری بخش برازجان واقع شده و قراء آن در جلگه ٔ ساحلی خلیج فارس است . هوای آن گرم، مرطوب و مالاریائی است و در حدود <span class=\"hlight\" dir=\"rtl\">٢٥٠٠</span> تن سکنه دارد. آب مشروبش از آب چاه تأمین میشود و زراعتش بطور کلی دیمی است . محصولش غلات و جزئی خرما و شغل اهالی زراعت است . این دهستان از شش آبادی تشکیل شده و قراء مهم آن عبارت است از احمدی -دوبیره و تل اشگی . راه شوسه ٔ بوشهر به کازرون و شیراز از وسط این دهستان میگذرد و مرکز این دهستان قریه ٔ چاه کوتاه است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282896, 'چاه کوته', '<span class=\"hlight\">چاه کوته .</span> <font color=\"DarkGreen\"><b>[ ت َ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد «از متعلقات تون یا طبس است » (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(282897, 'چاه کورکی', '<span class=\"hlight\">چاه کورکی .</span> (اِخ ) ده کوچکی است از دهستان آباده طشتک بخش نی ریز شهرستان فسا که در <span class=\"hlight\" dir=\"rtl\">٣٤</span> هزارگزی شمال باختری نی ریز واقعشده و <span class=\"hlight\" dir=\"rtl\">٢٥</span> تن سکنه دارد که از ایل قرائی میباشند و ییلاق قشلاق میکنند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282898, 'چاه کوری', '<span class=\"hlight\">چاه کوری .</span> (اِخ ) دهی است از دهستان علامرودشت بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١٠٥</span> هزارگزی جنوب خاور کنگان ویک هزارگزی جنوب راه عمومی اشکنان به پسرودک واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢٧٨</span> تن سکنه دارد. آبش از چاه، محصولش غلات و خرما، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282899, 'چاه کوه', '<span class=\"hlight\">چاه کوه .</span> (اِخ ) ده کوچکی است از دهستان حومه ٔبخش لنگه ٔ شهرستان لار که در <span class=\"hlight\" dir=\"rtl\">١٠</span> هزارگزی شمال خاور لنگه بر کنار راه عمومی لنگه به بندرعباس واقع شده و <span class=\"hlight\" dir=\"rtl\">٢٦</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282900, 'چاه کویر', '<span class=\"hlight\">چاه کویر.</span> <font color=\"DarkGreen\"><b>[ ک ]</font></b> (اِخ ) دهی است از دهستان دستگردان بخش طبس شهرستان فردوس که در <span class=\"hlight\" dir=\"rtl\">١١٥</span> هزارگزی شمال طبس واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٩٨</span> تن سکنه دارد. آبش از قنات، محصولش غلات، پنبه، گاورس و ذرت، شغل اهالی زراعت و راهش اتومبیل رو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282901, 'چاه کویه', '<span class=\"hlight\">چاه کویه .</span> <font color=\"DarkGreen\"><b>[ ی ِ ]</font></b> (اِخ ) دهی است از دهستان کوهستان بخش داراب شهرستان فسا که در <span class=\"hlight\" dir=\"rtl\">٩٠</span> هزارگزی خاور داراب واقع شده . کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">١٠٠٤</span> تن سکنه دارد. آبش از چشمه، محصولش انجیر، مویز، گل سرخ، توتون، بادام و گردو، شغل اهالی باغبانی و قالی بافی وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282902, 'چاه گاه', '<span class=\"hlight\">چاه گاه .</span> (اِخ ) دهی است از دهستان جانکی بخش لردگان شهرستان شهرکرد که در <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی شمال خاور لردگان، متصل به راه عمومی لردگان به پل کره واقع شده . جلگه و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٣٨</span> تن سکنه دارد. آبش از چشمه، محصولش غلات آبی و دیمی، شغل اهالی زراعت، گله داری و ذغال سوزی، صنایع دستی جاجیم بافی و راهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282903, 'چاه گاوی', '<span class=\"hlight\">چاه گاوی .</span> (اِخ ) دهی است ازدهستان گوهر کوه بخش خاش شهرستان زاهدان که در <span class=\"hlight\" dir=\"rtl\">٥١</span> هزارگزی باختر خاش و <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی جنوب راه فرعی نرماشیربه خاش واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢٠٠</span> تن سکنه دارد. آبش از چاه، محصولش لبنیات، شغل اهالی گله داری و راهش فرعی است و ساکنین ده از طایفه ٔ گشادزائی میباشند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282904, 'چاه گربه', '<span class=\"hlight\">چاه گربه .</span> <font color=\"DarkGreen\"><b>[ گ ُ ب ِ ]</font></b> (اِخ ) ده کوچکی است از دهستان حومه ٔ بخش انارک شهرستان نائین که در <span class=\"hlight\" dir=\"rtl\">١٣</span> هزارگزی شمال انارک وصل به راه مالرو حاجی مهدی به انارک واقع شده . جلگه و معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٩</span> تن سکنه دارد. آبش از قنات، محصولش، غلات، شغل اهالی زراعت و راهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282905, 'چاه گرد', '<span class=\"hlight\">چاه گرد.</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (اِخ ) دهی است از دهستان عربخانه بخش شوسف شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٦٩</span> هزارگزی شمال باختری شوسف، سر راه مالرو عمومی گیوبه شوسف واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٣</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282906, 'چاه گرگی', '<span class=\"hlight\">چاه گرگی .</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (اِخ ) دهی است از دهستان طیبی سر حدی بخش کهکیلویه ٔ شهرستان بهبهان که در یازده هزارگزی جنوب خاوری قلعه رئیسی واقعشده . کوهستانی، سردسیر و مالاریائی است و صد تن سکنه دارد. آبش از چشمه، محصولش غلات، پشم و لبنیات، شغل اهالی زراعت و حشم داری، صنایع دستی بافتن قالی، قالیچه و پارچه و راهش مالرو است . ساکنین این ده از طایفه ٔ طیبی میباشند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٦</span>).<br /></font></div>'),
(282907, 'چاه گز', '<span class=\"hlight\">چاه گز.</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِخ ) دهی است از دهستان مرکزی بخش قاین شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٧٥</span> هزارگزی شمال خاوری قاین واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٦١</span> تن سکنه دارد. آبش از قنات محصولش غلات و شلغم، شغل اهالی زراعت و مالداری و راهش مالرو است . این ده را در اصطلاح محلی قطارگز نیز گویند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282908, 'چاه گز', '<span class=\"hlight\">چاه گز.</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِخ ) دهی است از دهستان عربخانه بخش شوسف شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی باختر شوسف و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی جنوب خاوری هشتوکان واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٠٥</span> تن سکنه دارد. آبش از قنات، محصولش غلات و لبنیات، شغل اهالی زراعت و مالداری وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282909, 'چاه گزی', '<span class=\"hlight\">چاه گزی .</span> <font color=\"DarkGreen\"><b>[ گ َ ]</font></b> (اِخ ) دهی است از دهستان تراکمه بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١١٤</span> هزارگزی جنوب خاور کنگان، کنار راه فرعی لار به گله دار واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه ٔ فارس و ترک دارد. آبش از قنات، محصولش غلات و انار و شغل اهالی زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282910, 'چاه گل', '<span class=\"hlight\">چاه گل .</span> <font color=\"DarkGreen\"><b>[ گ ُ ]</font></b> (اِخ ) دهی است جزء دهستان اشکور بالا بخش رودسر شهرستان لاهیجان که در <span class=\"hlight\" dir=\"rtl\">٦٢</span> هزارگزی جنوب رودسر و <span class=\"hlight\" dir=\"rtl\">٢٦</span> هزارگزی جنوب خاوری سی پل واقع شده . کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٢٢٨</span> تن سکنه دارد. آبش از چشمه، محصولش غلات، بنشن، لبنیات و عسل، شغل اهالی زراعت، گله داری و شالبافی و راهش مالرو وصعب العبور است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٢</span>).<br /></font></div>'),
(282911, 'چاه گنبد تلخ', '<span class=\"hlight\">چاه گنبد تلخ .</span> <font color=\"DarkGreen\"><b>[ گُم ْ ب َ ت َ ]</font></b> (اِخ ) دهی است از دهستان دیهوک بخش طلیس شهرستان فردوس که در <span class=\"hlight\" dir=\"rtl\">٢٢</span> هزارگزی خاور طلبس واقع شده . کویر است و سکنه ندارد و مکاران و رهگذران از آب چاه آن استفاده میکنند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282912, 'چاه گو', '<span class=\"hlight\">چاه گو.</span> (اِخ ) ده کوچکی است از دهستان رودبار بخش کهنوج شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزارگزی باختر کهنوج، سر راه مالرو رودخانه ٔ کهنوج واقع شده و <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه دارد. مزارع چاه مراد، چاه گوک و سید مرادجزء این ده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282913, 'چاه گیل', '<span class=\"hlight\">چاه گیل .</span> (اِخ ) ده کوچکی است از دهستان سیاهو بخش مرکزی شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">١٠٨</span> هزارگزی شمال بندرعباس و <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی شمال راه شوسه کرمان به بندرعباس واقع شده و<span class=\"hlight\" dir=\"rtl\">١٥</span> تن سکنه دارد. (از فرهنگ جغرافیای ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282914, 'چاه گین', '<span class=\"hlight\">چاه گین .</span> (اِخ ) دهی است از دهستان حصن بخش زرندشهرستان کرمان که در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی جنوب باختری زرند و<span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی باختر راه مالرو زرند به بافق واقع شده . جلگه و معتدل است و <span class=\"hlight\" dir=\"rtl\">٣٥٣</span> تن سکنه دارد. آبش از قنات، محصولش غلات، حبوبات، پسته و پنبه، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282915, 'چاه یخ', '<span class=\"hlight\">چاه یخ .</span> <font color=\"DarkGreen\"><b>[ هَِ ی َ ]</font></b> (ترکیب اضافی، اِ مرکب ) چاله ٔ یخ . یخچال . یخدان . محلی که هنگام زمستان و فصل یخ بندان، یخ در آنجا ذخیره کنندو از آن یخ در تابستان استفاده نمایند <span class=\"hlight\">:</span> <br />بود غاری در آن خرابستان <br />خوشتر از چاه یخ به تابستان .<br /><font color=\"Red\">نظامی .</font><br /></font></div>'),
(282916, 'چاه یعقوب', '<span class=\"hlight\">چاه یعقوب .</span> <font color=\"DarkGreen\"><b>[ هَِ ی َ ]</font></b> (اِخ ) در کتاب قاموس مقدس آمده است : «چاهی است که عیسی مسیح درکنار آن چاه با زن سامری تکلم نمود، و آن چاه در نزدیکی شکیم واقع است ... هیچیک از طوایف دنیا را در خصوص موضع آن چاه اختلافی نبوده است زیرا که آن بمسافت یک میل و نیم بطرف شرقی نابلس، در دامنه ٔ کوه جرزیم، که همان کوه طور میباشد در نزدیکی دروازه ای که از اورشلیم به جلیل میرود واقع است . و خود چاه در میان حیاطی بوده که فعلاً خراب است ... عمق این چاه <span class=\"hlight\" dir=\"rtl\">٧٥</span> قدم وفراخیش <span class=\"hlight\" dir=\"rtl\">٧</span> قدم و <span class=\"hlight\" dir=\"rtl\">٦</span> قیراط میباشد. لکن مدققین گمان برده اند که عمق اصلی آن <span class=\"hlight\" dir=\"rtl\">١٥٠</span> قدم بوده و از کثرت سنگهایی که در آن افتاده به این صورت درآمده . در قرن چهارم کلیسائی بر آن بنا کردند و جز زمستان در سایر اوقات خشک میباشد». (از کتاب قاموس مقدس صص <span class=\"hlight\" dir=\"rtl\">٣٠٢</span> - <span class=\"hlight\" dir=\"rtl\">٣٠٣</span>).<br /></font></div>'),
(282917, 'چاه یوز', '<span class=\"hlight\">چاه یوز.</span> (اِ مرکب ) قلاب چندند که بدان دلو از چاه بیرون آورند. (انجمن آرا). کنایه از قلاب آهنین که چیزهای در چاه افتاده را بدان برآرند. (آنندراج ). قلابی که بدان چیز به چاه افتاده را برآرند. (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> (نف مرکب ) چاخو. مقنی . چاه کن . حفرکننده ٔ چاه قنات . آنکه در کندن چاه های قنات و باز کردن مجرای زیرزمینی قنوات مهارت دارد. چاهجو. معنی ترکیبی آن جوینده ٔ چاه و یوز بمعنی جوینده است . (انجمن آرا) (آنندراج ). چاهجو، یوز مبدل یوس است و یوس بمعنی تفحص و تجسس است . (فرهنگ نظام ). چاه یوس . (فرهنگ نظام ). رجوع به چاه پوز و چاهجو شود.<br /></font></div>'),
(282918, 'چاه یوسف', '<span class=\"hlight\">چاه یوسف .</span> <font color=\"DarkGreen\"><b>[ هَِ س ُ ]</font></b> (اِخ ) مشهور است، و آن دراراضی اردن که از نواحی شام است نزدیک به طبریه باشد. (برهان ). نام چاهی در اراضی اردن که از نواحی شام است نزدیک به طبریه، که آن حضرت را برادران در آن انداخته بودند. (آنندراج ). چاهی که یوسف بن یعقوب را برادرانش در آن چاه انداختند. چاه کنعان <span class=\"hlight\">:</span> <br />مگردر دل گذشت آن گوهر نایاب دریا را<br />که چاه یوسفی گردید هر گرداب دریا را.<br /><font color=\"Red\">میرزا انوار(از آنندراج ).</font><br /></font></div>'),
(282919, 'چاهار', '<span class=\"hlight\">چاهار.</span> (اِخ ) ایالتی از کشور چین در مشرق ژهل که در سال <span class=\"hlight\" dir=\"rtl\">١٩٢١</span> م . بوسیله مغولان تجزیه شده است . دارای <span class=\"hlight\" dir=\"rtl\">٢١٧٠٠٠٠</span> تن سکنه است و مرکز این ایالت شهر«چانگ چیاکئو» میباشد.<br /></font></div>'),
(282920, 'چاهان', '<span class=\"hlight\">چاهان .</span> (اِخ ) ده کوچکی است از دهستان سیربک بخش میناب شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">٩٠</span> هزارگزی جنوب میناب و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی خاور راه مالرو جاسک به میناب واقع شده و <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282921, 'چاهان', '<span class=\"hlight\">چاهان .</span> (اِخ ) ده کوچکی است از دهستان انگهران بخش کهنوج شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">١٣٢</span> هزارگزی جنوب کهنوج بر سر راه مالرو سیربک به چغین واقع شده . کوهستانی و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٤٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282922, 'چاهان', '<span class=\"hlight\">چاهان .</span> (اِخ ) دهی است از دهستان رمشک بخش کهنوج شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">١٨٠</span> هزارگزی جنوب خاوری کهنوج بر سر راه مالرو گابریک به رمشک واقع شده .کوهستانی و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٥٠</span> تن سکنه دارد. آبش از قنات، محصولش برنج، تنباکو و خرما، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282923, 'چاهان', '<span class=\"hlight\">چاهان .</span> (اِخ ) دهی است از دهستان بنت بخش نیکشهر شهرستان چاه بهار که در <span class=\"hlight\" dir=\"rtl\">٤٨</span> هزارگزی جنوب باختری نیکشهر، کنار راه مالرو بنت به چاه بهار واقع شده . کوهستانی، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢٥٠</span> تن سکنه بلوچ سنی دارد. آبش از رودخانه، محصولش خرما و لبنیات، شغل اهالی زراعت و گله داری وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282924, 'چاهجو', '<span class=\"hlight\">چاهجو.</span> (اِ مرکب ) قلابی باشد که بدان چیزی که بچاه افتد برآرند. (برهان ) (آنندراج ) (ناظم الاطباء). قلابی که بدان چیزی که در چاه افتد بیرون میاورند (فرهنگ نظام ). بمعنی چاهیوز است . (برهان ) (آنندراج ). چاهیوز نیز گویند. (ناظم الاطباء) <span class=\"hlight\">:</span> <br />چاهجوئی ز سر زلف کژت راست کنم <br />مگر آرم دل از آن چاه زنخدان بر سر.<br /> <font color=\"Red\">(شرفنامه منیری ).</font><br /><BR><font color=\"Blue\">◄</font> (نف مرکب ) چاه کن را نیز گویند. (برهان ) (آنندراج ). چاخو. مُقَنّی . (ناظم الاطباء). کسی که چاههای قنات را چاهجویی کند. آنکه در کندن چاه و نقب زدن و متصل ساختن چاهها در زیر زمین بیکدیگر، استادی و مهارت دارد. چاهجوی .<br /></font></div>'),
(282925, 'چاهخانی', '<span class=\"hlight\">چاهخانی .</span> (اِخ ) دهی است از دهستان عیسوند بخش برازجان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی جنوب باختر برازجان و یک هزارگزی شوسه ٔ برازجان به بوشهر واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٧٠٧</span> تن سکنه دارد. آبش از چاه محصولش غلات، تنباکو و خرما، شغل اهالی زراعت و راهش فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282926, 'چاهر', '<span class=\"hlight\">چاهر.</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «از متعلقات تون یا طبس است ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282927, 'چاهریسه', '<span class=\"hlight\">چاهریسه .</span> <font color=\"DarkGreen\"><b>[ هََ س َ ]</font></b> (اِخ ) دهی است ازدهستان بالا، شهرستان اردستان که در <span class=\"hlight\" dir=\"rtl\">٣٢</span> هزارگزی جنوب باختر اردستان و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی شمال شوسه ٔ اردستان به اصفهان واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٧١</span> تن سکنه دارد. آبش از قنات، محصولش غلات، شغل اهالی زراعت و راهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282928, 'چاهسار', '<span class=\"hlight\">چاهسار.</span> (اِخ ) مؤلف مرآت البلدان نویسد: «از مزارع قدیم النسق قاینات است، حالا سکنه ندارد و اهل مزارع دیگر آن را زرع مینمایند. (مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282929, 'چاهسار', '<span class=\"hlight\">چاهسار.</span> (اِ مرکب ) چاه . چاهسر <span class=\"hlight\">:</span> <br />دو پایش فروشد به یک چاهسار<br />نبد جای آویزش و کارزار.<br /> <font color=\"Red\">فردوسی .</font><br />چو آمد ز ره نزد آن چاهسار<br />بنزدیک آن چاه بنهاد بار.<br /> <font color=\"Red\">فردوسی .</font><br />دگر چاهساری که بی آب گشت <br />فراوان برو سالیان برگذشت .<br /> <font color=\"Red\">فردوسی .</font><br />سوی خانه رفتند از آن چاهسار<br />به یک دست بیژن به دیگر زوار.<br /> <font color=\"Red\">فردوسی .</font><br />کشیدش دوان تا بدان چاهسار<br />دو دیده پر از خون و رخ چون بهار.<br /> <font color=\"Red\">فردوسی .</font><br />ز خس گشته هر چاهساری چو خوری <br />ز کف گشته هر آبگیری چو طبلی .<br /> <font color=\"Red\">منوچهری .</font><br />چاهساری ببین خراب شده <br />گشته مطموس و خشک از آب شده <br />اندر آن چاه گوی راز دلت <br />تا بیاساید این سرشته گلت .<br /> <font color=\"Red\">سنایی .</font><br />چاهساری هزار پایه در او<br />ناشده کس مگر که سایه در او.<br /> <font color=\"Red\">نظامی .</font><br /><BR><font color=\"Blue\">◄</font> گودی عمیق . گودالی ژرف . <BR><font color=\"Blue\">◄</font> چاهسر. (آنندراج ). دهانه ٔ چاه . (ناظم الاطباء). سرچاه . لب چاه .<br /></font></div>'),
(282930, 'چاهستان', '<span class=\"hlight\">چاهستان .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان شمین بخش مرکزی شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">٦٠</span> هزارگزی شمال خاوری بندرعباس و<span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی شمال راه مالرو کشکوه به بندرعباس واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٨١٧</span> تن سکنه دارد. آبش از رودخانه و چاه، محصولش غلات و خرما، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282931, 'چاهشور', '<span class=\"hlight\">چاهشور.</span> (اِخ ) دهی است از دهستان مرکزی بخش قاین شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٥٩</span> هزارگزی شمال باختری قاین واقع شده . دامنه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٥٧</span> تن سکنه دارد.آبش از قنات، محصولش غلات و شلغم، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282932, 'چاهشک', '<span class=\"hlight\">چاهشک .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان طرقبه بخش مرکزی شهرستان مشهد که در <span class=\"hlight\" dir=\"rtl\">٨</span> هزارگزی شمال خاوری طرقبه و <span class=\"hlight\" dir=\"rtl\">١٥</span>هزارگزی خاور شوسه ٔ قدیمی مشهد به قوچان واقع شده . دامنه و سردسیر است و <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد. آبش از قنات، محصولش غلات، بنشن و میوجات، شغل اهالی زراعت و راهش اتومبیل رو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282933, 'چاهه', '<span class=\"hlight\">چاهه .</span> <font color=\"DarkGreen\"><b>[ هَِ ]</font></b> (اِخ ) دهی است از دهستان جم بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی خاور کنگان، کنار راه مالرو کنگان به جم واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٤٤٧</span> تن سکنه دارد. آبش ازقنات، محصولش غلات، مرکبات و انار و شغل اهالی زراعت و گلیم بافی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282934, 'چاهه', '<span class=\"hlight\">چاهه .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد:«قریه ای است از قرای طوس خراسان و در آنجا رباطی است که آن را رباط چاهه و رباط فردوسی نیز نامند. و درتاریخ حافظ ابرو مسطور است که چون حکیم ابوالقاسم فردوسی شاهنامه را به امر سلطان محمود تمام کرد و سلطان از ادای صلتی که به فردوسی وعده کرده بود تخلف ورزید، حکیم فردوسی قهر کرد و به جانب طوس روانه شد، سلطان محمود خواست نقض عهد خود را جبران کند پس وجهی کرامند برای او فرستاد و آن وجه هنگامی به طوس رسید که فردوسی برحمت ایزدی پیوسته و از او دختری باقیمانده بود. دختر مال را قبول نکرد و سلطان فرمود که از آن وجه بین راه طوس و سرخس به ثواب روان فردوسی رباطی ساختند، نزدیک به قریه ٔ چاهه و رباط چاهه خواندند و این واقعه در <span class=\"hlight\" dir=\"rtl\">٤١٠</span> هَ . ق . بوده . از رباط سنگ بست تا رباط چاهه، سر راه سرخس پنج فرسنگ راه است ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>). اما این روایت قطعی نیست .<br /></font></div>'),
(282935, 'چاهه', '<span class=\"hlight\">چاهه .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد: «قریه ای است از قرای سبزوار که در میان کوه واقع شده . هوایش بسیار خوب و معتدل است و بیست خانوار سکنه دارد.آبش از قنات و چشمه، محصولش زراعت دیمی و اشجار انگور و سایر میوه هاست » (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(282936, 'چاهه', '<span class=\"hlight\">چاهه .</span> <font color=\"DarkGreen\"><b>[ هََ <span class=\"hlight\" dir=\"rtl\">/</span> هَِ ]</font></b> (اِ) گوی عمیق چاه مانند را گویند. (برهان ) گوی عمیق را که چاه مانند باشد گویند. (آنندراج ). گودال عمیق چاه مانند. (ناظم الاطباء) چاه . چاهک . گودال عمیق .<br /></font></div>'),
(282937, 'چاهو', '<span class=\"hlight\">چاهو.</span> (اِخ ) ده کوچکی است از دهستان طارم بخش سعادت آباد شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">٤٥</span> هزارگزی جنوب باختری حاجی آباد، سر راه مالرو فورک واقع شده و <span class=\"hlight\" dir=\"rtl\">١٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282938, 'چاهو', '<span class=\"hlight\">چاهو.</span> (اِخ ) ده کوچکی است از دهستان سیاهو بخش مرکزی شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">٨٠</span> هزارگزی شمال خاور بندرعباس و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی باختر راه مالرو سیاهو به قلعه قاضی واقع شده و <span class=\"hlight\" dir=\"rtl\">٣٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282939, 'چاهو', '<span class=\"hlight\">چاهو.</span> (اِخ ) ده کوچکی است از دهستان سیلوئید بخش زرند شهرستان کرمان که در <span class=\"hlight\" dir=\"rtl\">٢٠</span> هزارگزی جنوب زرند و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی باختر راه مالرو و زرند به رفسنجان واقع شده و <span class=\"hlight\" dir=\"rtl\">٣٤</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282940, 'چاهو', '<span class=\"hlight\">چاهو.</span> (اِخ ) ده کوچکی است از دهستان طارم بخش سعادت آباد شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">٣٠</span> هزارگزی باختر حاجی آباد، سر راه مالرو طارم به دراگاه واقع شده و <span class=\"hlight\" dir=\"rtl\">٤٠</span> تن سکنه دارد. مزارع مدنو، مزرعه، و محمدآبادجزء این ده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282941, 'چاهو', '<span class=\"hlight\">چاهو.</span> (اِخ ) دهی است از دهستان ایسین بخش مرکزی شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">٣٦</span> هزارگزی شمال باختری بندرعباس و <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی جنوب راه فرعی لار به بندرعباس واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٢٣١</span> تن سکنه دارد. آبش از چاه، محصولش خرما، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282942, 'چاهو', '<span class=\"hlight\">چاهو.</span> (اِخ ) دهی است از دهستان گله دار بخش کنگان شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٩٠</span> هزارگزی جنوب خاور کنگان، کنار راه فرعی لار به گله دار واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">١٢٠</span>تن سکنه دارد. آبش از چاه، محصولش غلات، تنباکو و پیاز و شغل اهالی زراعت است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282943, 'چاهو قبله', '<span class=\"hlight\">چاهو قبله .</span> <font color=\"DarkGreen\"><b>[ ق ِ ل ِ ]</font></b> (اِخ ) دهی است از بخش قشم شهرستان بندرعباس که در <span class=\"hlight\" dir=\"rtl\">١٠٠</span> هزارگزی باختر قشم، سر راه مالرو قشم به باسعید واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٩٠</span> تن سکنه دارد. آبش از چاه و آب باران، محصولش غلات، شغل اهالی صید ماهی وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282944, 'چاهورد', '<span class=\"hlight\">چاهورد.</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِخ ) دهی است از دهستان پیرم بخش گاوبندی شهرستان لار که در <span class=\"hlight\" dir=\"rtl\">٨٧</span> هزارگزی شمال خاور گاوبندی کنار راه فرعی لار به اشکنان واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٥٨٣</span> تن سکنه دارد. آبش از چاه، محصولش غلات، خرما و لبنیات و شغل اهالی زراعت و گله داری است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282945, 'چاهون', '<span class=\"hlight\">چاهون .</span> (اِخ ) ده کوچکی است از دهستان سرویزن بخش ساردوئیه ٔ شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">٣٥</span> هزارگزی جنوب خاوری ساردوئیه و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی شمال راه مالرو دارزین به ساردوئیه واقع شده و <span class=\"hlight\" dir=\"rtl\">٢٢</span> تن سکنه دارد که از طایفه مهنی میباشند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282946, 'چاهوک', '<span class=\"hlight\">چاهوک .</span> (اِخ )دهی است از دهستان پشتکوه بخش نیر شهرستان یزد که در <span class=\"hlight\" dir=\"rtl\">١٣</span> هزارگزی شمال باختر نیر و <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی شمال باختر راه نیربه ابرقو واقع شده . جلگه، معتدل و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٤٣٧</span> تن سکنه دارد. آبش از قنات، محصولش غلات . چغندر و اشجار بادام، گردو، انگور و هلو، شغل اهالی زراعت، صنایع دستی زنان کرباس بافی و راهش فرعی است . دبستان هم دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١٠</span>).<br /></font></div>'),
(282947, 'چاهوک', '<span class=\"hlight\">چاهوک .</span> (اِخ ) دهی است از دهستان پائین ولایت بخش حومه ٔ شهرستان تربت حیدریه که در <span class=\"hlight\" dir=\"rtl\">١٩</span> هزارگزی جنوب خاوری تربت حیدریه و سه هزارگزی باختر راه شوسه ٔ عمومی تربت حیدریه به رشتخوار واقعشده . دامنه و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٠٠</span> تن سکنه دارد. آبش ازقنات، محصولش غلات و پنبه، شغل اهالی زراعت و گله داری و راهش مالرو است و از بوری آباد و قلعه نو. اتومبیل هم میتوان برد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282948, 'چاهوک', '<span class=\"hlight\">چاهوک .</span> (اِخ ) دهی است از دهستان زاوه بخش حومه ٔ شهرستان تربت حیدریه که در <span class=\"hlight\" dir=\"rtl\">٧٢</span> هزارگزی شمال خاوری تربت حیدریه سر راه مالرو عمومی زاوه واقع شده دامنه و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٢٤</span> تن سکنه دارد آبش از قنات، محصولش غلات، شغل اهالی زراعت و راهش مالرو است . طایفه ٔ کرخیل دراین ده سکونت دارند. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282949, 'چاهوک', '<span class=\"hlight\">چاهوک .</span> (اِخ ) ده کوچکی است از بخش زابلی شهرستان سراوان که در <span class=\"hlight\" dir=\"rtl\">١٥</span> هزارگزی باختر زابلی، کنار راه مالرو سوران به زابلی واقع شده و <span class=\"hlight\" dir=\"rtl\">٤٥</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282950, 'چاهچه', '<span class=\"hlight\">چاهچه .</span> <font color=\"DarkGreen\"><b>[ چ َ <span class=\"hlight\" dir=\"rtl\">/</span> چ ِ ]</font></b> (اِ مصغر) چاهک . چاه خُرد. چاه کوچک . چاه نزدیک تک . گودالی کم عمق، چاچه . آبشی . چاهی که در صحن سرای کنند رفع حوائج کودکان و گرد آمدن فاضلاب را. رجوع به آبشی در همین لغت نامه شود.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاهچه ٔ قفا</span> ؛ گوی که در پشت گردن بدرازا هست .<br /></font></div>'),
(282951, 'چاهچور', '<span class=\"hlight\">چاهچور.</span> (اِ مرکب ) دولاغ و چاقشوری که زنان هنگام بیرون رفتن از خانه می پوشند. (ناظم الاطباء). چاقچور.<br /></font></div>'),
(282952, 'چاهچول', '<span class=\"hlight\">چاهچول .</span> (اِخ ) دهی است از دهستان لب کویر بخش بجستان شهرستان گناباد که در <span class=\"hlight\" dir=\"rtl\">٢٥</span> هزارگزی شمال خاوری بجستان و <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارگزی شمال شوسه گناباد به فردوس واقع شده . دامنه، خشک و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">٤٦</span> تن سکنه دارد.آبش از قنات، محصولش غلات و زیره، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282953, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد «دهی است قدیم النسق، از قرای دودانگه ٔ زنجان که ملک خورده مالک است و هوایی معتدل دارد. آبش از چشمه سار، زراعتش غله ٔ دیمی و آبی، پنبه، باغات انگور و اشجار میوه است و ایل شاهسون اینانلو درآنجا ییلاق میکنند». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(282954, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد «از متعلقات میان ولایت شهر مشهد است که در سه فرسنگی شهر واقع شده و ده خانوار سکنه دارد. هوایش مرطوبی و زراعتش از آب قنات است » (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(282955, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد «از مزارع قدیم النسق طبس است و یکصد و سی و هشت تن سکنه دارد. آبش از قنات و هوایش معتدل است ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282956, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد «از قرای بلوک بوانات فارس است . صنعت و حرفه ٔ اهالی این بلوک قاشق و جعبه سازی است، میوجات گرمسیری و سردسیری هر دو در این بلوک بعمل میاید و حاصل صیفی و شتوی هر دو خوب میشود» (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282957, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد «در جلگه ٔ تهران در مشرق شهر و جنوب البرز، بین راه تهران به مازندران دهی بود بایر و خالی از سکنه، متعلق بورثه ٔ میرزامحمد لواسانی وزیر که جناب میرزا علینقی حکیم الممالک و پیشخدمت باشی سلام، آن را ابتیاع نمود و قنات آن را دایر نمود و باغی و عمارتی و آبادی در آنجا ایجاد کرد و حکیمیه اش نامید» (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٣</span>).<br /></font></div>'),
(282958, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از دهستان وزوا بخش دستجرد شهرستان قم که در <span class=\"hlight\" dir=\"rtl\">٢٩</span> هزارگزی شمال دستجرد و <span class=\"hlight\" dir=\"rtl\">٤</span> هزارگزی راه فرعی طغرود به قاهان واقع شده . سردسیر است و <span class=\"hlight\" dir=\"rtl\">٦٨٤</span> تن سکنه ٔ فارسی وخلجی دارد. محصولش غلات و بنشن، شغل اهالی زراعت و بافتن گلیم، جاجیم و جوال و راهش مالرو است و از راه آقلک ماشین هم میتوان برد مزرعه ٔ کوچک زر جمله کردکی جزء این ده است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">١</span>).<br /></font></div>'),
(282959, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از دهستان طبس بخش صفی آباد شهرستان سبزوار که در <span class=\"hlight\" dir=\"rtl\">٣٧</span> هزارگزی جنوب صفی آباد و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی جنوب راه آهن واقع شده . کوهستانی و سردسیر است و <span class=\"hlight\" dir=\"rtl\">٦٧٦</span> تن سکنه دارد آبش از قنات، محصولش غلات، پنبه، باغات و ابریشم، شغل اهالی زراعت، باغداری و کرباس بافی و راهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282960, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از دهستان پسکوه بخش قاین شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٦٤</span> هزارگزی جنوب باختری قاین بر سر راه مالرو عمومی چلونک به محمدآباد واقع شده . جلگه و گرمسیر است و <span class=\"hlight\" dir=\"rtl\">١٠٥١</span> تن سکنه دارد. آبش از قنات، محصولش غلات، شغل اهالی زراعت، مالداری و قالیچه بافی و راهش مالرو است و از محمدآباد میتوان اتومبیل برد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282961, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از دهستان گل فریز بخش خوسف شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٥٠</span> هزارگزی جنوب خاوری خوسف واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">١٨٥</span> تن سکنه دارد. آبش از قنات، محصولش غلات و باغات، شغل اهالی زراعت وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282962, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از دهستان کاریزنو بالا جام بخش تربت جام شهرستان مشهد که در <span class=\"hlight\" dir=\"rtl\">٣٨</span> هزارگزی شمال باختری تربت جام بر سر راه مالرو عمومی تربت جام به فریمان واقع شده . کوهستانی و معتدل است و <span class=\"hlight\" dir=\"rtl\">٢١١</span> تن سکنه دارد. آبش از فنات، محصولش غلات و پنبه، شغل اهالی زراعت و راهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>');
INSERT INTO `words` (`id`, `word`, `meaning`) VALUES
(282963, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از دهستان پائین ولایت بخش فریمان شهرستان مشهد که در <span class=\"hlight\" dir=\"rtl\">٦٢</span> هزارگزی شمال خاوری فریمان بر سر راه شوسه ٔ عمومی مشهد به سرخس واقع شده . جلگه و معتدل است و <span class=\"hlight\" dir=\"rtl\">٣٨٢</span> تن سکنه دارد. آبش از قنات، محصولش غلات و چغندر، شغل اهالی زراعت و مالداری و راهش اتومبیل رو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282964, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) ده کوچکی است از دهستان گوک بخش شهداد شهرستان کرمان که در <span class=\"hlight\" dir=\"rtl\">٥٠</span> هزارگزی جنوب شهداد بر سر راه فرعی گوک به شهداد واقع شده و<span class=\"hlight\" dir=\"rtl\">٦</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282965, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) ده کوچکی است از دهستان سبزواران بخش مرکزی شهرستان جیرفت که در <span class=\"hlight\" dir=\"rtl\">١٣</span> هزارگزی جنوب خاوری سبزواران و <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی خاور راه فرعی سبزواران به کهنوج واقع شده و <span class=\"hlight\" dir=\"rtl\">٢٩</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٨</span>).<br /></font></div>'),
(282966, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) ده کوچکی است از دهستان حیات داود بخش گناوه ٔ شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">١٨</span> هزارگزی شمال باختر گناوه واقع شده و <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282967, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) دهی است از دهستان مشکان بخش نی ریز شهرستان فسا که در <span class=\"hlight\" dir=\"rtl\">٩٠</span> هزارگزی شمال نی ریز بر کنار راه فرعی نی ریز به هرات واقع شده . جلگه، گرمسیر و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٣٣٦</span> تن سکنه دارد. آبش از قنات، محصولش غلات و میوجات و شغل اهالی زراعت، باغداری و قالی بافی است . پاسگاه ژاندارمری ودبستان هم دارد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282968, 'چاهک', '<span class=\"hlight\">چاهک .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِ مصغر) چاه کوچک . (آنندراج ). مصغر چاه، یعنی چاه کوچک . (ناظم الاطباء). چاچه . چاهچه . چاه نزدیک تک . چاه کم عمق . چاه خرد. <BR><font color=\"Blue\">◄</font> آبشی . چاه خرد برای آبهای ریختنی مطبخ . چاه کوچک و کم عمقی که برای ریختن آب چلو و دیگر آبهای آلوده به چربی در آشپزخانه حفر میکنند. <BR><font color=\"Blue\">◄</font> گوی که در زیر شیرآب انبار سازند. <BR><font color=\"Blue\">◄</font> گودی چانه . چاهک لب . <BR><font color=\"Blue\">◄</font> پاچال . (ناظم الاطباء). <BR><font color=\"Blue\">◄</font> چاهک سیم پالا. گاه . (فرهنگ اسدی ص <span class=\"hlight\" dir=\"rtl\">٤٢١</span>) بوته ٔ زرگری .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">چاهک ثرید</span> ؛ آن قطعه ای از حلواها که میان آن را گود کنند جهت ریختن چاشنی . (ناظم الاطباء).<br /></font></div>'),
(282969, 'چاهک ملکان', '<span class=\"hlight\">چاهک ملکان .</span> <font color=\"DarkGreen\"><b>[ هََ ک ِ م َ ل ِ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد «در حوالی ارض اقدس (مشهد) واقع شده، از متعلقات قدیم النسق شادکان است وهیجده خانوار سکنه از اهل بربر دارد. آبش از قنوات و هوایش معتدل است ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(282970, 'چاهکان', '<span class=\"hlight\">چاهکان .</span> <font color=\"DarkGreen\"><b>[ هََ ]</font></b> (اِخ ) مؤلف مرآت البلدان نویسد «مزرعه ای است از مزارع قدیم النسق قاینات که هوایش ییلاقی و آبش از قنات است ». (از مرآت البلدان ج <span class=\"hlight\" dir=\"rtl\">٤</span> ص <span class=\"hlight\" dir=\"rtl\">١٣٤</span>).<br /></font></div>'),
(282971, 'چاهکاه', '<span class=\"hlight\">چاهکاه .</span> (اِخ ) دهی است از دهستان شنبه بخش خورموج شهرستان بوشهر که در <span class=\"hlight\" dir=\"rtl\">٣٦</span> هزارگزی جنوب خاور خور موج و <span class=\"hlight\" dir=\"rtl\">٦</span> هزارگزی شمال رودخانه ٔ مند واقع شده . جلگه . گرمسیر مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢٢٦</span> تن سکنه دارد. آبش از چشمه ٔ، محصولش غلات، تنباکو و لبنیات، شغل اهالی زراعت و گله داری و راهش فرعی است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٧</span>).<br /></font></div>'),
(282972, 'چاهی', '<span class=\"hlight\">چاهی .</span> (اِ) چای . شای . چایی . صاحب فلاحتنامه ٔ غازانی این گیاه معروف را چاهی نام میدهد و باز میگوید بزبان ختائی «چَه » گویند.<br /></font></div>'),
(282973, 'چاهی', '<span class=\"hlight\">چاهی .</span> (ص نسبی ) منسوب به چاه . از چاه . <BR><font color=\"Blue\">◄</font> زندانی . محبوس در چاه <span class=\"hlight\">:</span> <br />نه چاهی را بگه دارد نه گاهی رابه چه دارد<br />ز عفوش بهره ورتر هرکه او افزون گنه دارد.<br /> <font color=\"Red\">فرخی .</font><BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">پیغمبر چاهی </span> ؛ بعض شعرا از آن به یوسف بن یعقوب اسرائیلی کنایت کنند. یوسف علیه السلام .یوسف بن یعقوب که برادرانش او را در چاه افکندند. یوسف چاهی .<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">کبوتر چاهی </span> ؛ قسمی کبوتر برنگ کبود یا خاکستری که از سایر کبوتران خردترند و بیشتر در بیرون آبادیها، در میان چاههای قنات یا چاههای متروک و مدروس منزل کنند. نوعی کبوتر وحشی برنگ خاکستری سیر که بیشتر در چاههایی از قبیل چاه، قنات چاه آسباب و دیگر چاههای مدروس آشیان کنند.<BR><font color=\"HotPink\">♦ </font><span class=\"hlight\">یوسف چاهی </span> ؛ پیغمبر چاهی . یوسف (ع ) <span class=\"hlight\">:</span> <br />یکی یعقوب بن اسحاق و دیگر یوسف چاهی <br />سیم ایوب پیغمبر چهارم یونس متی .<br /><font color=\"Red\">منوچهری .</font><br /></font></div>'),
(282974, 'چاهیدن', '<span class=\"hlight\">چاهیدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b>(مص ) زکام شدن . دچار سرماخوردگی شدن . سرما خوردن . احساس سرما کردن . (ناظم الاطباء). سردشدن <span class=\"hlight\">:</span> <br />دل من ز خود بسکه چاهیده است <br />مگر گرمی از ثعلبش دیده است .<br /> <font color=\"Red\">وحید (در تعریف ثعلب فروش از آنندراج ).</font><br />شدم بمدرس و چاهید فوق دین سر و مغزم <br />ز بس بگوش سخنهای سرد میرود آنجا.<br /> <font color=\"Red\">ملا فوقی یزدی (از آنندراج ).</font><br /><BR><font color=\"Blue\">◄</font> سرد شدن دندان بخوردن تگرگ یا آب که بغایت سرد باشد. (آنندراج ). <BR><font color=\"Blue\">◄</font> بهم خوردن دندانها از اثر سرما. (ناظم الاطباء).<br /></font></div>'),
(282975, 'چاو', '<span class=\"hlight\">چاو.</span> (اِ صوت ) بانگ مرغ است . (فرهنگ اسدی ). گنجشک که از اشکره بگریزد یاکسی بچه اش برگیرد او بانگ همی از درد و از بیم کند آن آواز را چاو خوانند و گویند همی چاود. (نسخه ٔ دیگر فرهنگ اسدی ) (فرهنگ نظام ). <BR><font color=\"Blue\">◄</font> تیز. تیز ناله و بانگ مردم بود از درد عشق . (نسخه ای از فرهنگ اسدی ). <BR><font color=\"Blue\">◄</font> (اِ) آوازه . (زمخشری ). در تداول عامه «چو». صیت . شهرت . و رجوع به چو انداختن شود.<br /></font></div>'),
(282976, 'چاو', '<span class=\"hlight\">چاو.</span> (چینی، اِ) نوعی اسکناس . اسکناس گونه ای از چرم که نخستین بار در کشور چین معمول گردید. شهروا. پول کاغذی . لغتی است ختایی و آن کاغذ پاره ای بود مربع و طولانی که یکی از پادشاهان چنگیزی نام خود را بر آن نقش کرده بود و رایج گردانیده، چون مردم آذربایجان و اهل تبریز قبول نکردند و عزالدین مظفر که باعث و بانی چاو بود بقتل آمد، رسم چاو برطرف شد. (برهان ). بزبان چیناوی کاغذی بود، از طرف پادشاه هر دو روی آن عباراتی چند نوشته و در بازار چون زر رایج بود و خرج میشد. (فرهنگ وصاف از آنندراج ). کاغذپاره ای بود که وقتی گیخاتوخان مغول در ایران میخواسته آن را رایج کند و نشده . (انجمن آرا) (آنندراج ). قطعه کاغذ دولتی که گیخاتوخان مغول میخواست بعوض پول آن را رایج کند و مردم آذربایجان و اهالی تبریز قبول نکردند و عزالدین مظفر بهمین جهت بقتل رسید. (ناظم الاطباء). اسکناسی بوده که گیخاتوخان مغول می خواست در ایران جاری کند، پیش نرفت . (فرهنگ نظام ). کاغذپاره ای مستطیل مربع که هردو طرف کلمه شهادتین و چند کلمه بخط ختا مرقوم بود و در میان آن دایره کشیده و از نیم درم تا ده درم بنا بر اختلاف چاورقم زده و گیخاتوخان در ممالک ایران روان گردانید، چون دانستند که موجب خرابی رعایا و فقدان حاصل و رفعآمدوشد کاروان است حکم به ابطال فرمود <span class=\"hlight\">:</span> <br />چاو تا در جهان روان باشد<br />رونق ملک جاودان باشد.<br /> <font color=\"Red\">(از انجمن آرا).</font><br />روان شد چو زر موکب شیخ عهد<br />رهی، ناروان ماند مانند چاو.<br /> <font color=\"Red\">ابن یمین (از انجمن آرا).</font><br />... و در آن ملک <font color=\"DarkGreen\"><b>[ ختا و چین ]</font></b>کاغذ زیاده از همه ولایات خرج میشود چه بسبب تنکی کاغذ کتابت بر یک روی کاغذ میکنند و در دیگر ولایات بر دو روی، و دیگر آنکه اکثر آلات و اقمشه در کاغذ پیچندو دیگر آنکه اکثر معاملات ایشان به «چاو» است که چون همواره چاو دست بدست میرود کهنه میگردد و آن کهنه را هر کس که بدیوان برد عوض آن نو به وی دهند و هیچ موقوف نمی دارند و کهن را میسوزند و بجهت آن یک خرج باضعاف کتابت صرف میشود. (فلاحتنامه ٔ غازانی ). و رجوع شود به حبیب السیر ج <span class=\"hlight\" dir=\"rtl\">٣</span> صص <span class=\"hlight\" dir=\"rtl\">١٣٦</span> - <span class=\"hlight\" dir=\"rtl\">١٣٧</span> و تاریخ وصاف ص <span class=\"hlight\" dir=\"rtl\">٢٧٣</span> و تاریخ مغول عباس اقبال صص <span class=\"hlight\" dir=\"rtl\">٢٤٩</span> - <span class=\"hlight\" dir=\"rtl\">٢٥٠</span>. و اکنون چاو و چاپ بر صفت طبع و باسمه خط اطلاق میشود بر خلاف آن چاو، این چاو روان و دایر است . (انجمن آرا) (آنندراج ). لفظ مذکور چینی است بمعنی چاپ بلکه لفظ چاپ مبدل آن است چون اسکناس مذکور چاپی بوده و آن وقت در چین صنعت چاپ بوده . (فرهنگ نظام ). رجوع به چاپ در همین لغت نامه شود. و رجوع به اسکناس شود.<br /></font></div>'),
(282977, 'چاو پاره', '<span class=\"hlight\">چاو پاره .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) نام موضعی از ثغور روم . نام محلی از ثغور روم که زادگاه ابوعبداﷲ صوفی همدانی بوده است . آبادیی از ثغور روم که ابوعبداﷲ صوفی همدانی از آنجاست .<br /></font></div>'),
(282978, 'چاو چاو', '<span class=\"hlight\">چاو چاو.</span> (اِ صوت مرکب ) بانگ گنجشک را گویند، وقتی که جانوری قصد گرفتن او کرده باشد یا کسی دست به آشیان او کند که بچه او را برآورد. (برهان ). آواز گنجشک باشد در زمانی که جانور شکاری قصد او کند یا وقتی که بچه ٔ او را از خانه ٔ او بردارند. (انجمن آرا) (آنندراج ) (جهانگیری ). بانگ گنجشک و دیگر مرغان خصوصاً وقتی که جانوری قصد گرفتن او کند و یا کسی جهت گرفتن بچه ٔ وی دست در آشیان آن نماید. (ناظم الاطباء). صدای گنجشک و دیگر پرندگان کوچک در موقعترس یا هنگام اضطراب . جیرجیر. جیک جیک <span class=\"hlight\">:</span> <br />بی خانمان و بی زن و فرزند دشمنت <br />گنجشک وار دارد پیوسته چاوچاو.<br /> <font color=\"Red\">شمس فخری (از انجمن آرا).</font><br /><BR><font color=\"Blue\">◄</font> صدا. (برهان ). <BR><font color=\"Blue\">◄</font> شور و غوغا. (برهان ) (ناظم الاطباء).<br /></font></div>'),
(282979, 'چاو چاوان', '<span class=\"hlight\">چاو چاوان .</span> (نف مرکب، ق مرکب ) در حال چاویدن . ناله کنان . بانگ زنان . بانگ کنان ببانگی که مرغ جوجه دار کند خواندن جوجه های خود را. تیز تیز ناله کنان و بانگ زنان چون مرغی که دنبال جوجه ٔ گم گشته گردد <span class=\"hlight\">:</span> <br />مرغ دیدی که بچه زو ببرند<br />چاوچاوان درست چونان است .<br /><BR><font color=\"Blue\">◄</font> تیزتیز ناله و بانگ کنان از درد عشق . <BR><font color=\"Blue\">◄</font> معوج و غیر مستقیم و منحرف . <BR><font color=\"Blue\">◄</font> گمراه . (ناظم الاطباء). و رجوع به چاوچاو شود.<br /></font></div>'),
(282980, 'چاواز', '<span class=\"hlight\">چاواز.</span> (اِخ ) دهی از دهستان نهارجانات بخش حومه ٔ شهرستان بیرجند که در <span class=\"hlight\" dir=\"rtl\">٢٨</span> هزارگزی جنوب خاوری بیرجند واقع شده، دامنه و معتدل است و <span class=\"hlight\" dir=\"rtl\">٢٠</span> تن سکنه دارد. آبش از قنات و محصولش غلات و لبنیات است . شغل اهالی زراعت و راهش مالرو میباشد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٩</span>).<br /></font></div>'),
(282981, 'چاوان', '<span class=\"hlight\">چاوان .</span> (نف، ق ) در حال چاویدن . بانگ کنان مرغی از دوری فرزند یااز بیم و جز آن . چاوچاوان . رجوع به چاوچاوان شود.<br />و رجوع به چاو شود.<br /></font></div>'),
(282982, 'چاودار', '<span class=\"hlight\">چاودار.</span> (اِ) چودار. چودر. ویبگ . گیاهی هرزه که در غله زار روید و دانه ٔ آن چون گندمی لاغر و کشیده است . قسمی گندم وحشی . نوعی از حبوبات که در میان گندم و جو پیدا آید. و رجوع به چودار شود.<br /></font></div>'),
(282983, 'چاورش', '<span class=\"hlight\">چاورش .</span> <font color=\"DarkGreen\"><b>[ رَ ]</font></b> (اِخ ) دهی از دهستان باراندوزچای بخش حومه ٔ شهرستان ارومیه که در <span class=\"hlight\" dir=\"rtl\">٢٣</span> هزارگزی جنوب باختر ارومیه و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی شمال ارابه روزیوه به ارومیه واقع شده . دره ای است سردسیر و سالم که <span class=\"hlight\" dir=\"rtl\">٤٥</span> تن سکنه دارد. آبش از چشمه و محصولش غلات و توتون میباشد. شغل اهالی زراعت و گله داری، صنایع دستی جاجیم بافی راهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(282984, 'چاورچین', '<span class=\"hlight\">چاورچین .</span> <font color=\"DarkGreen\"><b>[ وِ ]</font></b> (اِخ ) دهی از دهستان آختاچی بوکان بخش بوکان شهرستان مهاباد که در <span class=\"hlight\" dir=\"rtl\">١٢</span> هزارو پانصدگزی شمال باختر بوکان و <span class=\"hlight\" dir=\"rtl\">١١</span> هزار و پانصدگزی باختر شوسه ٔ بوکان به میاندواب واقع شده، جلگه ای معتدل و مالاریائی است و <span class=\"hlight\" dir=\"rtl\">٢١٦</span> تن سکنه کرد دارد. آبش از سیمین رود و محصولش غلات و توتون و حبوبات است . شغل اهالی زراعت و گله داری میباشد. صنایع دستی جاجیم بافی وراهش مالرو است . (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(282985, 'چاوش', '<span class=\"hlight\">چاوش .</span> <font color=\"DarkGreen\"><b>[ وُ ]</font></b> (ترکی، ص، اِ) نقیب لشکر. (آنندراج ) (غیاث ). چاووش . (ناظم الاطباء). نقیب سپاه . (فرهنگ نظام ). آنکه در جنگ فرمان حمله دهد و سپاهیان را تشجیع و تشویق کند <span class=\"hlight\">:</span> <br />گر حاجب تو پوشد پیکار را زره <br />ور چاوش تو بندد پرخاش را کمر.<br /> <font color=\"Red\">امیرمعزی .</font><br />تو قاهر مصر و چاوشت را<br />بر قاهره قهرمان ببینم .<br /> <font color=\"Red\">خاقانی .</font><br />نفیر چاوشان از دورشو دور<br />ز گیتی چشم بد را کرده مهجور.<br /> <font color=\"Red\">نظامی .</font><br />ز دل دادن چاوشان دلیر<br />دلاور شده گور بر جنگ شیر.<br /> <font color=\"Red\">نظامی .</font><br />پسر چاوشان دید و تیغ و تبر<br />قباهای اطلس کمرهای زر.<br /> <font color=\"Red\">نظامی .</font><br /> <BR><font color=\"Blue\">◄</font> کسی که در دربار شاهان یا در نزد امراء و بزرگان وظیفه دار امور تشریفاتی بوده و در روزهای سلام اشخاص را به حضور آنان معرفی مینموده است . رئیس تشریفات <span class=\"hlight\">:</span> <br />چاوش اوهام نتواند رسیدن <br />تا کجا تا آخرین صف روز بارت .<br /> <font color=\"Red\">انوری .</font><br />نه نه قباد مخوان کیقباد خوانش از آنک <br />قباد چاوش روز سلام اوزیبد.<br /> <font color=\"Red\">خاقانی .</font><br /> <BR><font color=\"Blue\">◄</font> نقیب قافله . (آنندراج ) (غیاث ). نگهبان و مراقب کاروانیان . <BR><font color=\"Blue\">◄</font> دربان . (فرهنگ نظام ) <span class=\"hlight\">:</span> <br />ای چاوش سپید تو هم خادم سیاه <br />خورشید روم پرور و ماه حبش نگار.<br /> <font color=\"Red\">خاقانی .</font><br />خلیل از خیلتاشان سپاهش <br />کلیم از چاوشان بارگاهش .<br /> <font color=\"Red\">نظامی .</font><br />روزها شد که بنده می آید<br />بر در و ره نمیدهد چاوش .<br /> <font color=\"Red\">پوربهای جامی .</font><br />و رجوع به چاووش شود.<br /></font></div>'),
(282986, 'چاوش زاده', '<span class=\"hlight\">چاوش زاده .</span> <font color=\"DarkGreen\"><b>[ وُ دَ <span class=\"hlight\" dir=\"rtl\">/</span> دِ ]</font></b> (اِخ ) ابراهیم بن محمد؛ مؤلف کتاب «الصحائف فی الفرائض » که بسال <span class=\"hlight\" dir=\"rtl\">١٠٥٣</span> هَ . ق . وفات یافته و کتاب «مجمع اللطائف فی شرح الصحائف » شرح کتاب وی میباشد. (از کشف الظنون ج <span class=\"hlight\" dir=\"rtl\">٢</span> ص <span class=\"hlight\" dir=\"rtl\">١٠٧٥</span> و <span class=\"hlight\" dir=\"rtl\">١٦٠٣</span>).<br /></font></div>'),
(282987, 'چاوش قلی', '<span class=\"hlight\">چاوش قلی .</span> <font color=\"DarkGreen\"><b>[ وُ ق َ ]</font></b> (اِخ ) دهی است از دهستان رهال بخش حومه ٔ شهرستان خوی که در<span class=\"hlight\" dir=\"rtl\">١٠</span> هزار و پانصدگزی جنوب باختری خوی و <span class=\"hlight\" dir=\"rtl\">٦</span> هزار و پانصدگزی جنوب شوسه ٔ خوی به سیه چشمه واقع شده، جلگه ای است کنار رود قطور، معتدل و مالاریائی که <span class=\"hlight\" dir=\"rtl\">١٣٩</span> تن سکنه دارد. آبش از رود قطور و محصولش غلات، حبوبات و کرچک است . شغل اهالی زراعت و صنایع دستی آنان جوراب بافی وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٤</span>).<br /></font></div>'),
(282988, 'چاوشان', '<span class=\"hlight\">چاوشان .</span> <font color=\"DarkGreen\"><b>[ وُ]</font></b> (اِخ ) دهی است از دهستان ماهیدشت پائین بخش مرکزی شهرستان کرمانشاهان، که در <span class=\"hlight\" dir=\"rtl\">٧</span> هزارگزی باختر کرمانشاه و <span class=\"hlight\" dir=\"rtl\">٣</span> هزارگزی شمال شوسه کرمانشاه بشاه آباد واقع شده، تپه ماهور و سردسیر است و <span class=\"hlight\" dir=\"rtl\">١٥٠</span> تن سکنه دارد. آبش از چشمه و محصولش غلات دیم و لبنیات است . شغل اهالی زراعت و گله داری است . در تابستان از طریق چشمه سینه اتومبیل میتوان برد. (از فرهنگ جغرافیایی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(282989, 'چاوشکی', '<span class=\"hlight\">چاوشکی .</span> <font color=\"DarkGreen\"><b>[ وُ ]</font></b> (اِخ ) قریه ای است در هفت فرسنگی میانه ٔ جنوب و مشرق تنگستان . (از فارسنامه ٔ ناصری ).<br /></font></div>'),
(282990, 'چاوله', '<span class=\"hlight\">چاوله .</span> <font color=\"DarkGreen\"><b>[ وَ ل َ <span class=\"hlight\" dir=\"rtl\">/</span> ل ِ ]</font></b> (اِ) گلی است . (فرهنگ اسدی ) نام گلی باشد صد برگ و بغایت رنگین . (برهان ) (آنندراج ). گلی باشد خوشرنگ . (جهانگیری ). گل سرخ صد برگ و بغایت رنگین . (ناظم الاطباء). گلی خوشرنگ و خوشبوی . گلی باشد نیکو <span class=\"hlight\">:</span> <br />همی بوستان سازی از دشت او<br />چمنهاش پر لاله و چاوله .<br /> <font color=\"Red\">عنصری (از فرهنگ اسدی ).</font><br /><BR><font color=\"Blue\">◄</font> بمعنی کجواج و ناهموار نیز آمده است .(برهان ) (آنندراج ) (ناظم الاطباء).<br /></font></div>'),
(282991, 'چاولی', '<span class=\"hlight\">چاولی .</span> <font color=\"DarkGreen\"><b>[ وُ ]</font></b> (اِخ ) اتابک فخرالدوله ٔ چاولی، حاکم شیراز و امیرالامراء سلطان مسعودبن محمدبن ملکشاه که بنا بگفته ٔ صاحب «نزهة القلوب » چون فارسیان با سلاجقه نافرمانی کردند، سلاجقه اتابک چاولی را به فتح آن دیار فرستادند و او بقهر و جبر اکثر قلاع آنجا را خراب کرد و بعضی که به مطاوعت درآمدند برقرار گذاشت و نگهبانان نشاند. و نیز نویسد که اتابک چاولی بندرامجرد را که بر روی رود کر در قدیم بنا شده و در عهد سلاجقه خلل یافته بود عمارت کرد و شهر «فسا» و شهرنوبنجان (نوبندگان ) را معمور گردانید و صاحب حبیب السیر نویسد که اتابک چاولی با قلیج ارسلان بن سلیمان که متوجه فتح عراق شده بود در کنار نهر خابوبه مصاف داد و سپاهیانش را منهزم گردانید و قلج ارسلان خود را با مرکب خویش در آب انداخت و خفه شد: «اکنون اتابک چاولی آن بند (بند رامجرد) را عمارت کرد و ناحیت آبادان شد». (فارسنامه ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٢٨</span>) «و هیچکس ایشان را مالش نتوانست داد مگر اتابک چاولی کی آن جمله اعمال را مستخلص گردانید». (فارسنامه ٔ ابن البلخی ص <span class=\"hlight\" dir=\"rtl\">١٤١</span>). رجوع به فارسنامه ٔ ابن البلخی و نزهة القلوب ص <span class=\"hlight\" dir=\"rtl\">١٢٣</span>، <span class=\"hlight\" dir=\"rtl\">١٢٥</span>، <span class=\"hlight\" dir=\"rtl\">١٢٩</span>، <span class=\"hlight\" dir=\"rtl\">١٣٨</span>، <span class=\"hlight\" dir=\"rtl\">٢١٩</span> و حبیب السیر ص <span class=\"hlight\" dir=\"rtl\">٣٨٣</span>، <span class=\"hlight\" dir=\"rtl\">٣٩٦</span> شود.<br /></font></div>'),
(282992, 'چاولی', '<span class=\"hlight\">چاولی .</span> (اِ) چیزی باشد پهن که از نی بوریا و امثال آن بافند و غله را بدان بیفشانند تا پاک شود. (برهان ). غله برافشان . (جهانگیری ) (انجمن آرا) (آنندراج ). افزاری که از نی بوریا سازند و بدان غله افشانند. (ناظم الاطباء). ظرفی بافته از نی یا مانند آن برای پیش زدن و پاک کردن غله (فرهنگ نظام ). چچ نیز گویند. (جهانگیری ). چِل . (در لهجه اهالی فیض آباد محولات بخش تربت حیدریه ) <span class=\"hlight\">:</span> <br />فرستاد یرلق به هر کاولی <br />که بافند بهر سپر چاولی .<br /> <font color=\"Red\">بسحاق اطعمه (از جهانگیری ).</font><br />و رجوع به چچ شود.<br /></font></div>'),
(282993, 'چاوه', '<span class=\"hlight\">چاوه .</span><font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِخ ) نام ولایتی است از دربار. (آنندراج ).<br /></font></div>'),
(282994, 'چاووش', '<span class=\"hlight\">چاووش .</span> (ترکی، ص، اِ) چاوش . نقیب لشکر. (برهان ). آنکه صفوف در حرب راست کند و از تعدی لشکریان ممانعت نماید. کسی که شماره ٔ افراد لشکر و هویت یکایک آنان و وظائف هر یک را داند. مراقب سپاهیان . اُترور. زابِن . (منتهی الارب )« <span class=\"hlight\">:</span> هیچکس را زهره نبود که شراب آشکارا خورد که چاووشان و محتسبان گماشته بودند». (تاریخ بیهقی ).<br />از حشمت سلطانی و از تاج فریدون <br />چاووش ورا قبه و قوقوی کلاه است .<br /> <font color=\"Red\">سوزنی .</font><br /> <BR><font color=\"Blue\">◄</font> نقیب قافله . (برهان ). نقیب و جارچی و پیک و یساول و رئیس و پیشوا و وکیل و پیشرو کاروان . (ناظم الاطباء). کسی که دعوت رفتن بزیارت عتبات عالیات کند. در اصطلاح روستائیان خراسان، کسی باشد که در فصل مناسب زیارت در دهات و روستاها سواره یا پیاده براه افتد و روستائیان را بوسیله ٔ جار زدن یا خواندن اشعار مهیج و مناسب بزیارت اعتاب مقدسه تشویق و تهییج نماید. <BR><font color=\"Blue\">◄</font> سرهنگ و صاحب منصبی که پیشاپیش حاکم و اشخاص بزرگ میرود. (ناظم الاطباء) <span class=\"hlight\">:</span> <br />بانگ چاووشان چو از ره بشنود<br />تا نبیند رو به دیواری کند.<br /> <font color=\"Red\">مولوی .</font><br />و رجوع به چاوش شود. <BR><font color=\"Blue\">◄</font> بزغاله ٔ نر یکساله . (در اصطلاح روستائیان تربت حیدریه و گناباد).<br /></font></div>'),
(282995, 'چاووش خوان', '<span class=\"hlight\">چاووش خوان .</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span> خا ]</font></b> (نف مرکب ) چاوش . خواننده ٔ اشعار در منقبت ائمه مناسب با زیارت عتبات عالیات .<br /></font></div>'),
(282996, 'چاووش خوانی', '<span class=\"hlight\">چاووش خوانی .</span> <font color=\"DarkGreen\"><b>[ خوا <span class=\"hlight\" dir=\"rtl\">/</span>خا ]</font></b> (حامص مرکب ) عمل چاووش خوان . آواز و اشعاری که چاووش قافله ٔ زوار خواند. خواندن چاووش قافله زوار اشعار در منقبت ائمه و مناسب با زیارت اعتاب مقدسه .<br /></font></div>'),
(282997, 'چاووش غوری', '<span class=\"hlight\">چاووش غوری .</span> <font color=\"DarkGreen\"><b>[ ش ِ ]</font></b> (اِخ ) ازامرای دربار سلطان سنجر سلجوقی . وی بر سپاه سلطان سالاری فرمود و وقتی که سلطان لشکر بر سر سلطان مسعود برادرزاده ٔ خود کشیده بعضی از امراء سلطان را از جنگ منع مینمودند امیر چاووش شعری چند گفته سلطان را ترغیب بجنگ کرد و از جمله اشعار وی این چند بیت است :<br />خسروا کارزار باید کرد<br />بر عدو کار زار باید کرد<br />شرزه شیران مرغزاری را<br />همه در مرغزار باید کرد<br />روز جنگ است جنگ باید جست <br />وقت کار است کار باید کرد.<br /><font color=\"Red\">(از مجمع الفصحاء ج <span class=\"hlight\" dir=\"rtl\">١</span> ص <span class=\"hlight\" dir=\"rtl\">١٧٧</span>).</font><br /></font></div>'),
(282998, 'چاوچای', '<span class=\"hlight\">چاوچای .</span> (اِ مرکب ) نام دوائی و آن برگی باشد که از ختا آورند و جوشانیده مانند قهوه خورند. (آنندراج ) (غیاث ).<br /></font></div>'),
(282999, 'چاوک', '<span class=\"hlight\">چاوک .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِخ ) دهی از دهستان سرشیو بخش مریوان شهرستان سنندج که در <span class=\"hlight\" dir=\"rtl\">٥</span> هزارگزی شمال دژ شاهپور و <span class=\"hlight\" dir=\"rtl\">٢</span> هزارگزی ثلاثه ٔ بالا واقع شده دامنه و سردسیر است و <span class=\"hlight\" dir=\"rtl\">١٢٥</span> تن سکنه دارد. آبش از چشمه و محصولش غلات، لبنیات و توتون میباشد. شغل اهالی زراعت و گله داری وراهش مالرو است . (از فرهنگ جغرافیائی ایران ج <span class=\"hlight\" dir=\"rtl\">٥</span>).<br /></font></div>'),
(283000, 'چاوک', '<span class=\"hlight\">چاوک .</span> <font color=\"DarkGreen\"><b>[ وَ ]</font></b> (اِ) مخفف چکاوک است . (برهان ) (جهانگیری ). بمعنی چکاوک و مخفف آن است . (انجمن آرا) (آنندراج ) چکاوک . (ناظم الاطباء). مرغی باشد برابر به گنجشک .(برهان ). قبره (به عربی ) (برهان ). (ناظم الاطباء).<br /></font></div>'),
(283001, 'چاویدن', '<span class=\"hlight\">چاویدن .</span> <font color=\"DarkGreen\"><b>[ دَ ]</font></b> (مص ) فریاد کردن گنجشک باشد وقتی که دست بر آشیانه ٔ او دراز کنند. (برهان ) (آنندراج ) (ناظم الاطباء). بانگ کردن مرغ . جیرجیر کردن . نالیدن و بانک کردن مرغ از بیم یا ازدوری بچه و جز آن . <BR><font color=\"Blue\">◄</font> بطریق استعاره بانگ کردن سایر حیوانات و انسان را گویند. (برهان ) (آنندراج ). بانگ بلند کردن انسان و سایر حیوانات . (ناظم الاطباء). (فرهنگ نظام ). لابه و زاری کردن <span class=\"hlight\">:</span> <br />ای عاشق مهجور ز کام دل خود دور<br />مینال و همی چاو که معذوری معذور.<br /> <font color=\"Red\">بوشعیب هروی (از فرهنگ اسدی ).</font><br />شاهی بنالدی و ممالک بگریدی <br />مردی بچاودی و جوانی بزاردی .<br /> <font color=\"Red\">سیدحسن غزنوی .</font><br /><BR><font color=\"Blue\">◄</font> خائیدن . (غیاث ). جاویدن و خائیدن و مضغ کردن . (ناظم الاطباء).<br /></font></div>');
